package gps;

import java.lang.reflect.Proxy;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import org.junit.Assume;
import org.junit.Test;
import org.mockito.Mockito;
import gps.pathfinder.CollisionMap;
import gps.pathfinder.PathStep;
import gps.pathfinder.Pathfinder;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.SplitFlagMap;
import gps.pathfinder.TestPathfinderConfig;

/**
 * Debug probe for the Keldagrim east-side stairs (gps-capture-20260721-212441):
 * dumps plane-1 walkability around the crossing and pathfinds from the stairs
 * landing tile to the captured targets, printing any non-walk jumps. Gated by
 * -DkeldaProbe=true.
 */
public class KeldagrimStairsProbeTest
{
	@Test
	public void probe()
	{
		Assume.assumeTrue(Boolean.getBoolean("keldaProbe"));

		final Thread clientThread = Thread.currentThread();
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState":
						return GameState.LOGGED_IN;
					case "getClientThread":
						return clientThread;
					case "getBoostedSkillLevel":
						return 99;
					default:
						return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
		ShortestPathConfig config = Mockito.mock(ShortestPathConfig.class, invocation ->
		{
			String name = invocation.getMethod().getName();
			Class<?> type = invocation.getMethod().getReturnType();
			if (type == boolean.class)
			{
				return !"avoidWilderness".equals(name) && !"enableSeasonalTransports".equals(name);
			}
			if (type == int.class)
			{
				return "calculationCutoff".equals(name) ? 120 : 0;
			}
			if (type == TeleportationItem.class)
			{
				return TeleportationItem.ALL;
			}
			if (type == JewelleryBoxTier.class)
			{
				return JewelleryBoxTier.ORNATE;
			}
			return HybridPageFillTest.defaultValue(type);
		});

		CollisionMap map = new CollisionMap(SplitFlagMap.fromResources());

		for (int plane = 0; plane <= 1; plane++)
		{
			System.out.println("=== walkability plane " + plane + " (x 2855-2900, '.'=open '#'=blocked) ===");
			System.out.println("      " + "         2         2         2         2      ".trim());
			for (int y = 10214; y >= 10184; y--)
			{
				StringBuilder sb = new StringBuilder();
				for (int x = 2855; x <= 2900; x++)
				{
					boolean open = map.n(x, y, plane) || map.s(x, y, plane) || map.e(x, y, plane) || map.w(x, y, plane);
					sb.append(open ? '.' : '#');
				}
				System.out.println(y + " " + sb);
			}
		}

		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();

		Set<Integer> targets = new LinkedHashSet<>();
		targets.add(WorldPointUtil.packWorldPoint(2893, 10212, 0));
		targets.add(WorldPointUtil.packWorldPoint(2892, 10212, 0));
		targets.add(WorldPointUtil.packWorldPoint(2891, 10212, 0));
		targets.add(WorldPointUtil.packWorldPoint(2893, 10210, 0));
		targets.add(WorldPointUtil.packWorldPoint(2893, 10211, 0));
		targets.add(WorldPointUtil.packWorldPoint(2892, 10211, 0));

		int[][] starts = {
			{2865, 10188, 0},   // captured route start (sanity: should walk via plane 1)
			{2862, 10188, 1},   // transport-data stairs landing tile
			{2862, 10187, 1},
			{2863, 10188, 1},
			{2863, 10187, 1},
			{2865, 10190, 0},   // player tile at capture time
		};

		for (int[] s : starts)
		{
			int start = WorldPointUtil.packWorldPoint(s[0], s[1], s[2]);
			Pathfinder pathfinder = new Pathfinder(planning, start, targets);
			pathfinder.run();
			List<PathStep> path = pathfinder.getPath();
			System.out.println("=== from (" + s[0] + "," + s[1] + "," + s[2] + ") reached="
				+ pathfinder.getResult().isReached() + " steps=" + path.size());
			int prev = start;
			for (int i = 0; i < path.size(); i++)
			{
				int cur = path.get(i).getPackedPosition();
				int d = WorldPointUtil.distanceBetween(prev, cur);
				if (i < 4 || d > 1)
				{
					System.out.println("  [" + i + "] " + WorldPointUtil.unpackWorldX(cur) + ","
						+ WorldPointUtil.unpackWorldY(cur) + "," + WorldPointUtil.unpackWorldPlane(cur)
						+ (d > 1 ? "   <-- JUMP (transport/teleport)" : ""));
				}
				prev = cur;
			}
		}
	}
}

package gps.leagues;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Locks down the {@link LeagueRegion#isAlwaysUnlocked()} and
 * {@link LeagueRegion#isAlwaysBlocked()} contract. The Demonic Pacts League
 * starts players locked to Varlamore alone — every other region (including
 * Karamja, which the wiki describes as a free unlock at 80 tasks) flows
 * through the same area-slot varbits and must be reported as <em>not</em>
 * always-unlocked here.
 */
public class LeagueRegionTest
{
	@Test
	public void onlyVarlamoreAndNeutralAreAlwaysUnlocked()
	{
		assertTrue(LeagueRegion.VARLAMORE.isAlwaysUnlocked());
		assertTrue(LeagueRegion.NEUTRAL.isAlwaysUnlocked());

		assertFalse(LeagueRegion.KARAMJA.isAlwaysUnlocked());
		assertFalse(LeagueRegion.ASGARNIA.isAlwaysUnlocked());
		assertFalse(LeagueRegion.KANDARIN.isAlwaysUnlocked());
		assertFalse(LeagueRegion.FREMENNIK.isAlwaysUnlocked());
		assertFalse(LeagueRegion.KOUREND.isAlwaysUnlocked());
		assertFalse(LeagueRegion.WILDERNESS.isAlwaysUnlocked());
		assertFalse(LeagueRegion.MORYTANIA.isAlwaysUnlocked());
		assertFalse(LeagueRegion.DESERT.isAlwaysUnlocked());
		assertFalse(LeagueRegion.TIRANNWN.isAlwaysUnlocked());
		assertFalse(LeagueRegion.MISTHALIN.isAlwaysUnlocked());
	}

	@Test
	public void misthalinIsTheOnlyAlwaysBlockedRegion()
	{
		for (LeagueRegion region : LeagueRegion.values())
		{
			assertEquals(
				"isAlwaysBlocked mismatch for " + region,
				region == LeagueRegion.MISTHALIN,
				region.isAlwaysBlocked());
		}
	}
}

package gps.leagues;

import java.util.EnumSet;
import static org.junit.Assert.assertEquals;
import org.junit.Test;
import gps.WorldPointUtil;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class LeagueModeStateTest
{
	private static final int VARROCK_WEST = WorldPointUtil.packWorldPoint(3186, 3438, 0);
	private static final int CIVITAS = WorldPointUtil.packWorldPoint(1781, 3100, 0);

	@Test
	public void nonSeasonalReportsEverythingUnlocked()
	{
		LeagueModeState state = new LeagueModeState();
		state.setForTest(false, EnumSet.noneOf(LeagueRegion.class));

		assertTrue(state.isUnlocked(LeagueRegion.MISTHALIN));
		assertTrue(state.isUnlocked(LeagueRegion.KOUREND));
		assertFalse(state.isInBlockedRegion(VARROCK_WEST));
	}

	@Test
	public void seasonalBlocksMisthalinAndLocksUnpickedRegions()
	{
		LeagueModeState state = new LeagueModeState();
		state.setForTest(true, EnumSet.of(LeagueRegion.KANDARIN, LeagueRegion.KARAMJA));

		assertTrue(state.isUnlocked(LeagueRegion.VARLAMORE));
		assertTrue(state.isUnlocked(LeagueRegion.KARAMJA));
		assertTrue(state.isUnlocked(LeagueRegion.NEUTRAL));
		assertTrue(state.isUnlocked(LeagueRegion.KANDARIN));
		assertFalse(state.isUnlocked(LeagueRegion.MISTHALIN));
		assertFalse(state.isUnlocked(LeagueRegion.MORYTANIA));

		assertTrue(state.isInBlockedRegion(VARROCK_WEST));
		assertFalse(state.isInBlockedRegion(CIVITAS));
	}

	@Test
	public void seasonalStartsWithOnlyVarlamoreUnlocked()
	{
		// Pre-80-task state: only Varlamore. Karamja must require its
		// own varbit pick like every other region.
		LeagueModeState state = new LeagueModeState();
		state.setForTest(true, EnumSet.noneOf(LeagueRegion.class));

		assertTrue(state.isUnlocked(LeagueRegion.VARLAMORE));
		assertFalse(state.isUnlocked(LeagueRegion.KARAMJA));
		assertFalse(state.isUnlocked(LeagueRegion.WILDERNESS));
	}

	@Test
	public void areaSelectionVarbitsCoverAllSixSlots()
	{
		// Catches accidental drift if Jagex or RuneLite renumber the
		// LEAGUE_AREA_SELECTION_* varbits. Six contiguous IDs starting at
		// 10662 mirror the gameval VarbitID table.
		assertEquals(6, LeagueModeState.AREA_SELECTION_VARBITS.length);
		for (int i = 0; i < 6; i++)
		{
			assertEquals(LeagueModeState.AREA_SELECTION_VARBITS[i], 10662 + i);
		}
	}
}

package gps.leagues;

import org.junit.Test;
import gps.WorldPointUtil;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class LeagueRegionCheckerTest
{
	@Test
	public void resolvesKnownVarlamoreTile()
	{
		// Civitas illa Fortis east bank: chunk (27, 48) = 6960
		int packed = WorldPointUtil.packWorldPoint(1781, 3100, 0);
		assertEquals(LeagueRegion.VARLAMORE, LeagueRegionChecker.getRegion(packed));
	}

	@Test
	public void resolvesKnownMisthalinTile()
	{
		// Varrock west bank: chunk (49, 53) = 12597
		int packed = WorldPointUtil.packWorldPoint(3186, 3438, 0);
		assertEquals(LeagueRegion.MISTHALIN, LeagueRegionChecker.getRegion(packed));
		assertTrue(LeagueRegionChecker.isInMisthalin(packed));
	}

	@Test
	public void unmappedTileFallsBackToNeutral()
	{
		// chunk (10, 10) = 2570 - not in stub regions.tsv
		int packed = WorldPointUtil.packWorldPoint(640, 640, 0);
		assertEquals(LeagueRegion.NEUTRAL, LeagueRegionChecker.getRegion(packed));
		assertFalse(LeagueRegionChecker.isInMisthalin(packed));
	}

	@Test
	public void reloadOverridesMapping()
	{
		// Capture original
		int someTile = WorldPointUtil.packWorldPoint(640, 640, 0);
		LeagueRegionChecker.reload("2570\tWILDERNESS\n");
		try
		{
			assertEquals(LeagueRegion.WILDERNESS, LeagueRegionChecker.getRegion(someTile));
		}
		finally
		{
			// Reset to whatever the resource file ships
			LeagueRegionChecker.reload(null);
		}
	}
}

package gps;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The ETA/priority separation: the card's ETA is the route's FULL configured cost (travel time,
 * bank detour, and the implicit cost modifiers — charged items, transport type, currency), while
 * explicit priorities stay outside as the green/red chip. List order is always ETA + chip; no
 * hidden component may reorder cards (the Combat-bracelet capture: a 13s-looking route ranked
 * last because its charged-item surcharge was invisible).
 */
public class RouteEtaTest
{
	private static RouteOption route(int totalCost, int rawCost, boolean viaBank)
	{
		TeleportMethod method = new TeleportMethod(
			gps.transport.TransportType.TELEPORTATION_ITEM, "Test", 1);
		return new RouteOption(java.util.List.of(), java.util.List.of(method), java.util.List.of(),
			java.util.List.of(), totalCost, rawCost, true,
			viaBank ? java.util.Set.of(method) : java.util.Set.of(), java.util.List.of(), 0);
	}

	@Test
	public void etaIsTheFullConfiguredCostIncludingModifiers()
	{
		// rawCost 84 with a +30 surcharge (bank pickup or charged-item modifier): the ETA shows
		// the full 114 — the surcharge is never hidden from the number the user compares.
		assertEquals(114, ShortestPathPanel.routeEtaUnits(route(114, 84, true)));
		// No modifiers: ETA == raw travel cost.
		assertEquals(104, ShortestPathPanel.routeEtaUnits(route(104, 104, false)));
	}

	/**
	 * The directions overlay's bank-withdraw step must count the same bank time the search put
	 * into totalCost: {@code bankWithdrawTicks} in cost units tracks {@code max(0, pickup)}
	 * within one-tick granularity, and a negative modifier (a ranking preference) is no time.
	 */
	@Test
	public void directionsBankTicksMatchTheChargedPickup()
	{
		for (int cost : new int[]{0, 15, 16, 30, 100})
		{
			int chargedUnits = Math.max(0, cost);
			int overlayUnits = RouteDirections.bankWithdrawTicks(cost)
				* gps.pathfinder.CostUnits.UNITS_PER_TICK;
			assertTrue("bank time must agree for costBankPickup=" + cost
				+ " (charged " + chargedUnits + " vs overlay " + overlayUnits + ")",
				Math.abs(chargedUnits - overlayUnits) <= 1);
		}
		assertEquals(0, RouteDirections.bankWithdrawTicks(-50));
	}

}

package gps;

import java.util.Scanner;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/** Every shipped sailing leg must produce a drawable sea track (else the overlay dashes). */
public class SeaTrackCoverageTest
{
	@Test
	public void everyPortPairHasATrack()
	{
		// Full sweep incl. full-grid legs takes minutes: audit tool, not a suite tax.
		org.junit.Assume.assumeTrue(Boolean.getBoolean("gps.trackCoverage"));
		int total = 0;
		java.util.List<String> missing = new java.util.ArrayList<>();
		try (Scanner scanner = new Scanner(
			SailingSea.class.getResourceAsStream("/transports/sailing.tsv"), "UTF-8"))
		{
			while (scanner.hasNextLine())
			{
				String line = scanner.nextLine();
				if (line.startsWith("#") || line.isBlank())
				{
					continue;
				}
				String[] f = line.split("	");
				String[] o = f[0].split(" ");
				String[] d = f[1].split(" ");
				int origin = WorldPointUtil.packWorldPoint(
					Integer.parseInt(o[0]), Integer.parseInt(o[1]), 0);
				int destination = WorldPointUtil.packWorldPoint(
					Integer.parseInt(d[0]), Integer.parseInt(d[1]), 0);
				total++;
				if (SailingSea.seaPathBlocking(origin, destination) == null)
				{
					if (missing.size() < 12)
					{
						missing.add(f[0] + " -> " + f[1] + " (" + f[7] + ")");
					}
				}
			}
		}
		assertTrue("checked rows", total > 2000);
		assertTrue(missing.size() + " of " + total + " sailing legs have NO drawable track:\n  "
			+ String.join("\n  ", missing), missing.isEmpty());
	}
}

package gps;

import gps.pathfinder.PathStep;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * The route progress tracker's maze rules: straight-line proximity is wall-blind, so eligibility
 * is based on walking distance. A path tile one tile away across a wall, or a corridor doubling
 * back a few tiles over, must not capture progress — the exact bugs seen in the field ("it thinks
 * I'm at a point in the route that is unreachable from where I stand").
 */
public class RouteProgressTest
{
	private static final int NO_GATE = Integer.MAX_VALUE;

	private static int tile(int x, int y)
	{
		return WorldPointUtil.packWorldPoint(x, y, 0);
	}

	/** A straight east-west path at y=3200: indexes 0..length-1 map to x=3200+i. */
	private static List<PathStep> corridor(int length)
	{
		List<PathStep> path = new ArrayList<>();
		for (int i = 0; i < length; i++)
		{
			path.add(new PathStep(tile(3200 + i, 3200), false));
		}
		return path;
	}

	/** Walking distances where every listed tile is openly reachable (walk == straight line). */
	private static Map<Integer, Integer> openField(int playerPacked, int radius)
	{
		Map<Integer, Integer> walk = new HashMap<>();
		int px = WorldPointUtil.unpackWorldX(playerPacked);
		int py = WorldPointUtil.unpackWorldY(playerPacked);
		for (int dx = -radius; dx <= radius; dx++)
		{
			for (int dy = -radius; dy <= radius; dy++)
			{
				walk.put(tile(px + dx, py + dy), Math.max(Math.abs(dx), Math.abs(dy)));
			}
		}
		return walk;
	}

	@Test
	public void adjacentTileAcrossAWallDoesNotCount()
	{
		// Player at (3205,3201): one tile north of path index 5 — but a wall is between (the
		// BFS never reached any path tile). Legacy straight-line rules would have snapped here.
		List<PathStep> path = corridor(20);
		int player = tile(3205, 3201);
		Map<Integer, Integer> walk = new HashMap<>();
		walk.put(player, 0); // only the player's own tile is reachable
		assertNull("wall-adjacent tile must not capture progress",
			RouteProgress.select(path, 3, NO_GATE, NO_GATE, player, walk));
	}

	@Test
	public void mazeDoubleBackDoesNotTeleportProgress()
	{
		// A U-shaped corridor: outbound leg y=3200 (indexes 0..9), return leg y=3202
		// (indexes 30..39) — 2 tiles apart straight-line, but the wall between means the real
		// walk goes around (14+ steps). The player stands on index 4; index ~34 is 2 tiles away.
		List<PathStep> path = new ArrayList<>();
		for (int i = 0; i < 10; i++)
		{
			path.add(new PathStep(tile(3200 + i, 3200), false));
		}
		for (int i = 10; i < 30; i++)
		{
			path.add(new PathStep(tile(3215, 3200 + (i - 10) / 10), false)); // filler far away
		}
		for (int i = 30; i < 40; i++)
		{
			path.add(new PathStep(tile(3209 - (i - 30), 3202), false));
		}
		int player = tile(3204, 3200);
		Map<Integer, Integer> walk = new HashMap<>();
		// Reachable along the outbound corridor only; the return leg is walled off (absent).
		for (int i = 0; i < 10; i++)
		{
			walk.put(tile(3200 + i, 3200), Math.abs(3200 + i - 3204));
		}
		RouteProgress.Result result = RouteProgress.select(path, 4, NO_GATE, NO_GATE, player, walk);
		assertNotNull(result);
		assertEquals("progress stays on the outbound leg, not across the wall", 4, result.index);
	}

	@Test
	public void doubleBackWithinReachStillPrefersTheNearWalk()
	{
		// Same shape but the wall has a gap: the return tile IS walkable — in 14 steps. Straight
		// line says 2; walking says 14 > 2 + slack, so the near-line match is rejected as
		// through-a-wall even though the tile is technically reachable.
		List<PathStep> path = new ArrayList<>();
		for (int i = 0; i < 10; i++)
		{
			path.add(new PathStep(tile(3200 + i, 3200), false));
		}
		for (int i = 10; i < 12; i++)
		{
			path.add(new PathStep(tile(3204 - (i - 10), 3202), false));
		}
		int player = tile(3204, 3200);
		Map<Integer, Integer> walk = new HashMap<>();
		for (int i = 0; i < 10; i++)
		{
			walk.put(tile(3200 + i, 3200), Math.abs(3200 + i - 3204));
		}
		walk.put(tile(3204, 3202), 11); // reachable, but only the long way round
		walk.put(tile(3203, 3202), 12);
		RouteProgress.Result result = RouteProgress.select(path, 4, NO_GATE, NO_GATE, player, walk);
		assertNotNull(result);
		assertEquals(4, result.index);
	}

	@Test
	public void honestWalkingAdvancesAlongTheCorridor()
	{
		List<PathStep> path = corridor(20);
		int player = tile(3207, 3200); // standing exactly on index 7
		RouteProgress.Result result = RouteProgress.select(
			path, 4, NO_GATE, NO_GATE, player, openField(player, RouteProgress.REACH_RADIUS));
		assertNotNull(result);
		assertEquals(7, result.index);
		assertEquals(0, result.distance);
	}

	@Test
	public void teleportLandingOnThePathJumpsAnyIndexDistance()
	{
		// Landing exactly on index 18 from reachedIndex 2: far outside STEP_WINDOW, but standing
		// ON the path counts anywhere (transport landings).
		List<PathStep> path = corridor(20);
		int player = tile(3218, 3200);
		RouteProgress.Result result = RouteProgress.select(
			path, 2, NO_GATE, NO_GATE, player, openField(player, RouteProgress.REACH_RADIUS));
		assertNotNull(result);
		assertEquals(18, result.index);
	}

	@Test
	public void beyondAnUncrossedDoorOnlyExactPresenceCounts()
	{
		List<PathStep> path = corridor(20);
		int doorGate = 10;
		// One tile from index 12 (beyond the door), openly walkable — still not enough.
		RouteProgress.Result near = RouteProgress.select(
			path, 9, doorGate, NO_GATE, tile(3212, 3201), openField(tile(3212, 3201), RouteProgress.REACH_RADIUS));
		assertEquals("only pre-door tiles are eligible near the door", 9, near.index);
		// Standing exactly on index 12: the door was evidently crossed.
		RouteProgress.Result exact = RouteProgress.select(
			path, 9, doorGate, NO_GATE, tile(3212, 3200), openField(tile(3212, 3200), RouteProgress.REACH_RADIUS));
		assertEquals(12, exact.index);
	}

	@Test
	public void returnLegIsIneligibleUntilTheTurnaround()
	{
		// Round trip retracing the same street: outbound 0..9, return 10..19 on the SAME tiles.
		List<PathStep> path = new ArrayList<>();
		for (int i = 0; i < 10; i++)
		{
			path.add(new PathStep(tile(3200 + i, 3200), false));
		}
		for (int i = 0; i < 10; i++)
		{
			path.add(new PathStep(tile(3209 - i, 3200), false));
		}
		int player = tile(3204, 3200);
		RouteProgress.Result result = RouteProgress.select(
			path, 4, NO_GATE, 9, player, openField(player, RouteProgress.REACH_RADIUS));
		assertNotNull(result);
		assertEquals("walking out must not read as coming back", 4, result.index);
	}

	@Test
	public void legacyStraightLineRulesApplyWithoutACollisionMap()
	{
		// No walk map (collision not loaded): the old behaviour — including its wall-blindness —
		// keeps the tracker functional rather than frozen.
		List<PathStep> path = corridor(20);
		RouteProgress.Result result = RouteProgress.select(
			path, 3, NO_GATE, NO_GATE, tile(3205, 3201), null);
		assertNotNull(result);
		// Indexes 4 and 5 are both straight-line distance 1; ties break toward the previous
		// position — and crucially, the wall-adjacent snap IS allowed in legacy mode.
		assertEquals(4, result.index);
	}

	@Test
	public void offRouteDetourHoldsTheEstimate()
	{
		List<PathStep> path = corridor(20);
		int player = tile(3240, 3240); // nowhere near
		assertNull(RouteProgress.select(
			path, 4, NO_GATE, NO_GATE, player, openField(player, RouteProgress.REACH_RADIUS)));
	}
}

package gps;

import gps.pathfinder.Pathfinder;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

/**
 * Mount Karuulm's dungeon was a one-way island: the cave EXIT existed but the elevator DOWN
 * did not, so everything beneath the mountain — Kaal-Mej-San included — was unreachable. A
 * hub user hit this during A Kingdom Divided: Quest Helper targeted the Tasakaal and GPS
 * routed to "the most random area" (the closest reachable point). The Activate Elevator row
 * closes it; this pins the descent from the surface to the Tasakaal.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class KaruulmElevatorTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

