package gps;

import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import net.runelite.api.gameval.ObjectID;

public class PohScannerTest
{
	@Test
	public void emptyHouseDetectsNothing()
	{
		PohScanner.Detected d = PohScanner.detect(Set.of(1, 2, 3));
		assertFalse(d.any());
		assertEquals(JewelleryBoxTier.NONE, d.jewelleryBox);
	}

	@Test
	public void recognisesEachCleanFeature()
	{
		PohScanner.Detected d = PohScanner.detect(Set.of(
			ObjectID.POH_FAIRY_RING, ObjectID.POH_SPIRIT_TREE, ObjectID.POH_WILDERNESS_OBELISK,
			ObjectID.POH_JEWELLERY_BOX_2));
		assertTrue(d.fairyRing);
		assertTrue(d.spiritTree);
		assertTrue(d.obelisk);
		assertEquals(JewelleryBoxTier.FANCY, d.jewelleryBox);
		assertTrue(d.any());
	}

	@Test
	public void spawnRelevanceMatchesWhatDetectRecognises()
	{
		// Every id detect() reacts to must be flagged, so the spawn-event fast path never misses
		// furniture the tile scan would have found.
		for (int id : new int[]{
			ObjectID.POH_FAIRY_RING, ObjectID.POH_FAIRY_HOUSE, ObjectID.POH_FAIRY_HOUSE_OPEN,
			ObjectID.POH_SPIRIT_TREE, ObjectID.POH_WILDERNESS_OBELISK,
			ObjectID.POH_JEWELLERY_BOX_1, ObjectID.POH_JEWELLERY_BOX_2, ObjectID.POH_JEWELLERY_BOX_3})
		{
			assertTrue(String.valueOf(id), PohScanner.isRecognised(id));
			assertTrue(PohScanner.detect(Set.of(id)).any());
		}
		assertFalse(PohScanner.isRecognised(1));
	}

	@Test
	public void encodeDecodeRoundTripsEveryCombination()
	{
		for (JewelleryBoxTier tier : JewelleryBoxTier.values())
		{
			for (int flags = 0; flags < 8; flags++)
			{
				PohScanner.Detected original = new PohScanner.Detected(
					(flags & 1) != 0, (flags & 2) != 0, (flags & 4) != 0, tier);
				PohScanner.Detected decoded = PohScanner.decode(PohScanner.encode(original));
				assertTrue(tier + "/" + flags, original.sameAs(decoded));
			}
		}
	}

	@Test
	public void missingOrMalformedStoredDataDecodesToNull()
	{
		assertEquals(null, PohScanner.decode(null));
		assertEquals(null, PohScanner.decode(""));
		assertEquals(null, PohScanner.decode("garbage,fairyRing"));
		assertEquals(null, PohScanner.encode(null));
		// Duplicate flags are tolerated, not fatal.
		assertTrue(PohScanner.decode("NONE,fairyRing,fairyRing").fairyRing);
	}

	@Test
	public void jewelleryBoxTakesTheHighestTierPresent()
	{
		// A house upgraded to ornate may still show the lower box ids; the highest wins.
		assertEquals(JewelleryBoxTier.ORNATE, PohScanner.detect(Set.of(
			ObjectID.POH_JEWELLERY_BOX_1, ObjectID.POH_JEWELLERY_BOX_3)).jewelleryBox);
		assertEquals(JewelleryBoxTier.BASIC, PohScanner.detect(Set.of(
			ObjectID.POH_JEWELLERY_BOX_1)).jewelleryBox);
	}

	@Test
	public void openFairyHouseAlsoCounts()
	{
		assertTrue(PohScanner.detect(Set.of(ObjectID.POH_FAIRY_HOUSE_OPEN)).fairyRing);
	}
}

package gps;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Set;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertFalse;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Hidden type-toggle keys with no panel control: a stored value (old build / pre-fork upstream
 * config) is unreachable and silently disables a whole network — the field report was
 * useCharterShips=false with no checkbox anywhere, and charters never appeared. Startup clears
 * such keys so the on-by-default decision holds; panel-backed toggles must never be touched.
 */
@RunWith(MockitoJUnitRunner.class)
public class StrandedToggleMigrationTest
{
	@Mock
	ConfigManager configManager;

	@Test
	public void strandedValuesAreClearedAndPanelBackedTogglesUntouched() throws Exception
	{
		ShortestPathPlugin plugin = new ShortestPathPlugin();
		Field f = ShortestPathPlugin.class.getDeclaredField("configManager");
		f.setAccessible(true);
		f.set(plugin, configManager);
		// Only the charter key has a stored (stranded) value in this scenario.
		when(configManager.getConfiguration(anyString(), anyString())).thenReturn(null);
		when(configManager.getConfiguration("gps", "useCharterShips")).thenReturn("false");

		Method migrate = ShortestPathPlugin.class.getDeclaredMethod("clearUnsurfacedTypeToggles");
		migrate.setAccessible(true);
		migrate.invoke(plugin);

		verify(configManager).unsetConfiguration("gps", "useCharterShips");
		verify(configManager, never()).unsetConfiguration(eq("gps"), eq("useBoats"));

		// The list itself must never contain a toggle the panel writes: clearing one of those
		// would undo a choice the user CAN see and make.
		Set<String> panelBacked = Set.of("useSailing", "useHotAirBalloons", "usePoh", "usePohFairyRing",
			"usePohSpiritTree", "usePohObelisk", "usePohMountedItems", "useTeleportationPortalsPoh",
			"useSpiritTrees", "useSeasonalTransports", "useTeleportationItems");
		for (String key : ShortestPathPlugin.UNSURFACED_TYPE_TOGGLES)
		{
			assertFalse(key + " is panel-backed and must not be cleared", panelBacked.contains(key));
		}
	}
}

package gps;

import gps.pathfinder.Pathfinder;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.PathStep;
import gps.pathfinder.TestPathfinderConfig;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

/**
 * The Mysterious pipe (88 Agility, id 34655) shortcuts the Karuulm Slayer Dungeon's hydra
 * chamber straight to the Alchemical Hydra corridor. The Agility plugin knew it; GPS data
 * didn't. Standing/landing tiles are cache-derived (~geometry): the pipe object tiles
 * (1316,10214) and (1346,10231) are blocked, so the rows use their open-side neighbours.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class KaruulmPipeTest
{
	private static final int NEAR_HYDRA = WorldPointUtil.packWorldPoint(1346, 10232, 0);
	private static final int NEAR_HALL = WorldPointUtil.packWorldPoint(1315, 10214, 0);

	@Mock
	Client client;
	private final TestShortestPathConfig config = new TestShortestPathConfig();

	/**
	 * The LIVE config (not copyForPlanning) — planning mode bypasses per-player unlock gates,
	 * skill levels included, which would defeat the 88 Agility assertions.
	 */
	private PathfinderConfig liveAt(int agilityLevel)
	{
		config.setCalculationCutoffValue(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(agilityLevel);
		PathfinderConfig live = new TestPathfinderConfig(client, config);
		live.refresh();
		return live;
	}

	private static boolean usesPipe(List<PathStep> steps, int from, int to)
	{
		for (int i = 0; i + 1 < steps.size(); i++)
		{
			if (steps.get(i).getPackedPosition() == from
				&& steps.get(i + 1).getPackedPosition() == to)
			{
				return true;
			}
		}
		return false;
	}

	@Test
	public void with88AgilityThePipeCarriesBothDirections()
	{
		PathfinderConfig planning = liveAt(99);
		Pathfinder toHall = new Pathfinder(planning, NEAR_HYDRA, Set.of(NEAR_HALL));
		toHall.run();
		assertTrue(toHall.getResult().isReached());
		assertTrue("hydra-side to hall must squeeze through the pipe",
			usesPipe(toHall.getResult().getPathSteps(), NEAR_HYDRA, NEAR_HALL));

		Pathfinder toHydra = new Pathfinder(planning, NEAR_HALL, Set.of(NEAR_HYDRA));
		toHydra.run();
		assertTrue(toHydra.getResult().isReached());
		assertTrue("hall to hydra-side must squeeze through the pipe",
			usesPipe(toHydra.getResult().getPathSteps(), NEAR_HALL, NEAR_HYDRA));
	}

	@Test
	public void below88AgilityThePipeIsClosed()
	{
		PathfinderConfig planning = liveAt(87);
		Pathfinder toHall = new Pathfinder(planning, NEAR_HYDRA, Set.of(NEAR_HALL));
		toHall.run();
		assertFalse("at 87 Agility the pipe edge must not be taken",
			usesPipe(toHall.getResult().getPathSteps(), NEAR_HYDRA, NEAR_HALL));
	}
}

