package gps;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * Track QUALITY as numbers, not eyeballs: for the field capture 212843 leg (the Pandemonium's
 * ship berth to open water at 2882,2872), report how many straight legs the helm must steer
 * and the closest the track ever comes to a blocked tile — then hold both to the bounds the
 * standoff/smoothing machinery promises. The second test re-runs the leg with hull obstacles
 * planted on the course (the moored ships of screenshot report 2026-08-14): the dogleg
 * snapping must keep the 16-bearing grid around hulls, where the old two-leg-or-chord
 * fallback wiggled. Run with -i to see the reports in the test log.
 */
public class SeaTrackQualityTest
{
	private static final int PANDEMONIUM_BERTH_LAND = WorldPointUtil.packWorldPoint(3069, 2986, 0);
	private static final int CAPTURE_PIN = WorldPointUtil.packWorldPoint(2882, 2872, 0);
	/** Endpoint approaches may legally close in (port water); the open-sea body may not. */
	private static final int ENDPOINT_SLACK_POINTS = 3;

	@Test
	public void captureLegIsFewStraightLegsWithClearance()
	{
		int[] track = SailingSea.seaPathBlocking(PANDEMONIUM_BERTH_LAND, CAPTURE_PIN);
		assertTrue("track must exist", track != null && track.length > 2);

		// Real helm changes via the windowed corner detector — per-point bearings count the
		// integer stair-stepping of densified straight chords as phantom turns.
		int straightLegs = SailingSea.trackCorners(track).size() - 1;

		int minClearance = Integer.MAX_VALUE;
		int clearanceAtX = -1;
		int clearanceAtY = -1;
		for (int w = ENDPOINT_SLACK_POINTS; w < track.length - ENDPOINT_SLACK_POINTS; w++)
		{
			int x = WorldPointUtil.unpackWorldX(track[w]);
			int y = WorldPointUtil.unpackWorldY(track[w]);
			int clearance = clearanceAt(x, y);
			if (clearance < minClearance)
			{
				minClearance = clearance;
				clearanceAtX = x;
				clearanceAtY = y;
			}
		}

		System.out.println("TRACK QUALITY " + 3069 + "," + 2986 + " -> 2882,2872: "
			+ straightLegs + " straight leg(s) over " + track.length + " points; minimum "
			+ minClearance + " tile(s) of clearance (tightest at " + clearanceAtX + ","
			+ clearanceAtY + ")");

		assertTrue("a mostly open-water leg should need few helm changes, got " + straightLegs,
			straightLegs <= 10);
		assertTrue("the open-sea body of the track must keep the standoff, got "
				+ minClearance + " tile(s) at " + clearanceAtX + "," + clearanceAtY,
			minClearance >= 2);

		String offenders = bearingOffenders(track);
		assertTrue("legs must steer the 16 boat bearings, off-grid:" + offenders,
			offenders.isEmpty());
	}

	/**
	 * The screenshot condition (2026-08-14): moored hulls on the course force the track to
	 * dodge — every leg must STILL steer the 16 bearings. Before the dogleg snapping,
	 * obstacle-blocked cones fell back to raw off-grid chords, and the field track wiggled
	 * exactly where the green hull boxes sat. Hulls are planted ON the clean track's own
	 * mid-course points (learner-style, +1 dilation applied by learnObstacles), so the
	 * dodge is guaranteed and the fixture survives any future course change.
	 */
	@Test
	public void hullObstaclesKeepTheBearingGrid()
	{
		int[] clean = SailingSea.seaPathBlocking(PANDEMONIUM_BERTH_LAND, CAPTURE_PIN);
		assertTrue("clean track must exist", clean != null && clean.length > 8);

		List<Integer> hulls = new ArrayList<>();
		for (int at : new int[]{clean.length / 4, clean.length / 2})
		{
			int cx = WorldPointUtil.unpackWorldX(clean[at]);
			int cy = WorldPointUtil.unpackWorldY(clean[at]);
			for (int dx = -2; dx <= 2; dx++)
			{
				for (int dy = -2; dy <= 2; dy++)
				{
					hulls.add(WorldPointUtil.packWorldPoint(cx + dx, cy + dy, 0));
				}
			}
		}

		try
		{
			SailingSea.learnObstacles(hulls);
			int[] track = SailingSea.seaPathBlocking(PANDEMONIUM_BERTH_LAND, CAPTURE_PIN);
			assertTrue("track must exist with hulls loaded", track != null && track.length > 2);
			for (int point : track)
			{
				assertTrue("track must dodge the hulls, hit "
						+ WorldPointUtil.unpackWorldX(point) + "," + WorldPointUtil.unpackWorldY(point),
					!SailingSea.obstacleAt(
						WorldPointUtil.unpackWorldX(point), WorldPointUtil.unpackWorldY(point)));
			}
			int straightLegs = SailingSea.trackCorners(track).size() - 1;
			String offenders = bearingOffenders(track, true);
			System.out.println("TRACK QUALITY (hulls on course): " + straightLegs
				+ " straight leg(s) over " + track.length + " points;"
				+ (offenders.isEmpty() ? " all on the bearing grid" : " off-grid:" + offenders));
			StringBuilder geometry = new StringBuilder("TRACK GEOMETRY corners:");
			for (int c : SailingSea.trackCorners(track))
			{
				geometry.append(' ').append(c).append('@')
					.append(WorldPointUtil.unpackWorldX(track[c])).append(',')
					.append(WorldPointUtil.unpackWorldY(track[c]));
			}
			System.out.println(geometry);
			assertTrue("hull-dodging legs must steer the 16 boat bearings, off-grid:" + offenders,
				offenders.isEmpty());
		}
		finally
		{
			SailingSea.clearLiveObstacles();
		}
	}

	/**
	 * Every leg must lie on one of the 16 bearings the boat can steer (22.5-degree grid);
	 * port-approach legs (both corners within 25 tiles of an endpoint) may fall back to raw
	 * chords in tight corridors, and one SHORT connector (<= 16 tiles, <= 8 degrees off)
	 * may absorb the integer residue of the fractional bearing decomposition. Returns the
	 * offender list — empty means the grid holds.
	 */
	private static String bearingOffenders(int[] track)
	{
		return bearingOffenders(track, false);
	}

	/**
	 * {@code hullDodges} widens the one-connector tolerance to 25 tiles / 12 degrees:
	 * a corner butted against a learned hull box has no on-bearing exit at all (every
	 * candidate clips the box; only the diagonal chord threads it) — fixing that needs
	 * bearing-aware corner PLACEMENT, tracked as follow-up work, not a better snapper.
	 */
	private static String bearingOffenders(int[] track, boolean hullDodges)
	{
		List<Integer> corners = SailingSea.trackCorners(track);
		StringBuilder offenders = new StringBuilder();
		for (int c = 0; c + 1 < corners.size(); c++)
		{
			// Sample the leg INTERIOR: the windowed detector places corners up to two dense
			// points (~8 tiles) off the true geometric corner, smearing edge angles.
			int from = corners.get(c);
			int to = corners.get(c + 1);
			if (to - from >= 6)
			{
				from += 2;
				to -= 2;
			}
			int a1 = track[from];
			int b1 = track[to];
			double dx = WorldPointUtil.unpackWorldX(b1) - WorldPointUtil.unpackWorldX(a1);
			double dy = WorldPointUtil.unpackWorldY(b1) - WorldPointUtil.unpackWorldY(a1);
			double angle = Math.toDegrees(Math.atan2(dy, dx));
			double offGrid = Math.abs(angle % 22.5);
			offGrid = Math.min(offGrid, 22.5 - offGrid);
			boolean approach =
				(WorldPointUtil.distanceBetween(a1, track[0]) <= 25
					&& WorldPointUtil.distanceBetween(b1, track[0]) <= 25)
				|| (WorldPointUtil.distanceBetween(a1, track[track.length - 1]) <= 25
					&& WorldPointUtil.distanceBetween(b1, track[track.length - 1]) <= 25);
			boolean shortConnector = hullDodges
				? Math.hypot(dx, dy) <= 25 && offGrid <= 12.0
				: Math.hypot(dx, dy) <= 16 && offGrid <= 8.0;
			if (offGrid > 4.0 && !approach && !shortConnector)
			{
				offenders.append(' ').append(WorldPointUtil.unpackWorldX(a1)).append(',')
					.append(WorldPointUtil.unpackWorldY(a1)).append("->")
					.append(WorldPointUtil.unpackWorldX(b1)).append(',')
					.append(WorldPointUtil.unpackWorldY(b1))
					.append(String.format("(%.1f deg off)", offGrid));
			}
		}
		return offenders.toString();
	}

	/** Chebyshev distance from (x, y) to the nearest non-sailable tile, capped at 6. */
	private static int clearanceAt(int x, int y)
	{
		for (int radius = 1; radius <= 6; radius++)
		{
			for (int dx = -radius; dx <= radius; dx++)
			{
				for (int dy = -radius; dy <= radius; dy++)
				{
					if (Math.max(Math.abs(dx), Math.abs(dy)) == radius
						&& !SailingSea.isSailable(WorldPointUtil.packWorldPoint(x + dx, y + dy, 0)))
					{
						return radius;
					}
				}
			}
		}
		return 6;
	}

}

package gps;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.lang.reflect.Field;
import javax.imageio.ImageIO;
import net.runelite.api.Client;
import org.junit.Test;
import org.mockito.Mockito;

/**
 * Scratch harness: renders the directions HUD's "Finding the best route" panel headlessly to a
 * PNG (GPS_HUD_DUMP=path) so its layout can be inspected without a client. Not a regression test.
 */
public class HudRenderDumpTest
{
	@Test
	public void dumpFindingPanel() throws Exception
	{
		if (System.getenv("GPS_HUD_DUMP") == null)
		{
			return;
		}
		ShortestPathPlugin plugin = Mockito.mock(ShortestPathPlugin.class, Mockito.withSettings().lenient());
		Mockito.when(plugin.isFindingRoute()).thenReturn(true);
		Mockito.when(plugin.getDisplayedRoute()).thenReturn(null);
		Mockito.when(plugin.getTargetSource()).thenReturn(System.getenv("GPS_HUD_SOURCE"));
		set(plugin, "showDirections", true);
		set(plugin, "colourOverlayAccent", new Color(0x3C, 0x8C, 0xE6));
		set(plugin, "overlayFontSize", OverlayFontSize.NORMAL);
		set(plugin, "overrideOverlayTransparency", false);

		RouteDirectionsOverlay overlay = new RouteDirectionsOverlay(Mockito.mock(Client.class), plugin);
		for (String source : new String[]{"Slayer gear advisor", null})
		{
			Mockito.when(plugin.getTargetSource()).thenReturn(source);
			BufferedImage image = new BufferedImage(420, 160, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = image.createGraphics();
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			// A game-like backdrop so the translucent panel reads as it does in the client.
			g.setColor(new Color(0x4A, 0x6B, 0x3A));
			g.fillRect(0, 0, image.getWidth(), image.getHeight());
			g.setFont(net.runelite.client.ui.FontManager.getRunescapeFont());
			g.translate(10, 10);
			// The panel component sizes itself from the previous frame: render twice, keep the second.
			overlay.render(g);
			g.setColor(new Color(0x4A, 0x6B, 0x3A));
			g.fillRect(-10, -10, image.getWidth(), image.getHeight());
			Dimension size = overlay.render(g);
			g.dispose();
			File out = new File(System.getenv("GPS_HUD_DUMP") + (source == null ? "-plain.png" : "-source.png"));
			ImageIO.write(image, "png", out);
			System.out.println("wrote " + out.getAbsolutePath() + " panel=" + size
				+ " children=" + overlay.getPanelComponent().getChildren().size());
		}
	}

	private static void set(Object target, String field, Object value) throws Exception
	{
		Field f = ShortestPathPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(target, value);
	}
}

package gps;

import java.lang.reflect.Proxy;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;

public class PohHeuristicRegressionTest
{
	private AlternativeRoutesService service;
	private PathfinderConfig planningConfig;

	@Before
	public void before()
	{
		final Thread clientThread = Thread.currentThread();
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState":
						return GameState.LOGGED_IN;
					case "getClientThread":
						return clientThread;
					case "getBoostedSkillLevel":
						return 99;
					default:
						return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		Mockito.when(cfg.usePoh()).thenReturn(true);
		Mockito.when(cfg.useTeleportationPortalsPoh()).thenReturn(true);
		PathfinderConfig config = new TestPathfinderConfig(client, cfg).copyForPlanning();
		config.refresh();
		planningConfig = config;
		ClientThread ct = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(Mockito.any(Runnable.class));
		service = new AlternativeRoutesService(ct, config);
	}

	@org.junit.After
	public void after()
	{
		service.shutdown();
	}

	/**
	 * User capture pair (20260713-232224/232231): from Keldagrim, the four "enter the POH, take the
	 * Lassar Portal" routes (cost 29) only appeared AFTER "+", jumping above the first page's 67+
	 * routes. The distance field's reverse transport index credited POH portals to their interior
	 * origin instead of the remapped landing key, leaving the landing unflooded — the heuristic then
	 * overestimated inside the house (inadmissible), so house-mediated routes settled late. The
	 * first page must now carry them.
	 */
	@Test
	public void houseMediatedRoutesAreOnTheFirstPage() throws Exception
	{
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(WorldPointUtil.packWorldPoint(2907, 10172, 0),
			Set.of(WorldPointUtil.packWorldPoint(3009, 3487, 0)), Set.of(),
			AlternativeRoutesMode.ALL_EVERYTHING, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue(latch.await(60, TimeUnit.SECONDS));
		List<RouteOption> routes = out.get();
		assertNotNull(routes);
		int pohPortalRoutesAtBestTier = 0;
		for (RouteOption route : routes)
		{
			boolean viaPohPortal = route.getMethods().stream()
				.anyMatch(m -> gps.transport.TransportType.TELEPORTATION_PORTAL_POH.equals(m.getType()));
			if (viaPohPortal && route.getTotalCost() <= routes.get(0).getTotalCost() + 2)
			{
				pohPortalRoutesAtBestTier++;
			}
		}
		assertTrue("the first page must include the house->Lassar Portal routes at the best cost tier"
			+ " (found " + pohPortalRoutesAtBestTier + ")", pohPortalRoutesAtBestTier >= 3);
	}

	/**
	 * Route 0 itself was vulnerable, not just the lower ranks: for a player without the direct
	 * Lassar teleports, the TRUE optimum is the house route (29) — pre-fix, the inadmissible
	 * heuristic made the first search return Mind Altar (67) as the top route instead. Excluding
	 * the direct teleports simulates that player.
	 */
	@Test
	public void routeZeroIsTheHouseRouteWhenDirectTeleportsAreMissing() throws Exception
	{
		Set<TeleportMethod> exclusions = new java.util.HashSet<>();
		for (TeleportMethod method : planningConfig.getMethodCatalog())
		{
			if (method.label().equals("Lassar tablet") || method.label().equals("Lassar Teleport"))
			{
				exclusions.add(method);
			}
		}
		assertTrue("both direct Lassar methods must exist in the catalog", exclusions.size() == 2);

		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(WorldPointUtil.packWorldPoint(2907, 10172, 0),
			Set.of(WorldPointUtil.packWorldPoint(3009, 3487, 0)), exclusions,
			AlternativeRoutesMode.ALL_EVERYTHING, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue(latch.await(60, TimeUnit.SECONDS));
		List<RouteOption> routes = out.get();
		assertNotNull(routes);
		assertTrue("routes must be found", !routes.isEmpty());
		RouteOption best = routes.get(0);
		boolean viaPohPortal = best.getMethods().stream()
			.anyMatch(m -> gps.transport.TransportType.TELEPORTATION_PORTAL_POH.equals(m.getType()));
		assertTrue("route 0 must be the house-mediated optimum (cost " + best.getTotalCost()
			+ ", methods " + best.getMethods() + ")", viaPohPortal && best.getTotalCost() <= 30);
	}
}

package gps;

import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import org.junit.Test;
import org.mockito.Mockito;

import static org.junit.Assert.assertTrue;

/**
 * The overlay's route across a REAL generation (real service, real threads), sampled at high
 * frequency from a render-like thread: for a fresh destination the overlay must show nothing
 * while the generation streams and then the settled best — one appearance, no flicker through
 * the re-sorted list.
 */
public class ProvisionalDisplayLiveTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3221, 3219, 0);
	private static final int GRAND_EXCHANGE = WorldPointUtil.packWorldPoint(3164, 3487, 0);
	/** Capture 20260822-163446: Lumbridge -> Civitas illa Fortis, 10 chain routes + seeds + a 383 ms walk. */
	private static final int CIVITAS = WorldPointUtil.packWorldPoint(1687, 3141, 0);

	private static Client client()
	{
		final Thread ct = Thread.currentThread();
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState": return GameState.LOGGED_IN;
					case "getClientThread": return ct;
					case "getBoostedSkillLevel": return 99;
					default: return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
	}

	private static void set(Object target, String field, Object value) throws Exception
	{
		Field f = target.getClass().getDeclaredField(field);
		f.setAccessible(true);
		f.set(target, value);
	}

	private static Object get(Object target, String field) throws Exception
	{
		Field f = target.getClass().getDeclaredField(field);
		f.setAccessible(true);
		return f.get(target);
	}

	private static List<String> sampleGeneration(int start, int target, AlternativeRoutesMode mode) throws Exception
	{
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		Mockito.when(cfg.currencyThreshold()).thenReturn(10000000);
		Mockito.when(cfg.useTeleportationItems()).thenReturn(TeleportationItem.INVENTORY);
		for (String name : new String[]{"useTeleportationSpells", "useFairyRings", "useSpiritTrees", "useShips",
			"useMinecarts", "useCharterShips", "useGnomeGliders", "useQuetzals", "useTeleportationMinigames",
			"useTeleportationPortals", "useAgilityShortcuts", "useBoats", "useMagicCarpets", "useCanoes",
			"useTeleportationLevers", "useMountainGuides", "useHotAirBalloons", "useMagicMushtrees", "useSailing"})
		{
			Mockito.when((Boolean) ShortestPathConfig.class.getMethod(name).invoke(cfg)).thenReturn(true);
		}
		Mockito.when(cfg.defaultRouteCount()).thenReturn(10);
		PathfinderConfig planning = new TestPathfinderConfig(client(), cfg).copyForPlanning();
		planning.refresh();
		// The service refreshes on "the client thread": the test thread here, via a direct-run mock.
		ClientThread ct = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(Mockito.any(Runnable.class));
		AlternativeRoutesService service = new AlternativeRoutesService(ct, planning);

		ShortestPathPlugin plugin = new ShortestPathPlugin();
		set(plugin, "routeDirectionsOverlay", Mockito.mock(RouteDirectionsOverlay.class));
		set(plugin, "altRoutesService", service);
		set(plugin, "config", cfg);
		set(plugin, "pathTargets", Set.of(target));
		set(plugin, "routeLimit", 10);
		set(plugin, "routesMode", mode);

		// Sample what the overlay would draw, as fast as a render loop and then some.
		List<String> trace = new ArrayList<>();
		Thread sampler = new Thread(() ->
		{
			RouteOption last = null;
			boolean started = false;
			boolean sawFinding = false;
			long until = System.currentTimeMillis() + 30000;
			while (System.currentTimeMillis() < until)
			{
				try
				{
					boolean inFlight = (boolean) get(plugin, "altGenerationInFlight");
					started |= inFlight;
					RouteOption now = plugin.getDisplayedRoute();
					// The initial empty state is only "seen" once the generation is in flight.
					if (!sawFinding && now == null && plugin.isFindingRoute())
					{
						sawFinding = true;
						synchronized (trace)
						{
							trace.add("null [finding] [in-flight]");
						}
					}
					if (now != last)
					{
						synchronized (trace)
						{
							trace.add((now == null ? "null" : now.getTotalCost() + " " + now.getMethods())
								+ (plugin.isFindingRoute() ? " [finding]" : "")
								+ (inFlight ? " [in-flight]" : ""));
						}
						last = now;
					}
					if (started && !inFlight)
					{
						break;
					}
					Thread.sleep(0, 200_000);
				}
				catch (Exception e)
				{
					throw new RuntimeException(e);
				}
			}
		});
		sampler.start();

		Method trigger = ShortestPathPlugin.class.getDeclaredMethod("triggerAlternatives", int.class, Set.class);
		trigger.setAccessible(true);
		trigger.invoke(plugin, start, new HashSet<>(Set.of(target)));
		sampler.join(40000);
		service.shutdown();
		synchronized (trace)
		{
			return new ArrayList<>(trace);
		}
	}

	private static void assertOneAppearance(List<String> trace)
	{
		int routeChanges = 0;
		for (String t : trace)
		{
			if (!t.startsWith("null"))
			{
				routeChanges++;
			}
		}
		assertTrue("the overlay must stay empty while finding and then show the settled route once; saw " + trace,
			routeChanges == 1);
		assertTrue("the finding state must be visible before the list settles; saw " + trace,
			trace.stream().anyMatch(t -> t.startsWith("null") && t.contains("[finding]")));
	}

	@Test
	public void lumbridgeToGrandExchange() throws Exception
	{
		assertOneAppearance(sampleGeneration(LUMBRIDGE, GRAND_EXCHANGE, AlternativeRoutesMode.OWNED_INVENTORY));
	}

	@Test
	public void lumbridgeToCivitasEverything() throws Exception
	{
		assertOneAppearance(sampleGeneration(LUMBRIDGE, CIVITAS, AlternativeRoutesMode.ALL_EVERYTHING));
	}
}

package gps;

import java.io.ByteArrayInputStream;
import java.io.FilterInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.Random;
import javax.annotation.Nonnull;
import org.junit.Assert;
import org.junit.Test;

/**
 * Unit tests for {@link Util} helper methods.
 */
public class UtilTest
{

	// --- readAllBytes -----------------------------------------------------

	@Test
	public void readAllBytesEmptyStream() throws IOException
	{
		byte[] data = Util.readAllBytes(new ByteArrayInputStream(new byte[0]));
		Assert.assertNotNull(data);
		Assert.assertEquals(0, data.length);
	}

	@Test
	public void readAllBytesSmall() throws IOException
	{
		byte[] expected = {1, 2, 3, 4, 5};
		byte[] data = Util.readAllBytes(new ByteArrayInputStream(expected));
		Assert.assertArrayEquals(expected, data);
	}

	@Test
	public void readAllBytesLargerThanBuffer() throws IOException
	{
		// Create data larger than the internal 1024 byte buffer to exercise loop logic
		byte[] expected = new byte[4096];
		for (int i = 0; i < expected.length; i++)
		{
			expected[i] = (byte) (i * 31); // deterministic pattern
		}
		byte[] data = Util.readAllBytes(new ByteArrayInputStream(expected));
		Assert.assertArrayEquals(expected, data);
	}

	@Test(expected = IOException.class)
	public void readAllBytesPropagatesIOException() throws IOException
	{
		// InputStream that throws after first read
		InputStream failing = new FilterInputStream(new ByteArrayInputStream(new byte[]{1, 2, 3}))
		{
			private boolean first = true;

			@Override
			public int read(@Nonnull byte[] b, int off, int len) throws IOException
			{
				if (first)
				{
					first = false;
					return super.read(b, off, len);
				}
				throw new IOException("boom");
			}
		};
		// Should throw on second read attempt
		Util.readAllBytes(failing);
	}

	// --- concatenate ------------------------------------------------------

	@Test
	public void concatenateAllNullOrEmptyReturnsNull()
	{
		Assert.assertNull(Util.concatenate(new int[][]{null, new int[0], null}));
	}

	@Test
	public void concatenateSingleArrayIdentity()
	{
		int[] a = {1, 2, 3};
		Assert.assertArrayEquals(a, Util.concatenate(new int[][]{a}));
	}

	@Test
	public void concatenateSkipsNulls()
	{
		int[] a = {1, 2};
		int[] c = {3};
		int[] result = Util.concatenate(new int[][]{a, null, c});
		Assert.assertArrayEquals(new int[]{1, 2, 3}, result);
	}

	@Test
	public void concatenateMultiple()
	{
		int[] a = {1};
		int[] b = {2, 3};
		int[] c = {4, 5, 6};
		int[] result = Util.concatenate(new int[][]{a, b, c});
		Assert.assertArrayEquals(new int[]{1, 2, 3, 4, 5, 6}, result);
	}

	@Test
	public void concatenateLarge()
	{
		// Use random sizes to stress size accumulation & copy loop
		Random rnd = new Random(123);
		int[][] arrays = new int[50][];
		int total = 0;
		for (int i = 0; i < arrays.length; i++)
		{
			int len = rnd.nextInt(10); // small to keep test fast
			if (len == 0)
			{
				arrays[i] = new int[0];
			}
			else
			{
				arrays[i] = new int[len];
				for (int j = 0; j < len; j++)
				{
					arrays[i][j] = i * 100 + j;
				}
				total += len;
			}
		}
		int[] combined = Util.concatenate(arrays);
		if (total == 0)
		{
			Assert.assertNull(combined);
		}
		else
		{
			int count = 0;
			for (int[] arr : arrays)
			{
				if (arr == null)
				{
					continue;
				}
				for (int v : arr)
				{
					Assert.assertNotNull(combined);
					Assert.assertEquals(v, combined[count++]);
				}
			}
			Assert.assertNotNull(combined);
			Assert.assertEquals(total, combined.length);
		}
	}
}

package gps;

import gps.pathfinder.Pathfinder;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

/**
 * The Underground Pass field campaign's connectivity, locked in: from the West Ardougne street,
 * routing reaches level 1's far west and — through the captured Well 4004 — the DEEP BAND, all
 * across ~350 field-captured rows (rockslides, bridges, ledges, wells, the lever, the fire-arrow
 * bridge, the rope swing). Still open: the deep band's internal links (well landing -> bridge
 * maze -> Iban's Temple) — extend this test as those captures land; the temple is the finish
 * line (see also CuratedDestinationsTest's pin test).
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class UndergroundPassConnectivityTest
{
	private static final int OUTSIDE_ENTRANCE = WorldPointUtil.packWorldPoint(2436, 3315, 0);

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	@Test
	public void streetToDeepBandRoutesAcrossTheCapturedPass()
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		int[][] milestones = {
			{2495, 9716, 0}, // entrance chamber
			{2464, 9692, 0}, // past the rope swing
			{2419, 9674, 0}, // internal well, top
			{2343, 9622, 0}, // Well 4004: the level transition
			{2010, 4712, 1}, // the deep band
			// NOT yet a milestone: Iban's temple. The walk frontier from the well landing sits
			// at (2014,4710,1) — the swamp path obstacles between it and the bridge network at
			// x2126+ still need a field walk before the temple joins this chain.
		};
		for (int[] m : milestones)
		{
			Pathfinder pathfinder = new Pathfinder(planning, OUTSIDE_ENTRANCE,
				Set.of(WorldPointUtil.packWorldPoint(m[0], m[1], m[2])));
			pathfinder.run();
			assertTrue("must reach " + m[0] + "," + m[1] + "," + m[2],
				pathfinder.getResult().isReached());
		}
	}

	@Test
	public void templeDoorsTeleportIntoTheInstancedTemple()
	{
		// The inner sanctum doors are type-10 OBJECTS (3333/3334), invisible to the doors.tsv
		// registry — and they TELEPORT into an instanced temple (field-observed: standing at
		// 2145,4647 lands at template 2014,4711). The visible interior west of the doors is
		// scenery; destination-remaps.tsv snaps targets there to the door step.
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		Pathfinder pathfinder = new Pathfinder(planning,
			WorldPointUtil.packWorldPoint(2152, 4647, 1),
			Set.of(WorldPointUtil.packWorldPoint(2014, 4711, 1)));
		pathfinder.run();
		assertTrue("the instanced temple's template band must be reachable through the doors",
			pathfinder.getResult().isReached());
	}
}

package gps.transport;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import gps.ShortestPathPlugin;
import gps.Util;
import gps.WorldPointUtil;
import gps.leagues.LeagueRegion;

/**
 * Unit tests for the per-transport seasonal-league region override
 * (column {@code Region override} in seasonal_transports.tsv). The
 * override replaces the chunk-classifier result for the destination
 * endpoint in
 * {@code PathfinderConfig.isTransportRegionAllowed(Transport)}.
 */
public class TransportRegionOverrideTest
{
	private Map<Integer, Set<Transport>> transports;

	@Before
	public void setUp()
	{
		transports = new HashMap<>();
	}

	private Transport firstTransport(int origin)
	{
		Set<Transport> set = transports.get(origin);
		Assert.assertNotNull("Expected transports for origin " + origin, set);
		Assert.assertFalse("Transport set for origin " + origin + " should not be empty", set.isEmpty());
		return set.iterator().next();
	}

	// ── Builder parsing ───────────────────────────────────────────────

	@Test
	public void testBuilderAcceptsValidEnum()
	{
		Transport t = new Transport.TransportBuilder()
			.origin(WorldPointUtil.packWorldPoint(3200, 3200, 0))
			.destination(WorldPointUtil.packWorldPoint(3300, 3300, 0))
			.type(TransportType.TRANSPORT)
			.regionOverride("ASGARNIA")
			.build();
		Assert.assertEquals(LeagueRegion.ASGARNIA, t.getRegionOverride());
	}

	@Test
	public void testBuilderAcceptsLowercaseAndWhitespace()
	{
		Transport t = new Transport.TransportBuilder()
			.origin(WorldPointUtil.packWorldPoint(3200, 3200, 0))
			.destination(WorldPointUtil.packWorldPoint(3300, 3300, 0))
			.type(TransportType.TRANSPORT)
			.regionOverride("  kandarin  ")
			.build();
		Assert.assertEquals(LeagueRegion.KANDARIN, t.getRegionOverride());
	}

	@Test
	public void testBuilderNullValueLeavesOverrideUnset()
	{
		Transport t = new Transport.TransportBuilder()
			.origin(WorldPointUtil.packWorldPoint(3200, 3200, 0))
			.destination(WorldPointUtil.packWorldPoint(3300, 3300, 0))
			.type(TransportType.TRANSPORT)
			.regionOverride((String) null)
			.build();
		Assert.assertNull(t.getRegionOverride());
	}

	@Test
	public void testBuilderEmptyValueLeavesOverrideUnset()
	{
		Transport t = new Transport.TransportBuilder()
			.origin(WorldPointUtil.packWorldPoint(3200, 3200, 0))
			.destination(WorldPointUtil.packWorldPoint(3300, 3300, 0))
			.type(TransportType.TRANSPORT)
			.regionOverride("")
			.build();
		Assert.assertNull(t.getRegionOverride());
	}

	@Test
	public void testBuilderInvalidValueLeavesOverrideUnset()
	{
		// Unknown enum name is logged and silently ignored so a single
		// malformed row does not break the whole TSV load.
		Transport t = new Transport.TransportBuilder()
			.origin(WorldPointUtil.packWorldPoint(3200, 3200, 0))
			.destination(WorldPointUtil.packWorldPoint(3300, 3300, 0))
			.type(TransportType.TRANSPORT)
			.regionOverride("NOT_A_REGION")
			.build();
		Assert.assertNull(t.getRegionOverride());
	}

	// ── TSV round-trip ────────────────────────────────────────────────

	@Test
	public void testTsvRoundTripPopulatesOverride()
	{
		String contents = "# Origin\tDestination\tDuration\tRegion override\n" +
			"3200 3200 0\t3300 3300 0\t5\tVARLAMORE\n";

		TransportLoader.addTransportsFromContents(transports, contents, TransportType.TRANSPORT, 0);

		int origin = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		Transport t = firstTransport(origin);
		Assert.assertEquals(LeagueRegion.VARLAMORE, t.getRegionOverride());
	}

	@Test
	public void testTsvRoundTripWithoutOverrideLeavesNull()
	{
		String contents = "# Origin\tDestination\tDuration\tRegion override\n" +
			"3200 3200 0\t3300 3300 0\t5\t\n";

		TransportLoader.addTransportsFromContents(transports, contents, TransportType.TRANSPORT, 0);

		int origin = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		Transport t = firstTransport(origin);
		Assert.assertNull(t.getRegionOverride());
	}

	@Test
	public void testTsvRoundTripWithoutColumnLeavesNull()
	{
		String contents = "# Origin\tDestination\tDuration\n" +
			"3200 3200 0\t3300 3300 0\t5\n";

		TransportLoader.addTransportsFromContents(transports, contents, TransportType.TRANSPORT, 0);

		int origin = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		Transport t = firstTransport(origin);
		Assert.assertNull(t.getRegionOverride());
	}

	// ── Real seasonal_transports.tsv resource ─────────────────────────

	/**
	 * Locks in the active set of per-row overrides shipped with the
	 * plugin. The bbox classifier in leagues_regions.tsv is the source
	 * of truth; any chunk that still disagrees with the wiki keeps an
	 * override here. Adjust the expected map when adding, removing, or
	 * relocating an override and document the reason in the TSV.
	 */
	@Test
	public void testSeasonalTransportsResourceCarriesDocumentedOverrides() throws IOException
	{
		Map<Integer, LeagueRegion> expected = new HashMap<>();
		// Banker's Briefcase: Aldarin — chunk cx=23 cy=53 is Kourend
		// (Land's End shoreline), wiki lists destination under Varlamore.
		expected.put(WorldPointUtil.packWorldPoint(1502, 3410, 0), LeagueRegion.VARLAMORE);
		// Map of Alacrity: Trollheim Wilderness climb — chunk cx=46
		// cy=57 is Wilderness, wiki lists destination under Asgarnia.
		expected.put(WorldPointUtil.packWorldPoint(2946, 3678, 0), LeagueRegion.ASGARNIA);
		// Fairy Mushroom: AIR (SE of Ardougne) — chunk cx=42 cy=50 is
		// Karamja (Brimhaven east), wiki lists destination under Kandarin.
		expected.put(WorldPointUtil.packWorldPoint(2700, 3247, 0), LeagueRegion.KANDARIN);
		// Map of Alacrity: Barbarian Outpost Basalt causeway — chunk
		// cx=39 cy=56 stays FREMENNIK because the Lighthouse dominates
		// the chunk; the Basalt causeway is listed under Kandarin on
		// the league wiki and so carries a per-row override.
		expected.put(WorldPointUtil.packWorldPoint(2522, 3595, 0), LeagueRegion.KANDARIN);
		// Map of Alacrity: Sinclair Mansion Log balance — chunk cx=42
		// cy=56 is FREMENNIK; the destination is listed under Kandarin
		// on the league wiki and so carries a per-row override.
		expected.put(WorldPointUtil.packWorldPoint(2722, 3592, 0), LeagueRegion.KANDARIN);
		// Fairy Mushroom: DLR (Poison Waste south of Isafdar) — chunk
		// cx=34 cy=48 is Tirannwn, wiki lists destination under Kandarin.
		expected.put(WorldPointUtil.packWorldPoint(2213, 3099, 0), LeagueRegion.KANDARIN);

		Map<Integer, LeagueRegion> seen = new HashMap<>();
		for (Set<Transport> set : loadSeasonalTransports().values())
		{
			for (Transport t : set)
			{
				if (t.getRegionOverride() != null)
				{
					seen.put(t.getDestination(), t.getRegionOverride());
				}
			}
		}

		Assert.assertEquals(
			"Active region overrides drifted from documented set — update both this test "
				+ "and the in-file comments when changing the override list.",
			expected, seen);
	}

	private Map<Integer, Set<Transport>> loadSeasonalTransports() throws IOException
	{
		Map<Integer, Set<Transport>> loaded = new HashMap<>();
		try (InputStream in = ShortestPathPlugin.class.getResourceAsStream(
			"/transports/seasonal_transports.tsv"))
		{
			String contents = new String(
				Util.readAllBytes(Objects.requireNonNull(in)),
				StandardCharsets.UTF_8);
			TransportLoader.addTransportsFromContents(
				loaded, contents, TransportType.SEASONAL_TRANSPORTS, 0);
		}
		return loaded;
	}
}

package gps.transport;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;
import gps.ShortestPathConfig;
import gps.TeleportationItem;
import gps.WorldPointUtil;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import gps.transport.parser.VarRequirement;
import gps.transport.requirement.ItemRequirement;

/**
 * Balloon flights are destination-keyed (wiki: the log type and Firemaking level belong to the
 * DESTINATION, and each route needs its first-flight unlock varbit): the permutation pair-combiner
 * merges the destination-role row's requirements into every generated edge, so a flight from any
 * station to Varrock must require 40 Firemaking, a willow log, and the Varrock unlock (2872=1) —
 * verified against live varbit values (a player with 2872=1 can fly there; 2869=0 cannot fly to
 * Castle Wars). The log can be paid from the inventory or from the balloon storage crates
 * (chat-parsed counts; see {@link gps.BalloonLogStorage}).
 */
public class BalloonRouteTest
{
	private static final int WILLOW_LOGS = 1519;
	private static final int VARROCK_LANDING = WorldPointUtil.packWorldPoint(3299, 3482, 0);
	private static final int ENTRANA_LANDING = WorldPointUtil.packWorldPoint(2808, 3354, 0);

	@Test
	public void flightsCarryTheDestinationsRequirements()
	{
		HashMap<Integer, Set<Transport>> all = TransportLoader.loadAllFromResources();
		// A Castle Wars basket tile; the edge to Varrock's landing (3299,3482).
		Transport flight = null;
		for (Set<Transport> transports : all.values())
		{
			for (Transport transport : transports)
			{
				if (TransportType.HOT_AIR_BALLOON.equals(transport.getType())
					&& transport.getDestination() == VARROCK_LANDING)
				{
					flight = transport;
					break;
				}
			}
			if (flight != null)
			{
				break;
			}
		}
		assertNotNull("a balloon flight to Varrock must exist", flight);

		// Firemaking 40 (destination-keyed).
		boolean firemaking40 = false;
		int[] skills = flight.getSkillLevels();
		// Skill array indexing follows Skill.ordinal(); scan for a 40 requirement.
		for (int level : skills)
		{
			if (level == 40)
			{
				firemaking40 = true;
				break;
			}
		}
		assertTrue("the Varrock flight must require level 40 (Firemaking)", firemaking40);

		// One willow log.
		boolean willow = false;
		if (flight.getItemRequirements() != null)
		{
			for (ItemRequirement req : flight.getItemRequirements().getRequirements())
			{
				if (req.getItemIds() != null)
				{
					for (int id : req.getItemIds())
					{
						if (id == WILLOW_LOGS)
						{
							willow = true;
							break;
						}
					}
				}
			}
		}
		assertTrue("the Varrock flight must require a willow log", willow);

		// The Varrock route unlock varbit (2872=1), verified against live player values.
		boolean unlockVarbit = false;
		for (VarRequirement var : flight.getVarbits())
		{
			if (var.getId() == 2872)
			{
				unlockVarbit = true;
				break;
			}
		}
		assertTrue("the Varrock flight must be gated on its route unlock varbit (2872)", unlockVarbit);

		// And the quest gate from the origin-role row survives the merge.
		Map<Integer, Integer> questState = new HashMap<>();
		questState.put(2867, 2);
		questState.put(2872, 1);
		boolean allPass = true;
		for (VarRequirement var : flight.getVarbits())
		{
			if (!var.check(questState))
			{
				allPass = false;
				break;
			}
		}
		assertTrue("an unlocked player (2867=2, 2872=1) must pass every varbit gate", allPass);
	}

	/**
	 * The possession check must BIND in owned modes: a player whose inventory holds only a willow
	 * log can fly to Varrock (its log) but not to Entrana (needs a normal log). Uses a
	 * possession-checked config (not a planning copy) with the balloon type enabled and varbit
	 * checks bypassed, so the log requirement is the only difference between the two flights.
	 */
	@Test
	public void logPossessionGatesFlightsInOwnedModes()
	{
		Client client = loggedInClient();
		ItemContainer inventory = mock(ItemContainer.class);
		doReturn(new Item[]{new Item(WILLOW_LOGS, 1)}).when(inventory).getItems();
		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);

		boolean[] usable = flightUsability(client, balloonConfig());
		assertTrue("holding a willow log, the Varrock flight must be usable", usable[0]);
		assertFalse("without a normal log, the Entrana flight must not be usable", usable[1]);
	}

	/**
	 * In smart mode the balloon log storage pays for flights without carrying logs: an empty
	 * inventory plus a chat-parsed stored willow count makes the Varrock flight usable, while
	 * Entrana (normal logs; that type's storage is empty) stays gated.
	 */
	@Test
	public void storedLogsCoverFlightsWithoutCarrying()
	{
		ShortestPathConfig config = balloonConfig();
		when(config.balloonSmartMode()).thenReturn(true);
		when(config.balloonStoredWillowLogs()).thenReturn(5);

		boolean[] usable = flightUsability(loggedInClient(), config);
		assertTrue("with willow logs in storage, the Varrock flight must be usable", usable[0]);
		assertFalse("with no normal log stored or carried, the Entrana flight must not be usable", usable[1]);
	}

	/** With smart mode off the storage is not tracked, so stored counts must not pay for flights. */
	@Test
	public void smartModeOffIgnoresTheStoredCounts()
	{
		ShortestPathConfig config = balloonConfig();
		when(config.balloonStoredWillowLogs()).thenReturn(5);

		boolean[] usable = flightUsability(loggedInClient(), config);
		assertFalse("without smart mode, stored counts must not make the Varrock flight usable", usable[0]);
	}

	private static ShortestPathConfig balloonConfig()
	{
		ShortestPathConfig config = mock(ShortestPathConfig.class);
		when(config.calculationCutoff()).thenReturn(30);
		when(config.useHotAirBalloons()).thenReturn(true);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.NONE);
		return config;
	}

	private static Client loggedInClient()
	{
		Client client = mock(Client.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		return client;
	}

	/** Whether the Varrock ([0]) and Entrana ([1]) flights are usable under the given mocks. */
	private static boolean[] flightUsability(Client client, ShortestPathConfig config)
	{
		PathfinderConfig cfg = new TestPathfinderConfig(client, config);
		cfg.refresh();

		boolean varrock = false;
		boolean entrana = false;
		for (int origin : cfg.getTransportsPacked(false).keys())
		{
			for (Transport transport : cfg.getTransportsPacked(false).get(origin))
			{
				if (!TransportType.HOT_AIR_BALLOON.equals(transport.getType()))
				{
					continue;
				}
				varrock |= transport.getDestination() == VARROCK_LANDING;
				entrana |= transport.getDestination() == ENTRANA_LANDING;
			}
		}
		return new boolean[]{varrock, entrana};
	}
}

