package gps.transport;

import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import gps.transport.parser.VarCheckType;
import gps.transport.parser.VarRequirement;

public class TransportVarbitTest
{

	@Test
	public void testEqual()
	{
		Map<Integer, Integer> values = new HashMap<>();
		values.put(1, 5);
		VarRequirement v = VarRequirement.varbit(1, 5, VarCheckType.EQUAL);
		assertTrue(v.check(values));
		values.put(1, 4);
		assertFalse(v.check(values));
	}

	@Test
	public void testGreater()
	{
		Map<Integer, Integer> values = new HashMap<>();
		values.put(2, 10);
		VarRequirement v = VarRequirement.varbit(2, 5, VarCheckType.GREATER);
		assertTrue(v.check(values));
		values.put(2, 5);
		assertFalse(v.check(values));
	}

	@Test
	public void testSmaller()
	{
		Map<Integer, Integer> values = new HashMap<>();
		values.put(3, 3);
		VarRequirement v = VarRequirement.varbit(3, 5, VarCheckType.SMALLER);
		assertTrue(v.check(values));
		values.put(3, 5);
		assertFalse(v.check(values));
	}

	@Test
	public void testBitSet()
	{
		Map<Integer, Integer> values = new HashMap<>();
		values.put(4, 0b1010);
		VarRequirement v = VarRequirement.varbit(4, 0b0010, VarCheckType.BIT_SET);
		assertTrue(v.check(values));
		v = VarRequirement.varbit(4, 0b0100, VarCheckType.BIT_SET);
		assertFalse(v.check(values));
	}

	@Test
	public void testCooldownMinutes()
	{
		Map<Integer, Integer> values = new HashMap<>();
		long nowMinutes = System.currentTimeMillis() / 60000;
		values.put(5, (int) (nowMinutes - 10)); // stored timestamp 10 minutes ago

		VarRequirement v = VarRequirement.varbit(5, 5, VarCheckType.COOLDOWN_MINUTES);
		assertTrue(v.check(values)); // 10 > 5

		values.put(5, (int) (nowMinutes - 3)); // 3 minutes ago
		assertFalse(v.check(values)); // 3 > 5 is false
	}
}

package gps.transport;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import gps.TeleportMethod;
import gps.WorldPointUtil;

/**
 * Every method-type transport must carry display info: the panel's method rows and the direction
 * steps label methods by it, and the fallback is a bare coordinate pair ("Portals (2440, 3089)") —
 * meaningless to a player. Permutation networks inherit the destination row's info, so this
 * effectively requires every direct row and every destination-role row to be named.
 */
public class MethodDisplayInfoTest
{
	@Test
	public void everyMethodTransportIsNamed()
	{
		List<String> unnamed = new ArrayList<>();
		for (Set<Transport> transports : TransportLoader.loadAllFromResources().values())
		{
			for (Transport transport : transports)
			{
				if (!TeleportMethod.isMethodType(transport.getType()))
				{
					continue;
				}
				String info = transport.getDisplayInfo();
				if (info == null || info.isEmpty())
				{
					int d = transport.getDestination();
					unnamed.add(transport.getType() + " -> (" + WorldPointUtil.unpackWorldX(d)
						+ ", " + WorldPointUtil.unpackWorldY(d) + ", " + WorldPointUtil.unpackWorldPlane(d) + ")");
				}
			}
		}
		assertTrue("method transports without display info (would label as coordinates): " + unnamed,
			unnamed.isEmpty());
	}

	/**
	 * Every network RIDE must cost at least a tick: a missing Duration cell prices the ride at
	 * zero, and the search then uses it as a free shortcut (the Keldagrim train rode to White Wolf
	 * Mountain and back to cross 18 tiles — user capture 20260713-233919).
	 */
	@Test
	public void everyNetworkRideHasADuration()
	{
		Set<TransportType> rides = java.util.EnumSet.of(
			TransportType.BOAT, TransportType.CANOE, TransportType.CHARTER_SHIP, TransportType.SHIP,
			TransportType.GNOME_GLIDER, TransportType.HOT_AIR_BALLOON, TransportType.MAGIC_CARPET,
			TransportType.MAGIC_MUSHTREE, TransportType.MINECART, TransportType.MOUNTAIN_GUIDE,
			TransportType.QUETZAL, TransportType.SPIRIT_TREE, TransportType.WILDERNESS_OBELISK);
		List<String> free = new ArrayList<>();
		for (Set<Transport> transports : TransportLoader.loadAllFromResources().values())
		{
			for (Transport transport : transports)
			{
				if (rides.contains(transport.getType()) && transport.getDuration() < 1)
				{
					free.add(transport.getType() + " -> " + transport.getDisplayInfo());
				}
			}
		}
		assertTrue("rides with no duration (searched as free shortcuts): " + free, free.isEmpty());
	}
}

package gps.transport;

import gps.WorldPointUtil;
import java.util.HashMap;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Xeric's Honour (Mount Quidamortem) requires using an Ancient tablet on the talisman once —
 * tracked by varbit 4916 (gameval ZEAH_TELEPORT_UNLOCKED; upstream issue #380). Both Honour
 * rows (the carried talisman and the POH teleport box) must carry that gate, so accounts that
 * never used the tablet aren't offered a locked teleport.
 */
public class XericHonourGateTest
{
	@Test
	public void bothHonourRowsAreGatedOnVarbit4916()
	{
		int honour = WorldPointUtil.packWorldPoint(1254, 3560, 0);
		HashMap<Integer, Set<Transport>> all = TransportLoader.loadAllFromResources();
		int checked = 0;
		for (Set<Transport> transports : all.values())
		{
			for (Transport transport : transports)
			{
				if (transport.getDestination() != honour)
				{
					continue;
				}
				String info = String.valueOf(transport.getDisplayInfo());
				if (!info.contains("Honour"))
				{
					continue;
				}
				checked++;
				assertFalse(info + " must carry a varbit requirement",
					transport.getVarRequirements().isEmpty());
				assertTrue(info + " must gate on varbit 4916",
					transport.getVarRequirements().stream().anyMatch(r -> r.toString().contains("4916")));
			}
		}
		assertTrue("expected both Honour rows (talisman + POH box), found " + checked, checked >= 2);
	}
}

