	@Test
	public void testRadiusThresholdFiltering()
	{
		String contents = "# Origin\tDestination\tDisplay info\n" +
			"3100 3100 0\t\tLocation1\n" +
			"3200 3200 0\t\tLocation2\n" +
			"\t3102 3102 0\tLocation1\n" + // Distance 2.8 from first origin
			"\t3105 3105 0\tLocation1\n" + // Distance 7.1 from first origin
			"\t3400 3400 0\tLocation2\n";

		// Test with radius threshold of 5
		TransportLoader.addTransportsFromContents(transports, contents, TransportType.SPIRIT_TREE, 5);

		int origin1 = WorldPointUtil.packWorldPoint(3100, 3100, 0);
		int origin2 = WorldPointUtil.packWorldPoint(3200, 3200, 0);

		Assert.assertTrue("Should contain first origin", transports.containsKey(origin1));
		Assert.assertTrue("Should contain second origin", transports.containsKey(origin2));

		Set<Transport> transports1 = transports.get(origin1);
		Set<Transport> transports2 = transports.get(origin2);

		// Exact expectations given radius=5 and Chebyshev metric with strict '>'
		// Distance to 3102 is 2 (filtered), to 3105 is 5 (filtered), to 3400 is 300
		// (kept)
		Assert.assertEquals("Origin 1 should have one transport (3400)", 1, transports1.size());
		Assert.assertEquals("Origin 2 should have three transports (3102,3105,3400)", 3, transports2.size());

		int closeDestination = WorldPointUtil.packWorldPoint(3102, 3102, 0);
		int midDestination = WorldPointUtil.packWorldPoint(3105, 3105, 0);
		int farDestination = WorldPointUtil.packWorldPoint(3400, 3400, 0);

		boolean o1hasClose = false, o1hasMid = false, o1hasFar = false;
		for (Transport t : transports1)
		{
			if (t.getDestination() == closeDestination)
			{
				o1hasClose = true;
			}
			if (t.getDestination() == midDestination)
			{
				o1hasMid = true;
			}
			if (t.getDestination() == farDestination)
			{
				o1hasFar = true;
			}
		}
		Assert.assertFalse("Origin1 should not include very close destination", o1hasClose);
		Assert.assertFalse("Origin1 should not include mid destination at equal threshold", o1hasMid);
		Assert.assertTrue("Origin1 should include far destination", o1hasFar);

		boolean o2hasClose = false, o2hasMid = false, o2hasFar = false;
		for (Transport t : transports2)
		{
			if (t.getDestination() == closeDestination)
			{
				o2hasClose = true;
			}
			if (t.getDestination() == midDestination)
			{
				o2hasMid = true;
			}
			if (t.getDestination() == farDestination)
			{
				o2hasFar = true;
			}
		}
		Assert.assertTrue("Origin2 should include close destination (not close to origin2)", o2hasClose);
		Assert.assertTrue("Origin2 should include mid destination", o2hasMid);
		Assert.assertTrue("Origin2 should include far destination", o2hasFar);
	}

	@Test
	public void testZeroRadiusThreshold()
	{
		String contents = "# Origin\tDestination\tDisplay info\n" +
			"3100 3100 0\t\tLocation1\n" +
			"3200 3200 0\t\tLocation2\n" +
			"\t3101 3101 0\tLocation1\n" + // Very close
			"\t3400 3400 0\tLocation2\n";

		// Test with radius threshold of 0 (no filtering)
		TransportLoader.addTransportsFromContents(transports, contents, TransportType.FAIRY_RING, 0);

		int origin1 = WorldPointUtil.packWorldPoint(3100, 3100, 0);
		int origin2 = WorldPointUtil.packWorldPoint(3200, 3200, 0);

		Set<Transport> transports1 = transports.get(origin1);
		Set<Transport> transports2 = transports.get(origin2);

		// With radius 0, only exact same coordinates should be filtered out
		// All different coordinates should be included
		Assert.assertEquals("Origin 1 should have 2 transports", 2, transports1.size());
		Assert.assertEquals("Origin 2 should have 2 transports", 2, transports2.size());

		int nearDest = WorldPointUtil.packWorldPoint(3101, 3101, 0);
		int farDest = WorldPointUtil.packWorldPoint(3400, 3400, 0);
		boolean o1near = false, o1far = false, o2near = false, o2far = false;
		for (Transport t : transports1)
		{
			if (t.getDestination() == nearDest)
			{
				o1near = true;
			}
			if (t.getDestination() == farDest)
			{
				o1far = true;
			}
		}
		for (Transport t : transports2)
		{
			if (t.getDestination() == nearDest)
			{
				o2near = true;
			}
			if (t.getDestination() == farDest)
			{
				o2far = true;
			}
		}
		Assert.assertTrue("Origin1 should include near destination", o1near);
		Assert.assertTrue("Origin1 should include far destination", o1far);
		Assert.assertTrue("Origin2 should include near destination", o2near);
		Assert.assertTrue("Origin2 should include far destination", o2far);
	}

	@Test
	public void testExactSameCoordinatesFiltered()
	{
		String contents = "# Origin\tDestination\tDisplay info\n" +
			"3100 3100 0\t\tLocation1\n" +
			"\t3100 3100 0\tLocation1\n"; // Exact same coordinates

		TransportLoader.addTransportsFromContents(transports, contents, TransportType.FAIRY_RING, 0);

		// Should not create transport from location to itself
		Assert.assertTrue("Should not create transport to same location", transports.isEmpty());
	}

	@Test
	public void testLargeRadiusThreshold()
	{
		String contents = "# Origin\tDestination\tDisplay info\n" +
			"3100 3100 0\t\tLocation1\n" +
			"3200 3200 0\t\tLocation2\n" +
			"\t3150 3150 0\tLocation1\n" + // Distance ~70
			"\t3400 3400 0\tLocation2\n"; // Distance much larger

		// Test with large radius threshold
		TransportLoader.addTransportsFromContents(transports, contents, TransportType.SPIRIT_TREE, 100);

		int origin1 = WorldPointUtil.packWorldPoint(3100, 3100, 0);
		int origin2 = WorldPointUtil.packWorldPoint(3200, 3200, 0);

		Set<Transport> transports1 = transports.get(origin1);
		Set<Transport> transports2 = transports.get(origin2);

		// With large radius, only very far destinations should remain
		Assert.assertEquals("Origin 1 should have 1 transport (close one filtered)", 1, transports1.size());
		Assert.assertEquals("Origin 2 should have 1 transport (close one filtered)", 1, transports2.size());

		// Verify the remaining transport goes to the far destination
		Transport transport1 = getFirstTransport(transports1);
		int farDestination = WorldPointUtil.packWorldPoint(3400, 3400, 0);
		Assert.assertEquals("Should transport to far destination", farDestination, transport1.getDestination());
	}

	@Test
	public void testPermutationOnlyRowsAreIgnored()
	{
		String contents = "# Origin\tDestination\tDisplay info\n" +
			"\t\tOnlyLabel\n"; // both origin and destination missing -> permutation-only

		TransportLoader.addTransportsFromContents(transports, contents, TransportType.FAIRY_RING, 0);
		Assert.assertTrue("No transports should be created for permutation-only row", transports.isEmpty());
	}
}

package gps.transport;

import gps.transport.parser.TransportRecord;
import gps.transport.parser.TsvParser;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The optional Note column: a free-text advisory shown on the route step ("fire arrow needed",
 * "can fail") that must never gate the transport — it carries no requirement semantics, so a
 * noted transport stays exactly as routable as an un-noted one.
 */
public class TransportNoteTest
{
	private static final String HEADER =
		"# Origin\tDestination\tmenuOption menuTarget objectID\tSkills\tItems\tQuests\tVarbits\tVarPlayers\tDuration\tDisplay info\tNote\n";

	@Test
	public void noteColumnIsParsedAndExposed()
	{
		List<TransportRecord> records = new TsvParser().parse(HEADER
			+ "2446 3316 0\t2495 9716 0\tEnter Cave entrance 3213\t\t\t\t\t\t3\t\tfire arrow needed for the bridge ahead\n");
		Transport transport = new Transport(records.get(0), TransportType.TRANSPORT);
		assertEquals("fire arrow needed for the bridge ahead", transport.getNote());
	}

	@Test
	public void missingOrEmptyNoteIsNull()
	{
		// Short row (file without the column) and empty trailing column both mean "no note".
		List<TransportRecord> records = new TsvParser().parse(HEADER
			+ "2446 3316 0\t2495 9716 0\tEnter Cave entrance 3213\t\t\t\t\t\t3\t\n"
			+ "2446 3317 0\t2495 9717 0\tEnter Cave entrance 3213\t\t\t\t\t\t3\t\t\n");
		assertNull(new Transport(records.get(0), TransportType.TRANSPORT).getNote());
		assertNull(new Transport(records.get(1), TransportType.TRANSPORT).getNote());
	}

	@Test
	public void notedTransportCarriesNoRequirements()
	{
		List<TransportRecord> records = new TsvParser().parse(HEADER
			+ "2446 3316 0\t2495 9716 0\tCross Bridge 3254\t\t\t\t\t\t3\t\tbring a fire arrow\n");
		Transport transport = new Transport(records.get(0), TransportType.TRANSPORT);
		// Advisory only: no quests, no items, no skill levels appear because of a note.
		assertTrue(transport.getQuests().isEmpty());
		assertNull(transport.getItemRequirements());
		for (int level : transport.getSkillLevels())
		{
			assertEquals(0, level);
		}
	}
}

package gps;

import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Covers the auto-compute decision ({@link ShortestPathPlugin#shouldAutoCompute}): alternatives are
 * (re)generated when the target changes or when the last generation was allowed fewer routes than
 * wanted now (its budget grew meanwhile). The route budget itself never depends on whether the
 * side panel is shown ({@link ShortestPathPlugin#routeLimitFor}).
 */
public class AutoComputeDecisionTest
{
	private static final Set<Integer> TARGETS = Set.of(WorldPointUtil.packWorldPoint(3200, 3200, 0));
	private static final Set<Integer> OTHER_TARGETS = Set.of(WorldPointUtil.packWorldPoint(3300, 3300, 0));
	private static final int FULL = 5;
	private static final int PRIMARY_ONLY = 1;

	@Test
	public void routeBudgetDoesNotDependOnThePanel()
	{
		// The overlay's route must be the same with the panel open or hidden: both states run the
		// configured budget, never a primary-only search (the "different route once the panel
		// opens" experience).
		assertEquals(ShortestPathPlugin.routeLimitFor(true, 10), ShortestPathPlugin.routeLimitFor(false, 10));
		assertEquals(10, ShortestPathPlugin.routeLimitFor(false, 10));
		assertEquals(1, ShortestPathPlugin.routeLimitFor(false, 0));
		assertEquals(25, ShortestPathPlugin.routeLimitFor(true, 99));
	}

	@Test
	public void noTargetsNeverComputes()
	{
		assertFalse("No destination -> nothing to compute",
			ShortestPathPlugin.shouldAutoCompute(Set.of(), Set.of(), 0, FULL));
	}

	@Test
	public void newTargetComputes()
	{
		assertTrue("A destination the last generation didn't cover must compute",
			ShortestPathPlugin.shouldAutoCompute(TARGETS, OTHER_TARGETS, FULL, FULL));
		assertTrue("The first destination of the session must compute",
			ShortestPathPlugin.shouldAutoCompute(TARGETS, Set.of(), 0, PRIMARY_ONLY));
	}

	@Test
	public void sameTargetAlreadyGeneratedSkips()
	{
		assertFalse("Same destination, already generated at the wanted limit -> skip",
			ShortestPathPlugin.shouldAutoCompute(TARGETS, TARGETS, FULL, FULL));
		assertFalse("Panel hidden after a primary-only run for the same destination -> skip",
			ShortestPathPlugin.shouldAutoCompute(TARGETS, TARGETS, PRIMARY_ONLY, PRIMARY_ONLY));
	}

	@Test
	public void openingThePanelCatchesUpAPrimaryOnlyGeneration()
	{
		assertTrue("Panel opened after a hidden primary-only run -> full generation",
			ShortestPathPlugin.shouldAutoCompute(TARGETS, TARGETS, PRIMARY_ONLY, FULL));
	}

	@Test
	public void closingThePanelDoesNotDiscardAFullGeneration()
	{
		assertFalse("Panel hidden after a full generation -> keep it, no primary-only redo",
			ShortestPathPlugin.shouldAutoCompute(TARGETS, TARGETS, FULL, PRIMARY_ONLY));
	}

	@Test
	public void showMoreRoutesIsNotUndoneByTheAutoCompute()
	{
		assertFalse("A generation grown past the default (Show more) must not be regenerated smaller",
			ShortestPathPlugin.shouldAutoCompute(TARGETS, TARGETS, FULL + 10, FULL));
	}
}

package gps;

import gps.pathfinder.CollisionMap;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import gps.transport.Transport;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import org.junit.Assume;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Triage for the unreachable-destination backlog (enable with -DsnapReport=true).
 *
 * Splits the failures into the two populations that need completely different fixes:
 *   SNAPPABLE — a reachable tile sits within a few tiles, so the pin is merely on the wrong
 *   tile (amenity dumps pin the OBJECT, not the tile you stand on). Fixable programmatically
 *   by rewriting the coordinate.
 *   SEALED — nothing reachable anywhere near, so the area genuinely has no mapped way in
 *   (missing staircase, door or cave entrance). Needs data, not a coordinate nudge.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class DestinationSnapReportTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int INSTANCE_MIN_Y = 4160;
	private static final int INSTANCE_MAX_Y = 8000;
	private static final int MAX_SNAP = 12;

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Test
	public void report()
	{
		Assume.assumeTrue(Boolean.getBoolean("snapReport"));
		when(config.calculationCutoff()).thenReturn(120);
		when(config.useTeleportationItems()).thenReturn(gps.TeleportationItem.ALL);
		when(config.useSailing()).thenReturn(true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		TestPathfinderConfig testConfig = new TestPathfinderConfig(client, config);
		// Universal bank: reachable means "a player CAN get there" — any obtainable item is
		// assumed owned (dashboard's BANK-preset pattern), else item-gated teleports like the
		// Sailors' amulet would wrongly strand their destinations (Port Roberts).
		net.runelite.api.ItemContainer universalBank = mock(net.runelite.api.ItemContainer.class);
		net.runelite.api.Item[] everyItem = new net.runelite.api.Item[40000];
		for (int i = 0; i < everyItem.length; i++)
		{
			everyItem[i] = new net.runelite.api.Item(i, 1000);
		}
		when(universalBank.getItems()).thenReturn(everyItem);
		testConfig.bank = universalBank;
		PathfinderConfig planning = testConfig.copyForPlanning();
		planning.refresh();
		CollisionMap map = planning.getMap();
		PrimitiveIntHashMap<Transport[]> transports = planning.getTransportsPacked(true);

		Set<Integer> reachable = new HashSet<>(1 << 20);
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		reachable.add(LUMBRIDGE);
		queue.add(LUMBRIDGE);
		// ORIGIN-LESS teleports (jewellery, tablets, spells) work ANYWHERE, so their landing
		// tiles are reachable outright. Keyed under UNDEFINED_ORIGIN rather than a tile, they
		// were invisible to a walk-the-graph flood — which made every teleport-only place,
		// Port Roberts included, look sealed.
		Transport[] anywhere = transports.get(Transport.UNDEFINED_ORIGIN);
		if (anywhere != null)
		{
			for (Transport transport : anywhere)
			{
				if (transport.getDestination() != WorldPointUtil.UNDEFINED
					&& reachable.add(transport.getDestination()))
				{
					queue.add(transport.getDestination());
				}
			}
		}
		while (!queue.isEmpty())
		{
			int at = queue.poll();
			int x = WorldPointUtil.unpackWorldX(at);
			int y = WorldPointUtil.unpackWorldY(at);
			int plane = WorldPointUtil.unpackWorldPlane(at);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					int next = WorldPointUtil.packWorldPoint(x + dx, y + dy, plane);
					if ((dx != 0 || dy != 0) && !reachable.contains(next) && map.canStep(at, next))
					{
						reachable.add(next);
						queue.add(next);
					}
				}
			}
			Transport[] from = transports.get(at);
			if (from != null)
			{
				for (Transport t : from)
				{
					if (t.getDestination() != WorldPointUtil.UNDEFINED && reachable.add(t.getDestination()))
					{
						queue.add(t.getDestination());
					}
				}
			}
		}

		int[] snapBuckets = new int[MAX_SNAP + 1];
		int sealed = 0;
		int total = 0;
		Map<String, Integer> sealedByArea = new TreeMap<>();
		Map<String, Integer> sealedByCategory = new TreeMap<>();
		for (Destinations.Entry entry : Destinations.resourceEntries())
		{
			int x = WorldPointUtil.unpackWorldX(entry.packedPosition);
			int y = WorldPointUtil.unpackWorldY(entry.packedPosition);
			int plane = WorldPointUtil.unpackWorldPlane(entry.packedPosition);
			if (y >= INSTANCE_MIN_Y && y <= INSTANCE_MAX_Y)
			{
				continue;
			}
			boolean ok = false;
			for (int target : Destinations.walkableTargets(map, entry.packedPosition))
			{
				if (reachable.contains(target))
				{
					ok = true;
					break;
				}
			}
			if (ok)
			{
				continue;
			}
			total++;
			int found = -1;
			for (int radius = 1; radius <= MAX_SNAP && found < 0; radius++)
			{
				for (int dx = -radius; dx <= radius && found < 0; dx++)
				{
					for (int dy = -radius; dy <= radius && found < 0; dy++)
					{
						if (Math.max(Math.abs(dx), Math.abs(dy)) != radius)
						{
							continue;
						}
						if (reachable.contains(WorldPointUtil.packWorldPoint(x + dx, y + dy, plane)))
						{
							found = radius;
						}
					}
				}
			}
			if (found > 0)
			{
				snapBuckets[found]++;
			}
			else
			{
				sealed++;
				sealedByArea.merge((x / 64 * 64) + "," + (y / 64 * 64) + " p" + plane, 1, Integer::sum);
				sealedByCategory.merge(entry.category, 1, Integer::sum);
			}
		}

		System.out.println("UNREACHABLE TOTAL: " + total);
		int running = 0;
		for (int r = 1; r <= MAX_SNAP; r++)
		{
			running += snapBuckets[r];
			System.out.println("  snappable within " + r + " tiles: " + snapBuckets[r]
				+ "   (cumulative " + running + ")");
		}
		System.out.println("SEALED (no reachable tile within " + MAX_SNAP + "): " + sealed);
		System.out.println("--- sealed by category ---");
		sealedByCategory.entrySet().stream()
			.sorted((a, b) -> b.getValue() - a.getValue()).limit(15)
			.forEach(e -> System.out.println("  " + e.getValue() + "  " + e.getKey()));
		System.out.println("--- worst sealed areas (64x64 blocks) ---");
		sealedByArea.entrySet().stream()
			.sorted((a, b) -> b.getValue() - a.getValue()).limit(20)
			.forEach(e -> System.out.println("  " + e.getValue() + "  @" + e.getKey()));
	}
}

package gps;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import static net.runelite.api.Constants.CHUNK_SIZE;
import static net.runelite.api.Perspective.LOCAL_COORD_BITS;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import org.mockito.Mockito;

/**
 * Unit tests for {@link WorldPointUtil}.
 */
public class WorldPointUtilTest
{

	private static final WorldArea WILDERNESS_ABOVE_GROUND = new WorldArea(2944, 3523, 448, 448, 0);

	@Test
	public void packAndUnpackRoundTrip()
	{
		WorldPoint p = new WorldPoint(1234, 5678, 2);
		int packed = WorldPointUtil.packWorldPoint(p);
		assertEquals(1234, WorldPointUtil.unpackWorldX(packed));
		assertEquals(5678, WorldPointUtil.unpackWorldY(packed));
		assertEquals(2, WorldPointUtil.unpackWorldPlane(packed));

		WorldPoint unpacked = WorldPointUtil.unpackWorldPoint(packed);
		assertEquals(p, unpacked);
	}

	@Test
	public void packMasksHighBits()
	{
		int x = 40000; // exceeds 15 bits
		int y = 50000; // exceeds 15 bits
		int plane = 7; // exceeds 2 bits
		int packed = WorldPointUtil.packWorldPoint(x, y, plane);
		assertEquals(x & 0x7FFF, WorldPointUtil.unpackWorldX(packed));
		assertEquals(y & 0x7FFF, WorldPointUtil.unpackWorldY(packed));
		assertEquals(plane & 0x3, WorldPointUtil.unpackWorldPlane(packed));
	}

	@Test
	public void dxdyOffsetsCorrectly()
	{
		int base = WorldPointUtil.packWorldPoint(3200, 3200, 1);
		int moved = WorldPointUtil.dxdy(base, 5, -7);
		assertEquals(3200 + 5, WorldPointUtil.unpackWorldX(moved));
		assertEquals(3200 - 7, WorldPointUtil.unpackWorldY(moved));
		assertEquals(1, WorldPointUtil.unpackWorldPlane(moved));
	}

	@Test
	public void distanceChebyshevAndManhattan()
	{
		int a = WorldPointUtil.packWorldPoint(10, 10, 0);
		int b = WorldPointUtil.packWorldPoint(15, 13, 0); // dx=5 dy=3
		assertEquals(5, WorldPointUtil.distanceBetween(a, b)); // Chebyshev
		assertEquals(5, WorldPointUtil.distanceBetween(a, b, WorldPointUtil.CHEBYSHEV_DISTANCE_METRIC)); // Chebyshev
		assertEquals(5, WorldPointUtil.distanceBetween2D(a, b)); // Chebyshev 2D
		assertEquals(5 + 3, WorldPointUtil.distanceBetween(a, b, WorldPointUtil.MANHATTAN_DISTANCE_METRIC)); // Manhattan
		assertEquals(5 * 5 + 3 * 3, WorldPointUtil.distanceBetween(a, b, WorldPointUtil.EUCLIDEAN_SQUARED_DISTANCE_METRIC)); // Euclidean
		// squared
		assertEquals(5 * 5 + 3 * 3, WorldPointUtil.distanceBetween(a, b, 99));
	}

	@Test
	public void distanceDifferentPlanesReturnsMax()
	{
		int a = WorldPointUtil.packWorldPoint(10, 10, 0);
		int b = WorldPointUtil.packWorldPoint(11, 11, 1);
		assertEquals(Integer.MAX_VALUE, WorldPointUtil.distanceBetween(a, b));
	}

	@Test
	public void distanceWorldPointOverloads()
	{
		WorldPoint a = new WorldPoint(100, 150, 0);
		WorldPoint b = new WorldPoint(103, 160, 0); // dx=3 dy=10
		assertEquals(10, WorldPointUtil.distanceBetween(a, b)); // Chebyshev
		assertEquals(10 + 3, WorldPointUtil.distanceBetween(a, b, WorldPointUtil.MANHATTAN_DISTANCE_METRIC)); // Manhattan
		assertEquals(10 * 10 + 3 * 3,
			WorldPointUtil.distanceBetween(a, b, WorldPointUtil.EUCLIDEAN_SQUARED_DISTANCE_METRIC)); // Euclidean squared
	}

	@Test
	public void distanceToAreaInsideAndOutside()
	{
		WorldArea area = new WorldArea(3000, 4000, 5, 4, 0); // x:[3000..3004], y:[4000..4003]
		int inside = WorldPointUtil.packWorldPoint(3002, 4001, 0);
		int leftOutside = WorldPointUtil.packWorldPoint(2995, 4002, 0);
		int diagOutside = WorldPointUtil.packWorldPoint(2990, 3990, 0);
		int otherPlane = WorldPointUtil.packWorldPoint(3002, 4001, 1);

		assertEquals(0, WorldPointUtil.distanceToArea(inside, area));
		assertEquals(0, WorldPointUtil.distanceToArea2D(inside, area));
		// leftOutside: dx = 3000-2995=5, dy=0 => Chebyshev 5
		assertEquals(5, WorldPointUtil.distanceToArea(leftOutside, area));
		assertEquals(5, WorldPointUtil.distanceToArea2D(leftOutside, area));
		// diagOutside: dx=3000-2990=10, dy=4000-3990=10 => Chebyshev 10
		assertEquals(10, WorldPointUtil.distanceToArea(diagOutside, area));
		assertEquals(10, WorldPointUtil.distanceToArea2D(diagOutside, area));
		// plane mismatch
		assertEquals(Integer.MAX_VALUE, WorldPointUtil.distanceToArea(otherPlane, area));
	}

	@Test
	public void toLocalPointWithinScene()
	{
		Client client = Mockito.mock(Client.class);
		WorldView worldView = Mockito.mock(WorldView.class);
		Mockito.when(client.getTopLevelWorldView()).thenReturn(worldView);
		Mockito.when(worldView.getPlane()).thenReturn(0);
		Mockito.when(worldView.getBaseX()).thenReturn(3200);
		Mockito.when(worldView.getBaseY()).thenReturn(3200);
		Mockito.when(worldView.getSizeX()).thenReturn(104); // typical scene size
		Mockito.when(worldView.getSizeY()).thenReturn(104);
		Mockito.when(worldView.getId()).thenReturn(0);

		int packed = WorldPointUtil.packWorldPoint(3210, 3220, 0);
		LocalPoint lp = WorldPointUtil.toLocalPoint(client, packed);
		assertNotNull(lp);
		int expectedLocalX = ((3210 - 3200) << LOCAL_COORD_BITS) + (1 << (LOCAL_COORD_BITS - 1));
		int expectedLocalY = ((3220 - 3200) << LOCAL_COORD_BITS) + (1 << (LOCAL_COORD_BITS - 1));
		assertEquals(expectedLocalX, lp.getX());
		assertEquals(expectedLocalY, lp.getY());
	}

	@Test
	public void toLocalPointOutOfSceneOrPlane()
	{
		Client client = Mockito.mock(Client.class);
		WorldView worldView = Mockito.mock(WorldView.class);
		Mockito.when(client.getTopLevelWorldView()).thenReturn(worldView);
		Mockito.when(worldView.getPlane()).thenReturn(0);
		Mockito.when(worldView.getBaseX()).thenReturn(3200);
		Mockito.when(worldView.getBaseY()).thenReturn(3200);
		Mockito.when(worldView.getSizeX()).thenReturn(104);
		Mockito.when(worldView.getSizeY()).thenReturn(104);
		Mockito.when(worldView.getId()).thenReturn(0);

		// Plane mismatch
		int packedWrongPlane = WorldPointUtil.packWorldPoint(3210, 3210, 1);
		assertNull(WorldPointUtil.toLocalPoint(client, packedWrongPlane));

		// Outside scene (x less than baseX)
		int packedOutside = WorldPointUtil.packWorldPoint(3199, 3210, 0);
		assertNull(WorldPointUtil.toLocalPoint(client, packedOutside));
	}

	@Test
	public void toLocalInstanceNonInstanceWorld()
	{
		Client client = Mockito.mock(Client.class);
		WorldView top = Mockito.mock(WorldView.class);
		Mockito.when(client.getTopLevelWorldView()).thenReturn(top);
		Mockito.when(top.isInstance()).thenReturn(false);
		int packed = WorldPointUtil.packWorldPoint(4000, 5000, 2);
		PrimitiveIntList list = WorldPointUtil.toLocalInstance(client, packed);
		assertEquals(1, list.size());
		assertEquals(packed, list.get(0));
	}

	@Test
	public void fromLocalInstanceNonInstanceWorld()
	{
