	@Override
	protected void startUp()
	{
		if (transportOriginTiles == null)
		{
			transportOriginTiles = new HashSet<>();
			transportDestTiles = new HashSet<>();
			HashMap<Integer, Set<Transport>> all = TransportLoader.loadAllFromResources();
			for (Map.Entry<Integer, Set<Transport>> entry : all.entrySet())
			{
				transportOriginTiles.add(entry.getKey());
				for (Transport transport : entry.getValue())
				{
					if (transport.getOrigin() != WorldPointUtil.UNDEFINED)
					{
						transportOriginTiles.add(transport.getOrigin());
					}
					if (transport.getDestination() != WorldPointUtil.UNDEFINED)
					{
						transportDestTiles.add(transport.getDestination());
					}
					String label = transport.getDisplayInfo() != null && !transport.getDisplayInfo().isEmpty()
						? transport.getDisplayInfo()
						: (transport.getObjectInfo() != null ? transport.getObjectInfo() : "(transport)");
					knownEntries.add(new KnownEntry(
						transport.getOrigin(), transport.getDestination(), label,
						transport.getDuration()));
				}
			}
			log.info("[audit] transport coverage: {} origin tiles, {} dest tiles",
				transportOriginTiles.size(), transportDestTiles.size());
		}
		if (doorTiles == null)
		{
			doorTiles = loadDoorTiles();
			log.info("[audit] door registry set: {} tiles", doorTiles.size());
		}
		if (auditFile == null)
		{
			auditFile = new java.io.File(
				new java.io.File(net.runelite.client.RuneLite.RUNELITE_DIR, "gps-debug"),
				"transport-audit.tsv");
			seedLoggedFromFile();
		}
		if (durationSamplesFile == null)
		{
			durationSamplesFile = new java.io.File(auditFile.getParentFile(), "duration-samples.tsv");
		}
		if (capturesFile == null)
		{
			capturesFile = new java.io.File(auditFile.getParentFile(), "transport-captures.tsv");
			seedCapturedFromFile();
		}
		if (ignoreFile == null)
		{
			ignoreFile = new java.io.File(auditFile.getParentFile(), "transport-ignore.tsv");
			seedIgnoredFromFile();
		}
		if (metaEdges.isEmpty())
		{
			metaEdges = MetaEdges.load();
			log.info("[audit] meta-tagged transport rows awaiting confirmation: {}", metaEdges.size());
		}
		if (oneWayFile == null)
		{
			oneWayFile = new java.io.File(auditFile.getParentFile(), "transport-oneway.tsv");
			try (java.util.Scanner scanner = oneWayFile.exists()
				? new java.util.Scanner(oneWayFile, "UTF-8") : null)
			{
				while (scanner != null && scanner.hasNextLine())
				{
					String line = scanner.nextLine().trim();
					if (!line.isEmpty() && !line.startsWith("#"))
					{
						noReverseKeys.add(line);
					}
				}
			}
			catch (Exception e)
			{
				log.warn("[audit] could not read {}", oneWayFile, e);
			}
			recomputeEdgePairs();
		}
		overlayManager.add(sceneOverlay);
		if (panel == null)
		{
			panel = new TransportAuditPanel(this);
			navButton = net.runelite.client.ui.NavigationButton.builder()
				.tooltip("GPS transport audit (dev)")
				.icon(navIcon())
				.priority(71)
				.panel(panel)
				.build();
		}
		clientToolbar.addNavigation(navButton);
		if (varbitPanel == null)
		{
			varbitPanel = new VarbitWatchPanel(varbitWatch, this::resolveVarbitComposition, this::dumpVarbitWatch);
			varbitNavButton = net.runelite.client.ui.NavigationButton.builder()
				.tooltip("GPS varbit watch (dev)")
				.icon(navIcon())
				.priority(72)
				.panel(varbitPanel)
				.build();
		}
		clientToolbar.addNavigation(varbitNavButton);
		// Plugin toggled on with a scene already loaded: sweep it once (spawn events only cover
		// objects loaded after this point).
		if (GameState.LOGGED_IN.equals(client.getGameState()))
		{
			clientThread.invokeLater(this::sweepScene);
		}
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(sceneOverlay);
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
		}
		if (varbitNavButton != null)
		{
			clientToolbar.removeNavigation(varbitNavButton);
		}
		findings.clear();
	}

	@Subscribe
	public void onVarbitChanged(net.runelite.api.events.VarbitChanged event)
	{
		if (varbitWatch.isPaused())
		{
			return;
		}
		int tick = client.getTickCount();
		long now = System.currentTimeMillis();
		int x = 0;
		int y = 0;
		int plane = 0;
		if (client.getLocalPlayer() != null)
		{
			net.runelite.api.coords.WorldPoint at = client.getLocalPlayer().getWorldLocation();
			x = at.getX();
			y = at.getY();
			plane = at.getPlane();
		}
		// A varp event carries varbitId -1; the varbits cut from that varp arrive as their own
		// events, so both the container and its bits get rows.
		if (event.getVarbitId() >= 0)
		{
			Integer old = lastVarbitValues.put(event.getVarbitId(), event.getValue());
			varbitWatch.record(true, event.getVarbitId(), old == null ? VarbitWatch.UNKNOWN : old,
				event.getValue(), tick, now, x, y, plane);
		}
		else if (event.getVarpId() >= 0)
		{
			int value = client.getVarpValue(event.getVarpId());
			Integer old = lastVarpValues.put(event.getVarpId(), value);
			varbitWatch.record(false, event.getVarpId(), old == null ? VarbitWatch.UNKNOWN : old,
				value, tick, now, x, y, plane);
		}
	}

	/** The selected varbit's varp and bit range, read on the client thread, handed back to the panel. */
	private void resolveVarbitComposition(VarbitWatchPanel.Detail detail)
	{
		if (!detail.varbit)
		{
			detail.composition = "varp " + detail.id + " (whole player variable)";
			varbitPanel.showComposition(detail);
			return;
		}
		clientThread.invokeLater(() ->
		{
			try
			{
				net.runelite.api.VarbitComposition composition = client.getVarbit(detail.id);
				detail.composition = composition == null ? "no composition in the cache"
					: "varp " + composition.getIndex() + " bits " + composition.getLeastSignificantBit()
					+ "-" + composition.getMostSignificantBit() + " · now " + client.getVarbitValue(detail.id);
			}
			catch (RuntimeException e)
			{
				detail.composition = "composition lookup failed: " + e.getMessage();
			}
			varbitPanel.showComposition(detail);
		});
	}

	/** Everything the watch holds, with histories, to gps-debug/varbit-watch-<stamp>.tsv. */
	private void dumpVarbitWatch()
	{
		try
		{
			java.io.File dir = new java.io.File(net.runelite.client.RuneLite.RUNELITE_DIR, "gps-debug");
			dir.mkdirs();
			String stamp = new java.text.SimpleDateFormat("yyyyMMdd-HHmmss").format(new java.util.Date());
			java.io.File out = new java.io.File(dir, "varbit-watch-" + stamp + ".tsv");
			try (java.io.FileWriter writer = new java.io.FileWriter(out))
			{
				writer.write(varbitWatch.dump(client.getTickCount()));
			}
			varbitPanel.setStatus("wrote " + out.getName());
		}
		catch (java.io.IOException e)
		{
			varbitPanel.setStatus("dump failed: " + e.getMessage());
		}
	}

