	/** EDT. Rebuilds only when the content signature changed, so scrolling isn't reset per tick. */
	void update(List<TransportAuditPlugin.Row> rows, String captureLine, Color captureColor,
		String builderOriginText, String builderDestText, String builderMenuText)
	{
		capture.setText(captureLine == null ? " " : captureLine);
		capture.setForeground(captureColor == null ? ColorScheme.LIGHT_GRAY_COLOR : captureColor);
		builderOrigin.setText("origin: " + (builderOriginText == null ? "\u2014 (shift right-click)" : builderOriginText));
		builderDest.setText("dest: " + (builderDestText == null ? "\u2014" : builderDestText));
		builderObject.setText("object: " + (builderMenuText == null ? "\u2014" : builderMenuText));

		long missing = rows.stream().filter(r -> r.state == TransportAuditPlugin.FindingState.MISSING
			|| r.state == TransportAuditPlugin.FindingState.ARMED).count();
		long doors = rows.stream().filter(r -> r.state == TransportAuditPlugin.FindingState.DOOR).count();
		long resolved = rows.stream().filter(r -> r.state == TransportAuditPlugin.FindingState.RESOLVED).count();
		long known = rows.stream().filter(r -> r.state == TransportAuditPlugin.FindingState.KNOWN).count();
		long captured = rows.size() - missing - doors - resolved - known;
		summary.setText(rows.isEmpty()
			? "Nothing recorded yet"
			: missing + " missing, " + doors + " door(s), " + captured + " captured, " + resolved + " resolved");

		currentRows = rows;
		String signature = computeSignature(rows);
		if (signature.equals(lastSignature))
		{
			return;
		}
		lastSignature = signature;
		rebuildList();
	}

	private String computeSignature(List<TransportAuditPlugin.Row> rows)
	{
		StringBuilder signature = new StringBuilder();
		for (TransportAuditPlugin.Row row : rows)
		{
			signature.append(row.id).append(':').append(row.packedTile).append(':')
				.append(row.state).append(':').append(row.live).append(':')
				.append(row.distance / 16).append(';');
		}
		return signature.append("sel=").append(selectedKey)
			.append(";f=").append(filterText).toString();
	}

	/** Search keystrokes re-render immediately and hand the text to the plugin's known-data trim. */
	private void applyFilter()
	{
		filterText = searchBar.getText().trim().toLowerCase(java.util.Locale.ROOT);
		plugin.listFilter = filterText;
		lastSignature = computeSignature(currentRows);
		rebuildList();
	}

	private boolean matchesFilter(TransportAuditPlugin.Row row)
	{
		if (filterText.isEmpty())
		{
			return true;
		}
		String haystack = (row.name + ' ' + row.action + ' ' + row.id + ' '
			+ gps.WorldPointUtil.unpackWorldX(row.packedTile) + ','
			+ gps.WorldPointUtil.unpackWorldY(row.packedTile) + ','
			+ gps.WorldPointUtil.unpackWorldPlane(row.packedTile) + ' '
			+ stateText(row.state)).toLowerCase(java.util.Locale.ROOT);
		return haystack.contains(filterText);
	}

	private static String groupOf(TransportAuditPlugin.Row row)
	{
		if (row.live)
		{
			return "In this scene";
		}
		return row.state == TransportAuditPlugin.FindingState.KNOWN
			? "Known data (curated)" : "Recorded elsewhere";
	}

	private void rebuildList()
	{
		list.removeAll();
		// Caps are PER GROUP so the backlog can't starve the known-data section (KNOWN sorts
		// last), and searching lifts them \u2014 a filtered list should show what it matched.
		boolean filtering = !filterText.isEmpty();
		int backlogShown = 0;
		int shown = 0;
		String currentGroup = null;
		boolean truncated = false;
		JPanel selectedPanel = null;
		for (TransportAuditPlugin.Row row : currentRows)
		{
			if (!matchesFilter(row))
			{
				continue;
			}
			String group = groupOf(row);
			if (!group.equals(currentGroup))
			{
				list.add(groupLabel(group));
				currentGroup = group;
				truncated = false;
			}
			if (truncated)
			{
				continue;
			}
			boolean backlog = !row.live
				&& row.state != TransportAuditPlugin.FindingState.KNOWN;
			if ((!filtering && backlog && ++backlogShown > MAX_BACKLOG_ROWS)
				|| (filtering && ++shown > MAX_FILTERED_ROWS))
			{
				JLabel more = groupLabel(filtering
					? "\u2026 narrow the search to see the rest"
					: "\u2026 more in transport-audit.tsv (see audit_diff.py)");
				more.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
				list.add(more);
				truncated = true;
				continue;
			}
			JPanel rowPanel = buildRow(row);
			if (keyOf(row) == selectedKey)
			{
				selectedPanel = rowPanel;
			}
			list.add(rowPanel);
		}
		if (currentGroup == null && filtering)
		{
			JLabel none = groupLabel("No matches");
			none.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			list.add(none);
		}
		list.revalidate();
		list.repaint();
		renderDetail();
		// Scroll only on selection changes — snapping the viewport on every content rebuild
		// would fight the user's own scrolling.
		if (selectedPanel != null && scrollSelectionIntoView)
		{
			scrollSelectionIntoView = false;
			final JPanel target = selectedPanel;
			javax.swing.SwingUtilities.invokeLater(() ->
				list.scrollRectToVisible(target.getBounds()));
		}
	}

	private static JLabel groupLabel(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(Color.WHITE);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setBorder(new EmptyBorder(6, 0, 3, 0));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private static long keyOf(TransportAuditPlugin.Row row)
	{
		return ((long) row.packedTile << 20) | row.id;
	}

	/**
	 * ONE compact line per entry: a state dot, the name, and the distance \u2014 details and
	 * actions live in the detail card below. Click selects, double-click routes, arrows navigate.
	 */
	private JPanel buildRow(TransportAuditPlugin.Row row)
	{
		final long key = keyOf(row);
		final boolean selected = key == selectedKey;
		JPanel panel = new JPanel(new BorderLayout(5, 0));
		panel.setBackground(selected ? SELECTED_BG : ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(new EmptyBorder(2, 6, 2, 6));
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));

		JLabel dot = new JLabel("\u25CF");
		dot.setForeground(stateColor(row.state));
		dot.setFont(FontManager.getRunescapeSmallFont());
		panel.add(dot, BorderLayout.WEST);

		JLabel name = new JLabel(row.name);
		name.setForeground(selected ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
		name.setFont(FontManager.getRunescapeSmallFont());
		panel.add(name, BorderLayout.CENTER);

		JLabel distance = new JLabel(row.distance == Integer.MAX_VALUE
			? "\u2191\u2193" : row.distance + "t");
		distance.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		distance.setFont(FontManager.getRunescapeSmallFont());
		panel.add(distance, BorderLayout.EAST);

		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, panel.getPreferredSize().height));
		panel.addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mousePressed(java.awt.event.MouseEvent e)
			{
				if (e.getClickCount() >= 2)
				{
					plugin.routeTo(row.packedTile);
					builderStatus.setText("Routing GPS to " + row.name);
					return;
				}
				selectRow(key);
			}
		});
		return panel;
	}

	/** Selects a row by key: highlight, detail card, and (for known rows) the world spotlight. */
	private void selectRow(long key)
	{
		selectedKey = key;
		scrollSelectionIntoView = true;
		TransportAuditPlugin.Row row = selectedRow();
		if (row != null && row.state == TransportAuditPlugin.FindingState.KNOWN)
		{
			plugin.spotlightKnownAt(row.packedTile);
		}
		// Immediate feedback: restyle now instead of waiting for the next tick snapshot.
		lastSignature = computeSignature(currentRows);
		rebuildList();
	}

	private TransportAuditPlugin.Row selectedRow()
	{
		for (TransportAuditPlugin.Row row : currentRows)
		{
			if (keyOf(row) == selectedKey)
			{
				return row;
			}
		}
		return null;
	}

	/** The detail card: everything about the selected row, plus its actions \u2014 rendered ONCE. */
	private void renderDetail()
	{
		detail.removeAll();
		TransportAuditPlugin.Row row = selectedRow();
		if (row == null)
		{
			detail.setVisible(false);
			detail.revalidate();
			detail.repaint();
			return;
		}
		detail.setVisible(true);
		Color color = stateColor(row.state);
		detail.setBorder(javax.swing.BorderFactory.createCompoundBorder(
			javax.swing.BorderFactory.createMatteBorder(0, 3, 0, 0, color),
			new EmptyBorder(4, 6, 6, 6)));

		JLabel title = new JLabel(htmlWrap(
			row.name + "  (" + row.action + (row.id > 0 ? " id=" + row.id : "") + ")"));
		title.setForeground(Color.WHITE);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		detail.add(title);

		JLabel state = new JLabel(stateText(row.state));
		state.setForeground(color);
		state.setFont(FontManager.getRunescapeSmallFont());
		state.setAlignmentX(Component.LEFT_ALIGNMENT);
		detail.add(state);

		JLabel where = new JLabel("@" + gps.WorldPointUtil.unpackWorldX(row.packedTile)
			+ "," + gps.WorldPointUtil.unpackWorldY(row.packedTile)
			+ "," + gps.WorldPointUtil.unpackWorldPlane(row.packedTile)
			+ (row.distance == Integer.MAX_VALUE ? " (another floor)" : " \u2014 " + row.distance + " tiles"));
		where.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		where.setFont(FontManager.getRunescapeSmallFont());
		where.setAlignmentX(Component.LEFT_ALIGNMENT);
		detail.add(where);

		// HTML label, not a JTextArea: a wrapped text area still reports its longest line as
		// preferred width (stretching the sidebar), and its preferred height is computed
		// pre-wrap (clipping). A width-constrained HTML body wraps AND sizes correctly.
		JLabel info = new JLabel(htmlWrap(row.dossier));
		info.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		info.setFont(FontManager.getRunescapeSmallFont());
		info.setAlignmentX(Component.LEFT_ALIGNMENT);
		info.setBorder(new EmptyBorder(3, 0, 3, 0));
		detail.add(info);

		JPanel actions = new JPanel(new java.awt.GridLayout(0, 3, 4, 3));
		actions.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		actions.setAlignmentX(Component.LEFT_ALIGNMENT);
		actions.add(rowButton("Go", "Route GPS to this tile (double-click a row does this too)",
			() -> plugin.routeTo(row.packedTile)));
		actions.add(rowButton("Copy", "Copy the dossier to the clipboard",
			() -> copyText(row.dossier)));
		if (row.state != TransportAuditPlugin.FindingState.KNOWN)
		{
			actions.add(rowButton("Builder", "Load into the transport builder",
				() -> builderStatus.setText(plugin.loadIntoBuilder(row))));
			actions.add(rowButton("Ignore", "Not a transport \u2014 never flag this object again",
				() -> plugin.ignoreEntry(row.id, row.packedTile, row.name)));
		}
		if (row.state == TransportAuditPlugin.FindingState.CAPTURED_ONE_WAY
			|| row.state == TransportAuditPlugin.FindingState.DATA_ONE_WAY)
		{
			actions.add(rowButton("1-way", "No reverse exists in-game \u2014 mark complete",
				() -> builderStatus.setText(plugin.markNoReverse(row.id, row.packedTile))));
		}
		actions.setMaximumSize(new Dimension(Integer.MAX_VALUE, actions.getPreferredSize().height));
		detail.add(actions);
		detail.revalidate();
		detail.repaint();
	}

	/**
	 * Wraps text for a JLabel at a width that fits the sidebar: escaped, newlines kept, and
	 * the body width pinned so long dossier lines fold instead of widening the panel.
	 */
	static String htmlWrap(String text)
	{
		String escaped = text
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;")
			.replace("\n", "<br>");
		return "<html><body style='width:165px'>" + escaped + "</body></html>";
	}

	private JButton rowButton(String label, String tooltip, Runnable action)
	{
		JButton button = new JButton(label);
		button.setMargin(new Insets(2, 6, 2, 6));
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setToolTipText(tooltip);
		button.setFocusable(false); // keep keyboard focus on the game canvas after a click
		button.addActionListener(e -> action.run());
		return button;
	}

	private static void copyText(String text)
	{
		java.awt.Toolkit.getDefaultToolkit().getSystemClipboard()
			.setContents(new java.awt.datatransfer.StringSelection(text), null);
	}

	/**
	 * EDT (from the shift right-click "Builder: add item req" menu entry). Appends an item
	 * requirement in the transports.tsv Items format; & = AND (edit to | for alternatives, and
	 * adjust the quantity as needed).
	 */
	void appendBuilderItem(int itemId, String itemName)
	{
		String current = builderItems.getText().trim();
		builderItems.setText(current.isEmpty() ? itemId + "=1" : current + "&" + itemId + "=1");
		builderStatus.setText("added item: " + itemName + " (" + itemId + ")");
	}

	/**
	 * EDT (from a refusal message while a capture was armed). Fills empty requirement fields
	 * with what the game just said; never overwrites operator-typed values.
	 */
	void suggestRequirements(String skill, String quest, String rawMessage)
	{
		if (skill != null && builderSkills.getText().trim().isEmpty())
		{
			builderSkills.setText(skill);
		}
		if (quest != null && builderQuests.getText().trim().isEmpty())
		{
			builderQuests.setText(quest);
		}
		String text = rawMessage.length() > 60 ? rawMessage.substring(0, 57) + "…" : rawMessage;
		builderStatus.setText("<html>requirement: " + text + "</html>");
	}

	static Color stateColor(TransportAuditPlugin.FindingState state)
	{
		switch (state)
		{
			case ARMED:
				return Color.YELLOW;
			case DOOR:
				return TransportAuditSceneOverlay.UNMAPPED_DOOR;
			case CONFIRM:
				return new Color(176, 128, 255);
			case CAPTURED_ONE_WAY:
			case DATA_ONE_WAY:
				return new Color(190, 220, 60);
			case CAPTURED_SESSION:
				return new Color(70, 220, 90);
			case CAPTURED_PRIOR:
				return new Color(0, 190, 170);
			case KNOWN:
				return new Color(80, 200, 255);
			case RESOLVED:
				return ColorScheme.MEDIUM_GRAY_COLOR;
			default:
				return TransportAuditSceneOverlay.UNMAPPED;
		}
	}

	private static String stateText(TransportAuditPlugin.FindingState state)
	{
		switch (state)
		{
			case ARMED:
				return "capture armed — traverse it now";
			case DOOR:
				return "door not in registry — re-run doorDump";
			case CONFIRM:
				return "machine-derived — traverse with the audit on to confirm";
			case CAPTURED_ONE_WAY:
				return "captured ONE-WAY ✓ — walk the reverse to complete";
			case DATA_ONE_WAY:
				return "data covers ONE direction — traverse the other way to capture it";
			case CAPTURED_SESSION:
				return "captured this session ✓ (in transport-captures.tsv)";
			case CAPTURED_PRIOR:
				return "captured in an earlier session ✓";
			case KNOWN:
				return "curated data — select to spotlight in the world";
			case RESOLVED:
				return "covered by current data ✓ (prunable)";
			default:
				return "missing — use it to auto-capture, or Copy";
		}
	}

	private static String hex(Color color)
	{
		return String.format("#%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
	}
}

package gps.dev;

import gps.WorldPointUtil;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * The one-way/two-way pairing rules, pinned with the exact field data that exposed two bugs:
 * live captures read as ONE-WAY until restart (pairing was never recomputed on capture — fixed
 * at the completeCapture call site, exercised here by recomputing after each add the way that
 * site now does), and same-plane short hops (rockslides) paired with THEMSELVES through the
 * 5-tile tolerance, showing two-way after a single direction.
 */
public class TransportAuditPairingTest
{
	private static int tile(int x, int y, int p)
	{
		return WorldPointUtil.packWorldPoint(x, y, p);
	}

	private static TransportAuditPlugin plugin()
	{
		return new TransportAuditPlugin();
	}

	@Test
	public void varlamoreStairsPairAcrossTheTwoObjects()
	{
		// The user's captures, verbatim: descent via 27856 and ascent via 27854.
		TransportAuditPlugin plugin = plugin();
		plugin.capturedEdges.add(new int[]{tile(1610, 3796, 1), tile(1617, 3796, 0), 27856});
		plugin.recomputeEdgePairs();
		assertEquals("only one direction captured yet",
			TransportAuditPlugin.FindingState.CAPTURED_ONE_WAY,
			plugin.capturedState(27856, tile(1613, 3797, 1), true));

		plugin.capturedEdges.add(new int[]{tile(1617, 3796, 0), tile(1610, 3796, 1), 27854});
		plugin.recomputeEdgePairs();
		assertEquals("both directions captured — must read as complete, LIVE, without a restart",
			TransportAuditPlugin.FindingState.CAPTURED_SESSION,
			plugin.capturedState(27856, tile(1613, 3797, 1), true));
		assertEquals(TransportAuditPlugin.FindingState.CAPTURED_SESSION,
			plugin.capturedState(27854, tile(1615, 3797, 0), true));
	}

	@Test
	public void samePlaneShortHopDoesNotPairWithItself()
	{
		// An Underground Pass rockslide: origin and dest 2 tiles apart on the same plane — well
		// inside the 5-tile pairing tolerance, so without the identity/direction checks it
		// paired with itself and showed two-way after a single crossing.
		TransportAuditPlugin plugin = plugin();
		plugin.capturedEdges.add(new int[]{tile(2485, 9720, 0), tile(2485, 9722, 0), 3309});
		plugin.recomputeEdgePairs();
		assertEquals(TransportAuditPlugin.FindingState.CAPTURED_ONE_WAY,
			plugin.capturedState(3309, tile(2485, 9721, 0), true));
	}

	@Test
	public void samePlaneShortHopPairsWithItsRealReverse()
	{
		TransportAuditPlugin plugin = plugin();
		plugin.capturedEdges.add(new int[]{tile(2485, 9720, 0), tile(2485, 9722, 0), 3309});
		plugin.capturedEdges.add(new int[]{tile(2485, 9722, 0), tile(2485, 9720, 0), 3309});
		plugin.recomputeEdgePairs();
		assertEquals(TransportAuditPlugin.FindingState.CAPTURED_SESSION,
			plugin.capturedState(3309, tile(2485, 9721, 0), true));
	}

	@Test
	public void sameDirectionJitterDuplicateIsNotAReverse()
	{
		// Two captures of the SAME crossing with 1-tile landing jitter: same direction, so they
		// must not satisfy each other's reverse check.
		TransportAuditPlugin plugin = plugin();
		plugin.capturedEdges.add(new int[]{tile(2485, 9720, 0), tile(2485, 9722, 0), 3309});
		plugin.capturedEdges.add(new int[]{tile(2485, 9720, 0), tile(2486, 9722, 0), 3309});
		plugin.recomputeEdgePairs();
		assertEquals(TransportAuditPlugin.FindingState.CAPTURED_ONE_WAY,
			plugin.capturedState(3309, tile(2485, 9721, 0), true));
	}

	@Test
	public void crossPlanePairsViaSeparateObjects()
	{
		// Cave entrance/exit style: each object one-directional; together a round trip.
		TransportAuditPlugin plugin = plugin();
		plugin.capturedEdges.add(new int[]{tile(2435, 3314, 0), tile(2495, 9716, 0), 3213});
		plugin.capturedEdges.add(new int[]{tile(2496, 9713, 0), tile(2436, 3315, 0), 3214});
		plugin.recomputeEdgePairs();
		assertEquals(TransportAuditPlugin.FindingState.CAPTURED_SESSION,
			plugin.capturedState(3213, tile(2434, 3315, 0), true));
		assertEquals(TransportAuditPlugin.FindingState.CAPTURED_SESSION,
			plugin.capturedState(3214, tile(2498, 9716, 0), true));
	}

	@Test
	public void operatorOneWayMarkerCompletesTheEdge()
	{
		TransportAuditPlugin plugin = plugin();
		int[] edge = {tile(2485, 9720, 0), tile(2485, 9722, 0), 3309};
		plugin.capturedEdges.add(edge);
		plugin.noReverseKeys.add("2485 9720 0|2485 9722 0|3309");
		plugin.recomputeEdgePairs();
		assertEquals(TransportAuditPlugin.FindingState.CAPTURED_SESSION,
			plugin.capturedState(3309, tile(2485, 9721, 0), true));
	}
}

package gps.dev;

import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.Deque;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * The varbit heatmap's model: every varbit/varp change seen since tracking started, per-id
 * counts and histories, a "mark" to bracket an in-game action ("Mark, change respawn point,
 * read what flipped"), and a noise classifier so tick timers don't drown the list. Pure
 * Java — the panel renders it, the plugin feeds it, the unit test drives it.
 */
final class VarbitWatch
{
	/** Unknown previous value: the first time we see an id we only know its new value. */
	static final int UNKNOWN = Integer.MIN_VALUE;
	/** History kept per id (newest first). */
	static final int HISTORY_CAP = 200;
	/** Ticks until a change has cooled fully in the heat scale. */
	static final int COOL_TICKS = 60;
	/** Noisy: changed in at least this many of the last {@link #NOISE_WINDOW} ticks. */
	static final int NOISE_WINDOW = 10;
	static final int NOISE_HITS = 6;

	static final class Change
	{
		final int tick;
		final long atMillis;
		final int from;
		final int to;
		final int x;
		final int y;
		final int plane;

		Change(int tick, long atMillis, int from, int to, int x, int y, int plane)
		{
			this.tick = tick;
			this.atMillis = atMillis;
			this.from = from;
			this.to = to;
			this.x = x;
			this.y = y;
			this.plane = plane;
		}
	}

	static final class Entry
	{
		final boolean varbit;
		final int id;
		int count;
		int firstTick;
		int lastTick;
		int lastFrom = UNKNOWN;
		int lastTo;
		final Deque<Change> history = new ArrayDeque<>();

		Entry(boolean varbit, int id)
		{
			this.varbit = varbit;
			this.id = id;
		}

		String kind()
		{
			return varbit ? "varbit" : "varp";
		}

		String name()
		{
			return VarbitWatch.name(varbit, id);
		}

		/** Changes within the last {@code window} ticks before {@code nowTick}. */
		int changesWithin(int nowTick, int window)
		{
			int hits = 0;
			int lastCounted = Integer.MIN_VALUE;
			for (Change change : history)
			{
				if (change.tick < nowTick - window)
				{
					break;
				}
				if (change.tick != lastCounted)
				{
					hits++;
					lastCounted = change.tick;
				}
			}
			return hits;
		}
	}

	private final Map<Long, Entry> entries = new LinkedHashMap<>();
	private int markTick = -1;
	private boolean paused;

	private static long key(boolean varbit, int id)
	{
		return (varbit ? 1L << 40 : 0L) | (id & 0xFFFFFFFFL);
	}

	synchronized void record(boolean varbit, int id, int from, int to, int tick, long atMillis,
		int x, int y, int plane)
	{
		if (paused)
		{
			return;
		}
		Entry entry = entries.computeIfAbsent(key(varbit, id), k ->
		{
			Entry e = new Entry(varbit, id);
			e.firstTick = tick;
			return e;
		});
		entry.count++;
		entry.lastTick = tick;
		entry.lastFrom = from;
		entry.lastTo = to;
		entry.history.addFirst(new Change(tick, atMillis, from, to, x, y, plane));
		while (entry.history.size() > HISTORY_CAP)
		{
			entry.history.removeLast();
		}
	}

	synchronized void mark(int tick)
	{
		markTick = tick;
	}

	synchronized int markTick()
	{
		return markTick;
	}

	synchronized void clear()
	{
		entries.clear();
		markTick = -1;
	}

	synchronized void setPaused(boolean paused)
	{
		this.paused = paused;
	}

	synchronized boolean isPaused()
	{
		return paused;
	}

	synchronized int size()
	{
		return entries.size();
	}

	synchronized Entry entry(boolean varbit, int id)
	{
		return entries.get(key(varbit, id));
	}

	boolean isNoisy(Entry entry, int nowTick)
	{
		return entry.changesWithin(nowTick, NOISE_WINDOW) >= NOISE_HITS;
	}

	/** 1.0 = changed this tick, fading linearly to 0 at {@link #COOL_TICKS} ticks ago. */
	static float heat(Entry entry, int nowTick)
	{
		int age = Math.max(0, nowTick - entry.lastTick);
		return Math.max(0f, 1f - (float) age / COOL_TICKS);
	}

	/**
	 * The rows to show, hottest first (most recent change, then most changes). {@code filter}
	 * matches id or name (case-insensitive); {@code sinceMark} keeps only ids that changed at or
	 * after the mark; {@code hideNoisy} drops tick timers and the like.
	 */
	synchronized List<Entry> rows(String filter, boolean sinceMark, boolean hideNoisy, int nowTick)
	{
		String needle = filter == null ? "" : filter.trim().toLowerCase(Locale.ROOT);
		List<Entry> out = new ArrayList<>();
		for (Entry entry : entries.values())
		{
			if (sinceMark && (markTick < 0 || entry.lastTick < markTick))
			{
				continue;
			}
			if (hideNoisy && isNoisy(entry, nowTick))
			{
				continue;
			}
			if (!needle.isEmpty())
			{
				String name = entry.name();
				if (!Integer.toString(entry.id).contains(needle)
					&& (name == null || !name.toLowerCase(Locale.ROOT).contains(needle)))
				{
					continue;
				}
			}
			out.add(entry);
		}
		out.sort(Comparator.comparingInt((Entry e) -> -e.lastTick).thenComparingInt(e -> -e.count));
		return out;
	}

	/** TSV of every entry plus each one's history — the attachment for an issue or a field note. */
	synchronized String dump(int nowTick)
	{
		StringBuilder sb = new StringBuilder();
		sb.append("# Varbit watch dump at tick ").append(nowTick)
			.append(markTick >= 0 ? ", mark at tick " + markTick : ", no mark").append('\n');
		sb.append("kind\tid\tname\tcount\tfirstTick\tlastTick\tlastFrom\tlastTo\n");
		List<Entry> sorted = new ArrayList<>(entries.values());
		sorted.sort(Comparator.comparingInt((Entry e) -> -e.lastTick));
		for (Entry entry : sorted)
		{
			sb.append(entry.kind()).append('\t').append(entry.id).append('\t')
				.append(entry.name() == null ? "" : entry.name()).append('\t')
				.append(entry.count).append('\t').append(entry.firstTick).append('\t')
				.append(entry.lastTick).append('\t').append(value(entry.lastFrom)).append('\t')
				.append(entry.lastTo).append('\n');
		}
		sb.append("\n# history: kind\tid\ttick\tfrom\tto\tx\ty\tplane\n");
		for (Entry entry : sorted)
		{
			List<Change> oldestFirst = new ArrayList<>(entry.history);
			Collections.reverse(oldestFirst);
			for (Change change : oldestFirst)
			{
				sb.append(entry.kind()).append('\t').append(entry.id).append('\t').append(change.tick)
					.append('\t').append(value(change.from)).append('\t').append(change.to)
					.append('\t').append(change.x).append('\t').append(change.y).append('\t')
					.append(change.plane).append('\n');
			}
		}
		return sb.toString();
	}

	static String value(int value)
	{
		return value == UNKNOWN ? "?" : Integer.toString(value);
	}

	// ---- names: RuneLite's gameval constants, reflected once ----

	private static final class Names
	{
		static final Map<Integer, String> VARBITS = reflect("net.runelite.api.gameval.VarbitID");
		static final Map<Integer, String> VARPS = reflect("net.runelite.api.gameval.VarPlayerID");

		private static Map<Integer, String> reflect(String className)
		{
			Map<Integer, String> names = new HashMap<>();
			try
			{
				for (Field field : Class.forName(className).getFields())
				{
					if (Modifier.isStatic(field.getModifiers()) && field.getType() == int.class)
					{
						names.putIfAbsent(field.getInt(null), field.getName());
					}
				}
			}
			catch (ReflectiveOperationException | RuntimeException e)
			{
				// No names, ids only — the heatmap still works.
			}
			return names;
		}
	}

	/** The gameval constant name for the id, or null when RuneLite has none. */
	static String name(boolean varbit, int id)
	{
		return (varbit ? Names.VARBITS : Names.VARPS).get(id);
	}
}

package gps.dev;

import gps.WorldPointUtil;
import gps.transport.Transport;
import gps.transport.TransportLoader;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The single-file metadata model: Meta-tagged rows are loadable for the dev audit's
 * needs-confirmation view, while the runtime loader keeps parsing tagged rows exactly like
 * untagged ones (the Meta column is invisible to routing).
 */
public class MetaEdgesTest
{
	@Test
	public void tagsAreLoadableAndPlentiful()
	{
		List<MetaEdges.Entry> entries = MetaEdges.load();
		assertTrue("expected hundreds of tagged rows, got " + entries.size(), entries.size() > 500);
		assertTrue("the Honour varbit gate must be tagged ?varbits",
			entries.stream().anyMatch(e -> e.tags.contains("?varbits")));
		assertTrue("derived rows must be tagged ~geometry",
			entries.stream().filter(e -> e.tags.contains("~geometry")).count() > 500);
	}

	@Test
	public void runtimeLoaderIsUnaffectedByTags()
	{
		// A calibrated derived row (ladder-up, family mode 4 ticks) parses with its real values.
		int origin = WorldPointUtil.packWorldPoint(1204, 3119, 0);
		int dest = WorldPointUtil.packWorldPoint(1203, 3118, 1);
		Set<Transport> transports = TransportLoader.loadAllFromResources()
			.getOrDefault(origin, Set.of());
		Transport ladder = transports.stream()
			.filter(t -> t.getDestination() == dest)
			.findFirst().orElseThrow(() -> new AssertionError("tagged ladder row not loaded"));
		assertEquals("calibrated duration must survive the Meta column", 4, ladder.getDuration());
	}
}

package gps.dev;

import gps.WorldPointUtil;
import java.util.List;
import java.util.function.IntPredicate;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Captures across multi-tile objects (a 4-wide lava gap, 2-wide climbing rocks) only record
 * the lane actually traversed — {@link TransportAuditPlugin#expandCaptureLanes} translates
 * the capture to the sibling lanes of the footprint. Real cases from the Mount Karuulm
 * field session that motivated it.
 */
public class ExpandCaptureLanesTest
{
	private static final IntPredicate OPEN = p -> false;

	private static int tile(int x, int y, int plane)
	{
		return WorldPointUtil.packWorldPoint(x, y, plane);
	}

	@Test
	public void twoLaneRocksDeriveTheOtherLane()
	{
		// Rocks 34548 (2x1 at x 1351-1352): southbound was only captured on the x=1351 lane.
		List<int[]> lanes = TransportAuditPlugin.expandCaptureLanes(
			tile(1351, 10252, 0), tile(1351, 10250, 0), 1351, 1352, OPEN);
		assertEquals(1, lanes.size());
		assertArrayEquals(new int[]{tile(1352, 10252, 0), tile(1352, 10250, 0)}, lanes.get(0));
	}

	@Test
	public void fourLaneGapDerivesThreeSiblings()
	{
		// Lava gap 34515 (4 lanes, x 1269-1272), jumped north on the x=1269 lane.
		List<int[]> lanes = TransportAuditPlugin.expandCaptureLanes(
			tile(1269, 10170, 0), tile(1269, 10175, 0), 1269, 1272, OPEN);
		assertEquals(3, lanes.size());
		assertArrayEquals(new int[]{tile(1270, 10170, 0), tile(1270, 10175, 0)}, lanes.get(0));
		assertArrayEquals(new int[]{tile(1271, 10170, 0), tile(1271, 10175, 0)}, lanes.get(1));
		assertArrayEquals(new int[]{tile(1272, 10170, 0), tile(1272, 10175, 0)}, lanes.get(2));
	}

	@Test
	public void blockedLanesAreDropped()
	{
		IntPredicate blocked = p -> WorldPointUtil.unpackWorldX(p) == 1271;
		List<int[]> lanes = TransportAuditPlugin.expandCaptureLanes(
			tile(1269, 10170, 0), tile(1269, 10175, 0), 1269, 1272, blocked);
		assertEquals(2, lanes.size());
	}

	@Test
	public void crossPlaneStepsKeepEachEndpointsPlane()
	{
		// Steps 34530: up from plane 0 to plane 1, two lanes (y 10205-10206).
		List<int[]> lanes = TransportAuditPlugin.expandCaptureLanes(
			tile(1329, 10205, 0), tile(1334, 10205, 1), 10205, 10206, OPEN);
		assertEquals(1, lanes.size());
		assertArrayEquals(new int[]{tile(1329, 10206, 0), tile(1334, 10206, 1)}, lanes.get(0));
	}

	@Test
	public void diagonalTravelIsNotExpanded()
	{
		assertTrue(TransportAuditPlugin.expandCaptureLanes(
			tile(1270, 10176, 0), tile(1272, 10174, 0), 1269, 1272, OPEN).isEmpty());
	}

	@Test
	public void angledWalkInApproachIsNotExpanded()
	{
		// Origin lane coordinate outside the footprint span (the Karuulm steps were clicked
		// from 2-3 tiles out, so the recorded origin never lined up with a lane).
		assertTrue(TransportAuditPlugin.expandCaptureLanes(
			tile(1313, 10191, 1), tile(1318, 10189, 2), 10188, 10189, OPEN).isEmpty());
	}
}

package gps.dev;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/** The refusal-message parsers behind the audit's automatic requirement harvesting. */
public class TransportAuditParseTest
