package gps;

import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The balloon storage crates have no varbits — the chat messages are the only source of truth for
 * the stored counts (same approach and message set as the dedicated tictac7x-balloon plugin). Each
 * game message form must resolve to the right config key and count.
 */
public class BalloonLogStorageTest
{
	@Test
	public void checkMessageSyncsEveryLogType()
	{
		Map<String, Integer> updates = BalloonLogStorage.parse(
			"This crate currently contains 12 logs, 3 oak logs, 0 willow logs, 5 yew logs and 2 magic logs.");
		assertEquals(Integer.valueOf(12), updates.get("balloonStoredLogs"));
		assertEquals(Integer.valueOf(3), updates.get("balloonStoredOakLogs"));
		assertEquals(Integer.valueOf(0), updates.get("balloonStoredWillowLogs"));
		assertEquals(Integer.valueOf(5), updates.get("balloonStoredYewLogs"));
		assertEquals(Integer.valueOf(2), updates.get("balloonStoredMagicLogs"));
		assertEquals(5, updates.size());
	}

	@Test
	public void storingLogsReportsTheNewTotal()
	{
		assertEquals(Map.of("balloonStoredWillowLogs", 7),
			BalloonLogStorage.parse("You put the Willow logs in the crate. You now have 7 stored."));
		assertEquals(Map.of("balloonStoredLogs", 4),
			BalloonLogStorage.parse("You put the Logs in the crate. You now have 4 stored."));
	}

	@Test
	public void flyingReportsTheRemainingCount()
	{
		assertEquals(Map.of("balloonStoredMagicLogs", 3),
			BalloonLogStorage.parse("You have 3 sets of Magic logs left in storage."));
		assertEquals(Map.of("balloonStoredOakLogs", 1),
			BalloonLogStorage.parse("You have one set of Oak logs left in storage."));
		assertEquals(Map.of("balloonStoredYewLogs", 0),
			BalloonLogStorage.parse("You used the last of your Yew logs."));
	}

	@Test
	public void aRefusedTripMeansTheStorageIsEmptyForThatType()
	{
		assertEquals(Map.of("balloonStoredWillowLogs", 0),
			BalloonLogStorage.parse("You need 1 willow logs to make this trip."));
	}

	@Test
	public void unrelatedAndUnknownTypeMessagesAreIgnored()
	{
		assertTrue(BalloonLogStorage.parse("You board the balloon and fly to Varrock.").isEmpty());
		assertTrue(BalloonLogStorage.parse(
			"You put the Redwood logs in the crate. You now have 2 stored.").isEmpty());
	}

	@Test
	public void lowTypesWarnsOnlyForUnlockedRoutesBelowTheThreshold()
	{
		int[] stored = {0, 5, 0, 2, 0};
		boolean[] unlocked = {true, true, true, true, false};
		// normal (0) and willow (0) are unlocked and below 1; oak (5) and yew (2) are covered;
		// magic (0) is low but the route is locked, so it is noise rather than a warning.
		assertEquals(java.util.List.of("normal", "willow"),
			BalloonLogStorage.lowTypes(stored, unlocked, 1));
		// Threshold 3 pulls yew (2) in; threshold 0 disables warnings entirely.
		assertEquals(java.util.List.of("normal", "willow", "yew"),
			BalloonLogStorage.lowTypes(stored, unlocked, 3));
		assertTrue(BalloonLogStorage.lowTypes(stored, unlocked, 0).isEmpty());
	}
}

package gps;

import gps.pathfinder.CollisionMap;
import gps.pathfinder.Pathfinder;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import org.junit.Assume;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.mockito.Mockito.when;

/**
 * Dev probe (-DkebosMineProbe=true) for gps-capture-20260724-180802: route from the Kebos
 * Lowlands shore (1235,3656) to the mine cave (1211,3648) walked 66 tiles through the south
 * instead of cutting west. Prints the pathfinder's path, an edge-aware BFS distance (fences
 * are EDGE flags, invisible to tile-walkability grids), and where the direct corridor is
 * actually severed.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class KebosMineProbeTest
{
	private static final int START = WorldPointUtil.packWorldPoint(1235, 3656, 0);
	private static final int TARGET = WorldPointUtil.packWorldPoint(1211, 3648, 0);

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Test
	public void probe()
	{
		Assume.assumeTrue(Boolean.getBoolean("kebosMineProbe"));
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		CollisionMap map = planning.getMap();

		Pathfinder pathfinder = new Pathfinder(planning, START, Set.of(TARGET));
		pathfinder.run();
		System.out.println("pathfinder cost=" + pathfinder.getResult().getTotalCost()
			+ " steps=" + pathfinder.getResult().getPathSteps().size());

		// Edge-aware BFS over the local box: the true walk distance with fences honoured.
		Map<Integer, Integer> dist = new HashMap<>();
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		dist.put(START, 0);
		queue.add(START);
		while (!queue.isEmpty())
		{
			int at = queue.poll();
			int x = WorldPointUtil.unpackWorldX(at);
			int y = WorldPointUtil.unpackWorldY(at);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if (dx == 0 && dy == 0)
					{
						continue;
					}
					int nx = x + dx;
					int ny = y + dy;
					if (nx < 1195 || nx > 1245 || ny < 3620 || ny > 3665)
					{
						continue;
					}
					int next = WorldPointUtil.packWorldPoint(nx, ny, 0);
					if (dist.containsKey(next) || !map.canStep(at, next))
					{
						continue;
					}
					dist.put(next, dist.get(at) + 1);
					queue.add(next);
				}
			}
		}
		System.out.println("edge-aware BFS distance to target: " + dist.getOrDefault(TARGET, -1));

		// The BFS wavefront as a grid: distance mod 10 per tile ('#' unreachable-or-blocked).
		// The frontier between low numbers (near start) and high/blank shows the barrier shape.
		System.out.println("     " + "0123456789".repeat(5).substring(0, 1245 - 1198 + 1));
		for (int y = 3660; y >= 3628; y--)
		{
			StringBuilder line = new StringBuilder(y + " ");
			for (int x = 1198; x <= 1245; x++)
			{
				Integer distance = dist.get(WorldPointUtil.packWorldPoint(x, y, 0));
				line.append(distance == null ? '#' : (char) ('0' + distance % 10));
			}
			System.out.println(line);
		}
	}
}

package gps;

import java.util.HashSet;
import java.util.Set;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.junit.MockitoJUnitRunner;
import gps.pathfinder.WildernessChecker;

@RunWith(MockitoJUnitRunner.class)
public class WildernessCheckerTest
{

	private static final int WILDERNESS_GREEN_DRAGONS = WorldPointUtil.packWorldPoint(3339, 3696, 0);
	private static final int WILDERNESS_EDGEVILLE_DUNGEON = WorldPointUtil.packWorldPoint(3089, 9957, 0);
	private static final int WILDERNESS_LAVA_MAZE_DUNGEON = WorldPointUtil.packWorldPoint(3039, 10260, 0);
	private static final int WILDERNESS_DARK_WARRIORS_FORTRESS = WorldPointUtil.packWorldPoint(3023, 3626, 1);
	private static final int WILDERNESS_REVENANT_CAVES = WorldPointUtil.packWorldPoint(3198, 10074, 0);
	private static final int WILDERNESS_SLAYER_CAVE = WorldPointUtil.packWorldPoint(3406, 10144, 0);
	private static final int WILDERNESS_SLAYER_CAVE_SOUTH = WorldPointUtil.packWorldPoint(3385, 10054, 0);
	private static final int WILDERNESS_GOD_WARS_DUNGEON = WorldPointUtil.packWorldPoint(3044, 10134, 0);
	private static final int WILDERNESS_GOD_WARS_DUNGEON_UPSTAIRS = WorldPointUtil.packWorldPoint(3065, 10155, 3);

	private static final int WILDERNESS_FEROX_ENCLAVE = WorldPointUtil.packWorldPoint(3134, 3629, 0);
	private static final int NON_WILDERNESS_PENINSULA = WorldPointUtil.packWorldPoint(3009, 3531, 0);

	private static final int WILDERNESS_BANDIT_CAMP = WorldPointUtil.packWorldPoint(3037, 3700, 0);

	@Test
	public void testIsInWilderness()
	{
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_GREEN_DRAGONS));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_EDGEVILLE_DUNGEON));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_LAVA_MAZE_DUNGEON));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_DARK_WARRIORS_FORTRESS));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_REVENANT_CAVES));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_SLAYER_CAVE));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_GOD_WARS_DUNGEON));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_GOD_WARS_DUNGEON_UPSTAIRS));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_SLAYER_CAVE_SOUTH));

		assertFalse(WildernessChecker.isInWilderness(NON_WILDERNESS_PENINSULA));
		assertFalse(WildernessChecker.isInWilderness(WILDERNESS_FEROX_ENCLAVE));
	}

	@Test
	public void testisInWildernessSet()
	{
		Set<Integer> packedPoints = new HashSet<>();

		// All wilderness areas
		packedPoints.add(WILDERNESS_DARK_WARRIORS_FORTRESS);
		packedPoints.add(WILDERNESS_EDGEVILLE_DUNGEON);
		assertTrue(WildernessChecker.isInWilderness(packedPoints));
		packedPoints.clear();

		// All non-wilderness areas
		packedPoints.add(WILDERNESS_FEROX_ENCLAVE);
		packedPoints.add(NON_WILDERNESS_PENINSULA);
		assertFalse(WildernessChecker.isInWilderness(packedPoints));
		packedPoints.clear();

		// Mixed areas
		packedPoints.add(WILDERNESS_GREEN_DRAGONS);
		packedPoints.add(NON_WILDERNESS_PENINSULA);
		assertTrue(WildernessChecker.isInWilderness(packedPoints));
	}

	@Test
	public void testInLevel20Wilderness()
	{
		assertTrue(WildernessChecker.isInLevel20Wilderness(WILDERNESS_BANDIT_CAMP));
		assertTrue(WildernessChecker.isInLevel20Wilderness(WILDERNESS_GOD_WARS_DUNGEON));
		assertTrue(WildernessChecker.isInLevel20Wilderness(WILDERNESS_SLAYER_CAVE)); // Northern entrance at level 29
		// wilderness
		assertFalse(WildernessChecker.isInLevel20Wilderness(WILDERNESS_SLAYER_CAVE_SOUTH));
	}

	@Test
	public void testInLevel30Wilderness()
	{
		assertTrue(WildernessChecker.isInLevel30Wilderness(WILDERNESS_LAVA_MAZE_DUNGEON));
	}
}

package gps;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.List;
import java.util.Map;
import java.util.Set;
import gps.pathfinder.PathStep;
import gps.transport.TransportType;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

/**
 * Selection stickiness across recalculations: the picked route survives re-ranking, survives the
 * player's own progress along it (methods already behind are consumed from the match), and only
 * falls back to the new best when no equivalent continuation exists. Exercised through the real
 * {@code onAlternativeRoutesUpdate} done-branch via reflection on a bare plugin instance.
 */
public class RouteRematchTest
{
	private static final TeleportMethod CLOAK =
		new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Ardougne cloak", WorldPointUtil.packWorldPoint(2606, 3230, 0));
	private static final TeleportMethod MINECART =
		new TeleportMethod(TransportType.MINECART, "Keldagrim minecart", WorldPointUtil.packWorldPoint(2908, 10170, 0));
	private static final TeleportMethod SPIRIT_TREE =
		new TeleportMethod(TransportType.SPIRIT_TREE, "Tree Gnome Village", WorldPointUtil.packWorldPoint(2542, 3170, 0));

	private ShortestPathPlugin plugin;
	private RouteDirectionsOverlay overlay;

	@Before
	public void before() throws Exception
	{
		plugin = new ShortestPathPlugin();
		overlay = Mockito.mock(RouteDirectionsOverlay.class);
		set("routeDirectionsOverlay", overlay);
		AlternativeRoutesService service = Mockito.mock(AlternativeRoutesService.class);
		Mockito.when(service.wasMoreLikely()).thenReturn(false);
		set("altRoutesService", service);
	}

	private void set(String field, Object value) throws Exception
	{
		Field f = ShortestPathPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	@SuppressWarnings("unchecked")
	private <T> T get(String field) throws Exception
	{
		Field f = ShortestPathPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		return (T) f.get(plugin);
	}

	private static RouteOption route(boolean viaBank, List<Integer> methodEdges, TeleportMethod... methods)
	{
		List<TeleportMethod> methodList = List.of(methods);
		Set<TeleportMethod> bankMethods = viaBank && methods.length > 0 ? Set.of(methods[0]) : Set.of();
		List<Integer> durations = methodList.stream().map(m -> 1).collect(java.util.stream.Collectors.toList());
		return new RouteOption(List.<PathStep>of(), methodList, methodEdges, durations,
			100, 100, true, bankMethods, List.of(), 0);
	}

	private static RouteOption route(TeleportMethod... methods)
	{
		List<Integer> edges = new java.util.ArrayList<>();
		for (int i = 0; i < methods.length; i++)
		{
			edges.add(10 * (i + 1)); // method edges at path indexes 10, 20, ...
		}
		return route(false, edges, methods);
	}

	/** Runs the private generation-update handler as the service would. */
	private void update(List<RouteOption> routes, boolean done) throws Exception
	{
		Method m = ShortestPathPlugin.class.getDeclaredMethod("onAlternativeRoutesUpdate",
			List.class, List.class, Map.class, boolean.class);
		m.setAccessible(true);
		m.invoke(plugin, routes, List.of(), Map.of(), done);
	}

	private void select(RouteOption route, int trackerProgress) throws Exception
	{
		set("selectedRoute", route);
		Mockito.when(overlay.reachedIndexFor(route)).thenReturn(trackerProgress);
	}

	@Test
	public void pickedRouteStaysSelectedWhenItsRankMoves() throws Exception
	{
		RouteOption picked = route(CLOAK);
		select(picked, 0);
		RouteOption newBest = route(SPIRIT_TREE);
		RouteOption equivalent = route(CLOAK); // same methods, different object, now ranked #2
		update(List.of(newBest, equivalent), true);
		assertSame("equivalent route keeps the selection despite the rank change",
			equivalent, this.<RouteOption>get("selectedRoute"));
		assertSame(equivalent, this.<RouteOption>get("committedDisplayRoute"));
	}

	@Test
	public void vanishedRouteFallsBackToTheNewBest() throws Exception
	{
		select(route(CLOAK), 0);
		RouteOption newBest = route(SPIRIT_TREE);
		update(List.of(newBest), true);
		assertNull("no equivalent -> selection cleared", this.<RouteOption>get("selectedRoute"));
		assertSame(newBest, this.<RouteOption>get("committedDisplayRoute"));
	}

	@Test
	public void bankDetourVariantIsNotTheSameRouteBeforeDeparture()
		throws Exception
	{
		select(route(false, List.of(10), CLOAK), 0);
		RouteOption bankVariant = route(true, List.of(10), CLOAK);
		update(List.of(bankVariant), true);
		assertNull("direct route must not silently become the bank-detour variant",
			this.<RouteOption>get("selectedRoute"));
	}

	@Test
	public void methodsAlreadyBehindAreConsumedFromTheMatch() throws Exception
	{
		// Picked minecart -> spirit tree; the tracker says the player is past the minecart edge
		// (index 10) but before the spirit tree (index 20).
		RouteOption picked = route(MINECART, SPIRIT_TREE);
		select(picked, 14);
		RouteOption continuation = route(SPIRIT_TREE); // fresh list re-plans only the remainder
		RouteOption other = route(CLOAK);
		update(List.of(other, continuation), true);
		assertSame("the continuation (remaining methods) keeps the selection",
			continuation, this.<RouteOption>get("selectedRoute"));
	}

	@Test
	public void bankNessIsIgnoredMidJourney() throws Exception
	{
		// Withdrew and departed: the picked route was via the bank, the continuation is direct.
		RouteOption picked = route(true, List.of(10, 20), MINECART, SPIRIT_TREE);
		select(picked, 14);
		RouteOption continuation = route(false, List.of(10), SPIRIT_TREE);
		update(List.of(continuation), true);
		assertSame(continuation, this.<RouteOption>get("selectedRoute"));
	}

	@Test
	public void walkRemainderMatchesOnlyWhenEveryMethodIsBehind() throws Exception
	{
		RouteOption picked = route(MINECART);
		RouteOption walk = route(); // no methods
		// Before the minecart: the walk route must NOT steal the selection.
		select(picked, 0);
		update(List.of(walk), true);
		assertNull("untouched selection must not match the plain-walk route",
			this.<RouteOption>get("selectedRoute"));
		// After the minecart (edge 10 crossed): the walk route IS the honest continuation.
		select(picked, 12);
		update(List.of(walk), true);
		assertSame(walk, this.<RouteOption>get("selectedRoute"));
	}

	@Test
	public void midStreamUpdatesDoNotDisturbTheSelection() throws Exception
	{
		RouteOption picked = route(CLOAK);
		select(picked, 0);
		// Streaming update (done=false) with no equivalent present yet: selection must survive
		// so the overlay keeps drawing the picked route until the generation settles.
		update(List.of(route(SPIRIT_TREE)), false);
		assertSame(picked, this.<RouteOption>get("selectedRoute"));
		// The equivalent arrives by the time the generation settles: selection transfers to it.
		RouteOption equivalent = route(CLOAK);
		update(List.of(route(SPIRIT_TREE), equivalent), true);
		assertSame(equivalent, this.<RouteOption>get("selectedRoute"));
	}

	@Test
	public void emptyFinalListClearsEverything() throws Exception
	{
		select(route(CLOAK), 0);
		update(List.of(), true);
		assertNull(this.<RouteOption>get("selectedRoute"));
		assertNull(this.<RouteOption>get("committedDisplayRoute"));
		assertEquals(Boolean.FALSE, this.<Boolean>get("moreRoutesLikely"));
	}
}

