package gps;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.UnsupportedEncodingException;
import java.net.URI;
import java.net.URLEncoder;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Assume;
import org.junit.Test;
import gps.pathfinder.CollisionMap;
import gps.pathfinder.SplitFlagMap;

/**
 * Dev tool, not a test: builds destinations-wiki.tsv for the GPS search from the OSRS wiki —
 * every article using {@code {{Infobox Location}}} (places, landmarks, dungeons) or
 * {@code {{Infobox Activity}}} (minigames) whose infobox carries a {@code {{Map|x=..|y=..}}} pin.
 * This fills the gap the cache dump leaves: locations without an in-game world-map label
 * (e.g. Giants' Foundry) become searchable without hand-curating each one.
 * <p>
 * Names already present in destinations.tsv / destinations-curated.tsv are skipped (the cache dump
 * and hand curation stay authoritative), and pins with no walkable tile nearby (instanced/unmapped
 * zones) are dropped against the plugin's own collision map.
 * <p>
 * Run with: {@code ./gradlew test --tests gps.WikiLocationDumperTest -DwikiLocations.dump=true}
 * (the plugin build forwards {@code wikiLocations.*} system properties to the test JVM); the
 * output default is src/main/resources/destinations-wiki.tsv — review the diff and commit.
 */
public class WikiLocationDumperTest
{
	private static final String API = "https://oldschool.runescape.wiki/api.php";
	private static final String USER_AGENT =
		"RuneLite GPS plugin location dump (github.com/PauloAguiar/runelite-gps-plugin)";
	private static final int BATCH = 50;
	private static final long THROTTLE_MILLIS = 300;

	// The infobox map pin: {{Map|x=3360|y=3151|plane=0|...}} (named params, any order).
	private static final Pattern MAP_TEMPLATE = Pattern.compile("\\{\\{Map\\|([^{}]*)}}", Pattern.CASE_INSENSITIVE);
	private static final Pattern INFOBOX_TYPE = Pattern.compile("\\|\\s*type\\s*=\\s*([^|\\n]*)", Pattern.CASE_INSENSITIVE);

	private final HttpClient http = HttpClient.newHttpClient();

	@Test
	public void dump() throws Exception
	{
		Assume.assumeTrue("Enable with -DwikiLocations.dump=true", Boolean.getBoolean("wikiLocations.dump"));
		Path resources = Paths.get(System.getProperty("wikiLocations.resources", "src/main/resources"));
		Path output = Paths.get(System.getProperty("wikiLocations.output",
			resources.resolve("destinations-wiki.tsv").toString()));

		Set<String> existingNames = new HashSet<>();
		for (String file : new String[]{"destinations.tsv", "destinations-curated.tsv"})
		{
			Path path = resources.resolve(file);
			if (Files.exists(path))
			{
				for (String line : Files.readAllLines(path, StandardCharsets.UTF_8))
				{
					String[] cols = line.split("\t");
					if (cols.length >= 2 && !"category".equals(cols[0]))
					{
						existingNames.add(normalize(cols[1]));
					}
				}
			}
		}
		System.out.println("existing names to dedupe against: " + existingNames.size());

		// category|name -> row; TreeMap for a stable, reviewable file order.
		Map<String, String> rows = new TreeMap<>();
		Set<String> emitted = new HashSet<>(existingNames);
		int[] scanned = new int[1];
		String today = LocalDate.now().toString();
		// Wiki pins in instanced/unmapped zones (cutscene areas, Memory instances) have no walkable
		// tile nearby in the plugin's collision map and would produce nonsense routes.
		CollisionMap collisionMap = new CollisionMap(SplitFlagMap.fromResources());

		Map<String, List<int[]>> candidates = new TreeMap<>();
		harvest("Template:Infobox Location", false, emitted, candidates, scanned);
		harvest("Template:Infobox Activity", true, emitted, candidates, scanned);
		resolvePins(rows, candidates, collisionMap, today);

		Files.createDirectories(output.getParent());
		try (BufferedWriter writer = Files.newBufferedWriter(output, StandardCharsets.UTF_8))
		{
			writer.write("category\tname\tx\ty\tplane\tverified_source\tverified_date\n");
			for (String row : rows.values())
			{
				writer.write(row);
				writer.write('\n');
			}
		}
		System.out.println("pages scanned: " + scanned[0] + ", entries written: " + rows.size());
		System.out.println("output: " + output.toAbsolutePath());
	}

	private void harvest(String template, boolean activity, Set<String> emitted, Map<String, List<int[]>> candidates,
		int[] scanned) throws Exception
	{
		List<String> titles = transcludingTitles(template);
		System.out.println(template + ": " + titles.size() + " pages");
		for (int i = 0; i < titles.size(); i += BATCH)
		{
			for (Map.Entry<String, String> page : wikitexts(titles.subList(i, Math.min(i + BATCH, titles.size()))).entrySet())
			{
				scanned[0]++;
				String title = page.getKey();
				if (title.contains("/") || title.contains("(historical)") || title.contains("Leagues"))
				{
					continue;
				}
				String category = categorize(page.getValue(), activity);
				if (category == null)
				{
					continue;
				}
				List<int[]> pins = mapPins(page.getValue());
				if (pins.isEmpty() || !emitted.add(normalize(title)))
				{
					continue;
				}
				candidates.put(category + "|" + title, pins);
			}
		}
	}

	/**
	 * Resolves each candidate to its first REACHABLE pin, or drops it: instanced and cutscene zones
	 * are walkable in the collision map but disconnected from the world graph, so a search from
	 * Lumbridge with every transport enabled (everything-mode planning config) is the oracle. Pages
	 * often pin an interior first and the entrance later (dungeons, altars), so every pin gets a
	 * chance. Slow (minutes — unreachable pins each flood the map) but this only runs when
	 * regenerating the data.
	 */
	private static void resolvePins(Map<String, String> rows, Map<String, List<int[]>> candidates,
		CollisionMap collisionMap, String today)
	{
		final Thread clientThread = Thread.currentThread();
		net.runelite.api.Client client = (net.runelite.api.Client) java.lang.reflect.Proxy.newProxyInstance(
			net.runelite.api.Client.class.getClassLoader(), new Class<?>[]{net.runelite.api.Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState":
						return net.runelite.api.GameState.LOGGED_IN;
					case "getClientThread":
						return clientThread;
					case "getBoostedSkillLevel":
						return 99;
					default:
						return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
		// Everything on: booleans true (minus the restricting toggles), items ALL, best jewellery box.
		ShortestPathConfig config = org.mockito.Mockito.mock(ShortestPathConfig.class, invocation ->
		{
			String name = invocation.getMethod().getName();
			Class<?> type = invocation.getMethod().getReturnType();
			if (type == boolean.class)
			{
				return !"avoidWilderness".equals(name) && !"enableSeasonalTransports".equals(name);
			}
			if (type == int.class)
			{
				return "calculationCutoff".equals(name) ? 120 : 0;
			}
			if (type == TeleportationItem.class)
			{
				return TeleportationItem.ALL;
			}
			if (type == JewelleryBoxTier.class)
			{
				return JewelleryBoxTier.ORNATE;
			}
			return HybridPageFillTest.defaultValue(type);
		});
		gps.pathfinder.PathfinderConfig planning =
			new gps.pathfinder.TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();

		final int lumbridge = WorldPointUtil.packWorldPoint(3221, 3218, 0);
		List<String> dropped = new ArrayList<>();
		List<String> review = new ArrayList<>();
		int salvagedByLaterPin = 0;
		for (Map.Entry<String, List<int[]>> candidate : candidates.entrySet())
		{
			// Evaluate EVERY pin, not just up to the first reachable one: when several distinct
			// sites are reachable, the first-pin choice is a guess that a human should review.
			List<int[]> pins = candidate.getValue();
			List<int[]> reachable = new ArrayList<>();
			for (int[] pin : pins)
			{
				Set<Integer> ring = Destinations.walkableTargets(collisionMap,
					WorldPointUtil.packWorldPoint(pin[0], pin[1], pin[2]));
				if (ring.isEmpty())
				{
					continue;
				}
				gps.pathfinder.Pathfinder pathfinder = new gps.pathfinder.Pathfinder(planning, lumbridge, ring);
				pathfinder.run();
				if (pathfinder.getResult().isReached())
				{
					reachable.add(pin);
				}
			}
			if (reachable.isEmpty())
			{
				dropped.add(candidate.getKey());
				continue;
			}
			int[] chosen = reachable.get(0);
			if (!java.util.Arrays.equals(chosen, pins.get(0)))
			{
				salvagedByLaterPin++;
			}
			// Ambiguous pick: more than one reachable pin, meaningfully apart — flag for a human.
			// A wrong pick is overridden by adding a curated row with the same name (the dedupe
			// then drops the wiki entry on the next run).
			for (int i = 1; i < reachable.size(); i++)
			{
				int[] other = reachable.get(i);
				if (other[2] != chosen[2]
					|| Math.abs(other[0] - chosen[0]) + Math.abs(other[1] - chosen[1]) > 40)
				{
					review.add(candidate.getKey() + "\tchose (" + chosen[0] + ", " + chosen[1] + ", " + chosen[2]
						+ ")\talternatives " + reachable.stream()
							.map(p -> "(" + p[0] + ", " + p[1] + ", " + p[2] + ")")
							.reduce((a, b) -> a + " " + b).orElse(""));
					break;
				}
			}
			String key = candidate.getKey();
			String category = key.substring(0, key.indexOf('|'));
			String title = key.substring(key.indexOf('|') + 1);
			rows.put(key, category + "\t" + title + "\t" + chosen[0] + "\t" + chosen[1] + "\t" + chosen[2]
				+ "\tosrs-wiki-infobox-map\t" + today);
		}
		System.out.println("salvaged by a later pin: " + salvagedByLaterPin);
		System.out.println("unreachable entries dropped: " + dropped.size() + " " + dropped);
		System.out.println("AMBIGUOUS picks needing review: " + review.size());
		for (String line : review)
		{
			System.out.println("  REVIEW " + line);
		}
	}

	/**
	 * The search category for a page, from its infobox type: activities count when they are
	 * minigames or raids ("minigame") or fixed-location bosses/activities like Barrows and the
	 * Blast mine ("landmark") — but not random events, forestry events, or roaming distractions.
	 * Locations map city/town/village/island to "place", dungeons and caves to "dungeon",
	 * everything else (mountains, ruins, guilds, buildings, ...) to "landmark". Null skips the page.
	 */
	private static String categorize(String wikitext, boolean activity)
	{
		Matcher typeMatcher = INFOBOX_TYPE.matcher(wikitext);
		String type = typeMatcher.find()
			? typeMatcher.group(1).replaceAll("\\[\\[|]]", "").trim().toLowerCase(Locale.ROOT) : "";
		if (activity)
		{
			if (type.contains("minigame") || type.contains("raid"))
			{
				return "minigame";
			}
			return type.equals("boss") || type.equals("activity") ? "landmark" : null;
		}
		if (type.contains("city") || type.contains("town") || type.contains("village") || type.contains("island"))
		{
			return "place";
		}
		if (type.contains("dungeon") || type.contains("cave"))
		{
			return "dungeon";
		}
		return "landmark";
	}

	/**
	 * Every plausible in-world {@code {{Map}}} pin on the page, in order: [x, y, plane] each. Many
	 * pages pin an interior first and the entrance later, so the reachability pass tries them all.
	 * Handles both named ({@code x=..|y=..}) and positional ({@code {{Map|2984,3291|...}}}) pins.
	 */
	private static List<int[]> mapPins(String wikitext)
	{
		List<int[]> pins = new ArrayList<>();
		Matcher matcher = MAP_TEMPLATE.matcher(wikitext);
		while (matcher.find())
		{
			Integer x = null;
			Integer y = null;
			int plane = 0;
			for (String param : matcher.group(1).split("\\|"))
			{
				String[] pair = param.split("=", 2);
				if (pair.length != 2)
				{
					// Positional coordinate pair: {{Map|2984,3291|mtype=pin}}.
					Matcher pos = Pattern.compile("^\\s*(\\d{4}),\\s*(\\d{4,5})\\s*$").matcher(param);
					if (pos.matches())
					{
						x = Integer.parseInt(pos.group(1));
						y = Integer.parseInt(pos.group(2));
					}
					continue;
				}
				String key = pair[0].trim().toLowerCase(Locale.ROOT);
				try
				{
					if ("x".equals(key))
					{
						x = Integer.parseInt(pair[1].trim());
					}
					else if ("y".equals(key))
					{
						y = Integer.parseInt(pair[1].trim());
					}
					else if ("plane".equals(key))
					{
						plane = Integer.parseInt(pair[1].trim());
					}
				}
				catch (NumberFormatException e)
				{
					// A templated/expression param — not a plain pin; keep scanning.
				}
			}
			if (x != null && y != null && x >= 1000 && x <= 4600 && y >= 2000 && y <= 13000 && plane >= 0 && plane <= 3)
			{
				pins.add(new int[]{x, y, plane});
			}
		}
		return pins;
	}

	/** Every mainspace title transcluding the template, via the paginated embeddedin API. */
	private List<String> transcludingTitles(String template) throws IOException, InterruptedException
	{
		List<String> titles = new ArrayList<>();
		String cont = null;
		do
		{
			String url = API + "?action=query&list=embeddedin&eititle=" + encode(template)
				+ "&einamespace=0&eilimit=500&format=json"
				+ (cont != null ? "&eicontinue=" + encode(cont) : "");
			JsonObject json = get(url);
			for (JsonElement e : json.getAsJsonObject("query").getAsJsonArray("embeddedin"))
			{
				titles.add(e.getAsJsonObject().get("title").getAsString());
			}
			cont = json.has("continue") ? json.getAsJsonObject("continue").get("eicontinue").getAsString() : null;
		}
		while (cont != null);
		return titles;
	}

	/** Raw wikitext per title for one batch (the API caps titles at 50 per request). */
	private Map<String, String> wikitexts(List<String> titles) throws IOException, InterruptedException
	{
		String url = API + "?action=query&prop=revisions&rvprop=content&rvslots=main&format=json"
			+ "&titles=" + encode(String.join("|", titles));
		JsonObject json = get(url);
		Map<String, String> out = new TreeMap<>();
		for (Map.Entry<String, JsonElement> entry : json.getAsJsonObject("query").getAsJsonObject("pages").entrySet())
		{
			JsonObject page = entry.getValue().getAsJsonObject();
			if (!page.has("revisions"))
			{
				continue;
			}
			JsonObject slot = page.getAsJsonArray("revisions").get(0).getAsJsonObject()
				.getAsJsonObject("slots").getAsJsonObject("main");
			out.put(page.get("title").getAsString(), slot.get("*").getAsString());
		}
		return out;
	}

	private JsonObject get(String url) throws IOException, InterruptedException
	{
		Thread.sleep(THROTTLE_MILLIS);
		HttpRequest request = HttpRequest.newBuilder(URI.create(url)).header("User-Agent", USER_AGENT).GET().build();
		HttpResponse<String> response = http.send(request, HttpResponse.BodyHandlers.ofString());
		if (response.statusCode() != 200)
		{
			throw new IOException("wiki API " + response.statusCode() + " for " + url);
		}
		return JsonParser.parseString(response.body()).getAsJsonObject();
	}

	private static String normalize(String name)
	{
		return name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
	}

	private static String encode(String value)
	{
		try
		{
			return URLEncoder.encode(value, "UTF-8");
		}
		catch (UnsupportedEncodingException e)
		{
			throw new IllegalStateException(e);
		}
	}
}

package gps.pathfinder;

import gps.JewelleryBoxTier;
import gps.MethodAvailability;
import gps.ShortestPathConfig;
import gps.TeleportMethod;
import gps.TeleportationItem;
import gps.transport.TransportType;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

/**
 * The rule: a method row never leaves the catalog for a structural reason — house off, a
 * jewellery-box tier not built, mounts off — it stays listed with a lock and a reason. The one
 * exception is seasonal content, which only exists on seasonal worlds.
 */
@RunWith(MockitoJUnitRunner.class)
public class CatalogNeverShrinksTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(30);
		when(config.currencyThreshold()).thenReturn(10000000);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.NONE);
		when(config.usePoh()).thenReturn(true);
		when(config.usePohMountedItems()).thenReturn(true);
		when(config.pohMountGlory()).thenReturn(true);
		when(config.pohMountXerics()).thenReturn(true);
		when(config.pohMountDigsite()).thenReturn(true);
		when(config.pohMountMythical()).thenReturn(true);
		when(config.pohJewelleryBoxTier()).thenReturn(JewelleryBoxTier.ORNATE);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	private PathfinderConfig planning()
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		return planning;
	}

	private static TeleportMethod first(Map<TeleportMethod, MethodAvailability> availability, TransportType type,
		String labelPrefix)
	{
		for (TeleportMethod method : availability.keySet())
		{
			if (method.getType() == type && (labelPrefix == null || method.label().startsWith(labelPrefix)))
			{
				return method;
			}
		}
		return null;
	}

	@Test
	public void houseOffLocksItsMethodsInsteadOfRemovingThem()
	{
		int withHouse = planning().getMethodCatalog().size();
		when(config.usePoh()).thenReturn(false);
		PathfinderConfig off = planning();
		assertEquals("the catalog must not shrink when the house is switched off",
			withHouse, off.getMethodCatalog().size());
		Map<TeleportMethod, MethodAvailability> availability = off.getMethodAvailability();
		TeleportMethod box = first(availability, TransportType.TELEPORTATION_BOX, null);
		assertTrue("a house method is still listed", box != null);
		assertEquals(MethodAvailability.LOCKED, availability.get(box));
		assertEquals("House is off (House section)", off.getMethodAvailabilityDetail().get(box));
	}

	@Test
	public void boxTierLocksHigherTierDestinations()
	{
		when(config.pohJewelleryBoxTier()).thenReturn(JewelleryBoxTier.NONE);
		PathfinderConfig none = planning();
		Map<TeleportMethod, MethodAvailability> availability = none.getMethodAvailability();
		boolean lockedBox = false;
		for (Map.Entry<TeleportMethod, MethodAvailability> entry : availability.entrySet())
		{
			String label = entry.getKey().label();
			boolean mount = label.startsWith("Xeric's talisman:") || label.startsWith("Amulet of glory:")
				|| label.startsWith("Digsite pendant:") || label.startsWith("Mythical cape:");
			if (entry.getKey().getType() == TransportType.TELEPORTATION_BOX && !mount
				&& entry.getValue() == MethodAvailability.LOCKED)
			{
				lockedBox = true;
				assertEquals("Not built at your jewellery box tier (House section)",
					none.getMethodAvailabilityDetail().get(entry.getKey()));
			}
		}
		assertTrue("with no box built its destinations stay listed, locked", lockedBox);
	}

	@Test
	public void travelOptionOffLocksItsMethodsInsteadOfRemovingThem()
	{
		// The charter network with its toggle off (the mock's default): listed, locked, named.
		PathfinderConfig off = planning();
		TeleportMethod charter = first(off.getMethodAvailability(), TransportType.CHARTER_SHIP, null);
		assertTrue("a charter method is still listed", charter != null);
		assertEquals(MethodAvailability.LOCKED, off.getMethodAvailability().get(charter));
		assertEquals("Charter ships are off (Travel options)",
			off.getMethodAvailabilityDetail().get(charter));
		int total = off.getMethodCatalog().size();

		when(config.useCharterShips()).thenReturn(true);
		PathfinderConfig on = planning();
		assertEquals("the catalog is the same size either way", total, on.getMethodCatalog().size());
		assertTrue("with the toggle on the charter is no longer locked",
			on.getMethodAvailability().get(charter) != MethodAvailability.LOCKED);
	}

	@Test
	public void seasonalContentIsTheOneException()
	{
		when(config.useSeasonalTransports()).thenReturn(false);
		assertFalse("seasonal rows must NOT be listed off a seasonal world",
			planning().getMethodCatalog().stream().anyMatch(m -> m.getType() == TransportType.SEASONAL_TRANSPORTS));
	}
}

package gps.pathfinder;

import gps.WorldPointUtil;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.BitSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;
import org.junit.Assume;
import org.junit.Test;

/**
 * Dev probe (-DcollisionDiff.run=true): quantifies what a collision-map change did to
 * PLAYER-REACHABLE space, not just raw edges. Loads two zips (-DcollisionDiff.oldZip /
 * -DcollisionDiff.newZip), measures load time and retained heap, then flood-fills each with
 * the real 8-direction canStep from Lumbridge plus every transport endpoint, and diffs the
 * reachable sets both ways: newly reachable tiles (possible void leaks) and newly
 * UNREACHABLE tiles (broken paths), grouped by region.
 */
public class CollisionDiffProbeTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);

	@Test
	public void diff() throws Exception
	{
		Assume.assumeTrue(Boolean.getBoolean("collisionDiff.run"));
		Path oldZip = Paths.get(System.getProperty("collisionDiff.oldZip"));
		Path newZip = Paths.get(System.getProperty("collisionDiff.newZip"));

		List<Integer> seeds = transportSeeds();
		seeds.add(LUMBRIDGE);
		System.out.println("seeds: " + seeds.size() + " (transport endpoints + Lumbridge)");

		Result oldResult = measure("old", oldZip, seeds);
		Result newResult = measure("new", newZip, seeds);

		BitSet gained = (BitSet) newResult.reachable.clone();
		gained.andNot(oldResult.reachable);
		BitSet lost = (BitSet) oldResult.reachable.clone();
		lost.andNot(newResult.reachable);

		StringBuilder report = new StringBuilder();
		report.append(String.format("old: load %dms, retained %.1f MB, flood %dms, reachable %,d%n",
			oldResult.loadMs, oldResult.retainedMb, oldResult.floodMs, oldResult.reachable.cardinality()));
		report.append(String.format("new: load %dms, retained %.1f MB, flood %dms, reachable %,d%n",
			newResult.loadMs, newResult.retainedMb, newResult.floodMs, newResult.reachable.cardinality()));
		report.append(String.format("newly reachable: %,d   newly UNREACHABLE: %,d%n%n",
			gained.cardinality(), lost.cardinality()));
		bandTotals(report, "gained", gained);
		summarize(report, "NEWLY REACHABLE (leak candidates)", gained);
		summarize(report, "NEWLY UNREACHABLE (broken paths)", lost);
		report.append("exact newly-unreachable tiles:\n");
		for (int i = lost.nextSetBit(0); i >= 0; i = lost.nextSetBit(i + 1))
		{
			report.append("  ").append(i & 0x3FFF).append(',')
				.append((i >> 14) & 0x3FFF).append(',').append(i >>> 28).append('\n');
		}

		Files.write(Paths.get("build/collision-diff-report.txt"),
			report.toString().getBytes(StandardCharsets.UTF_8));
		System.out.println(report);
	}

	private static final class Result
	{
		long loadMs;
		double retainedMb;
		long floodMs;
		BitSet reachable;
	}

	private Result measure(String label, Path zip, List<Integer> seeds) throws Exception
	{
		Result result = new Result();
		System.gc();
		Thread.sleep(200);
		long before = used();
		long t0 = System.nanoTime();
		CollisionMap map = loadMap(zip);
		result.loadMs = (System.nanoTime() - t0) / 1_000_000;
		System.gc();
		Thread.sleep(200);
		result.retainedMb = (used() - before) / 1048576.0;

		t0 = System.nanoTime();
		result.reachable = flood(map, seeds);
		result.floodMs = (System.nanoTime() - t0) / 1_000_000;
		System.out.println(label + " done: " + result.reachable.cardinality() + " reachable");
		return result;
	}

	private static long used()
	{
		Runtime r = Runtime.getRuntime();
		return r.totalMemory() - r.freeMemory();
	}

	/** Mirrors SplitFlagMap.fromResources but reads an arbitrary zip (extents set reflectively). */
	private static CollisionMap loadMap(Path zip) throws Exception
	{
		Map<Integer, byte[]> compressed = new HashMap<>();
		int minX = Integer.MAX_VALUE;
		int minY = Integer.MAX_VALUE;
		int maxX = 0;
		int maxY = 0;
		try (ZipInputStream in = new ZipInputStream(new FileInputStream(zip.toFile())))
		{
			ZipEntry entry;
			while ((entry = in.getNextEntry()) != null)
			{
				String[] n = entry.getName().split("_");
				int x = Integer.parseInt(n[0]);
				int y = Integer.parseInt(n[1]);
				minX = Math.min(minX, x);
				minY = Math.min(minY, y);
				maxX = Math.max(maxX, x);
				maxY = Math.max(maxY, y);
				compressed.put(SplitFlagMap.packPosition(x, y), gps.Util.readAllBytes(in));
			}
		}
		Constructor<?> extentCtor = SplitFlagMap.RegionExtent.class.getDeclaredConstructors()[0];
		extentCtor.setAccessible(true);
		Object extent = extentCtor.newInstance(minX, minY, maxX, maxY);
		Field field = SplitFlagMap.class.getDeclaredField("regionExtents");
		field.setAccessible(true);
		field.set(null, extent);
		return new CollisionMap(new SplitFlagMap(compressed));
	}

	private static BitSet flood(CollisionMap map, List<Integer> seeds)
	{
		BitSet visited = new BitSet(1 << 30);
		int[] queue = new int[1 << 22];
		int head = 0;
		int tail = 0;
		for (int seed : seeds)
		{
			int x = WorldPointUtil.unpackWorldX(seed);
			int y = WorldPointUtil.unpackWorldY(seed);
			int plane = WorldPointUtil.unpackWorldPlane(seed);
			if (map.isBlocked(x, y, plane))
			{
				continue;
			}
			int index = index(x, y, plane);
			if (!visited.get(index))
			{
				visited.set(index);
				queue[tail++] = seed;
			}
		}
		while (head != tail)
		{
			int at = queue[head++];
			if (head == queue.length)
			{
				head = 0;
			}
			int x = WorldPointUtil.unpackWorldX(at);
			int y = WorldPointUtil.unpackWorldY(at);
			int plane = WorldPointUtil.unpackWorldPlane(at);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if (dx == 0 && dy == 0)
					{
						continue;
					}
					int nx = x + dx;
					int ny = y + dy;
					if (nx < 1024 || nx > 4200 || ny < 2400 || ny > 12800)
					{
						continue;
					}
					int neighborIndex = index(nx, ny, plane);
					if (visited.get(neighborIndex))
					{
						continue;
					}
					int neighbor = WorldPointUtil.packWorldPoint(nx, ny, plane);
					if (!map.canStep(at, neighbor))
					{
						continue;
					}
					visited.set(neighborIndex);
					queue[tail++] = neighbor;
					if (tail == queue.length)
					{
						tail = 0;
					}
					if (tail == head)
					{
						throw new IllegalStateException("flood queue overflow");
					}
				}
			}
		}
		return visited;
	}

	private static int index(int x, int y, int plane)
	{
		return (plane << 28) | (y << 14) | x;
	}

	private static void bandTotals(StringBuilder report, String label, BitSet tiles)
	{
		int surface = 0;
		int under = 0;
		int instance = 0;
		for (int i = tiles.nextSetBit(0); i >= 0; i = tiles.nextSetBit(i + 1))
		{
			int y = (i >> 14) & 0x3FFF;
			if (y <= 4160)
			{
				surface++;
			}
			else if (y >= 8900)
			{
				under++;
			}
			else
			{
				instance++;
			}
		}
		report.append(label).append(" by band: surface=").append(surface)
			.append(" underground=").append(under).append(" instance-band=").append(instance)
			.append('\n');
	}

	private static void summarize(StringBuilder report, String title, BitSet tiles)
	{
		Map<Long, Integer> byRegion = new HashMap<>();
		for (int i = tiles.nextSetBit(0); i >= 0; i = tiles.nextSetBit(i + 1))
		{
			int x = i & 0x3FFF;
			int y = (i >> 14) & 0x3FFF;
			byRegion.merge(((long) (x / 64) << 20) | (y / 64), 1, Integer::sum);
		}
		List<Map.Entry<Long, Integer>> top = new ArrayList<>(byRegion.entrySet());
		top.sort((a, b) -> b.getValue() - a.getValue());
		report.append("=== ").append(title).append(": ").append(tiles.cardinality())
			.append(" tiles in ").append(byRegion.size()).append(" regions ===\n");
		for (int i = 0; i < Math.min(25, top.size()); i++)
		{
			int rx = (int) (top.get(i).getKey() >> 20);
			int ry = (int) (top.get(i).getKey() & 0xFFFFF);
			report.append(String.format("  %6d tiles  region %d_%d  world (%d,%d)%s%n",
				top.get(i).getValue(), rx, ry, rx * 64, ry * 64,
				ry * 64 >= 8900 ? "  [underground]" : (ry * 64 > 4160 ? "  [instance band]" : "")));
		}
	}

	private static List<Integer> transportSeeds() throws IOException
	{
		List<Integer> seeds = new ArrayList<>();
		File dir = new File("src/main/resources/transports");
		File[] files = dir.listFiles((d, name) -> name.endsWith(".tsv"));
		if (files == null)
		{
			return seeds;
		}
		for (File file : files)
		{
			for (String line : Files.readAllLines(file.toPath(), StandardCharsets.UTF_8))
			{
				if (line.startsWith("#") || line.isEmpty())
				{
					continue;
				}
				String[] cols = line.split("\t");
				for (int c = 0; c < Math.min(2, cols.length); c++)
				{
					String[] parts = cols[c].trim().split(" ");
					if (parts.length == 3)
					{
						try
						{
							seeds.add(WorldPointUtil.packWorldPoint(Integer.parseInt(parts[0]),
								Integer.parseInt(parts[1]), Integer.parseInt(parts[2])));
						}
						catch (NumberFormatException ignored)
						{
							// header or malformed row — not a tile
						}
					}
				}
			}
		}
		return seeds;
	}
}

package gps.pathfinder;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;
import gps.WorldPointUtil;

public class VisitedTilesTest
{
	private static CollisionMap collisionMap()
	{
		return new CollisionMap(SplitFlagMap.fromResources());
	}

	@Test
	public void settingBankedTileAlsoMarksUnbankedTileVisited()
	{
		VisitedTiles visited = new VisitedTiles(collisionMap());
		int tile = WorldPointUtil.packWorldPoint(3200, 3200, 0);

		assertTrue(visited.set(tile, true));

		assertTrue(visited.get(tile, true));
		assertTrue(visited.get(tile, false));
		assertFalse(visited.set(tile, false));
	}

	@Test
	public void settingBankedAbstractNodeAlsoMarksUnbankedAbstractNodeVisited()
	{
		VisitedTiles visited = new VisitedTiles(collisionMap());
		NodeGraph graph = new NodeGraph(16);
		int banked = graph.createAbstract(AbstractNodeKind.GLOBAL_TELEPORTS_NORMAL, NodeGraph.NO_NODE, true, 0);
		int unbanked = graph.createAbstract(AbstractNodeKind.GLOBAL_TELEPORTS_NORMAL, NodeGraph.NO_NODE, false, 0);

		assertTrue(visited.set(banked, graph));

		assertTrue(visited.get(banked, graph));
		assertTrue(visited.get(unbanked, graph));
		assertFalse(visited.set(unbanked, graph));
	}

	@Test
	public void settingUnbankedNodeDoesNotMarkBankedNodeVisited()
	{
		VisitedTiles visited = new VisitedTiles(collisionMap());
		int tile = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		NodeGraph graph = new NodeGraph(16);
		int unbanked = graph.createAbstract(AbstractNodeKind.GLOBAL_TELEPORTS_NORMAL, NodeGraph.NO_NODE, false, 0);
		int banked = graph.createAbstract(AbstractNodeKind.GLOBAL_TELEPORTS_NORMAL, NodeGraph.NO_NODE, true, 0);

		assertTrue(visited.set(tile, false));
		assertTrue(visited.get(tile, false));
		assertFalse(visited.get(tile, true));

		assertTrue(visited.set(unbanked, graph));
		assertTrue(visited.get(unbanked, graph));
		assertFalse(visited.get(banked, graph));
	}
}

package gps.pathfinder;

import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.ShortestPathConfig;
import gps.WorldPointUtil;

/**
 * The Stronghold of Security exit portal (leave-to-surface) and its surface entrance both land on
 * the same tile, so with a zero cost the search used "exit → surface → re-enter" as a FREE hop
 * between two adjacent inside tiles — routing the player needlessly out of the dungeon (user
 * capture 20260716-200841). Giving the exit transports a real duration restores the direct walk.
 */
@RunWith(MockitoJUnitRunner.class)
public class StrongholdExitTest
{
	// Adjacent, directly-walkable inside tiles either side of the exit portal.
	private static final int INSIDE_A = WorldPointUtil.packWorldPoint(2837, 10089, 2);
	private static final int INSIDE_B = WorldPointUtil.packWorldPoint(2837, 10090, 2);

	@Mock Client client;
	@Mock ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	@Test
	public void doesNotLeaveTheStrongholdToCrossOneTile()
	{
		PathfinderConfig cfg = new TestPathfinderConfig(client, config).copyForPlanning();
		cfg.refresh();

		Pathfinder pf = new Pathfinder(cfg, INSIDE_A, Set.of(INSIDE_B));
		pf.run();

		assertTrue(pf.getResult().isReached());
		assertEquals("the two tiles are adjacent — the route must be a single walking step", 1,
			pf.getResult().getTotalCost());
		for (PathStep step : pf.getPath())
		{
			assertTrue("the route must not dip out to the surface: " + step.getPackedPosition(),
				WorldPointUtil.unpackWorldPlane(step.getPackedPosition()) != 0);
		}
	}
}

package gps.pathfinder;

import java.util.EnumSet;
import net.runelite.api.Client;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import gps.ShortestPathConfig;
import gps.WorldPointUtil;
import gps.leagues.LeagueModeState;
import gps.leagues.LeagueRegion;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

@RunWith(MockitoJUnitRunner.class)
public class PathfinderConfigSeasonalTest
{
	private static final int VARROCK_WEST = WorldPointUtil.packWorldPoint(3186, 3438, 0);
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3225, 3220, 0);
	private static final int CIVITAS = WorldPointUtil.packWorldPoint(1781, 3100, 0);
	private static final int FORTIS_CIVITAS_WEST = WorldPointUtil.packWorldPoint(1646, 3112, 0);

	@Mock
	private Client client;
	@Mock
	private ShortestPathConfig config;

	private PathfinderConfig pathfinderConfig;

	@Before
	public void before()
	{
		pathfinderConfig = new TestPathfinderConfig(client, config);
	}

	@Test
	public void avoidBlockedRegionIsNoOpOffSeasonalWorlds()
	{
		LeagueModeState state = pathfinderConfig.getLeagueModeState();
		state.setForTest(false, EnumSet.noneOf(LeagueRegion.class));

		// Walking from Civitas towards Varrock would normally cross from Varlamore into Misthalin.
		// Off-seasonal we expect zero league filtering.
		assertFalse(pathfinderConfig.avoidBlockedRegion(CIVITAS, VARROCK_WEST, false));
		assertFalse(pathfinderConfig.avoidBlockedRegion(VARROCK_WEST, LUMBRIDGE, false));
	}

	@Test
	public void avoidBlockedRegionBlocksMisthalinEntryOnSeasonal()
	{
		LeagueModeState state = pathfinderConfig.getLeagueModeState();
		state.setForTest(true, EnumSet.of(LeagueRegion.KANDARIN));

		// Crossing FROM neutral/varlamore INTO Misthalin must be blocked.
		assertTrue(pathfinderConfig.avoidBlockedRegion(CIVITAS, VARROCK_WEST, false));
	}

