		planning.setPlanningMode(false);
		planning.setConsiderBank(true);
		AlternativeRoutesService service = new AlternativeRoutesService(clientThread, planning);

		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> finalRoutes = new AtomicReference<>(List.of());
		service.generate(varrockCentre, Set.of(cowbellDestination), Set.of(), AlternativeRoutesMode.OWNED_WITH_BANK, 10,
			(routes, catalog, unavailable, isDone) ->
			{
				if (isDone)
				{
					finalRoutes.set(routes);
					done.countDown();
				}
			});
		assertTrue("Generation should complete", done.await(120, TimeUnit.SECONDS));
		service.shutdown();

		RouteOption bankedRoute = finalRoutes.get().stream()
			.filter(r -> r.getMethods().stream().anyMatch(m -> m.getType() == TransportType.TELEPORTATION_ITEM))
			.findFirst().orElse(null);
		assertTrue("A route using the banked teleport item should exist", bankedRoute != null);

		List<PathStep> path = bankedRoute.getPath();
		int firstBankVisited = -1;
		for (int i = 0; i < path.size(); i++)
		{
			if (path.get(i).isBankVisited())
			{
				firstBankVisited = i;
				break;
			}
		}
		assertTrue("Route must pass through a bank (bankVisited must flip)", firstBankVisited >= 0);
		assertTrue("Route must include the walked leg to the bank before the teleport, but bankVisited "
				+ "flipped at step " + firstBankVisited + " of " + path.size(),
			firstBankVisited > 5);
		assertTrue("Route must be flagged as going via the bank (panel indicator)", bankedRoute.isViaBank());
		// The detour must be attributed to the right method: the banked teleport item, and only it —
		// so the panel can say which method the bank walk is for (user report: an equipped Ardougne
		// cloak looked like the reason for a bank trip that was actually for a banked item).
		assertTrue("The bank detour must be attributed to the teleport-item method",
			bankedRoute.getBankMethods().stream().anyMatch(m -> m.getType() == TransportType.TELEPORTATION_ITEM));
		assertTrue("Only bank-gated methods may be attributed to the bank detour",
			bankedRoute.getMethods().containsAll(bankedRoute.getBankMethods()));
	}

	@Test
	public void userExcludedTeleportIsNotSeeded() throws Exception
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.setPlanningMode(false);
		planning.setConsiderBank(false);
		AlternativeRoutesService service = new AlternativeRoutesService(clientThread, planning);

		// Far from Varrock the Varrock Teleport (landing on the target) is the cheapest route, so it
		// surfaces. Capture its method identity from a first, unexcluded run.
		CountDownLatch firstDone = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> firstRoutes = new AtomicReference<>(List.of());
		service.generate(FAR_START, Set.of(TARGET), Set.of(), AlternativeRoutesMode.OWNED_INVENTORY, 10,
			(routes, catalog, unavailable, isDone) ->
			{
				if (isDone)
				{
					firstRoutes.set(routes);
					firstDone.countDown();
				}
			});
		assertTrue(firstDone.await(120, TimeUnit.SECONDS));
		Set<TeleportMethod> spellMethods = new java.util.HashSet<>();
		for (RouteOption route : firstRoutes.get())
		{
			for (TeleportMethod method : route.getMethods())
			{
				if (method.getType() == TransportType.TELEPORTATION_SPELL)
				{
					spellMethods.add(method);
				}
			}
		}
		assertTrue("Precondition: a spell route was found", !spellMethods.isEmpty());

		// Re-run with those methods excluded: no spell route may appear.
		CountDownLatch secondDone = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> secondRoutes = new AtomicReference<>(List.of());
		service.generate(FAR_START, Set.of(TARGET), spellMethods, AlternativeRoutesMode.OWNED_INVENTORY, 10,
			(routes, catalog, unavailable, isDone) ->
			{
				if (isDone)
				{
					secondRoutes.set(routes);
					secondDone.countDown();
				}
			});
		assertTrue(secondDone.await(120, TimeUnit.SECONDS));
		service.shutdown();

		assertTrue("Excluded spell must not be seeded back in",
			secondRoutes.get().stream().noneMatch(r -> r.getMethods().stream().anyMatch(spellMethods::contains)));
	}

	@Test
	public void inBankMethodFlaggedInBankRegardlessOfMode() throws Exception
	{
		// Cowbell amulet only in the bank: the availability map records IN_BANK as the reason in
		// EVERY mode (it's mode-independent — the panel decides usability, and the "Item in the bank"
		// filter needs to see it in bank mode too). The catalog contains the method either way.
		int cowbellDestination = WorldPointUtil.packWorldPoint(3259, 3277, 0);
		PathfinderConfig base = new TestPathfinderConfig(client, config);
		base.setBankSnapshot(new Item[]{new Item(33104, 1)});
		PathfinderConfig planning = base.copyForPlanning();
		planning.setPlanningMode(false);
		planning.setConsiderBank(false);
		AlternativeRoutesService service = new AlternativeRoutesService(clientThread, planning);

		Map<TeleportMethod, MethodAvailability> inventoryUnavailable =
			finalUnavailable(service, AlternativeRoutesMode.OWNED_INVENTORY);
		Map<TeleportMethod, MethodAvailability> bankUnavailable =
			finalUnavailable(service, AlternativeRoutesMode.OWNED_WITH_BANK);
		service.shutdown();

		TeleportMethod cowbell = planning.getMethodCatalog().stream()
			.filter(m -> m.getType() == TransportType.TELEPORTATION_ITEM && m.getDestination() == cowbellDestination)
			.findFirst()
			.orElseThrow(() -> new AssertionError("Cowbell amulet method missing from the catalog"));
		assertTrue("Inventory mode must flag the banked item as IN_BANK",
			inventoryUnavailable.get(cowbell) == MethodAvailability.IN_BANK);
		assertTrue("Inv+bank mode must also record it as IN_BANK (usability is decided by the panel)",
			bankUnavailable.get(cowbell) == MethodAvailability.IN_BANK);
	}

	/**
	 * Runs one generation in the given mode and returns the final update's unavailable map.
	 */
	private Map<TeleportMethod, MethodAvailability> finalUnavailable(
		AlternativeRoutesService service, AlternativeRoutesMode mode) throws Exception
	{
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<Map<TeleportMethod, MethodAvailability>> result = new AtomicReference<>(Map.of());
		service.generate(START, Set.of(TARGET), Set.of(), mode, 10,
			(routes, catalog, unavailable, isDone) ->
			{
				if (isDone)
				{
					result.set(unavailable);
					done.countDown();
				}
			});
		assertTrue("Generation should complete", done.await(120, TimeUnit.SECONDS));
		return result.get();
	}

	@Test
	public void bankPickupWeightChargedExactlyOnceIntoBankedRouteCost() throws Exception
	{
		// Run the same bank-pickup scenario twice: first with no bank-pickup weight, then with a
		// 60-step weight (small enough that banking still beats the ~147-tile walk, so the route isn't
		// dropped by the stop-at-walk rule). The banked route's cost must rise by exactly the weight —
		// charged once on entering the banked state, not per edge. The zero run is clamped to the
		// one-tick floor (MIN_BANK_PICKUP_COST), so the rise is the weight less that floor.
		when(config.costBankPickup()).thenReturn(0, 60);
		int varrockCentre = WorldPointUtil.packWorldPoint(3213, 3424, 0);
		int cowbellDestination = WorldPointUtil.packWorldPoint(3259, 3277, 0);
		doReturn(new Item[]{new Item(33104, 1)}).when(bank).getItems();
		PathfinderConfig base = new TestPathfinderConfig(client, config);
		base.bank = bank;
		PathfinderConfig planning = base.copyForPlanning();
		planning.setPlanningMode(false);
		planning.setConsiderBank(true);
		AlternativeRoutesService service = new AlternativeRoutesService(clientThread, planning);

		int baseline = bankedRouteCost(service, varrockCentre, cowbellDestination);
		int weighted = bankedRouteCost(service, varrockCentre, cowbellDestination);
		service.shutdown();

		assertTrue("Baseline banked route should cost something, got " + baseline, baseline > 0);
		assertTrue("Banked route must carry the 60-step bank-pickup weight exactly once ("
				+ baseline + " -> " + weighted + ")",
			weighted == baseline + 60 - PathfinderConfig.MIN_BANK_PICKUP_COST);
	}

	/**
	 * Runs one Owned/Inv+bank generation and returns the via-bank route's total cost.
	 */
	private int bankedRouteCost(AlternativeRoutesService service, int start, int target) throws Exception
	{
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> finalRoutes = new AtomicReference<>(List.of());
		service.generate(start, Set.of(target), Set.of(), AlternativeRoutesMode.OWNED_WITH_BANK, 10,
			(routes, catalog, unavailable, isDone) ->
			{
				if (isDone)
				{
					finalRoutes.set(routes);
					done.countDown();
				}
			});
		assertTrue("Generation should complete", done.await(120, TimeUnit.SECONDS));
		RouteOption bankedRoute = finalRoutes.get().stream()
			.filter(RouteOption::isViaBank)
			.findFirst().orElse(null);
		assertTrue("A route via the bank should exist", bankedRoute != null);
		return bankedRoute.getTotalCost();
	}

	@Test
	public void routesAreOrderedByEtaWhenUnweighted() throws Exception
	{
		// With no configured weights (the mock returns 0 for every cost item), the blended cost must
		// equal the raw time-normalized cost, so the list order IS the ETA order — the bug this
		// guards against was ticks and tiles blending 1:1, letting a slower route sort first. Each
		// route's raw cost must also decompose exactly into its walked units plus its transport
		// travel times at 2 units per tick.
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.setPlanningMode(false);
		planning.setConsiderBank(false);
		AlternativeRoutesService service = new AlternativeRoutesService(clientThread, planning);

		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> finalRoutes = new AtomicReference<>(List.of());
		service.generate(FAR_START, Set.of(TARGET), Set.of(), AlternativeRoutesMode.OWNED_INVENTORY, 10,
			(routes, catalog, unavailable, isDone) ->
			{
				if (isDone)
				{
					finalRoutes.set(routes);
					done.countDown();
				}
			});
		assertTrue("Generation should complete", done.await(120, TimeUnit.SECONDS));
		service.shutdown();

		List<RouteOption> routes = finalRoutes.get();
		assertTrue("Expected at least a teleport route and the walk option", routes.size() >= 2);
		int previousRaw = Integer.MIN_VALUE;
		for (RouteOption route : routes)
		{
			assertTrue("Unweighted: blended cost must equal the raw (ETA) cost, got "
					+ route.getTotalCost() + " vs " + route.getRawCost(),
				route.getTotalCost() == route.getRawCost());
			assertTrue("Routes must be ordered by ETA (raw cost), got " + route.getRawCost()
					+ " after " + previousRaw,
				route.getRawCost() >= previousRaw);
			previousRaw = route.getRawCost();

			int walked = route.getTrailingWalkSteps();
			int transportUnits = 0;
			for (int m = 0; m < route.getMethods().size(); m++)
			{
				walked += route.walkBefore(m);
			}
			for (int duration : route.getMethodDurations())
			{
				transportUnits += CostUnits.fromTicks(duration);
			}
			assertTrue("Raw cost must decompose into walk units + 2×duration ticks ("
					+ route.getRawCost() + " != " + walked + " + " + transportUnits + ")",
				route.getRawCost() == walked + transportUnits);
		}
	}

	@Test
	public void roundTripRoutesGoOutAndComeBack() throws Exception
	{
		// "Bank (and back)": every produced route must end where it started, be flagged as a round
		// trip, and the list must be ranked by the combined out-and-back cost.
		int varrockCentre = WorldPointUtil.packWorldPoint(3213, 3424, 0);
		Set<Integer> bankTiles = gps.Destinations.tilesForCategory("bank_round_trip", null);
		assertTrue("Round-trip category must resolve to the bank tiles",
			bankTiles.equals(gps.Destinations.tilesForCategory("bank", null)) && !bankTiles.isEmpty());

		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.setPlanningMode(false);
		planning.setConsiderBank(false);
		AlternativeRoutesService service = new AlternativeRoutesService(clientThread, planning);

		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> finalRoutes = new AtomicReference<>(List.of());
		service.generate(varrockCentre, bankTiles, Set.of(), AlternativeRoutesMode.OWNED_INVENTORY, 5, 0, true,
			(routes, catalog, unavailable, isDone) ->
			{
				if (isDone)
				{
					finalRoutes.set(routes);
					done.countDown();
				}
			});
		assertTrue("Generation should complete", done.await(120, TimeUnit.SECONDS));
		service.shutdown();

		List<RouteOption> routes = finalRoutes.get();
		assertTrue("Round-trip routes should be found", !routes.isEmpty());
		int previousCost = -1;
		for (RouteOption route : routes)
		{
			assertTrue("Every route must be flagged as a round trip", route.isRoundTrip());
			assertTrue("Every route must reach", route.isReached());
			int first = route.getPath().get(0).getPackedPosition();
			int last = route.getPath().get(route.getPath().size() - 1).getPackedPosition();
			assertTrue("The route must start at the player", first == varrockCentre);
			assertTrue("The route must END back at the player (round trip), ended "
					+ WorldPointUtil.distanceBetween(last, varrockCentre) + " tiles away",
				last == varrockCentre);
			// The turnaround (where the outbound leg ends — the bank) must be a real interior
			// index away from the start: progress/arrival gate the return leg behind it.
			int turnaround = route.getTurnaroundIndex();
			assertTrue("Turnaround must be an interior path index, got " + turnaround,
				turnaround > 0 && turnaround < route.getPath().size() - 1);
			assertTrue("The turnaround tile must not be the start tile",
				route.getPath().get(turnaround).getPackedPosition() != varrockCentre);
			assertTrue("Routes must be ranked by combined cost", route.getTotalCost() >= previousCost);
			previousCost = route.getTotalCost();
		}
	}

	@Test
	public void everythingModeSurfacesTeleportsWithoutOwnedItems() throws Exception
	{
		// No inventory at all: the Owned modes could only walk, but "Everything" bypasses possession,
		// so teleport routes must still be offered.
		when(client.getItemContainer(InventoryID.INV)).thenReturn(null);
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		AlternativeRoutesService service = new AlternativeRoutesService(clientThread, planning);

		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> finalRoutes = new AtomicReference<>(List.of());
		service.generate(FAR_START, Set.of(TARGET), Set.of(), AlternativeRoutesMode.ALL_EVERYTHING, 10,
			(routes, catalog, unavailable, isDone) ->
			{
				if (isDone)
				{
					finalRoutes.set(routes);
					done.countDown();
				}
			});
		assertTrue("Generation should complete", done.await(120, TimeUnit.SECONDS));
		service.shutdown();

		assertTrue("Everything mode must offer teleport routes despite owning no items",
			finalRoutes.get().stream().anyMatch(r -> !r.getMethods().isEmpty()));
	}
}

package gps.pathfinder;

import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import org.junit.Test;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;
import gps.MethodAvailability;
import gps.ShortestPathConfig;
import gps.TeleportMethod;
import gps.transport.TransportType;

/**
 * The catalog's availability classification also records WHAT is missing, so the panel's lock
 * tooltip can say "Requires 40 Firemaking" or "Missing item: Willow logs" instead of a generic
 * category. The Varrock balloon flight is the probe: it carries a Firemaking level and a willow-log
 * requirement, and its unlock varbits are bypassed by the test config.
 */
public class MethodAvailabilityDetailTest
{
	private static final int WILLOW_LOGS = 1519;

	private PathfinderConfig planningConfig(int boostedLevel, boolean stubWillowName)
	{
		Client client = mock(Client.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(boostedLevel);
		if (stubWillowName)
		{
			ItemComposition willow = mock(ItemComposition.class);
			when(willow.getName()).thenReturn("Willow logs");
			when(client.getItemDefinition(WILLOW_LOGS)).thenReturn(willow);
		}
		ShortestPathConfig config = mock(ShortestPathConfig.class);
		when(config.calculationCutoff()).thenReturn(30);
		// The classifier now locks switched-off travel options first; balloons are the subject here.
		lenient().when(config.useHotAirBalloons()).thenReturn(true);
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		return planning;
	}

	private static TeleportMethod varrockFlight(PathfinderConfig config)
	{
		for (TeleportMethod method : config.getMethodAvailability().keySet())
		{
			if (TransportType.HOT_AIR_BALLOON.equals(method.getType())
				&& "Varrock".equals(method.getDisplayInfo()))
			{
				return method;
			}
		}
		return null;
	}

	@Test
	public void missingLevelNamesTheSkillAndLevel()
	{
		PathfinderConfig config = planningConfig(1, false);
		TeleportMethod flight = varrockFlight(config);
		assertNotNull("the Varrock balloon flight must be in the catalog", flight);
		assertEquals(MethodAvailability.MISSING_LEVEL, config.getMethodAvailability().get(flight));
		assertEquals("Requires 40 Firemaking", config.getMethodAvailabilityDetail().get(flight));
	}

	@Test
	public void missingItemNamesTheItem()
	{
		PathfinderConfig config = planningConfig(99, true);
		TeleportMethod flight = varrockFlight(config);
		assertNotNull("the Varrock balloon flight must be in the catalog", flight);
		assertEquals(MethodAvailability.MISSING_ITEM, config.getMethodAvailability().get(flight));
		assertEquals("Missing item: Willow logs", config.getMethodAvailabilityDetail().get(flight));
	}

	@Test
	public void unnameableDetailsFallBackToNoEntry()
	{
		// Without an item definition source (the common test/mocked case), the status is still
		// classified but the detail map simply has no entry — the panel falls back to its generic
		// per-status wording.
		PathfinderConfig config = planningConfig(99, false);
		TeleportMethod flight = varrockFlight(config);
		assertNotNull(flight);
		assertEquals(MethodAvailability.MISSING_ITEM, config.getMethodAvailability().get(flight));
		Map<TeleportMethod, String> details = config.getMethodAvailabilityDetail();
		assertEquals(null, details.get(flight));
	}
}

package gps.pathfinder;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.ShortestPathConfig;
import gps.TeleportMethod;
import gps.WorldPointUtil;
import gps.transport.Transport;

/**
 * The walk-out-of-the-wilderness scenario: global teleports unlock by wilderness band (the
 * abstract-hub-per-band machinery), so from deep wilderness the optimal route must WALK to the
 * first tile of a more permissive band and cast from there — no explicit "exit tile" is ever
 * chosen; it falls out of cost ordering. This pins:
 * <ul>
 * <li>the route walks (adjacent steps only) out of the level-30+ band and casts while still
 * inside the wilderness — at the earliest legal band, not after leaving entirely;</li>
 * <li>both the uninformed search and A* return the ORACLE's exact cost — the heuristic's field
 * deliberately ignores wilderness gates (underestimates are safe), and this proves that
 * blindness costs nothing in correctness.</li>
 * </ul>
 * Wilderness-origin escapes (obelisks, the lever) are excluded so the scenario genuinely
 * requires walking out; global teleports keep no origin and cannot be excluded that way.
 */
@RunWith(MockitoJUnitRunner.class)
public class WildernessEscapeTest
{
	// The Wilderness Agility Course entrance — deep wilderness (level ~52), verified walkable.
	private static final int DEEP_WILDERNESS = WorldPointUtil.packWorldPoint(3004, 3937, 0);
	private static final int VARROCK = WorldPointUtil.packWorldPoint(3213, 3424, 0);

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	@Test
	public void walksToTheFirstLegalBandThenTeleports()
	{
		assertTrue("premise: the start must lie in level-30+ wilderness",
			WildernessChecker.isInLevel30Wilderness(DEEP_WILDERNESS));

		PathfinderConfig cfg = new TestPathfinderConfig(client, config).copyForPlanning();
		cfg.refresh();

		// Exclude every method whose transport ORIGINATES inside the wilderness (obelisks, the
		// lever, boats...): those are dedicated deep-wildy escapes that would short-circuit the
		// scenario. What remains is walking plus origin-free global teleports.
		Set<TeleportMethod> wildernessOriginMethods = new HashSet<>();
		for (int origin : cfg.getTransportsPacked(false).keys())
		{
			if (!WildernessChecker.isInWilderness(origin))
			{
				continue;
			}
			for (Transport transport : cfg.getTransportsPacked(false).get(origin))
			{
				if (TeleportMethod.isMethodType(transport.getType()))
				{
					wildernessOriginMethods.add(TeleportMethod.fromTransport(transport));
				}
			}
		}
		cfg.rebuildAvailabilityWithExclusions(wildernessOriginMethods);

		Set<Integer> targets = Set.of(VARROCK);
		ReferenceDijkstra.Result oracle = ReferenceDijkstra.search(cfg, DEEP_WILDERNESS, targets);
		assertTrue("oracle must reach Varrock", oracle.reached);

		Pathfinder uninformed = new Pathfinder(cfg, DEEP_WILDERNESS, targets, Integer.MAX_VALUE, null);
		uninformed.run();
		assertEquals("uninformed search must match the oracle",
			oracle.cost, uninformed.getResult().getTotalCost());

		DistanceField field = DistanceField.build(cfg, targets);
		SearchHeuristic heuristic = SearchHeuristic.buildWithField(cfg, field);
		assertNotNull(heuristic);
		Pathfinder astar = new Pathfinder(cfg, DEEP_WILDERNESS, targets, Integer.MAX_VALUE, heuristic);
		astar.run();
		assertEquals("A* must match the oracle despite the field ignoring wilderness gates",
			oracle.cost, astar.getResult().getTotalCost());

		// The route's shape: a genuine walk (adjacent steps only) out of the 30+ band, then a
		// teleport jump cast INSIDE the wilderness below level 30 — the earliest legal band.
		List<PathStep> path = astar.getResult().getPathSteps();
		// A TELEPORT jump spans the map; agility obstacles along the way (the course's pipes and
		// ledges) also step >1 tile but only a handful — distinguish by span.
		int jumpIndex = -1;
		for (int i = 1; i < path.size(); i++)
		{
			if (WorldPointUtil.distanceBetween(
				path.get(i - 1).getPackedPosition(), path.get(i).getPackedPosition()) > 20)
			{
				jumpIndex = i;
				break;
			}
		}
		assertTrue("the route must contain a teleport jump", jumpIndex > 0);
		assertTrue("the walk out must be a real walk (dozens of steps), got " + jumpIndex,
			jumpIndex > 50);

		int castTile = path.get(jumpIndex - 1).getPackedPosition();
		assertTrue("the cast tile " + WorldPointUtil.unpackWorldPoint(castTile)
				+ " must be below the level-30 band (where teleports first unlock)",
			!WildernessChecker.isInLevel30Wilderness(castTile));
		assertTrue("the cast must happen while still INSIDE the wilderness — at the earliest legal"
				+ " band, not after walking all the way out",
			WildernessChecker.isInWilderness(castTile));
	}
}

package gps.pathfinder;

