/**
 * The Auburn Valley Mountain Guide (npc 14529, Quetzacalli Gorge <-> Auburn Valley) must be
 * traversable: both endpoints walkable, the transport registered at each origin, and a route from
 * beside the gorge guide to Auburn Valley taking the guide edge. Guards the gate/data regressions
 * that hid it (an unverifiable exact-equality varbit requirement).
 */
@RunWith(MockitoJUnitRunner.class)
public class MountainGuideTest
{
	private static final int GORGE_GUIDE = WorldPointUtil.packWorldPoint(1486, 3232, 0);
	private static final int AUBURN_GUIDE = WorldPointUtil.packWorldPoint(1361, 3309, 0);

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	@Test
	public void guideRouteIsTraversableAndTaken()
	{
		PathfinderConfig cfg = new TestPathfinderConfig(client, config).copyForPlanning();
		cfg.refresh();

		assertEquals("guide transport must be registered at the gorge origin", 1,
			cfg.getTransportsPacked(false).getOrDefault(GORGE_GUIDE, TransportAvailability.EMPTY_TRANSPORTS).length);
		assertEquals("guide transport must be registered at the Auburn origin", 1,
			cfg.getTransportsPacked(false).getOrDefault(AUBURN_GUIDE, TransportAvailability.EMPTY_TRANSPORTS).length);

		Pathfinder pathfinder = new Pathfinder(cfg, WorldPointUtil.packWorldPoint(1490, 3230, 0), Set.of(AUBURN_GUIDE));
		pathfinder.run();
		assertTrue("route beside the gorge guide must reach Auburn Valley", pathfinder.getResult().isReached());
		List<PathStep> path = pathfinder.getResult().getPathSteps();
		boolean usedGuide = false;
		for (int i = 1; i < path.size(); i++)
		{
			if (path.get(i - 1).getPackedPosition() == GORGE_GUIDE && path.get(i).getPackedPosition() == AUBURN_GUIDE)
			{
				usedGuide = true;
			}
		}
		assertTrue("the route must take the mountain guide edge", usedGuide);
	}
}

package gps.pathfinder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;
import gps.WorldPointUtil;

/**
 * Pins down the cost formulas and flag bookkeeping of the structure-of-arrays node store so a
 * regression in any of the three distinct cost rules (tile walk, transport, abstract) fails fast.
 * The expected values mirror the maths of the old {@code Node}/{@code TransportNode} classes.
 */
public class NodeGraphTest
{
	@Test
	public void startNodeHasZeroCostAndNoPrevious()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(WorldPointUtil.packWorldPoint(3200, 3200, 0));

		assertEquals(0, graph.cost(start));
		assertEquals(NodeGraph.NO_NODE, graph.previous(start));
		assertTrue(graph.isTile(start));
		assertFalse(graph.isAbstract(start));
		assertFalse(graph.isTransport(start));
		assertFalse(graph.bankVisited(start));
	}

	@Test
	public void tileFromTileAddsWalkingDistance()
	{
		NodeGraph graph = new NodeGraph(16);
		int a = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int b = WorldPointUtil.packWorldPoint(3205, 3203, 0);
		int start = graph.createStart(a);
		int tile = graph.createTile(b, start, false, 0);

		assertEquals(WorldPointUtil.distanceBetween(a, b), graph.cost(tile));
		assertEquals(start, graph.previous(tile));
		assertTrue(graph.isTile(tile));
		// With no heuristic the queue-ordering key is EXACTLY the accumulated cost.
		assertEquals(graph.cost(tile), graph.orderCost(tile));
	}

	@Test
	public void tileFromAbstractAddsNoWalkingDistance()
	{
		NodeGraph graph = new NodeGraph(16);
		int a = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int b = WorldPointUtil.packWorldPoint(3300, 3300, 0);
		int start = graph.createStart(a);
		int tileBeforeAbstract = graph.createTile(WorldPointUtil.packWorldPoint(3201, 3200, 0), start, false, 0);
		int abstractNode = graph.createAbstract(AbstractNodeKind.GLOBAL_TELEPORTS_NORMAL, tileBeforeAbstract, true, 0);
		int tileFromAbstract = graph.createTile(b, abstractNode, true, 0);

		// Reaching a tile from an abstract node adds no travel cost: it inherits the abstract cost.
		assertEquals(graph.cost(abstractNode), graph.cost(tileFromAbstract));
		assertTrue(graph.bankVisited(tileFromAbstract));
	}

	@Test
	public void tileEdgeAddsExtraCost()
	{
		NodeGraph graph = new NodeGraph(16);
		int a = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int b = WorldPointUtil.packWorldPoint(3205, 3203, 0);
		int start = graph.createStart(a);
		// The bank-pickup surcharge is charged on the edge that first enters the banked state.
		int tile = graph.createTile(b, start, true, 50);

		assertEquals(WorldPointUtil.distanceBetween(a, b) + 50, graph.cost(tile));
		assertTrue(graph.bankVisited(tile));
	}

	@Test
	public void abstractNodeAddsExtraCost()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(WorldPointUtil.packWorldPoint(3200, 3200, 0));
		int tile = graph.createTile(WorldPointUtil.packWorldPoint(3210, 3200, 0), start, false, 0);
		int abstractNode = graph.createAbstract(AbstractNodeKind.GLOBAL_TELEPORTS_NORMAL, tile, true, 50);

		// A global teleport reached via a bank inherits the bank-pickup surcharge from the abstract node.
		assertEquals(graph.cost(tile) + 50, graph.cost(abstractNode));
		assertTrue(graph.bankVisited(abstractNode));
	}

	@Test
	public void abstractInheritsPreviousCostAndCarriesKind()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(WorldPointUtil.packWorldPoint(3200, 3200, 0));
		int tile = graph.createTile(WorldPointUtil.packWorldPoint(3210, 3200, 0), start, false, 0);
		int abstractNode = graph.createAbstract(AbstractNodeKind.GLOBAL_TELEPORTS_OVER_30, tile, false, 0);

		assertEquals(graph.cost(tile), graph.cost(abstractNode));
		assertTrue(graph.isAbstract(abstractNode));
		assertFalse(graph.isTile(abstractNode));
		assertEquals(AbstractNodeKind.GLOBAL_TELEPORTS_OVER_30, graph.abstractKind(abstractNode));
		assertEquals(WorldPointUtil.UNDEFINED, graph.packedPosition(abstractNode));
	}

	@Test
	public void transportCostIsPreviousPlusTravelAndAdditionalWithNoDistance()
	{
		NodeGraph graph = new NodeGraph(16);
		int origin = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int destination = WorldPointUtil.packWorldPoint(2800, 3400, 0);
		int start = graph.createStart(origin);
		int prev = graph.createTile(WorldPointUtil.packWorldPoint(3201, 3200, 0), start, false, 0);

		int travelTime = 6;
		int additionalCost = 50;
		int transport = graph.createTransport(destination, prev, travelTime, additionalCost, false);

		// No walking-distance term for transports, unlike a walked tile.
		assertEquals(graph.cost(prev) + travelTime + additionalCost, graph.cost(transport));
		// The queue-ordering key is the cost and nothing else (no heuristic attached here): an
		// ordering-only term would break the first-settle-is-optimal invariant.
		assertEquals(graph.cost(transport), graph.orderCost(transport));
		assertTrue(graph.isTransport(transport));
		assertTrue(graph.isTile(transport)); // transports are concrete tile destinations
	}

	@Test
	public void bankVisitedTransportKeepsTheFlagAndPureCostKey()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(WorldPointUtil.packWorldPoint(3200, 3200, 0));
		int transport = graph.createTransport(WorldPointUtil.packWorldPoint(2800, 3400, 0), start, 6, 0, true);

		assertTrue(graph.isTransport(transport));
		assertEquals(graph.cost(transport), graph.orderCost(transport));
		assertTrue(graph.bankVisited(transport));
	}

	@Test
	public void pathStepsSkipAbstractNodesInOrder()
	{
		NodeGraph graph = new NodeGraph(16);
		int a = WorldPointUtil.packWorldPoint(3200, 3200, 0);
		int b = WorldPointUtil.packWorldPoint(3201, 3200, 0);
		int c = WorldPointUtil.packWorldPoint(2800, 3400, 0);
		int start = graph.createStart(a);
		int tile = graph.createTile(b, start, false, 0);
		int abstractNode = graph.createAbstract(AbstractNodeKind.GLOBAL_TELEPORTS_NORMAL, tile, false, 0);
		int teleportDest = graph.createTransport(c, abstractNode, 6, 0, false);

		var steps = graph.getPathSteps(teleportDest);
		assertEquals(3, steps.size()); // start, tile, teleportDest (abstract is skipped)
		assertEquals(a, steps.get(0).getPackedPosition());
		assertEquals(b, steps.get(1).getPackedPosition());
		assertEquals(c, steps.get(2).getPackedPosition());

		assertEquals(c, graph.getClosestTilePosition(teleportDest));
		assertEquals(b, graph.getClosestTilePosition(abstractNode));
	}

	@Test
	public void releaseMakesChainWalksReturnEmpty()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(WorldPointUtil.packWorldPoint(3200, 3200, 0));
		graph.release();

		assertTrue(graph.getPathSteps(start).isEmpty());
		assertEquals(WorldPointUtil.UNDEFINED, graph.getClosestTilePosition(start));
	}
}

package gps.pathfinder;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.PrimitiveIntHashMap;
import gps.ShortestPathConfig;
import gps.WorldPointUtil;
import gps.transport.Transport;

/**
 * Invariants of the target-rooted distance field: targets are zero, values lower-bound real
 * search costs (admissibility — the property the A* heuristic's exactness rests on), and
 * reverse-unreachable places stay unreached.
 */
@RunWith(MockitoJUnitRunner.class)
public class DistanceFieldTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int VARROCK = WorldPointUtil.packWorldPoint(3213, 3424, 0);
	private static final int ENTRANA = WorldPointUtil.packWorldPoint(2830, 3335, 0);

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	private PathfinderConfig walkOnlyConfig()
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		planning.rebuildAvailabilityWithExclusions(planning.getMethodCatalog());
		return planning;
	}

	@Test
	public void fieldLowerBoundsTheRealWalkCostAndIsZeroAtTargets()
	{
		PathfinderConfig config = walkOnlyConfig();
		DistanceField field = DistanceField.build(config, Set.of(VARROCK));

		assertEquals("A target tile must be at distance zero", 0, field.distance(VARROCK));

		Pathfinder walk = new Pathfinder(config, LUMBRIDGE, Set.of(VARROCK), Integer.MAX_VALUE, null);
		walk.run();
		int walkCost = walk.getResult().getTotalCost();
		int fieldAtStart = field.distance(LUMBRIDGE);
		assertTrue("Field must be reached at the start tile", fieldAtStart != DistanceField.UNREACHED);
		assertTrue("Field must lower-bound the real walk cost (" + fieldAtStart + " vs " + walkCost + ")",
			fieldAtStart <= walkCost);
		assertTrue("Field must be a meaningful distance, not zero", fieldAtStart > 100);

		// Admissibility along the actual route: at every step, the field may never exceed the
		// cost still ahead of that step (this is exactly the property A* exactness rests on).
		List<PathStep> path = walk.getResult().getPathSteps();
		for (int i = 0; i < path.size(); i++)
		{
			int remaining = walkCost - (i == 0 ? 0 : pathCostUpTo(path, i));
			int h = field.distance(path.get(i).getPackedPosition());
			assertTrue("Field overestimates at step " + i + " (" + h + " > " + remaining + ")",
				h == DistanceField.UNREACHED || h <= remaining);
		}
	}

	/** Walking cost accumulated up to step index (walk-only paths move 1 tile per step). */
	private static int pathCostUpTo(List<PathStep> path, int index)
	{
		int cost = 0;
		for (int i = 1; i <= index; i++)
		{
			cost += Math.max(1, WorldPointUtil.distanceBetween(
				path.get(i - 1).getPackedPosition(), path.get(i).getPackedPosition()));
		}
		return cost;
	}

	@Test
	public void reverseUnreachableIslandStaysUnreached()
	{
		// Entrana is boat-only; with every method excluded nothing walks there, so the island must
		// not be flooded from a mainland target — its heuristic falls back to the floor.
		DistanceField field = DistanceField.build(walkOnlyConfig(), Set.of(VARROCK));
		assertEquals("The island must be reverse-unreachable",
			DistanceField.UNREACHED, field.distance(ENTRANA));
	}

	/**
	 * The reverse index must fold every (destination, origin) pair to a single min-cost entry — a
	 * transport not gated on banking is present in both bank-state availability maps, and distinct
	 * methods can share an origin and landing, so the raw data holds duplicate/redundant edges the
	 * index is expected to collapse. Verified by independently reducing the raw availability the same
	 * way and asserting the index matches exactly.
	 */
	@Test
	public void reverseIndexKeepsOneMinCostEntryPerOrigin()
	{
		PathfinderConfig cfg = new TestPathfinderConfig(client, config).copyForPlanning();
		cfg.refresh();

		Map<Integer, Map<Integer, Integer>> expected = new HashMap<>();
		for (boolean bankVisited : new boolean[]{false, true})
		{
			PrimitiveIntHashMap<Transport[]> transports = cfg.getTransportsPacked(bankVisited);
			for (int origin : transports.keys())
			{
				Transport[] set = transports.get(origin);
				if (set == null)
				{
					continue;
				}
				for (Transport t : set)
				{
					if (t.getDestination() == WorldPointUtil.UNDEFINED
						|| t.getOrigin() == WorldPointUtil.UNDEFINED)
					{
						continue;
					}
					int cost = Math.max(0, CostUnits.fromTicks(t.getDuration())
						+ cfg.getAdditionalTransportCost(t));
					expected.computeIfAbsent(t.getDestination(), k -> new HashMap<>())
						.merge(t.getOrigin(), cost, Math::min);
				}
			}
		}

		PrimitiveIntHashMap<Map<Integer, Integer>> index = DistanceField.buildReverseTransportIndex(cfg);
		assertFalse("The transport data must produce some reverse edges for this test to mean anything",
			index.size() == 0);
		int[] landings = index.keys();
		assertEquals("Every landing (and only those) must be indexed", expected.size(), landings.length);
		for (int landing : landings)
		{
			// A Map<origin, cost> can't hold a duplicate origin, and each value must be the minimum
			// cost across both bank states — exactly the reduction computed above.
			assertEquals("One min-cost entry per origin at landing " + landing,
				expected.get(landing), index.get(landing));
		}
	}

	@Test
	public void multiSourceFieldTakesTheNearestTarget()
	{
		PathfinderConfig config = walkOnlyConfig();
		DistanceField single = DistanceField.build(config, Set.of(VARROCK));
		DistanceField multi = DistanceField.build(config, Set.of(VARROCK, LUMBRIDGE));
		assertEquals("A tile that IS a target must be zero in the multi-source field",
			0, multi.distance(LUMBRIDGE));
		assertTrue("Multi-source distances can only shrink",
			multi.distance(WorldPointUtil.packWorldPoint(3250, 3300, 0))
				<= single.distance(WorldPointUtil.packWorldPoint(3250, 3300, 0)));
	}
}

package gps.pathfinder;

import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.ShortestPathConfig;
import gps.TeleportationItem;
import gps.WorldPointUtil;

/**
 * The A* correctness contract: with a consistent heuristic the search must produce EXACTLY the
 * same costs as the uninformed (Dijkstra) search — only the exploration order and explored-set
 * size may differ. Every scenario runs both ways on the real collision map and compares. The
 * heuristic is force-engaged (zero floor gate) so the saturated-floor cases — where ordering bugs
 * would hide — are exercised too.
 */
@RunWith(MockitoJUnitRunner.class)
public class AStarEquivalenceTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int VARROCK = WorldPointUtil.packWorldPoint(3213, 3424, 0);
	private static final int FALADOR = WorldPointUtil.packWorldPoint(2965, 3380, 0);
	private static final int DRAYNOR = WorldPointUtil.packWorldPoint(3093, 3245, 0);
	private static final int BARROWS = WorldPointUtil.packWorldPoint(3566, 3291, 0);
	private static final int ENTRANA = WorldPointUtil.packWorldPoint(2830, 3335, 0);
	private static final int COWBELL_DESTINATION = WorldPointUtil.packWorldPoint(3259, 3277, 0);
	private static final int COWBELL_AMULET = 33104;

	@Mock
	Client client;
	@Mock
	net.runelite.api.ItemContainer bank;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	/** Runs one search and returns the pathfinder (search finished synchronously). */
	private static Pathfinder run(PathfinderConfig config, int start, Set<Integer> targets, SearchHeuristic heuristic)
	{
		Pathfinder pathfinder = new Pathfinder(config, start, targets, Integer.MAX_VALUE, heuristic);
		pathfinder.run();
		return pathfinder;
	}

	/** An Everything-mode planning copy (possession and unlocks bypassed), refreshed. */
	private PathfinderConfig everythingConfig()
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		return planning;
	}

	/** A walk-only variant: every travel method excluded, plain connectors remain. */
	private PathfinderConfig walkOnlyConfig()
	{
		PathfinderConfig planning = everythingConfig();
		planning.rebuildAvailabilityWithExclusions(planning.getMethodCatalog());
		return planning;
	}

	/** Field-mode equivalence: same contract, with the near-exact distance-field heuristic. */
	private static int[] assertEquivalentWithField(PathfinderConfig config, int start, Set<Integer> targets)
	{
		Pathfinder dijkstra = run(config, start, targets, null);
		DistanceField distanceField = DistanceField.build(config, targets);
		SearchHeuristic heuristic = SearchHeuristic.buildWithField(config, distanceField);
		assertNotNull("Field heuristic must build", heuristic);
		Pathfinder astar = run(config, start, targets, heuristic);

		assertEquals("reached must match (field mode)",
			dijkstra.getResult().isReached(), astar.getResult().isReached());
		assertEquals("total cost must be identical (field mode)",
			dijkstra.getResult().getTotalCost(), astar.getResult().getTotalCost());
		System.out.println("field-equivalent: cost " + dijkstra.getResult().getTotalCost()
			+ ", nodes dijkstra=" + dijkstra.getStats().getNodesChecked()
			+ " astar=" + astar.getStats().getNodesChecked());
		return new int[]{
			dijkstra.getStats().getNodesChecked(),
			astar.getStats().getNodesChecked()};
	}

	@Test
	public void fieldModeWalkRouteIsIdenticalAndCollapses()
	{
		int[] nodes = assertEquivalentWithField(walkOnlyConfig(), LUMBRIDGE, Set.of(VARROCK));
		assertTrue("The field heuristic must collapse a directed walk to a corridor ("
				+ nodes[0] + " -> " + nodes[1] + ")",
			nodes[1] < nodes[0] / 20);
	}

	/** Direction changes along a path — the zigzag metric (a straight run changes direction once). */
	private static int directionChanges(java.util.List<PathStep> path)
	{
		int changes = 0;
		int lastDx = 99;
		int lastDy = 99;
		for (int i = 1; i < path.size(); i++)
		{
			int prev = path.get(i - 1).getPackedPosition();
			int cur = path.get(i).getPackedPosition();
			int dx = Integer.signum(WorldPointUtil.unpackWorldX(cur) - WorldPointUtil.unpackWorldX(prev));
			int dy = Integer.signum(WorldPointUtil.unpackWorldY(cur) - WorldPointUtil.unpackWorldY(prev));
			if (dx != lastDx || dy != lastDy)
			{
				changes++;
				lastDx = dx;
				lastDy = dy;
			}
		}
		return changes;
	}

	@Test
	public void fieldModePathShapeDoesNotZigzag()
	{
		// Equal-cost corridors make every tile share the same f value; without the heap's
		// creation-order tie-break those pops are arbitrary and the path zigzags between cardinal
		// and diagonal steps (in-game report: erratic drawn path vs the game's straight walk).
		// The A* path must stay in the same shape class as the FIFO search's.
		PathfinderConfig config = walkOnlyConfig();
		Pathfinder dijkstra = run(config, LUMBRIDGE, Set.of(VARROCK), null);
		DistanceField field = DistanceField.build(config, Set.of(VARROCK));
		Pathfinder astar = run(config, LUMBRIDGE, Set.of(VARROCK),
			SearchHeuristic.buildWithField(config, field));

		int dijkstraChanges = directionChanges(dijkstra.getResult().getPathSteps());
		int astarChanges = directionChanges(astar.getResult().getPathSteps());
		System.out.println("shape: direction changes dijkstra=" + dijkstraChanges + " astar=" + astarChanges
			+ " (path " + astar.getResult().getPathSteps().size() + " steps)");
		assertTrue("A* path must not zigzag (direction changes " + astarChanges
				+ " vs Dijkstra's " + dijkstraChanges + ")",
			astarChanges <= dijkstraChanges + 5);
	}

	@Test
	public void fieldModeTeleportRouteCostsAreIdentical()
	{
		assertEquivalentWithField(everythingConfig(), LUMBRIDGE, Set.of(BARROWS));
	}

	@Test
	public void fieldModeBankedRouteCostsAreIdentical()
	{
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.NONE);
		when(config.currencyThreshold()).thenReturn(10000000);
		doReturn(new Item[]{new Item(COWBELL_AMULET, 1)}).when(bank).getItems();
		when(client.getItemContainer(InventoryID.INV)).thenReturn(null);
		TestPathfinderConfig base = new TestPathfinderConfig(client, config);
		base.bank = bank;
		PathfinderConfig planning = base.copyForPlanning();
		planning.setPlanningMode(false);
		planning.setBypassItemPossession(false);
		planning.setConsiderBank(true);
		planning.refresh();

		assertEquivalentWithField(planning, VARROCK, Set.of(COWBELL_DESTINATION));
	}

	@Test
	public void fieldModeMultiTargetReachesTheSameCheapestTarget()
	{
		assertEquivalentWithField(walkOnlyConfig(), LUMBRIDGE, Set.of(VARROCK, FALADOR, DRAYNOR));
	}

	@Test
	public void fieldModeUnreachableTargetYieldsTheSameClosestTile()
	{
		PathfinderConfig config = walkOnlyConfig();
		Pathfinder dijkstra = run(config, LUMBRIDGE, Set.of(ENTRANA), null);
		DistanceField distanceField = DistanceField.build(config, Set.of(ENTRANA));
		SearchHeuristic heuristic = SearchHeuristic.buildWithField(config, distanceField);
		assertNotNull(heuristic);
		Pathfinder astar = run(config, LUMBRIDGE, Set.of(ENTRANA), heuristic);

		assertEquals("neither search may reach the island (field mode)",
			false, dijkstra.getResult().isReached() || astar.getResult().isReached());
		assertEquals("both must fall back to the same closest reachable tile (field mode)",
			dijkstra.getResult().getClosestReachedPoint(), astar.getResult().getClosestReachedPoint());
		assertEquals("and at the same cost (field mode)",
			dijkstra.getResult().getTotalCost(), astar.getResult().getTotalCost());
	}

}

