	public void testBankPathDJPvsAKQTarget()
	{
		int castleWars = WorldPointUtil.packWorldPoint(2442, 3083, 0);
		int djpFairyRing = WorldPointUtil.packWorldPoint(2658, 3230, 0); // Near Kandarin Monastery
