package gps.pathfinder;

import static org.junit.Assert.assertEquals;
import org.junit.Test;
import gps.WorldPointUtil;

/**
 * Covers the time-normalized cost model: one cost unit = one run-tile = half a game tick (0.3s),
 * transport travel time converts at 2 units per tick, and every edge is clamped at free so a
 * negative configured weight can make a method free but never pay the route back (Dijkstra needs
 * non-negative edges).
 */
public class CostModelTest
{
	private static final int A = WorldPointUtil.packWorldPoint(3200, 3200, 0);
	private static final int B = WorldPointUtil.packWorldPoint(3201, 3200, 0);
	private static final int C = WorldPointUtil.packWorldPoint(3250, 3250, 0);

	@Test
	public void transportTravelTimeConvertsAtTwoUnitsPerTick()
	{
		assertEquals("A game tick covers 2 run-tiles", 2, CostUnits.UNITS_PER_TICK);
		assertEquals(10, CostUnits.fromTicks(5));
		assertEquals(0, CostUnits.fromTicks(0));
		// The unit really is real time: units * seconds-per-unit == ticks * 0.6s.
		assertEquals(5 * 0.6, CostUnits.fromTicks(5) * CostUnits.SECONDS_PER_UNIT, 1e-9);
	}

	@Test
	public void walkingEdgeCostsItsTileDistance()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(A);
		int step = graph.createTile(B, start, false, 0);
		assertEquals("One walked tile = one unit", 1, graph.cost(step));
	}

	@Test
	public void transportEdgeChargesTravelTimePlusWeight()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(A);
		int viaTransport = graph.createTransport(C, start, CostUnits.fromTicks(5), 7, false);
		assertEquals("5 ticks of travel (10 units) + weight 7", 17, graph.cost(viaTransport));
	}

	@Test
	public void negativeWeightClampsTheTransportEdgeAtFree()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(A);
		int walked = graph.createTile(B, start, false, 0); // cost 1
		// Travel 3 ticks (6 units) with a -20 favor weight: the edge is free, not -14 — the route
		// must never get cheaper by using a favored method (no negative edges).
		int viaTransport = graph.createTransport(C, walked, CostUnits.fromTicks(3), -20, false);
		assertEquals("The favored transport is free but never pays back", 1, graph.cost(viaTransport));
	}

	@Test
	public void negativeExtraCostClampsWalkAndAbstractEdgesAtFree()
	{
		NodeGraph graph = new NodeGraph(16);
		int start = graph.createStart(A);
		int walked = graph.createTile(B, start, false, -5);
		assertEquals("A negative surcharge can't make walking pay back", 0, graph.cost(walked));
		int abstractNode = graph.createAbstract(AbstractNodeKind.fromWildernessLevel(0), walked, false, -7);
		assertEquals("A negative surcharge can't make the abstract hop pay back", 0, graph.cost(abstractNode));
	}
}

package gps.pathfinder;

import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.Destinations;
import gps.ShortestPathConfig;
import gps.WorldPointUtil;

/**
 * Covers the walkable-ring expansion for arbitrary single-tile targets (map pins, Quest Helper
 * NPC tiles): a pin on an unwalkable tile must become a reachable target set instead of sending
 * every search into full-map exhaustion — the in-game capture that motivated this showed 11
 * exhausted searches (8.2s) for a pin on Draynor Manor furniture.
 */
@RunWith(MockitoJUnitRunner.class)
public class WalkableTargetsTest
{
	// An unwalkable furniture tile inside Draynor Manor, two tiles from the captured pin that
	// motivated the feature (the original tile opened with the 2026-07 collision fixes).
	private static final int MANOR_PIN = WorldPointUtil.packWorldPoint(3093, 3359, 0);
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	private PathfinderConfig planningConfig()
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		return planning;
	}

	@Test
	public void walkableTileStaysExact()
	{
		CollisionMap map = planningConfig().getMap();
		assertEquals("A walkable tile must stay an exact single target",
			Set.of(LUMBRIDGE), Destinations.walkableTargets(map, LUMBRIDGE));
	}

	@Test
	public void blockedPinExpandsToTheNearestWalkableRing()
	{
		CollisionMap map = planningConfig().getMap();
		assertTrue("Precondition: the pin tile is unwalkable",
			map.isBlocked(WorldPointUtil.unpackWorldX(MANOR_PIN),
				WorldPointUtil.unpackWorldY(MANOR_PIN), WorldPointUtil.unpackWorldPlane(MANOR_PIN)));

		Set<Integer> targets = Destinations.walkableTargets(map, MANOR_PIN);
		assertTrue("Expansion must add walkable ring tiles", targets.size() > 1);
		assertTrue("The original tile stays in the set (harmless, keeps identity)",
			targets.contains(MANOR_PIN));
		for (int target : targets)
		{
			if (target == MANOR_PIN)
			{
				continue;
			}
			assertFalse("Every added ring tile must be walkable",
				map.isBlocked(WorldPointUtil.unpackWorldX(target),
					WorldPointUtil.unpackWorldY(target), WorldPointUtil.unpackWorldPlane(target)));
		}
	}

	@Test
	public void expandedPinIsActuallyReachedBySearches()
	{
		// The end-to-end guarantee: targeting the expanded set REACHES (search terminates at a
		// ring tile) instead of exhausting the map for a closest-tile fallback.
		PathfinderConfig config = planningConfig();
		Set<Integer> targets = Destinations.walkableTargets(config.getMap(), MANOR_PIN);
		Pathfinder pathfinder = new Pathfinder(config, LUMBRIDGE, targets, Integer.MAX_VALUE, null);
		pathfinder.run();
		assertTrue("The expanded pin must be reached", pathfinder.getResult().isReached());
	}
}

package gps.pathfinder;

import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.ShortestPathConfig;
import gps.WorldPointUtil;

/**
 * Uncommon route shapes, each checked against the {@link ReferenceDijkstra} oracle with both the
 * uninformed search and production A* (bounded distance field): an island reachable only by boat,
 * the same island with every method excluded (must honestly end at the coast, not fake a route),
 * a deep-wilderness target no teleport can reach directly, and a plane-change target behind a
 * staircase transport. These exercise the gating machinery (wilderness bands, boat-only reverse
 * transports, plane transports) that ordinary overland queries never touch.
 */
@RunWith(MockitoJUnitRunner.class)
public class UncommonPathShapesTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	// Entrana: no walking connection, no teleports land there — the only way in is the Port Sarim
	// ferry (which lands on the ship's deck at plane 1, then the gangplank down).
	private static final int ENTRANA = WorldPointUtil.packWorldPoint(2830, 3335, 0);
	// The Wilderness Agility Course entrance, ~level 52: far deeper than any global teleport's band,
	// so a route must enter at a legal band (or via obelisks) and traverse from there.
	private static final int DEEP_WILDERNESS = WorldPointUtil.packWorldPoint(3004, 3937, 0);
	// The upper landing of a west-Varrock staircase (transports.tsv: 3159,3435,0 -> 3155,3435,1) —
	// a target only reachable through a plane-change transport.
	private static final int UPSTAIRS = WorldPointUtil.packWorldPoint(3155, 3435, 1);
	private static final int COST_MULTIPLE = 3;

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		Pathfinder.validateSettleOrder = true;
	}

	@After
	public void after()
	{
		Pathfinder.validateSettleOrder = false;
	}

	private PathfinderConfig everythingConfig()
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		return planning;
	}

	private PathfinderConfig walkOnlyConfig()
	{
		PathfinderConfig planning = everythingConfig();
		planning.rebuildAvailabilityWithExclusions(planning.getMethodCatalog());
		return planning;
	}

	/**
	 * Oracle parity for one query: the uninformed search and production A* (bounded field) must both
	 * agree with textbook Dijkstra on reachability and minimal cost. Returns the A* result for
	 * shape-specific assertions.
	 */
	private static PathfinderResult assertParity(PathfinderConfig cfg, int start, Set<Integer> targets)
	{
		ReferenceDijkstra.Result oracle = ReferenceDijkstra.search(cfg, start, targets);

		Pathfinder uninformed = new Pathfinder(cfg, start, targets);
		uninformed.run();
		assertEquals("uninformed reached must match the oracle",
			oracle.reached, uninformed.getResult().isReached());

		DistanceField field = DistanceField.build(cfg, targets, COST_MULTIPLE);
		SearchHeuristic heuristic = SearchHeuristic.buildWithField(cfg, field);
		assertNotNull(heuristic);
		Pathfinder astar = new Pathfinder(cfg, start, targets, Integer.MAX_VALUE, heuristic);
		astar.run();
		assertEquals("A* reached must match the oracle", oracle.reached, astar.getResult().isReached());

		if (oracle.reached)
		{
			assertEquals("uninformed cost must match the oracle",
				oracle.cost, uninformed.getResult().getTotalCost());
			assertEquals("A* cost must match the oracle",
				oracle.cost, astar.getResult().getTotalCost());
		}
		return astar.getResult();
	}

	@Test
	public void islandReachableOnlyByBoat()
	{
		PathfinderResult result = assertParity(everythingConfig(), LUMBRIDGE, Set.of(ENTRANA));
		assertTrue("Entrana must be reachable with boats available", result.isReached());
		// The route must genuinely cross water: some step lands on Entrana's side having been on the
		// mainland before it — i.e. a non-adjacent jump (the ferry) appears in the path.
		List<PathStep> path = result.getPathSteps();
		boolean jumped = false;
		for (int i = 1; i < path.size(); i++)
		{
			if (WorldPointUtil.distanceBetween(
				path.get(i - 1).getPackedPosition(), path.get(i).getPackedPosition()) > 20)
			{
				jumped = true;
				break;
			}
		}
		assertTrue("the route must include the ferry crossing (a non-adjacent transport edge)", jumped);
	}

	@Test
	public void islandHonestlyUnreachableWithEveryMethodExcluded()
	{
		PathfinderConfig cfg = walkOnlyConfig();
		PathfinderResult result = assertParity(cfg, LUMBRIDGE, Set.of(ENTRANA));
		assertFalse("with ships excluded nothing can reach Entrana", result.isReached());
		// The closest-tile path must honestly end on the mainland (near the coast), not on the island.
		List<PathStep> path = result.getPathSteps();
		assertFalse("a closest-tile path must still be produced", path.isEmpty());
		int end = path.get(path.size() - 1).getPackedPosition();
		assertTrue("the walk must end on the mainland side, not on Entrana",
			WorldPointUtil.distanceBetween(end, ENTRANA) > 20);
	}

	@Test
	public void deepWildernessTargetBeyondEveryTeleportBand()
	{
		PathfinderResult result = assertParity(everythingConfig(), LUMBRIDGE, Set.of(DEEP_WILDERNESS));
		assertTrue("deep wilderness must be reachable (teleport to a legal band, then traverse)",
			result.isReached());
		assertTrue("premise: the target lies in level-30+ wilderness",
			WildernessChecker.isInLevel30Wilderness(DEEP_WILDERNESS));
	}

	@Test
	public void startOnBlockedFairyRingPlatform()
	{
		// The Mount Karuulm (CIR) fairy ring's standing tile: transport ORIGINS on blocked tiles
		// are enterable and leavable only through the dedicated step-off rules — starting a search
		// there is the mirror image of the usual case and exercises the isBlocked branch of
		// getTileNeighbors. (Was the Karamja ring, whose platform turned out to be phantom
		// blocking and opened with the 2026-07 collision fixes.)
		final int ring = WorldPointUtil.packWorldPoint(1639, 3868, 0);
		PathfinderConfig cfg = everythingConfig();
		assertTrue("premise: the fairy ring standing tile is blocked in the collision map",
			cfg.getMap().isBlocked(1639, 3868, 0));
		PathfinderResult result = assertParity(cfg, ring, Set.of(LUMBRIDGE));
		assertTrue("a route off the ring platform must exist", result.isReached());
	}

	@Test
	public void blockedTransportLandingAsTarget()
	{
		// A transport LANDING on a blocked tile (a fairy ring platform, a jetty): forward searches
		// may step onto it only by taking the transport there; the reverse field values it via
		// patchBlockedLandings. Discovered from the data rather than hardcoded, so the test follows
		// the transport files.
		PathfinderConfig cfg = everythingConfig();
		int landing = WorldPointUtil.UNDEFINED;
		outer:
		for (boolean bankVisited : new boolean[]{false, true})
		{
			for (int origin : cfg.getTransportsPacked(bankVisited).keys())
			{
				for (gps.transport.Transport transport : cfg.getTransportsPacked(bankVisited).get(origin))
				{
					final int destination = transport.getDestination();
					if (destination == WorldPointUtil.UNDEFINED)
					{
						continue;
					}
					if (cfg.getMap().isBlocked(WorldPointUtil.unpackWorldX(destination),
						WorldPointUtil.unpackWorldY(destination), WorldPointUtil.unpackWorldPlane(destination)))
					{
						landing = destination;
						break outer;
					}
				}
			}
		}
		assertTrue("premise: the transport data must contain at least one blocked landing "
			+ "(the reason patchBlockedLandings exists)", landing != WorldPointUtil.UNDEFINED);
		PathfinderResult result = assertParity(cfg, LUMBRIDGE, Set.of(landing));
		assertTrue("the blocked landing must be reachable by taking the transport there: "
			+ WorldPointUtil.unpackWorldPoint(landing), result.isReached());
	}

	@Test
	public void undergroundTargetThroughTrapdoor()
	{
		// The Lumbridge castle cellar: underground regions connect to the surface only through
		// point transports (the kitchen trapdoor at 3210,3216 -> 3210,9616), so the route must
		// contain that jump — there is no walkable connection.
		final int cellar = WorldPointUtil.packWorldPoint(3210, 9616, 0);
		PathfinderResult result = assertParity(everythingConfig(), LUMBRIDGE, Set.of(cellar));
		assertTrue("the cellar must be reachable through the trapdoor", result.isReached());
		List<PathStep> path = result.getPathSteps();
		boolean jumped = false;
		for (int i = 1; i < path.size(); i++)
		{
			if (WorldPointUtil.distanceBetween(
				path.get(i - 1).getPackedPosition(), path.get(i).getPackedPosition()) > 20)
			{
				jumped = true;
				break;
			}
		}
		assertTrue("the route must include the trapdoor jump", jumped);
	}

	@Test
	public void midBandWildernessStart()
	{
		// Start at the level-27 obelisk platform: inside the wilderness but BELOW the level-30 band,
		// so the 20-30 abstract hub kind applies — teleports usable up to level 30 are legal right
		// away (unlike the 30+ escape case, which must walk out first).
		final int obelisk = WorldPointUtil.packWorldPoint(3035, 3732, 0);
		assertTrue("premise: in the wilderness", WildernessChecker.isInWilderness(obelisk));
		assertFalse("premise: below the level-30 band", WildernessChecker.isInLevel30Wilderness(obelisk));
		PathfinderResult result = assertParity(everythingConfig(), obelisk, Set.of(
			WorldPointUtil.packWorldPoint(3213, 3424, 0)));
		assertTrue("Varrock must be reachable from mid-band wilderness", result.isReached());
	}

	@Test
	public void startInsideTheTargetSet()
	{
		// Degenerate but real (e.g. "nearest bank" while standing in one): the search must finish
		// immediately with a zero-cost single-step path, not explore anything.
		PathfinderConfig cfg = everythingConfig();
		PathfinderResult result = assertParity(cfg, LUMBRIDGE, Set.of(LUMBRIDGE, ENTRANA));
		assertTrue(result.isReached());
		assertEquals("a start-is-target route costs nothing", 0, result.getTotalCost());
		assertEquals("the path is the single start tile", 1, result.getPathSteps().size());
		assertEquals(LUMBRIDGE, result.getPathSteps().get(0).getPackedPosition());
	}

	@Test
	public void planeChangeTargetBehindAStaircase()
	{
		PathfinderResult result = assertParity(everythingConfig(), LUMBRIDGE, Set.of(UPSTAIRS));
		assertTrue("the upstairs tile must be reachable via the staircase transport", result.isReached());
		// The path must actually change planes: it starts on plane 0 and ends on plane 1.
		List<PathStep> path = result.getPathSteps();
		assertEquals("path must start on the ground floor",
			0, WorldPointUtil.unpackWorldPlane(path.get(0).getPackedPosition()));
		assertEquals("path must end on the upper floor",
			1, WorldPointUtil.unpackWorldPlane(path.get(path.size() - 1).getPackedPosition()));
	}
}

package gps.pathfinder;

import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import java.util.Map;
import java.util.Set;
import gps.Destination;
import gps.DestinationRequirements;
import gps.ShortestPathConfig;
import gps.transport.Transport;
import gps.transport.TransportLoader;

// This subclass is used to provide mocked implementations of methods from the normal
// PathfinderConfig. CRUCIAL: Not implemented via Mockito as these methods are called
// many times in the inner pathfinding loop.
//
// In particular, at the moment you can provide default values for:
//  * getQuestState: Whether all quests are completed or not started.
//  * varbitChecks: Ignore any varbitChecks.
//  * varPlayerChecks: Ignore any varPlayerChecks.
// Other methods are delegated to a normal PathfinderConfig.
public class TestPathfinderConfig extends PathfinderConfig
{
	/**
	 * Initialization-on-Demand Holder: loads the five resource-heavy fields exactly once
	 * per JVM, so every TestPathfinderConfig instance shares the same pre-parsed data.
	 */
	private static final class ResourceHolder
	{
		static final SplitFlagMap MAP_DATA;
		static final Map<Integer, Set<Transport>> ALL_TRANSPORTS;
		static final Map<String, Set<Integer>> ALL_DESTINATIONS;
		static final Map<String, Set<Integer>> FILTERED_DESTINATIONS;
		static final Map<Integer, DestinationRequirements> BANK_REQUIREMENTS;

		static
		{
			MAP_DATA = SplitFlagMap.fromResources();
			ALL_TRANSPORTS = TransportLoader.loadAllFromResources();
			PathfinderConfig.remapPohDestinations(ALL_TRANSPORTS);
			ALL_DESTINATIONS = Destination.loadAllFromResources();
			FILTERED_DESTINATIONS = PathfinderConfig.filterDestinations(ALL_DESTINATIONS);
			BANK_REQUIREMENTS = Destination.loadBankRequirementsFromResources();
		}
	}

	private final QuestState questState;
	private final boolean bypassVarbitChecks;
	private final boolean bypassVarPlayerChecks;

	public TestPathfinderConfig(Client client, ShortestPathConfig config)
	{
		this(client, config, QuestState.FINISHED, true, true);
	}

	public TestPathfinderConfig(Client client, ShortestPathConfig config, QuestState questState,
		boolean bypassVarbitChecks, boolean bypassVarPlayerChecks)
	{
		super(client, config,
			ResourceHolder.MAP_DATA,
			ResourceHolder.ALL_TRANSPORTS,
			ResourceHolder.ALL_DESTINATIONS,
			ResourceHolder.FILTERED_DESTINATIONS,
			ResourceHolder.BANK_REQUIREMENTS);
		this.questState = questState;
		this.bypassVarbitChecks = bypassVarbitChecks;
		this.bypassVarPlayerChecks = bypassVarPlayerChecks;
	}

	protected TestPathfinderConfig(TestPathfinderConfig source)
	{
		super(source);
		this.questState = source.questState;
		this.bypassVarbitChecks = source.bypassVarbitChecks;
		this.bypassVarPlayerChecks = source.bypassVarPlayerChecks;
	}

	@Override
	protected PathfinderConfig newPlanningCopy()
	{
		return new TestPathfinderConfig(this);
	}

	@Override
	public QuestState getQuestState(Quest quest)
	{
		return questState;
	}

	@Override
	public boolean varbitChecks(Transport transport)
	{
		return !bypassVarbitChecks && super.varbitChecks(transport);
	}

	@Override
	public boolean varPlayerChecks(Transport transport)
	{
		return !bypassVarPlayerChecks && super.varPlayerChecks(transport);
	}
}

package gps.pathfinder;

import gps.JewelleryBoxTier;
import gps.MethodAvailability;
import gps.ShortestPathConfig;
import gps.TeleportMethod;
import gps.TeleportationItem;
import gps.transport.TransportType;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

/**
 * The house's mounted items are individual assumptions (they can't be scene-detected): each
 * mount has its own toggle under "Mounted items". An unticked mount stays IN the catalog —
 * nothing vanishes — but classifies LOCKED with a "not built" reason and drops out of routing,
 * exactly like any other unlock the player lacks.
 */
@RunWith(MockitoJUnitRunner.class)
public class PohMountSelectionTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(30);
		when(config.currencyThreshold()).thenReturn(10000000);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.NONE);
		when(config.usePoh()).thenReturn(true);
		when(config.usePohMountedItems()).thenReturn(true);
		// Below Ornate, so the mounted glory is not folded into the box.
		when(config.pohJewelleryBoxTier()).thenReturn(JewelleryBoxTier.BASIC);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	private PathfinderConfig planning(boolean glory, boolean xerics, boolean digsite, boolean mythical)
	{
		when(config.pohMountGlory()).thenReturn(glory);
		when(config.pohMountXerics()).thenReturn(xerics);
		when(config.pohMountDigsite()).thenReturn(digsite);
		when(config.pohMountMythical()).thenReturn(mythical);
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		return planning;
	}

	private static TeleportMethod mount(Map<TeleportMethod, MethodAvailability> availability, String mount)
	{
		for (TeleportMethod method : availability.keySet())
		{
			if (method.getType() == TransportType.TELEPORTATION_BOX && method.label().startsWith(mount + ":"))
			{
				return method;
			}
		}
		return null;
	}

	@Test
	public void untickedMountStaysListedButLocked()
	{
		PathfinderConfig all = planning(true, true, true, true);
		Map<TeleportMethod, MethodAvailability> availability = all.getMethodAvailability();
		for (String name : new String[]{"Amulet of glory", "Xeric's talisman", "Digsite pendant", "Mythical cape"})
		{
			TeleportMethod method = mount(availability, name);
			assertTrue(name + " mount in the catalog", method != null);
			assertEquals(name + " usable when ticked", MethodAvailability.AVAILABLE, availability.get(method));
		}

		PathfinderConfig noXerics = planning(true, false, true, true);
		availability = noXerics.getMethodAvailability();
		TeleportMethod xerics = mount(availability, "Xeric's talisman");
		assertTrue("unticked Xeric's must STAY in the catalog", xerics != null);
		assertEquals("…but locked", MethodAvailability.LOCKED, availability.get(xerics));
		assertEquals("…with the reason the lock tooltip shows",
			"Not built in your house (House section)", noXerics.getMethodAvailabilityDetail().get(xerics));
		assertEquals("the other mounts stay usable", MethodAvailability.AVAILABLE,
			availability.get(mount(availability, "Amulet of glory")));
	}

	@Test
	public void untickedMountDropsOutOfOwnedRouting()
	{
		PathfinderConfig noXerics = planning(true, false, true, true);
		noXerics.setPlanningMode(false);
		noXerics.setBypassItemPossession(false);
		noXerics.refresh();
		boolean xericsEdge = false;
		boolean gloryEdge = false;
		// The mounts sit on two house tiles (glory/cape at 1960,5750; Xeric's/digsite at
		// 1886,5760) — scan every origin rather than hard-code either.
		gps.PrimitiveIntHashMap<gps.transport.Transport[]> byOrigin = noXerics.getTransportsPacked(false);
		for (int origin : byOrigin.keys())
		{
			gps.transport.Transport[] transports = byOrigin.get(origin);
			for (gps.transport.Transport transport : transports == null ? new gps.transport.Transport[0] : transports)
			{
				String info = transport.getObjectInfo();
				if (info != null && transport.getType() == TransportType.TELEPORTATION_BOX)
				{
					xericsEdge |= info.contains("Xeric's Talisman");
					gloryEdge |= info.contains("Amulet of Glory");
				}
			}
		}
		assertFalse("an unbuilt mount must not be a routable edge", xericsEdge);
		assertTrue("a built mount still is", gloryEdge);
	}
}

package gps.pathfinder;

import java.util.HashSet;
