	{
		// Ladder pair 17148/17149: ground to first floor, first to second, and back down —
		// every edge exists purely via derivation.
		// Ladder climbs UP are calibrated at 4 ticks from 18 field samples (down: 2) — the
		// one family where the flat 2-tick guess was measurably wrong.
		assertRoute(3014, 3519, 0, 3015, 3518, 1, 4);
		assertRoute(3016, 3518, 1, 3015, 3519, 2, 5);
		assertRoute(3015, 3519, 2, 3014, 3519, 0, 6);
	}

	@Test
	public void derivedStaircaseDescends()
	{
		assertRoute(3012, 3515, 1, 3011, 3514, 0, 2);
	}
}

package gps.pathfinder;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.ShortestPathConfig;
import gps.TeleportMethod;
import gps.WorldPointUtil;
import gps.transport.TransportType;

/**
 * Captain Barnaby's ships (Ardougne / Brimhaven / Rimmington) drop you on the boat DECK, from which
 * you cross a gangplank to disembark — so the ship transports must land on the deck tile, not the
 * post-gangplank land tile. Landing on land skipped the gangplank: the route couldn't be tracked
 * (and the overlay froze on "Use ...") until the player had already crossed it by hand.
 */
@RunWith(MockitoJUnitRunner.class)
public class BarnabyShipTest
{
	private static final int ARDOUGNE_DOCK = WorldPointUtil.packWorldPoint(2683, 3271, 0);
	private static final int BRIMHAVEN_DECK = WorldPointUtil.packWorldPoint(2775, 3234, 1);
	private static final int BRIMHAVEN_LAND = WorldPointUtil.packWorldPoint(2772, 3234, 0);
	private static final int ARDOUGNE_DECK = WorldPointUtil.packWorldPoint(2683, 3268, 1);
	private static final int ARDOUGNE_LAND = WorldPointUtil.packWorldPoint(2683, 3271, 0);
	private static final int RIMMINGTON_DECK = WorldPointUtil.packWorldPoint(2915, 3222, 1);
	private static final int RIMMINGTON_LAND = WorldPointUtil.packWorldPoint(2915, 3225, 0);

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	private PathfinderConfig everythingConfig()
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		return planning;
	}

	@Test
	public void ardougneToBrimhavenLandsOnTheDeckAndCrossesTheGangplank()
	{
		// Ships only: every method-type but SHIP is excluded (gangplanks are plain walking connectors,
		// not methods, so they stay). Brimhaven is an island, so the Barnaby ship is the only route.
		PathfinderConfig config = everythingConfig();
		Set<TeleportMethod> excludeNonShips = new HashSet<>();
		for (TeleportMethod method : config.getMethodCatalog())
		{
			if (method.getType() != TransportType.SHIP)
			{
				excludeNonShips.add(method);
			}
		}
		config.rebuildAvailabilityWithExclusions(excludeNonShips);

		Pathfinder pathfinder = new Pathfinder(config, ARDOUGNE_DOCK, Set.of(BRIMHAVEN_LAND));
		pathfinder.run();

		assertTrue("Ardougne -> Brimhaven must be reachable by the Barnaby ship",
			pathfinder.getResult().isReached());
		List<PathStep> path = pathfinder.getResult().getPathSteps();
		assertTrue("the route must land on the Brimhaven boat deck, then cross the gangplank — "
				+ "landing straight on land would skip the gangplank the player must actually cross",
			path.stream().anyMatch(s -> s.getPackedPosition() == BRIMHAVEN_DECK));
	}

	@Test
	public void everyBarnabyDeckCanDisembark()
	{
		// Each tile the ships now land on must have a way off (guards against a dead-end landing).
		assertDisembark(BRIMHAVEN_DECK, BRIMHAVEN_LAND);
		assertDisembark(ARDOUGNE_DECK, ARDOUGNE_LAND);
		assertDisembark(RIMMINGTON_DECK, RIMMINGTON_LAND);
	}

	private void assertDisembark(int deck, int land)
	{
		Pathfinder pathfinder = new Pathfinder(everythingConfig(), deck, Set.of(land));
		pathfinder.run();
		assertTrue("boat deck " + WorldPointUtil.unpackWorldPoint(deck) + " must disembark to land",
			pathfinder.getResult().isReached());
	}
}

package gps.pathfinder;

import gps.Destinations;
import gps.ShortestPathConfig;
import gps.WorldPointUtil;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

/**
 * A blocked target on a mapped object's FOOTPRINT snaps to the object's transport origin —
 * the interactable side — not to whichever adjacent tile is walkable. Captured at the Troll
 * Stronghold south cave (gps-capture-20260725-183521): Quest Helper targeted the cave tiles,
 * the route ended one tile BEHIND the mouth, and the game walked the long way around.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class ObjectTargetSnapTest
{
	// A footprint tile of Cave Entrance 3759 (3x2 at 2892,3672; mapped origins at y 3671).
	private static final int CAVE_FOOTPRINT = WorldPointUtil.packWorldPoint(2893, 3673, 0);
	private static final int BEHIND_THE_CAVE = WorldPointUtil.packWorldPoint(2892, 3674, 0);
	private static final int CAVE_FRONT = WorldPointUtil.packWorldPoint(2893, 3671, 0);

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Test
	public void footprintTargetSnapsToTheMappedEntranceSide()
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();

		assertTrue("premise: the cave footprint tile is blocked",
			planning.getMap().isBlocked(2893, 3673, 0));
		assertTrue("premise: the cave's data rows make 2893,3671 a transport origin",
			planning.isTransportOrigin(CAVE_FRONT));

		Set<Integer> targets = Destinations.walkableTargets(
			planning.getMap(), CAVE_FOOTPRINT, planning::isTransportOrigin);
		assertTrue("the mapped entrance side must be targeted", targets.contains(CAVE_FRONT));
		assertFalse("the tile behind the mouth must not be", targets.contains(BEHIND_THE_CAVE));

		// Without origin data the old nearest-ring behaviour stands (no regression for
		// unmapped objects).
		Set<Integer> plain = Destinations.walkableTargets(planning.getMap(), CAVE_FOOTPRINT);
		assertTrue(plain.contains(BEHIND_THE_CAVE) || plain.contains(CAVE_FOOTPRINT));
	}
}

package gps.pathfinder;

import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.JewelleryBoxTier;
import gps.ShortestPathConfig;
import gps.ShortestPathPlugin;
import gps.WorldPointUtil;
import gps.transport.Transport;

/**
 * The POH model: the house is a zero-walk hub — every interior feature's transports are re-homed
 * onto the landing tile (1923,5709) — entered by house teleports/tabs/capes or the Home Portal at
 * the player's house location, and exited through the exit portal (both gated on the house-location
 * varbit). The master toggle removes ALL of it; the jewellery box filters by built tier.
 */
@RunWith(MockitoJUnitRunner.class)
public class PohGatingTest
{
	private static final int LANDING = WorldPointUtil.packWorldPoint(1923, 5709, 0);
	private static final int RIMMINGTON_PORTAL = WorldPointUtil.packWorldPoint(2953, 3224, 0);

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(30);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
	}

	private PathfinderConfig planningConfig()
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		return planning;
	}

	private static int landingTransportCount(PathfinderConfig cfg)
	{
		return cfg.getTransportsPacked(false)
			.getOrDefault(LANDING, TransportAvailability.EMPTY_TRANSPORTS).length;
	}

	@Test
	public void masterToggleRemovesEveryPohTransport()
	{
		// Default: usePoh is false — nothing POH-related may exist anywhere in the availability.
		PathfinderConfig cfg = planningConfig();
		assertEquals("no transports at the landing with POH disabled", 0, landingTransportCount(cfg));
		for (boolean bankVisited : new boolean[]{false, true})
		{
			for (Transport teleport : cfg.getUsableTeleports(bankVisited))
			{
				int d = teleport.getDestination();
				assertTrue("no teleport may land inside the POH with POH disabled: " + teleport,
					d == WorldPointUtil.UNDEFINED || !ShortestPathPlugin.isInsidePoh(
						WorldPointUtil.unpackWorldX(d), WorldPointUtil.unpackWorldY(d)));
			}
		}
	}

	@Test
	public void enabledPohExposesTheLandingHubIncludingTheExitPortal()
	{
		when(config.usePoh()).thenReturn(true);
		PathfinderConfig cfg = planningConfig();
		assertTrue("the landing hub must carry the re-homed feature transports",
			landingTransportCount(cfg) > 50);

		// The exit portal: from the landing straight to the house location outside (varbits are
		// bypassed in planning mode, so all nine location variants are present; in play the
		// house-location varbit selects one).
		boolean exitFound = false;
		for (Transport transport : cfg.getTransportsPacked(false)
			.getOrDefault(LANDING, TransportAvailability.EMPTY_TRANSPORTS))
		{
			if (transport.getDestination() == RIMMINGTON_PORTAL)
			{
				exitFound = true;
				break;
			}
		}
		assertTrue("the exit portal to the house location must be usable from the landing", exitFound);

		// End to end: standing at the landing, the outside portal is one transport away.
		ReferenceDijkstra.Result out = ReferenceDijkstra.search(cfg, LANDING, Set.of(RIMMINGTON_PORTAL));
		assertTrue("exiting the house must reach the outside portal", out.reached);
		assertTrue("the exit is a single cheap hop, not a trek (cost " + out.cost + ")", out.cost <= 5);
	}

	@Test
	public void jewelleryBoxFiltersByTier()
	{
		when(config.usePoh()).thenReturn(true);
		when(config.pohJewelleryBoxTier()).thenReturn(JewelleryBoxTier.BASIC);
		int basic = countBoxDestinations(planningConfig());

		when(config.pohJewelleryBoxTier()).thenReturn(JewelleryBoxTier.ORNATE);
		int ornate = countBoxDestinations(planningConfig());

		when(config.pohJewelleryBoxTier()).thenReturn(JewelleryBoxTier.NONE);
		int none = countBoxDestinations(planningConfig());

		// Wiki: Basic = ring of dueling + games necklace (9 destinations); Fancy adds combat
		// bracelet + skills necklace (10); Ornate adds glory + ring of wealth (8). Tiers include
		// everything below them.
		assertEquals("Basic box: 9 destinations", 9, basic);
		assertEquals("Ornate box: all 27 destinations", 27, ornate);
		assertEquals("No box: no jewellery box destinations", 0, none);
	}

	private int countBoxDestinations(PathfinderConfig cfg)
	{
		int count = 0;
		for (Transport transport : cfg.getTransportsPacked(false)
			.getOrDefault(LANDING, TransportAvailability.EMPTY_TRANSPORTS))
		{
			String info = transport.getObjectInfo();
			if (info != null && info.contains("Jewellery Box"))
			{
				count++;
			}
		}
		return count;
	}
}

package gps.pathfinder;

import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import static org.mockito.ArgumentMatchers.any;
import org.mockito.Mock;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import gps.ShortestPathConfig;
import gps.TeleportationItem;
import gps.WorldPointUtil;

/**
 * Verifies the alternative-routes "Bank" mode replicates Shortest Path's bank-pickup behaviour on
 * the planning copy: a teleport item that exists only in the bank must produce a route that walks to
 * a bank, flips into bankVisited state, and then teleports — even when the user's own Shortest Path
 * config has teleport items disabled.
 * <p>
 * Mirrors {@code PathfinderTest.testCowbellAmuletInBankUsedAfterBankVisit} (Varrock centre → Cowbell
 * amulet destination, expected path length 36) so any divergence from the main plugin's behaviour
 * fails the parity assertion.
 */
@RunWith(MockitoJUnitRunner.class)
public class AlternativeRoutesBankModeTest
{
	private static final int VARROCK_CENTRE = WorldPointUtil.packWorldPoint(3213, 3424, 0);
	private static final int COWBELL_DESTINATION = WorldPointUtil.packWorldPoint(3259, 3277, 0);
	private static final int COWBELL_AMULET = 33104;

	@Mock
	Client client;
	@Mock
	ItemContainer bank;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(30);
		when(config.currencyThreshold()).thenReturn(10000000);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		// The user's own Shortest Path config is deliberately restrictive: teleport items OFF.
		// The Owned modes force their own item setting, so they must work independently of it.
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.NONE);
	}

	/**
	 * A planning copy in the "Owned" family: inventory-only, or inventory + bank.
	 */
	private PathfinderConfig planningCopy(boolean considerBank)
	{
		return planningCopy(considerBank, new TestPathfinderConfig(client, config));
	}

	private PathfinderConfig planningCopy(boolean considerBank, PathfinderConfig base)
	{
		PathfinderConfig planning = base.copyForPlanning();
		planning.setPlanningMode(false);
		planning.setBypassItemPossession(false);
		planning.setConsiderBank(considerBank);
		planning.refresh();
		return planning;
	}

	private Pathfinder run(PathfinderConfig planning)
	{
		Pathfinder pathfinder = new Pathfinder(planning, VARROCK_CENTRE, Set.of(COWBELL_DESTINATION));
		pathfinder.run();
		return pathfinder;
	}

	@Test
	public void bankModeUsesBankedTeleportViaBankVisit()
	{
		// Bank open: the live container (event-captured by onItemContainerChanged) has the amulet.
		doReturn(new Item[]{new Item(COWBELL_AMULET, 1)}).when(bank).getItems();
		PathfinderConfig base = new TestPathfinderConfig(client, config);
		base.bank = bank;

		Pathfinder pathfinder = run(planningCopy(true, base));

		assertTrue("Bank mode should reach the target", pathfinder.getResult().isReached());
		assertTrue("Route should pass through a bank (bankVisited state)",
			pathfinder.getPath().stream().anyMatch(PathStep::isBankVisited));
		// Parity with PathfinderTest.testCowbellAmuletInBankUsedAfterBankVisit (main plugin behaviour).
		assertEquals("Bank-mode route should match the main plugin's bank-pickup path length",
			37, pathfinder.getPath().size());
	}

	@Test
	public void bankModeSurvivesLiveContainerEmptiedOnBankClose()
	{
		// Regression (user-reported): once the bank interface closes, the client can EMPTY the live
		// container — and with it every reference to it, including the event-captured one. The items
		// snapshot taken while the bank was open must keep bank routes working.
		doReturn(new Item[0]).when(bank).getItems(); // live container emptied on close
		PathfinderConfig base = new TestPathfinderConfig(client, config);
		base.bank = bank;
		base.setBankSnapshot(new Item[]{new Item(COWBELL_AMULET, 1)}); // captured while the bank was open

		Pathfinder pathfinder = run(planningCopy(true, base));

		assertTrue("Bank mode should reach the target using the bank snapshot", pathfinder.getResult().isReached());
		assertTrue("Route should pass through a bank (bankVisited state)",
			pathfinder.getPath().stream().anyMatch(PathStep::isBankVisited));
		assertEquals("Route should match the bank-pickup path length", 37, pathfinder.getPath().size());
	}

	/**
	 * The "Bank pickup modifier" (costBankPickup) must actually price banking: it adds exactly its
	 * value to a banking route's cost, and once it exceeds what banking saves the search abandons
	 * the bank detour for the plain walk. Same banked-Cowbell scenario as above.
	 */
	@Test
	public void bankPickupModifierPricesTheDetour()
	{
		Pathfinder free = runWithBankCost(0);
		assertTrue("with no modifier the cheapest route banks",
			free.getPath().stream().anyMatch(PathStep::isBankVisited));
		int freeCost = free.getResult().getTotalCost();

		Pathfinder charged = runWithBankCost(50);
		assertTrue("a modest modifier still banks", charged.getPath().stream().anyMatch(PathStep::isBankVisited));
		// A modifier of 0 is clamped to the one-tick floor (MIN_BANK_PICKUP_COST): the rise from
		// the "free" run is the modifier less that floor.
		assertEquals("the modifier must add exactly its value to the banking route's cost",
			freeCost + 50 - PathfinderConfig.MIN_BANK_PICKUP_COST, charged.getResult().getTotalCost());

		Pathfinder prohibitive = runWithBankCost(100000);
		assertFalse("a modifier larger than banking saves must suppress the bank detour",
			prohibitive.getPath().stream().anyMatch(PathStep::isBankVisited));
	}

	/**
	 * Banking is a choice, not a toll gate: a route that merely CROSSES a bank zone without
	 * withdrawing anything must not be charged the pickup modifier. (Regression: the bank-state
	 * flip used to be forced on any path touching a bank-accessible tile — every route from a
	 * start near a bank, e.g. the Grand Exchange, paid the surcharge, which cancelled it out of
	 * the route ranking and let a slower banking route outrank faster non-banking ones.)
	 */
	@Test
	public void merelyPassingABankIsFree()
	{
		// The prohibitive-modifier walk from bankPickupModifierPricesTheDetour: it declines to
		// bank, so its cost must be identical to the same walk with no modifier configured at all.
		Pathfinder freeWalk = runWithBankCost(0);
		int bankedCost = freeWalk.getResult().getTotalCost();

		Pathfinder walkNoModifier = runInventoryOnly();
		Pathfinder walkProhibitive = runWithBankCost(100000);
		assertFalse(walkProhibitive.getPath().stream().anyMatch(PathStep::isBankVisited));
		assertEquals("declining to bank must cost the same as bank routing not existing at all",
			walkNoModifier.getResult().getTotalCost(), walkProhibitive.getResult().getTotalCost());
		assertTrue("sanity: the banking route is genuinely cheaper than the walk in this scenario",
			bankedCost < walkProhibitive.getResult().getTotalCost());
	}

	private Pathfinder runInventoryOnly()
	{
		doReturn(new Item[]{new Item(COWBELL_AMULET, 1)}).when(bank).getItems();
		PathfinderConfig base = new TestPathfinderConfig(client, config);
		base.bank = bank;
		return run(planningCopy(false, base));
	}

	private Pathfinder runWithBankCost(int bankCost)
	{
		when(config.costBankPickup()).thenReturn(bankCost);
		doReturn(new Item[]{new Item(COWBELL_AMULET, 1)}).when(bank).getItems();
		PathfinderConfig base = new TestPathfinderConfig(client, config);
		base.bank = bank;
		return run(planningCopy(true, base));
	}

	@Test
	public void inventoryModeDoesNotUseBankedItems()
	{
		// Same scenario but in Owned/Inventory mode: the amulet is only in the bank, so the route
		// must not use it nor route through a bank.
		Pathfinder pathfinder = run(planningCopy(false));

		assertTrue("Walking route should still reach the target", pathfinder.getResult().isReached());
		assertFalse("Inventory mode must not enter bankVisited state",
			pathfinder.getPath().stream().anyMatch(PathStep::isBankVisited));
		assertTrue("Without the banked teleport the route must be longer than the bank-mode route",
			pathfinder.getPath().size() > 36);
	}
}

package gps;

import org.junit.Assert;
import org.junit.Test;

public class PrimitiveIntListTests
{
	@Test
	public void tryAddAndGet()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(10);
		intList.add(11);
		Assert.assertEquals(2, intList.size());
		Assert.assertEquals(10, intList.get(0));
		Assert.assertEquals(11, intList.get(1));
	}

	@Test
	public void tryGrow()
	{
		PrimitiveIntList intList = new PrimitiveIntList(4);
		intList.add(10);
		intList.add(11);
		intList.add(12);
		intList.add(13);
		intList.add(14);
		Assert.assertEquals(5, intList.size());
		int sum = 0;
		for (int i = 0; i < intList.size(); i++)
		{
			sum += intList.get(i);
		}
		Assert.assertEquals(10 + 11 + 12 + 13 + 14, sum);
	}

	@Test
	public void tryInitialize()
	{
		PrimitiveIntList intList = new PrimitiveIntList(3, true);
		Assert.assertEquals(3, intList.size());
		Assert.assertEquals(0, intList.get(0));
		Assert.assertEquals(0, intList.get(1));
		Assert.assertEquals(0, intList.get(2));
		intList.set(0, 10);
		intList.set(1, 11);
		intList.set(2, 12);
		Assert.assertEquals(10, intList.get(0));
		Assert.assertEquals(11, intList.get(1));
		Assert.assertEquals(12, intList.get(2));
	}

	@Test
	public void tryIterate()
	{
		int sum = 0;
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(10);
		intList.add(11);
		for (int i = 0; i < intList.size(); i++)
		{
			sum += intList.get(i);
		}
		Assert.assertEquals(10 + 11, sum);
	}

	@Test
	public void tryRemove()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(10);
		intList.add(11);
		Assert.assertEquals(2, intList.size());
		Assert.assertEquals(10, intList.removeAt(0));
		Assert.assertTrue(intList.remove(11));
		Assert.assertTrue(intList.isEmpty());
	}

	@Test
	public void defaultConstructor()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		Assert.assertEquals(0, intList.size());
		Assert.assertTrue(intList.isEmpty());
	}

	@Test
	public void capacityOnlyConstructor()
	{
		PrimitiveIntList intList = new PrimitiveIntList(5);
		// The list is not initialized so the size is 0
		Assert.assertEquals(0, intList.size());
		Assert.assertTrue(intList.isEmpty());
		intList.add(42);
		Assert.assertEquals(1, intList.size());
		Assert.assertEquals(42, intList.get(0));
	}

	@Test(expected = IllegalArgumentException.class)
	public void negativeCapacityConstructor()
	{
		new PrimitiveIntList(-1);
	}

	@Test
	public void zeroCapacityConstructor()
	{
		PrimitiveIntList intList = new PrimitiveIntList(0);
		Assert.assertEquals(0, intList.size());
		Assert.assertTrue(intList.isEmpty());
	}

	@Test
	public void addAtIndex()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(1);
		intList.add(2);
		intList.add(1, 99); // insert in middle
		Assert.assertEquals(3, intList.size());
		Assert.assertEquals(1, intList.get(0));
		Assert.assertEquals(99, intList.get(1));
		Assert.assertEquals(2, intList.get(2));
		intList.add(3, 100); // insert at end (index == size before add)
		Assert.assertEquals(4, intList.size());
		Assert.assertEquals(100, intList.get(3));
	}

	@Test(expected = IndexOutOfBoundsException.class)
	public void addAtIndexOutOfBoundsHigh()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(1, 5);
	}

	@Test(expected = IndexOutOfBoundsException.class)
	public void addAtIndexOutOfBoundsNegative()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(-1, 5);
	}

	@Test
	public void setReturnsOldValue()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(10);
		int old = intList.set(0, 20);
		Assert.assertEquals(10, old);
		Assert.assertEquals(20, intList.get(0));
	}

	@Test
	public void containsAndIndexOf()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(5);
		intList.add(6);
		intList.add(7);
		Assert.assertTrue(intList.contains(6));
		Assert.assertEquals(1, intList.indexOf(6));
		Assert.assertFalse(intList.contains(8));
		Assert.assertEquals(-1, intList.indexOf(8));
	}

	@Test
	public void removeNotPresent()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(1);
		Assert.assertFalse(intList.remove(2));
		Assert.assertEquals(1, intList.size());
	}

	@Test
	public void clearEmptiesList()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(1);
		intList.add(2);
		intList.clear();
		Assert.assertEquals(0, intList.size());
		Assert.assertTrue(intList.isEmpty());
		intList.add(3); // ensure list still usable
		Assert.assertEquals(1, intList.size());
		Assert.assertEquals(3, intList.get(0));
	}

	@Test(expected = IndexOutOfBoundsException.class)
	public void getOutOfBounds()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(1);
		intList.get(1); // size == 1 so index 1 invalid
	}

	@Test(expected = IndexOutOfBoundsException.class)
	public void setOutOfBounds()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(1);
		intList.set(1, 2);
	}

	@Test(expected = IndexOutOfBoundsException.class)
	public void removeAtOutOfBounds()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		intList.add(1);
		intList.removeAt(1);
	}

	@Test
	public void ensureCapacityNoOpAndGrowth()
	{
		PrimitiveIntList intList = new PrimitiveIntList();
		// ensureCapacity(0) should be a no-op and size unchanged
		intList.ensureCapacity(0);
		Assert.assertEquals(0, intList.size());

		// Pre-grow to capacity for 500 elements
		intList.ensureCapacity(500);
		// Add 500 elements and assert size; this should work without errors
		for (int i = 0; i < 500; i++)
		{
			intList.add(i);
		}
		Assert.assertEquals(500, intList.size());
		// Spot check a few values
		Assert.assertEquals(0, intList.get(0));
		Assert.assertEquals(123, intList.get(123));
		Assert.assertEquals(499, intList.get(499));
	}

	@Test
	public void ensureCapacityIdempotentForSmaller()
	{
		PrimitiveIntList intList = new PrimitiveIntList(4);
		intList.add(1);
		intList.add(2);
		intList.ensureCapacity(2); // already at least 2; should not affect size
		Assert.assertEquals(2, intList.size());
		Assert.assertEquals(1, intList.get(0));
		Assert.assertEquals(2, intList.get(1));
	}
}

package gps;

import gps.pathfinder.PathStep;
import gps.transport.TransportType;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The overlay's route while a generation streams: for a fresh destination NOTHING is shown — the
 * HUD is in its "Finding the best route" state — until the generation settles, when the best
 * route appears once. Front-runners streamed mid-generation never reach the overlay. A
 * same-destination regeneration keeps the committed route on screen throughout. Exercised through
 * the real trigger/update methods via reflection on a bare plugin instance (the RouteRematchTest
 * pattern).
 */
public class ProvisionalDisplayTest
{
	private static final int START = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int TARGET = WorldPointUtil.packWorldPoint(3164, 3487, 0);
	private static final TeleportMethod TABLET =
		new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Varrock tablet", TARGET);
	private static final TeleportMethod SPELL =
		new TeleportMethod(TransportType.TELEPORTATION_SPELL, "Varrock Teleport", TARGET);

	private ShortestPathPlugin plugin;

	@Before
	public void before() throws Exception
	{
		plugin = new ShortestPathPlugin();
		RouteDirectionsOverlay overlay = Mockito.mock(RouteDirectionsOverlay.class);
		set("routeDirectionsOverlay", overlay);
		AlternativeRoutesService service = Mockito.mock(AlternativeRoutesService.class);
		Mockito.when(service.wasMoreLikely()).thenReturn(false);
		set("altRoutesService", service);
		set("pathTargets", Set.of(TARGET));
		// The done-branch publishes to other plugins through the config (postTransports).
		set("config", Mockito.mock(ShortestPathConfig.class));
	}

	private void set(String field, Object value) throws Exception
	{
		Field f = ShortestPathPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	@SuppressWarnings("unchecked")
	private <T> T get(String field) throws Exception
	{
		Field f = ShortestPathPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		return (T) f.get(plugin);
	}

	private void trigger() throws Exception
	{
		Method m = ShortestPathPlugin.class.getDeclaredMethod("triggerAlternatives", int.class, Set.class);
		m.setAccessible(true);
		m.invoke(plugin, START, new HashSet<>(Set.of(TARGET)));
	}

	private void update(List<RouteOption> routes, boolean done) throws Exception
	{
		Method m = ShortestPathPlugin.class.getDeclaredMethod("onAlternativeRoutesUpdate",
			List.class, List.class, Map.class, boolean.class);
		m.setAccessible(true);
		m.invoke(plugin, routes, List.<TeleportMethod>of(), Map.<TeleportMethod, MethodAvailability>of(), done);
	}

	private static RouteOption route(int cost, TeleportMethod method)
	{
		List<PathStep> path = List.of(new PathStep(START, false), new PathStep(TARGET, false));
		return new RouteOption(path, List.of(method), List.of(1), List.of(1), cost, cost, true,
			Set.of(), List.of(0), 0);
	}

	@Test
	public void freshDestinationStaysClearUntilTheListSettles() throws Exception
	{
		RouteOption first = route(100, SPELL);
		RouteOption cheaper = route(50, TABLET);
		RouteOption middle = route(70, SPELL);

		trigger();
		assertTrue("a generation is in flight", (boolean) get("altGenerationInFlight"));
		assertNull("nothing on the overlay before the routes settle", plugin.getDisplayedRoute());
		assertTrue("the HUD is in its finding state", plugin.isFindingRoute());

		update(List.of(first), false);
		assertNull("the first route found is NOT shown — it may still change", plugin.getDisplayedRoute());
		assertTrue(plugin.isFindingRoute());
		update(List.of(cheaper, first), false);
		update(List.of(cheaper, middle, first), false);
		assertNull("front-runners mid-stream never reach the overlay", plugin.getDisplayedRoute());
		assertTrue(plugin.isFindingRoute());

		update(List.of(cheaper, middle, first), true);
		assertSame("settled: the final best appears, once", cheaper, plugin.getDisplayedRoute());
		assertFalse("finding state over", plugin.isFindingRoute());
		assertFalse((boolean) get("altGenerationInFlight"));
	}

	@Test
	public void sameDestinationRegenerationKeepsTheCommittedRoute() throws Exception
	{
		RouteOption settled = route(50, TABLET);
		RouteOption newer = route(40, SPELL);

		trigger();
		update(List.of(settled), false);
		update(List.of(settled), true);
		assertSame(settled, plugin.getDisplayedRoute());

		// Off-route recalc / method toggle: same targets, the overlay holds the committed route
		// steadily while the fresh list streams — no blank, no finding state.
		trigger();
		assertSame("committed route survives the regeneration start", settled, plugin.getDisplayedRoute());
		assertFalse("a held route is not a finding state", plugin.isFindingRoute());
		update(List.of(newer), false);
		assertSame("streaming does not swap the held route", settled, plugin.getDisplayedRoute());
		update(List.of(newer), true);
		assertSame("settles to the new best once", newer, plugin.getDisplayedRoute());
	}
}

package gps;

import gps.pathfinder.CollisionMap;
import gps.pathfinder.SplitFlagMap;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * Sanity budget for the progress tracker's walk-distance flood on the REAL collision map: it
 * runs once per player-tile change (memoized in the overlay), so it must be comfortably
 * sub-millisecond. Fails only if it regresses catastrophically; prints the measured average.
 */
public class RouteProgressBenchTest
{
	@Test
	public void walkDistanceFloodIsSubMillisecond()
	{
		CollisionMap map = new CollisionMap(SplitFlagMap.fromResources());
		// Anchors near open ground; the scan below snaps each to a genuinely unblocked tile
		// (hand-picked tiles kept landing inside GE fences and castle walls).
		int[][] anchors = {{3164, 3487, 0}, {2465, 9650, 0}, {3222, 3218, 0}};
		int[] spots = new int[anchors.length];
		for (int a = 0; a < anchors.length; a++)
		{
			outer:
			for (int dx = 0; dx < 6; dx++)
			{
				for (int dy = 0; dy < 6; dy++)
				{
					if (!map.isBlocked(anchors[a][0] + dx, anchors[a][1] + dy, anchors[a][2]))
					{
						spots[a] = WorldPointUtil.packWorldPoint(
							anchors[a][0] + dx, anchors[a][1] + dy, anchors[a][2]);
						break outer;
					}
				}
			}
			assertTrue("no open tile near anchor " + a, spots[a] != 0);
		}
		// Warm-up (JIT + page-in).
		for (int i = 0; i < 200; i++)
		{
			RouteProgress.walkDistances(map, spots[i % spots.length], RouteProgress.REACH_RADIUS);
		}
		int iterations = 600;
		long start = System.nanoTime();
		int sink = 0;
		for (int i = 0; i < iterations; i++)
		{
			Map<Integer, Integer> walk =
				RouteProgress.walkDistances(map, spots[i % spots.length], RouteProgress.REACH_RADIUS);
			sink += walk.size();
		}
		long nanos = System.nanoTime() - start;
		double microsPerFlood = nanos / 1000.0 / iterations;
		System.out.println("walkDistances avg: " + String.format("%.1f", microsPerFlood)
			+ " us/flood (tiles per flood avg " + (sink / iterations) + ")");
		// Budget: one flood per tile moved. 2 ms would already be absurd; typical should be far less.
		assertTrue("walk flood too slow: " + microsPerFlood + " us", microsPerFlood < 2000);
	}
}

package gps;

import net.runelite.api.WorldView;
import org.junit.Test;
import org.mockito.Mockito;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Pins the "is this scene a player-owned house" check: an instance whose map regions (the
 * template regions the scene is assembled from) include one of the POH template regions
 * (rx 29-32, ry 110-111 — regions 7534-8303). Confirmed against a real house's chunk dump, a
 * game-cache scan, and other plugins' POH region lists (2026-07-17); the transport data's POH
 * model band (y 5696) is NOT what live houses are built from, and checking it was why house
 * detection failed in the field.
 */
public class PohSceneDetectionTest
{
	private static WorldView instanceWithRegions(int... regions)
	{
		WorldView worldView = Mockito.mock(WorldView.class);
		Mockito.when(worldView.isInstance()).thenReturn(true);
		Mockito.when(worldView.getMapRegions()).thenReturn(regions);
		return worldView;
	}

	@Test
	public void everyPohTemplateRegionIsDetected()
	{
		for (int region : new int[]{7534, 7535, 7790, 7791, 8046, 8047, 8302, 8303})
		{
			assertTrue(String.valueOf(region),
				ShortestPathPlugin.isPohScene(instanceWithRegions(region)));
		}
	}

	@Test
	public void realHouseRegionSetIsDetected()
	{
		// The house whose chunk dump identified the band mapped entirely into region 7534.
		assertTrue(ShortestPathPlugin.isPohScene(instanceWithRegions(7534)));
	}

	@Test
	public void nonHouseInstancesAreNotDetected()
	{
		// A raid or cutscene instance is assembled from other regions.
		assertFalse(ShortestPathPlugin.isPohScene(instanceWithRegions(12889, 13136)));
		// The transport data's POH model band (region 7513, y 5696) is not a live house.
		assertFalse(ShortestPathPlugin.isPohScene(instanceWithRegions(7513)));
		assertFalse(ShortestPathPlugin.isPohScene(instanceWithRegions()));
		assertFalse(ShortestPathPlugin.isPohScene(instanceWithRegions((int[]) null)));
	}

	@Test
	public void nonInstanceWorldsAreNeverAHouse()
	{
		assertFalse(ShortestPathPlugin.isPohScene(null));
		// Standing OUTSIDE a house portal the overworld is not an instance, whatever its regions.
		WorldView overworld = Mockito.mock(WorldView.class);
		Mockito.when(overworld.isInstance()).thenReturn(false);
		assertFalse(ShortestPathPlugin.isPohScene(overworld));
	}
}

package gps;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
