import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;

/**
 * "+ more routes" (same query, wider limit/multiple) must CONTINUE the previous generation: the
 * already-found routes appear unchanged in the very first update (the panel never blanks), the
 * widened run only appends, and the outcome matches a from-scratch run at the wide settings.
 */
@RunWith(MockitoJUnitRunner.class)
public class ResumeMoreRoutesTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int BARROWS = WorldPointUtil.packWorldPoint(3566, 3291, 0);

	private AlternativeRoutesService service;
	private PathfinderConfig config;
	private ClientThread clientThread;

	static Object defaultValue(Class<?> t)
	{
		if (t == int.class || t == short.class || t == byte.class)
		{
			return 0;
		}
		if (t == long.class)
		{
			return 0L;
		}
		if (t == boolean.class)
		{
			return false;
		}
		if (t == double.class)
		{
			return 0.0;
		}
		if (t == float.class)
		{
			return 0f;
		}
		if (t == char.class)
		{
			return (char) 0;
		}
		return null;
	}

	@Before
	public void before()
	{
		final Thread ct = Thread.currentThread();
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState":
						return GameState.LOGGED_IN;
					case "getClientThread":
						return ct;
					case "getBoostedSkillLevel":
						return 99;
					default:
						return defaultValue(method.getReturnType());
				}
			});
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		config = new TestPathfinderConfig(client, cfg).copyForPlanning();
		config.refresh();
		clientThread = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(clientThread).invokeLater(Mockito.any(Runnable.class));
		service = new AlternativeRoutesService(clientThread, config);
	}

	@After
	public void after()
	{
		service.shutdown();
	}

	private List<RouteOption> generate(AlternativeRoutesService svc, int limit, int multiple,
		List<List<Integer>> streamedCosts) throws Exception
	{
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		svc.generate(LUMBRIDGE, Set.of(BARROWS), Set.of(), AlternativeRoutesMode.ALL_EVERYTHING,
			limit, multiple, false,
			(routes, catalog, unavailable, done) ->
			{
				if (streamedCosts != null)
				{
					List<Integer> costs = new ArrayList<>();
					for (RouteOption r : routes)
					{
						costs.add(r.getTotalCost());
					}
					streamedCosts.add(costs);
				}
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue("generation must finish", latch.await(60, TimeUnit.SECONDS));
		return out.get();
	}

	private static List<Integer> costs(List<RouteOption> routes)
	{
		List<Integer> costs = new ArrayList<>();
		for (RouteOption r : routes)
		{
			costs.add(r.getTotalCost());
		}
		return costs;
	}

	@Test
	public void wideningResumesAndNeverBlanksThePage() throws Exception
	{
		List<RouteOption> first = generate(service, 10, 3, null);
		assertNotNull(first);
		assertFalse("the narrow run must find routes", first.isEmpty());
		List<Integer> firstCosts = costs(first);

		// Widen ("+"): same start/targets/mode/exclusions, bigger limit and multiple.
		List<List<Integer>> streamed = new CopyOnWriteArrayList<>();
		List<RouteOption> widened = generate(service, 20, 6, streamed);
		assertNotNull(widened);

		// Continuity: every update (including the first) carries at least the narrow run's routes,
		// unchanged and in order — the page never blanks and never loses what it showed.
		assertFalse("the widened run must stream updates", streamed.isEmpty());
		for (List<Integer> update : streamed)
		{
			assertTrue("an update lost routes (page blanked): " + update,
				update.size() >= firstCosts.size());
			assertEquals("the previously shown routes must stay, unchanged and in order",
				firstCosts, update.subList(0, firstCosts.size()));
		}
		assertTrue("widening must add routes past the narrow page (got "
			+ widened.size() + " vs " + first.size() + ")", widened.size() > first.size());

		// Parity: a from-scratch service at the wide settings finds the same number of routes, and
		// the resumed run is never worse slot-for-slot. (Exact multiset equality is too strict: the
		// parallel seed pass fills the marginal last slots in completion order, so the two runs can
		// legitimately differ there — the resumed run keeping a cheaper marginal route is fine.)
		AlternativeRoutesService fresh = new AlternativeRoutesService(clientThread, config);
		try
		{
			List<RouteOption> scratch = generate(fresh, 20, 6, null);
			List<Integer> a = costs(widened);
			List<Integer> b = costs(scratch);
			a.sort(Integer::compareTo);
			b.sort(Integer::compareTo);
			assertEquals("resumed and from-scratch runs must find the same number of routes",
				b.size(), a.size());
			for (int i = 0; i < a.size(); i++)
			{
				assertTrue("resumed run must never be worse than from-scratch at slot " + i
					+ " (" + a.get(i) + " vs " + b.get(i) + ")", a.get(i) <= b.get(i));
			}
		}
		finally
		{
			fresh.shutdown();
		}
	}

	/**
	 * Resuming from a TINY prior generation must not silently drop routes. A panel-hidden generation
	 * computes only the primary route (limit 1), and its seed pass records signatures for routes it
	 * can't fit; the full generation that follows (panel opens / Quest Helper sets a target) resumes
	 * from it. If those burned signatures carried over, the wide run rejected cheap routes it found
	 * — the user capture where a Quest-Helper target showed 6 routes (missing the 2nd-cheapest) while
	 * a plain refresh showed 10. It must match a from-scratch wide run.
	 */
	@Test
	public void resumingFromATinyGenerationLosesNoRoutes() throws Exception
	{
		List<RouteOption> tiny = generate(service, 1, 3, null);
		assertNotNull(tiny);
		assertEquals("the panel-hidden run shows only the primary route", 1, tiny.size());

		List<RouteOption> resumed = generate(service, 10, 3, null);
		assertNotNull(resumed);

		AlternativeRoutesService fresh = new AlternativeRoutesService(clientThread, config);
		try
		{
			List<RouteOption> scratch = generate(fresh, 10, 3, null);
			List<Integer> a = costs(resumed);
			List<Integer> b = costs(scratch);
			a.sort(Integer::compareTo);
			b.sort(Integer::compareTo);
			assertEquals("resuming from a limit-1 generation must find as many routes as from scratch"
				+ " (resumed " + a + " vs scratch " + b + ")", b.size(), a.size());
			for (int i = 0; i < a.size(); i++)
			{
				assertTrue("resumed run must never be worse than from-scratch at slot " + i
					+ " (" + a.get(i) + " vs " + b.get(i) + ")", a.get(i) <= b.get(i));
			}
		}
		finally
		{
			fresh.shutdown();
		}
	}
}

package gps;

import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import org.junit.Assume;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.when;

/**
 * Probe (-Dgps.civitasProbe=true): capture 20260823-215617's question — where the Civitas illa
 * Fortis Teleport spell route lands with the runes in the inventory vs only in the bank, on the
 * fixed (junk-filtered) build. GE -> Zul-Andra, Owned inventory+bank.
 */
@RunWith(MockitoJUnitRunner.class)
public class CivitasSpellProbeTest
{
	@Mock
	Client client;
	@Mock
	ItemContainer inventory;
	@Mock
	ItemContainer bank;
	@Mock
	ShortestPathConfig config;
	@Mock
	ClientThread clientThread;

	private void run(String label, Item[] inventoryItems, Item[] bankItems) throws Exception
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(config.currencyThreshold()).thenReturn(10000000);
		lenient().when(config.costBankPickup()).thenReturn(15);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.INVENTORY_NON_CONSUMABLE);
		lenient().when(config.useQuetzals()).thenReturn(true);
		lenient().when(config.useCharterShips()).thenReturn(true);
		lenient().when(config.useTeleportationSpells()).thenReturn(true);
		lenient().when(config.useTeleportationMinigames()).thenReturn(true);
		lenient().when(config.useShips()).thenReturn(true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(i -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		doReturn(inventoryItems).when(inventory).getItems();
		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
		doAnswer(invocation ->
		{
			((Runnable) invocation.getArgument(0)).run();
			return null;
		}).when(clientThread).invokeLater(any(Runnable.class));

		doReturn(bankItems).when(bank).getItems();
		TestPathfinderConfig base = new TestPathfinderConfig(client, config);
		base.bank = bank;
		base.setBankSnapshot(bankItems);
		PathfinderConfig planning = base.copyForPlanning();
		planning.refresh();
		AlternativeRoutesService service = new AlternativeRoutesService(clientThread, planning);
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(WorldPointUtil.packWorldPoint(3162, 3486, 0),
			Set.of(WorldPointUtil.packWorldPoint(2207, 3159, 0)), Set.of(),
			AlternativeRoutesMode.OWNED_WITH_BANK, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		latch.await(120, TimeUnit.SECONDS);
		service.shutdown();
		StringBuilder sb = new StringBuilder("\nPROBE civitas — " + label + "\n");
		planning.getMethodAvailability().entrySet().stream()
			.filter(e -> e.getKey().getDisplayInfo() != null
				&& e.getKey().getDisplayInfo().contains("Civitas illa Fortis Teleport"))
			.forEach(e -> sb.append("  catalog: ").append(e.getKey().label()).append(" = ").append(e.getValue())
				.append(" detail=").append(planning.getMethodAvailabilityDetail().get(e.getKey())).append("\n"));
		for (AlternativeRoutesService.SearchRecord record : service.getLastSearchRecords())
		{
			sb.append("  search: ").append(record.label).append(" cost=").append(record.resultCost)
				.append(" reached=").append(record.reached).append(" term=").append(record.termination)
				.append("\n");
		}
		for (RouteOption route : out.get())
		{
			sb.append(String.format("  cost %d viaBank=%s %s%n",
				route.getTotalCost(), route.isViaBank(), route.getMethods()));
		}
		System.out.println(sb);
	}

	@Test
	public void whereTheSpellLands() throws Exception
	{
		Assume.assumeTrue(Boolean.getBoolean("gps.civitasProbe"));
		Item whistle = new Item(ItemID.HG_QUETZALWHISTLE_BASIC, 1);
		Item coins = new Item(ItemID.COINS, 100000);
		Item earth = new Item(ItemID.EARTHRUNE, 100);
		Item fire = new Item(ItemID.FIRERUNE, 100);
		Item law = new Item(ItemID.LAWRUNE, 100);
		run("runes IN INVENTORY", new Item[]{whistle, coins, earth, fire, law}, new Item[0]);
		run("runes ONLY IN BANK", new Item[]{whistle, coins}, new Item[]{earth, fire, law});
		run("no runes anywhere", new Item[]{whistle, coins}, new Item[0]);
	}
}

package gps;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import gps.transport.Transport;
import gps.transport.TransportType;

/**
 * Covers the seed-teleport candidate selection ({@link AlternativeRoutesService#rankSeedCandidates}):
 * candidates are ranked by estimated arrival cost (teleport duration + straight-line landing
 * distance), far-landing candidates are kept rather than dropped (an obstacle between start and
 * target makes straight-line comparisons lie), cross-plane landings rank last instead of
 * overflowing to first, duplicate landings keep the best-ranked candidate, user exclusions are
 * honoured, and the attempt cap bounds the list.
 */
public class SeedCandidateRankingTest
{
	private static final int TARGET = WorldPointUtil.packWorldPoint(3200, 3200, 0);

	private static Transport teleport(String name, int x, int y, int plane, int duration)
	{
		return new Transport.TransportBuilder()
			.type(TransportType.TELEPORTATION_SPELL)
			.destination(WorldPointUtil.packWorldPoint(x, y, plane))
			.duration(duration)
			.displayInfo(name)
			.build();
	}

	@Test
	public void farLandingCandidateIsKeptAndRankedByEstimate()
	{
		// The old drop rule discarded any candidate landing straight-line-farther than the start —
		// wrong when an obstacle separates start and target (start looks close but the walk is long).
		// A far-landing candidate must now be kept, ranked after closer ones.
		Transport near = teleport("near", 3205, 3200, 0, 0);   // 5 tiles from target
		Transport far = teleport("far", 3230, 3200, 0, 0);     // 30 tiles from target

		List<Transport> attempts = AlternativeRoutesService.rankSeedCandidates(
			new ArrayList<>(List.of(far, near)), Set.of(TARGET), Set.of(), 10);

		assertEquals("Both candidates must be kept (no distance-based drop)", 2, attempts.size());
		assertEquals("Closer landing must rank first", "near", attempts.get(0).getDisplayInfo());
		assertEquals("Farther landing must still be attempted", "far", attempts.get(1).getDisplayInfo());
	}

	@Test
	public void teleportDurationIsChargedIntoTheRankingAtTwoUnitsPerTick()
	{
		// The rank is the engine's time-normalized cost: duration ticks convert at 2 run-tiles per
		// tick. Chosen so the normalization decides the order: a 10-tick cast landing 15 tiles out
		// (2*10 + 15 = 35) must LOSE to an instant teleport landing 30 tiles out (30) — with the
		// old 1-unit-per-tick blend (10 + 15 = 25) it would have won.
		Transport slowCast = teleport("slow-cast", 3215, 3200, 0, 10);
		Transport instantFar = teleport("instant-far", 3230, 3200, 0, 0);

		List<Transport> attempts = AlternativeRoutesService.rankSeedCandidates(
			new ArrayList<>(List.of(slowCast, instantFar)), Set.of(TARGET), Set.of(), 10);

		assertEquals("Duration must be charged at 2 units per tick", "instant-far", attempts.get(0).getDisplayInfo());
		assertEquals("slow-cast", attempts.get(1).getDisplayInfo());
	}

	@Test
	public void crossPlaneLandingRanksLastNotFirst()
	{
		// A landing on another plane has straight-line distance Integer.MAX_VALUE; with int
		// arithmetic adding the duration would overflow negative and rank it FIRST. It must rank
		// last — but still be kept (the old drop rule discarded every seed for cross-plane targets).
		Transport samePlane = teleport("surface", 3300, 3300, 0, 10);
		Transport crossPlane = teleport("dungeon", 3201, 3200, 1, 10);

		List<Transport> attempts = AlternativeRoutesService.rankSeedCandidates(
			new ArrayList<>(List.of(crossPlane, samePlane)), Set.of(TARGET), Set.of(), 10);

		assertEquals("Cross-plane candidates must be kept", 2, attempts.size());
		assertEquals("Same-plane landing must rank first", "surface", attempts.get(0).getDisplayInfo());
		assertEquals("Cross-plane landing must rank last (no overflow)", "dungeon", attempts.get(1).getDisplayInfo());
	}

	@Test
	public void duplicateLandingsKeepTheBestRankedCandidate()
	{
		// Tab and spell to the same tile: only one attempt is spent, on the better-estimated one.
		Transport slow = teleport("slow-duplicate", 3210, 3200, 0, 30);
		Transport fast = teleport("fast-duplicate", 3210, 3200, 0, 4);

		List<Transport> attempts = AlternativeRoutesService.rankSeedCandidates(
			new ArrayList<>(List.of(slow, fast)), Set.of(TARGET), Set.of(), 10);

		assertEquals("Duplicate landings collapse to one attempt", 1, attempts.size());
		assertEquals("The better-ranked duplicate wins", "fast-duplicate", attempts.get(0).getDisplayInfo());
	}

	@Test
	public void userExcludedCandidatesAreDropped()
	{
		Transport kept = teleport("kept", 3210, 3200, 0, 0);
		Transport excluded = teleport("excluded", 3205, 3200, 0, 0);

		List<Transport> attempts = AlternativeRoutesService.rankSeedCandidates(
			new ArrayList<>(List.of(kept, excluded)), Set.of(TARGET),
			Set.of(TeleportMethod.fromTransport(excluded)), 10);

		assertEquals("Excluded method must not get an attempt", 1, attempts.size());
		assertEquals("kept", attempts.get(0).getDisplayInfo());
	}

	@Test
	public void multiTargetRankingMeasuresEachLandingAgainstItsNearestTarget()
	{
		// "Nearest bank" style query: two targets far apart. A teleport landing beside the DISTANT
		// target must outrank one landing moderately close to the near target — ranked against only
		// the near target (the old single-representative behavior) it would have come last.
		int nearTarget = TARGET;                                             // (3200, 3200)
		int farTarget = WorldPointUtil.packWorldPoint(2400, 2800, 0);        // far away
		Transport besideFarTarget = teleport("beside-far-target", 2402, 2800, 0, 0);  // 2 from far target
		Transport nearishNearTarget = teleport("nearish-near-target", 3220, 3200, 0, 0); // 20 from near target

		List<Transport> attempts = AlternativeRoutesService.rankSeedCandidates(
			new ArrayList<>(List.of(nearishNearTarget, besideFarTarget)),
			Set.of(nearTarget, farTarget), Set.of(), 10);

		assertEquals("A landing beside ANY target must rank by its nearest target",
			"beside-far-target", attempts.get(0).getDisplayInfo());
		assertEquals("nearish-near-target", attempts.get(1).getDisplayInfo());
	}

	@Test
	public void attemptCapKeepsTheBestRankedCandidates()
	{
		List<Transport> candidates = new ArrayList<>();
		for (int i = 1; i <= 5; i++)
		{
			candidates.add(teleport("t" + i, 3200 + 5 * i, 3200, 0, 0)); // 5, 10, ... 25 tiles out
		}

		List<Transport> attempts = AlternativeRoutesService.rankSeedCandidates(candidates, Set.of(TARGET), Set.of(), 3);

		assertEquals("Cap must bound the attempts", 3, attempts.size());
		for (int i = 0; i < attempts.size(); i++)
		{
			assertEquals("The cap must keep the best-ranked candidates in order",
				"t" + (i + 1), attempts.get(i).getDisplayInfo());
		}
		assertTrue("Zero cap yields no attempts",
			AlternativeRoutesService.rankSeedCandidates(candidates, Set.of(TARGET), Set.of(), 0).isEmpty());
	}
}

package gps;

import java.awt.Color;
import java.awt.Rectangle;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.util.ColorUtil;

@PluginDescriptor(name = "Shortest Path Test", description = "Test the Shortest Path Plugin Message events")
public class PluginMessageTestPlugin extends Plugin
{
	private static final String PLUGIN_MESSAGE_NAME = "shortestpath";
	private static final String PLUGIN_MESSAGE_PATH = "path";
	private static final String PLUGIN_MESSAGE_CLEAR = "clear";
	private static final String PLUGIN_MESSAGE_START = "start";
	private static final String PLUGIN_MESSAGE_TARGET = "target";
	private static final String PLUGIN_MESSAGE_CONFIG_OVERRIDE = "config";
	private static final String CLEAR = "Clear";
	private static final String PATH = ColorUtil.wrapWithColorTag("Path (PluginMessage)", JagexColors.MENU_TARGET);
	private static final String SET = "Set";
	private static final String START_INT = ColorUtil.wrapWithColorTag("Start Integer (PluginMessage)",
		JagexColors.MENU_TARGET);
	private static final String START_WP = ColorUtil.wrapWithColorTag("Start WorldPoint (PluginMessage)",
		JagexColors.MENU_TARGET);
	private static final String TARGET_INT = ColorUtil.wrapWithColorTag("Target Integer(s) (PluginMessage)",
		JagexColors.MENU_TARGET);
	private static final String TARGET_WP = ColorUtil.wrapWithColorTag("Target WorldPoint(s) (PluginMessage)",
		JagexColors.MENU_TARGET);
	private static final String CONFIG_COLOUR_PATH = ColorUtil.wrapWithColorTag("Yellow path colour (PluginMessage)",
		JagexColors.MENU_TARGET);

	private final Set<WorldPoint> targets = new HashSet<>(10);
	private Point lastMenuOpenedPoint;

	@Inject
	private Client client;

	@Inject
	private EventBus eventBus;

	private static int packWorldPoint(WorldPoint wp)
	{
		if (wp == null)
		{
			return -1;
		}
		return (wp.getX() & 0x7FFF) | ((wp.getY() & 0x7FFF) << 15) | ((wp.getPlane() & 0x3) << 30);
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		lastMenuOpenedPoint = client.getMouseCanvasPosition();

		if (!client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return;
		}

		for (MenuEntry menuEntry : event.getMenuEntries())
		{
			if (MenuAction.WALK.equals(menuEntry.getType()))
			{
				addMenuEntry(SET, TARGET_INT, 1);
				addMenuEntry(SET, TARGET_WP, 1);
				addMenuEntry(SET, CONFIG_COLOUR_PATH, 1);
				if (!targets.isEmpty())
				{
					addMenuEntry(SET, START_INT, 1);
					addMenuEntry(SET, START_WP, 1);
				}
				addMenuEntry(CLEAR, PATH, 1);
				break;
			}
		}

		final Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);

		if (map != null
			&& map.getBounds().contains(
			client.getMouseCanvasPosition().getX(),
			client.getMouseCanvasPosition().getY()))
		{
			addMenuEntry(SET, TARGET_INT, 0);
			addMenuEntry(SET, TARGET_WP, 0);
			addMenuEntry(SET, CONFIG_COLOUR_PATH, 0);
			if (!targets.isEmpty())
			{
				addMenuEntry(SET, START_INT, 0);
				addMenuEntry(SET, START_WP, 0);
				addMenuEntry(CLEAR, PATH, 0);
			}
		}
	}

	private void addMenuEntry(String option, String target, int position)
	{
		client.getMenu().createMenuEntry(position)
			.setOption(option)
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.onClick(this::onMenuOptionClicked);
	}

	private void onMenuOptionClicked(MenuEntry entry)
	{
		boolean isMessageInt = false;
		boolean overrideColourPath = false;
		WorldPoint start = null;
		WorldPoint target = null;

		if (entry.getOption().equals(SET) && entry.getTarget().equals(TARGET_INT))
		{
			isMessageInt = true;
			target = getSelectedWorldPoint();
		}
		else if (entry.getOption().equals(SET) && entry.getTarget().equals(TARGET_WP))
		{
			target = getSelectedWorldPoint();
		}
		else if (entry.getOption().equals(SET) && entry.getTarget().equals(START_INT))
		{
			isMessageInt = true;
			start = getSelectedWorldPoint();
		}
		else if (entry.getOption().equals(SET) && entry.getTarget().equals(START_WP))
		{
			start = getSelectedWorldPoint();
		}
		else if (entry.getOption().equals(SET) && entry.getTarget().equals(CONFIG_COLOUR_PATH))
		{
			overrideColourPath = true;
		}
		else if (entry.getOption().equals(CLEAR) && entry.getTarget().equals(PATH))
		{
			targets.clear();
			eventBus.post(new PluginMessage(PLUGIN_MESSAGE_NAME, PLUGIN_MESSAGE_CLEAR));
			return;
		}

		if (target != null)
		{
			targets.add(target);
		}

		Set<Integer> convertedTargets = new HashSet<>();
		if (isMessageInt)
		{
			for (WorldPoint t : targets)
			{
				convertedTargets.add(packWorldPoint(t));
			}
		}

		Map<String, Object> data = new HashMap<>();

		if (start != null)
		{
			data.put(PLUGIN_MESSAGE_START, isMessageInt ? packWorldPoint(start) : start);
		}

		if (!targets.isEmpty())
		{
			data.put(PLUGIN_MESSAGE_TARGET,
				targets.size() != 1 ? (isMessageInt ? convertedTargets : targets)
					: (isMessageInt ? convertedTargets.iterator().next() : targets.iterator().next()));
		}

		if (overrideColourPath)
		{
			Map<String, Object> configOverride = new HashMap<>();
			configOverride.put("colourPath", new Color(255, 255, 0));
			data.put(PLUGIN_MESSAGE_CONFIG_OVERRIDE, configOverride);
		}

		eventBus.post(new PluginMessage(PLUGIN_MESSAGE_NAME, PLUGIN_MESSAGE_PATH, data));
	}

	private WorldPoint getSelectedWorldPoint()
	{
		if (client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER) == null)
		{
			if (client.getTopLevelWorldView().getSelectedSceneTile() != null)
			{
				return WorldPoint.fromLocalInstance(client, client.getTopLevelWorldView().getSelectedSceneTile().getLocalLocation());
			}
		}
		else
		{
			return client.isMenuOpen()
				? calculateMapPoint(lastMenuOpenedPoint.getX(), lastMenuOpenedPoint.getY())
				: calculateMapPoint(client.getMouseCanvasPosition().getX(), client.getMouseCanvasPosition().getY());
		}
		return null;
	}

	private WorldPoint calculateMapPoint(int pointX, int pointY)
	{
		WorldMap worldMap = client.getWorldMap();
		float zoom = worldMap.getWorldMapZoom();
		WorldPoint mapPoint = new WorldPoint(worldMap.getWorldMapPosition().getX(), worldMap.getWorldMapPosition().getY(),
			0);
		int middleX = mapWorldPointToGraphicsPointX(mapPoint);
		int middleY = mapWorldPointToGraphicsPointY(mapPoint);

		if (pointX == Integer.MIN_VALUE || pointY == Integer.MIN_VALUE ||
			middleX == Integer.MIN_VALUE || middleY == Integer.MIN_VALUE)
		{
			return null;
		}

		final int dx = (int) ((pointX - middleX) / zoom);
		final int dy = (int) ((-(pointY - middleY)) / zoom);

		return mapPoint.dx(dx).dy(dy);
	}

	public int mapWorldPointToGraphicsPointX(WorldPoint worldPoint)
	{
		WorldMap worldMap = client.getWorldMap();

		float pixelsPerTile = worldMap.getWorldMapZoom();

		Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (map != null)
		{
			Rectangle worldMapRect = map.getBounds();

			int widthInTiles = (int) Math.ceil(worldMapRect.getWidth() / pixelsPerTile);

			Point worldMapPosition = worldMap.getWorldMapPosition();

			int xTileOffset = worldPoint.getX() + widthInTiles / 2 - worldMapPosition.getX();

			int xGraphDiff = ((int) (xTileOffset * pixelsPerTile));
			xGraphDiff += (int) (pixelsPerTile - Math.ceil(pixelsPerTile / 2));
			xGraphDiff += (int) worldMapRect.getX();

			return xGraphDiff;
		}
		return Integer.MIN_VALUE;
	}

	public int mapWorldPointToGraphicsPointY(WorldPoint worldPoint)
	{
		WorldMap worldMap = client.getWorldMap();

		float pixelsPerTile = worldMap.getWorldMapZoom();

		Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (map != null)
		{
			Rectangle worldMapRect = map.getBounds();

			int heightInTiles = (int) Math.ceil(worldMapRect.getHeight() / pixelsPerTile);

			Point worldMapPosition = worldMap.getWorldMapPosition();

			int yTileMax = worldMapPosition.getY() - heightInTiles / 2;
			int yTileOffset = (yTileMax - worldPoint.getY() - 1) * -1;

			int yGraphDiff = (int) (yTileOffset * pixelsPerTile);
			yGraphDiff -= (int) (pixelsPerTile - Math.ceil(pixelsPerTile / 2));
			yGraphDiff = worldMapRect.height - yGraphDiff;
			yGraphDiff += (int) worldMapRect.getY();

			return yGraphDiff;
		}
		return Integer.MIN_VALUE;
	}
}

package gps;

import java.util.Arrays;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * Issue #22: every elemental staff the wiki lists as an unlimited source of a rune must be in
 * that rune's staff family — the mystic element staves (1401-1407) and the "pretty" lava /
 * steam variants were missing, so a player wielding a Mystic air staff was told they had no
 * air runes.
 */
public class ItemVariationsTest
{
	private static void assertFamily(ItemVariations family, int... ids)
	{
		for (int id : ids)
		{
			assertTrue(family + " must include item " + id,
				Arrays.stream(family.getIds()).anyMatch(i -> i == id));
		}
	}

	@Test
	public void mysticElementStavesAreRuneSources()
	{
		assertFamily(ItemVariations.STAFF_OF_AIR, ItemID.STAFF_OF_AIR, ItemID.MYSTIC_AIR_STAFF,
			ItemID.AIR_BATTLESTAFF, ItemID.MYSTIC_MIST_BATTLESTAFF, ItemID.MYSTIC_DUST_BATTLESTAFF);
		assertFamily(ItemVariations.STAFF_OF_EARTH, ItemID.STAFF_OF_EARTH, ItemID.MYSTIC_EARTH_STAFF,
			ItemID.EARTH_BATTLESTAFF, ItemID.MYSTIC_MUD_STAFF, ItemID.MYSTIC_LAVA_STAFF,
			// The "(or)" cosmetic variants are the same staves — a pretty lava staff counted as
			// fire but not earth (field report 2026-08-23), so the Civitas spell demanded runes.
			ItemID.LAVA_BATTLESTAFF_PRETTY, ItemID.MYSTIC_LAVA_STAFF_PRETTY);
		assertFamily(ItemVariations.STAFF_OF_FIRE, ItemID.STAFF_OF_FIRE, ItemID.MYSTIC_FIRE_STAFF,
			ItemID.FIRE_BATTLESTAFF, ItemID.MYSTIC_LAVA_STAFF, ItemID.MYSTIC_LAVA_STAFF_PRETTY,
			ItemID.LAVA_BATTLESTAFF_PRETTY, ItemID.STEAM_BATTLESTAFF_PRETTY,
			ItemID.MYSTIC_STEAM_BATTLESTAFF, ItemID.MYSTIC_STEAM_BATTLESTAFF_PRETTY);
		assertFamily(ItemVariations.STAFF_OF_WATER, ItemID.STAFF_OF_WATER, ItemID.MYSTIC_WATER_STAFF,
			ItemID.WATER_BATTLESTAFF, ItemID.MYSTIC_MUD_STAFF, ItemID.MYSTIC_STEAM_BATTLESTAFF,
			ItemID.STEAM_BATTLESTAFF_PRETTY, ItemID.MYSTIC_STEAM_BATTLESTAFF_PRETTY);
	}

	@Test
	public void runeStaffSubstitutionCoversEveryElement()
	{
		// The substitution table must resolve for each elemental rune, else a staff never counts.
		for (ItemVariations rune : new ItemVariations[]{ItemVariations.AIR_RUNE, ItemVariations.EARTH_RUNE,
			ItemVariations.FIRE_RUNE, ItemVariations.WATER_RUNE})
		{
			int[] staves = ItemVariations.staves(rune);
			assertTrue("no staff family for " + rune, staves != null && staves.length > 0);
		}
	}
}

package gps;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The "report an issue" button must stay hub-review-clean: the routing context travels via the
 * CLIPBOARD, and the GitHub link is a bare constant — the old pre-filled {@code ?title=&body=}
 * URL read as network I/O of player data and flagged the 0.12.0 release for human review.
 */
public class IssueReportTest
{
	@Test
	public void newIssueLinkCarriesNoData()
	{
		assertTrue(ShortestPathPlugin.GITHUB_NEW_ISSUE.startsWith(
			"https://github.com/PauloAguiar/runelite-gps-plugin/issues/new"));
		assertFalse("the new-issue link must be bare — context goes via the clipboard, never the URL",
			ShortestPathPlugin.GITHUB_NEW_ISSUE.contains("?"));
	}

	@Test
	public void versionIsReadFromTheBundledManifest()
	{
		// build.gradle bundles runelite-plugin.properties onto the classpath, so the plugin reports
		// its real release version (not a hard-coded constant that can drift).
		String version = ShortestPathPlugin.pluginVersion();
		assertTrue("version must be read from the manifest, not the 'unknown' fallback: " + version,
			version.matches("\\d+\\.\\d+\\.\\d+"));
	}
}

