/**
 * Scratch harness: renders the side panel headlessly to a PNG so layout changes (label wrapping,
 * new sections, the warning toggle row) can be inspected without a client. Not a regression test.
 */
public class PanelRenderDumpTest
{
	@Test
	public void dump() throws Exception
	{
		if (System.getenv("GPS_PANEL_DUMP") == null)
		{
			return;
		}
		ShortestPathConfig config = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().lenient());
		Mockito.when(config.rememberBank()).thenReturn(true);
		Mockito.when(config.usePoh()).thenReturn(true);
		Mockito.when(config.pohSmartDetect()).thenReturn(true);
		Mockito.when(config.useSpiritTrees()).thenReturn(true);
		Mockito.when(config.spiritTreeSmartMode()).thenReturn(true);
		Mockito.when(config.useHotAirBalloons()).thenReturn(true);
		Mockito.when(config.balloonSmartMode()).thenReturn(true);
		Mockito.when(config.balloonStorageSynced()).thenReturn(false);
		Mockito.when(config.hideWarningBanners()).thenReturn(Boolean.parseBoolean(System.getenv("GPS_PANEL_HIDDEN")));
		Mockito.when(config.pohJewelleryBoxTier()).thenReturn(JewelleryBoxTier.NONE);

		ShortestPathPlugin plugin = Mockito.mock(ShortestPathPlugin.class, Mockito.withSettings().lenient());
		Mockito.when(plugin.getGpsConfig()).thenReturn(config);
		Mockito.when(plugin.getRoutesMode()).thenReturn(AlternativeRoutesMode.OWNED_WITH_BANK);
		Mockito.when(plugin.getBalloonLowLogTypes()).thenReturn(List.of());
		Mockito.when(plugin.getDetectedPohFurniture()).thenReturn(List.of());
		Mockito.when(plugin.getAvailablePlantedSpiritTrees()).thenReturn(List.of());
		Mockito.when(plugin.getFavoriteDestinations()).thenReturn(List.of());

		ShortestPathPanel panel = new ShortestPathPanel(plugin);
		for (String field : new String[]{"travelSectionExpanded", "bankSectionExpanded", "pohSectionExpanded"})
		{
			Field f = ShortestPathPanel.class.getDeclaredField(field);
			f.setAccessible(true);
			f.setBoolean(panel, true);
		}
		panel.refreshConfigSections();
		panel.displayRoutes(List.of(), List.of(), Map.of(), Set.of(), false, false);
		// Show the inline favourite editor so its layout is part of the dump.
		java.lang.reflect.Method toggle = ShortestPathPanel.class.getDeclaredMethod("toggleFavoriteEditor");
		toggle.setAccessible(true);
		toggle.invoke(panel);

		JPanel root = panel;
		root.setSize(242, 1400);
		layoutTree(root);
		BufferedImage image = new BufferedImage(242, 1400, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = image.createGraphics();
		root.paint(g);
		g.dispose();
		File out = new File(System.getenv("GPS_PANEL_DUMP"));
		ImageIO.write(image, "png", out);
		System.out.println("wrote " + out.getAbsolutePath());
	}

	private static void layoutTree(java.awt.Component c)
	{
		c.doLayout();
		if (c instanceof java.awt.Container)
		{
			for (java.awt.Component child : ((java.awt.Container) c).getComponents())
			{
				layoutTree(child);
			}
		}
	}
}

package gps;

import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import gps.transport.Transport;
import gps.transport.TransportType;
import java.lang.reflect.Proxy;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import org.junit.Test;
import org.mockito.Mockito;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Captures 20260823-213943 and -215617: most routes were "Quetzal whistle to some site, quetzal
 * back to Civitas, charter to Port Tyras" — pointless variants of the direct "Whistle to Civitas,
 * charter" (the whistle already lands at any built site), one per whistle destination the
 * exclusion chain tried. The filter's baseline is captured before the chain's own exclusion
 * rebuilds: the chain removes the direct whistle right before generating its hop variants, so a
 * live-availability check found nothing (the second capture, on the first cut of this filter).
 */
public class RedundantTeleportHopTest
{
	private static final int CIVITAS_LANDING = WorldPointUtil.packWorldPoint(1697, 3140, 0);
	private static final int QUETZACALLI_LANDING = WorldPointUtil.packWorldPoint(1510, 3222, 0);
	private static final int PRIMIO_VARROCK_LANDING = WorldPointUtil.packWorldPoint(3280, 3412, 0);

	private static Client client()
	{
		final Thread ct = Thread.currentThread();
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState": return GameState.LOGGED_IN;
					case "getClientThread": return ct;
					case "getBoostedSkillLevel": return 99;
					default: return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
	}

	private static PathfinderConfig planning(ShortestPathConfig cfg)
	{
		PathfinderConfig planning = new TestPathfinderConfig(client(), cfg).copyForPlanning();
		planning.refresh();
		return planning;
	}

	private static ShortestPathConfig config()
	{
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		Mockito.when(cfg.currencyThreshold()).thenReturn(10000000);
		Mockito.when(cfg.useTeleportationItems()).thenReturn(TeleportationItem.ALL);
		Mockito.when(cfg.useQuetzals()).thenReturn(true);
		Mockito.when(cfg.useCharterShips()).thenReturn(true);
		Mockito.when(cfg.useTeleportationMinigames()).thenReturn(true);
		Mockito.when(cfg.useShips()).thenReturn(true);
		return cfg;
	}

	@Test
	public void whistleThenQuetzalBackIsRedundantButPrimioIsNot()
	{
		PathfinderConfig planning = planning(config());
		List<Transport> baseline = AlternativeRoutesService.teleportHopBaseline(planning, Set.of());
		assertTrue("the baseline must hold the whistle teleports", !baseline.isEmpty());
		TeleportMethod whistleToQuetzacalli = new TeleportMethod(
			TransportType.QUETZAL_WHISTLE, "Quetzal whistle: Quetzacalli Gorge", QUETZACALLI_LANDING);
		TeleportMethod whistleToCivitas = new TeleportMethod(
			TransportType.QUETZAL_WHISTLE, "Quetzal whistle: Civitas illa Fortis", CIVITAS_LANDING);
		TeleportMethod quetzalToCivitas = new TeleportMethod(
			TransportType.QUETZAL, "Civitas illa Fortis", CIVITAS_LANDING);
		TeleportMethod primioToVarrock = new TeleportMethod(
			TransportType.QUETZAL, "Primio: Varrock", PRIMIO_VARROCK_LANDING);
		TeleportMethod charter = new TeleportMethod(
			TransportType.CHARTER_SHIP, "Port Tyras", WorldPointUtil.packWorldPoint(2142, 3122, 0));

		assertTrue("whistle -> quetzal back to a whistle-reachable site is the hop to drop",
			AlternativeRoutesService.hasRedundantTeleportHop(baseline,
				List.of(whistleToQuetzacalli, quetzalToCivitas, charter)));
		assertFalse("Varrock has no whistle landing: the Primio flight is a REAL leg",
			AlternativeRoutesService.hasRedundantTeleportHop(baseline,
				List.of(whistleToQuetzacalli, primioToVarrock)));
		assertFalse("unrelated method pairs are untouched",
			AlternativeRoutesService.hasRedundantTeleportHop(baseline,
				List.of(quetzalToCivitas, charter)));

		// A USER exclusion of the direct whistle makes its hop variants legitimate alternatives.
		List<Transport> withoutCivitas =
			AlternativeRoutesService.teleportHopBaseline(planning, Set.of(whistleToCivitas));
		assertFalse("with the direct whistle excluded by the user, the hop is a real route",
			AlternativeRoutesService.hasRedundantTeleportHop(withoutCivitas,
				List.of(whistleToQuetzacalli, quetzalToCivitas, charter)));
	}

	/**
	 * Capture 20260823-215617's exact query (Grand Exchange -> Zul-Andra): from the GE the whistle
	 * is the cheapest entry to Varlamore, so the chain excludes it and, before the baseline fix,
	 * emitted one whistle-hop variant per landing site. No emitted route may carry the hop.
	 */
	@Test
	public void capturedQueryNoLongerEmitsWhistleHopVariants() throws Exception
	{
		PathfinderConfig planning = planning(config());
		List<Transport> baseline = AlternativeRoutesService.teleportHopBaseline(planning, Set.of());
		ClientThread ct = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(Mockito.any(Runnable.class));
		AlternativeRoutesService service = new AlternativeRoutesService(ct, planning);
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(WorldPointUtil.packWorldPoint(3162, 3486, 0),
			Set.of(WorldPointUtil.packWorldPoint(2207, 3159, 0)), Set.of(),
			AlternativeRoutesMode.ALL_EVERYTHING, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue("generation must finish", latch.await(120, TimeUnit.SECONDS));
		service.shutdown();
		List<RouteOption> routes = out.get();
		assertTrue("routes expected", routes != null && !routes.isEmpty());
		boolean reached = false;
		for (RouteOption route : routes)
		{
			assertFalse("no route may keep a redundant whistle hop: " + route.getMethods(),
				AlternativeRoutesService.hasRedundantTeleportHop(baseline, route.getMethods()));
			reached |= route.isReached();
		}
		assertTrue("the target stays reachable with the junk variants filtered", reached);
	}
}

package gps;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * ONE-WAY ZONES must never hold a searchable destination.
 *
 * Some places can be left but never returned to, so a pin there is unroutable forever — no
 * transport row can fix it, unlike the sealed-entrance backlog. Tutorial Island is the clear
 * case: its bank and altar were imported by the amenity dump and, because that dump names
 * amenities after the nearest labelled place, they even shipped as "Lumbridge Bank" and
 * "Lumbridge Swamp Altar" — indistinguishable from the real ones in search results.
 *
 * The dump is regenerated from the cache periodically, so this guards the exclusion rather than
 * trusting a one-off deletion.
 */
public class DestinationExclusionZonesTest
{
	/** {minX, minY, maxX, maxY, why} — areas that cannot be re-entered once left. */
	private static final Object[][] ONE_WAY_ZONES = {
		{3050, 3060, 3145, 3150, "Tutorial Island"},
	};

	@Test
	public void noDestinationSitsInAOneWayZone()
	{
		List<String> offenders = new ArrayList<>();
		for (Destinations.Entry entry : Destinations.resourceEntries())
		{
			int x = WorldPointUtil.unpackWorldX(entry.packedPosition);
			int y = WorldPointUtil.unpackWorldY(entry.packedPosition);
			for (Object[] zone : ONE_WAY_ZONES)
			{
				if (x >= (Integer) zone[0] && y >= (Integer) zone[1]
					&& x <= (Integer) zone[2] && y <= (Integer) zone[3])
				{
					offenders.add(zone[4] + ": " + entry.category + " / " + entry.name
						+ " @" + x + "," + y);
				}
			}
		}
		assertTrue("destinations inside one-way zones can never be routed to and must not ship:\n  "
			+ String.join("\n  ", offenders), offenders.isEmpty());
	}
}

package gps;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * ARCHITECTURAL GUARD: live player position must flow through the boat-aware
 * {@code WorldPointUtil.fromLocalInstance(Client, Player)} overload. Aboard a boat the raw
 * player position lives in the boat's sub-WorldView (template-band coordinates), and the raw
 * idioms below regressed independently THREE times — the plugin's recalc start, the debug
 * snapshot, and the progress tracker — each one silently breaking the moment a player
 * boarded. A new use of these idioms in main sources is a test failure, not a field capture.
 */
public class RawPlayerPositionGuardTest
{
	private static final String[] FORBIDDEN = {
		".getLocalPlayer().getWorldLocation()",
		"fromLocalInstance(client, player.getLocalLocation())",
		"fromLocalInstance(client, local.getLocalLocation())",
	};

	@Test
	public void mainSourcesNeverReadRawPlayerPosition() throws IOException
	{
		List<String> offenders = new ArrayList<>();
		try (Stream<Path> files = Files.walk(Path.of("src/main/java/gps")))
		{
			for (Path file : (Iterable<Path>) files.filter(
				f -> f.toString().endsWith(".java"))::iterator)
			{
				// The overload itself legitimately reads the raw local as its ashore fallback.
				if (file.getFileName().toString().equals("WorldPointUtil.java"))
				{
					continue;
				}
				String source = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
				for (String idiom : FORBIDDEN)
				{
					if (source.contains(idiom))
					{
						offenders.add(file.getFileName() + ": " + idiom);
					}
				}
			}
		}
		assertTrue("Raw player-position idioms break aboard a boat; route through"
			+ " WorldPointUtil.fromLocalInstance(client, player):\n  "
			+ String.join("\n  ", offenders), offenders.isEmpty());
	}
}

