	@Test
	public void replacingDoesNotIncreaseSize()
	{
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(8);
		assertNull(map.put(10, "a"));
		int s1 = map.size();
		String prev = map.put(10, "b");
		assertEquals("a", prev);
		assertEquals(s1, map.size());
		assertEquals("b", map.get(10));
	}

	@Test
	public void manyRandomInsertionsAndLookups()
	{
		PrimitiveIntHashMap<Integer> map = new PrimitiveIntHashMap<>(32);
		Random rnd = new Random(42);
		Set<Integer> keys = new HashSet<>();

		for (int i = 0; i < 50_000; i++)
		{
			int k = rnd.nextInt();
			// avoid null values
			Integer prev = map.put(k, i);
			if (!keys.add(k))
			{
				// replacement path: previous value must be non-null
				assertNotNull(prev);
			}
			assertEquals(Integer.valueOf(i), map.get(k));
		}

		assertEquals(keys.size(), map.size());

		// sample lookups
		int checked = 0;
		for (int k : keys)
		{
			assertNotNull(map.get(k));
			if (++checked > 2000)
			{
				break;
			}
		}
	}

	@Test
	public void zeroLoadFactorCreatesMinimumCapacity()
	{
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(4, 0.0f);
		// With loadFactor 0.0, capacity should be 0, but map should still be usable
		assertNull(map.put(1, "test"));
		assertEquals("test", map.get(1));
		assertEquals(1, map.size());
	}

	@Test
	public void emptyCollectionAppending()
	{
		PrimitiveIntHashMap<List<Integer>> map = new PrimitiveIntHashMap<>(8);
		List<Integer> originalList = new ArrayList<>(Arrays.asList(1, 2, 3));
		List<Integer> emptyList = new ArrayList<>();

		map.put(10, originalList);
		List<Integer> prev = map.put(10, emptyList);

		// Original list should be returned and remain unchanged since empty list adds
		// nothing
		assertSame(originalList, prev);
		assertSame(originalList, map.get(10));
		assertEquals(Arrays.asList(1, 2, 3), map.get(10));
	}

	@Test
	public void mixedCollectionAndNonCollectionReplace()
	{
		PrimitiveIntHashMap<Object> map = new PrimitiveIntHashMap<>(8);
		List<Integer> list = new ArrayList<>(Arrays.asList(1, 2));

		// Start with non-collection value
		map.put(5, "string");

		// Replace with collection - should replace, not append
		Object prev = map.put(5, list);
		assertEquals("string", prev);
		assertSame(list, map.get(5));

		// Replace collection with non-collection - should replace, not append
		prev = map.put(5, "another string");
		assertSame(list, prev);
		assertEquals("another string", map.get(5));
	}

	@Test
	public void calculateFullnessEdgeCases()
	{
		// Test with completely empty map
		PrimitiveIntHashMap<Integer> map = new PrimitiveIntHashMap<>(8);
		assertTrue("Empty map fullness should be NaN", Double.isNaN(map.calculateFullness()));

		// Test with single element
		map.put(1, 1);
		double fullness = map.calculateFullness();
		assertTrue("Single element fullness should be valid", fullness >= 0.0 && fullness <= 100.0);

		// Test with all buckets having exactly one element
		map.clear();
		// Fill exactly one slot in each bucket if possible
		for (int i = 0; i < 8; i++)
		{
			map.put(i * 1000, i); // Use keys that likely hash to different buckets
		}
		fullness = map.calculateFullness();
		assertTrue("Evenly distributed fullness should be valid", fullness >= 0.0 && fullness <= 100.0);
	}

	@Test
	public void integerOverflowKeys()
	{
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(16);

		// Test keys near integer overflow boundaries
		map.put(Integer.MAX_VALUE, "max");
		map.put(Integer.MAX_VALUE - 1, "max-1");
		map.put(Integer.MIN_VALUE, "min");
		map.put(Integer.MIN_VALUE + 1, "min+1");
		map.put(0, "zero");
		map.put(-1, "neg-one");

		assertEquals("max", map.get(Integer.MAX_VALUE));
		assertEquals("max-1", map.get(Integer.MAX_VALUE - 1));
		assertEquals("min", map.get(Integer.MIN_VALUE));
		assertEquals("min+1", map.get(Integer.MIN_VALUE + 1));
		assertEquals("zero", map.get(0));
		assertEquals("neg-one", map.get(-1));
		assertEquals(6, map.size());
	}

	@Test
	public void extremeCollisionScenario()
	{
		// Force many collisions by using a small initial size and load factor 1.0
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(2, 1.0f);

		// Add many items that will definitely cause collisions and bucket growth
		for (int i = 0; i < 100; i++)
		{
			map.put(i, "value" + i);
		}

		// Verify all values are still accessible
		for (int i = 0; i < 100; i++)
		{
			assertEquals("value" + i, map.get(i));
		}
		assertEquals(100, map.size());
	}

	@Test
	public void largeCollectionAppending()
	{
		PrimitiveIntHashMap<List<Integer>> map = new PrimitiveIntHashMap<>(8);
		List<Integer> list1 = new ArrayList<>();
		for (int i = 0; i < 10000; i++)
		{
			list1.add(i);
		}

		List<Integer> list2 = new ArrayList<>();
		for (int i = 10000; i < 20000; i++)
		{
			list2.add(i);
		}

		map.put(1, list1);
		List<Integer> prev = map.put(1, list2);

		assertSame(list1, prev);
		assertSame(list1, map.get(1));
		assertEquals(20000, map.get(1).size());
		assertEquals(Integer.valueOf(0), map.get(1).get(0));
		assertEquals(Integer.valueOf(19999), map.get(1).get(19999));
	}

	@Test
	public void rehashDuringCollectionAppend()
	{
		// Create a map that will trigger rehash when a specific key is added
		PrimitiveIntHashMap<List<Integer>> map = new PrimitiveIntHashMap<>(4, 0.75f);

		// Add items until we're close to the rehash threshold
		map.put(1, new ArrayList<>(List.of(1)));
		map.put(2, new ArrayList<>(List.of(2)));

		// This should trigger a rehash when the collection is appended
		List<Integer> appendList = new ArrayList<>(Arrays.asList(100, 200));
		List<Integer> prev = map.put(1, appendList);

		assertNotNull(prev);
		assertEquals(Arrays.asList(1, 100, 200), map.get(1));
		assertEquals(List.of(2), map.get(2));
		assertEquals(2, map.size());
	}

	@Test
	public void sameKeyDifferentHashBehavior()
	{
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(8);

		// Test that same key always returns same value regardless of hash collisions
		map.put(42, "first");
		assertEquals("first", map.get(42));

		String prev = map.put(42, "second");
		assertEquals("first", prev);
		assertEquals("second", map.get(42));
		assertEquals(1, map.size()); // Size should not change
	}

	@Test
	public void clearAfterComplexOperations()
	{
		PrimitiveIntHashMap<List<String>> map = new PrimitiveIntHashMap<>(4);

		// Perform complex operations that cause growth and collection appending
		for (int i = 0; i < 50; i++)
		{
			List<String> list = new ArrayList<>(List.of("item" + i));
			map.put(i % 10, list); // This will cause appending for repeated keys
		}

		assertTrue(map.size() > 0);
		double fullness = map.calculateFullness();
		assertFalse(Double.isNaN(fullness));

		// Clear should reset everything
		map.clear();
		assertEquals(0, map.size());
		assertTrue(Double.isNaN(map.calculateFullness()));

		// Should be able to use normally after clear
		map.put(1, new ArrayList<>(List.of("after clear")));
		assertEquals(1, map.size());
		assertEquals(List.of("after clear"), map.get(1));
	}

	@Test
	public void incompatibleCollectionTypes()
	{
		PrimitiveIntHashMap<Object> map = new PrimitiveIntHashMap<>(8);

		// Put a list of strings
		List<String> stringList = new ArrayList<>(Arrays.asList("hello", "world"));
		map.put(10, stringList);

		// Try to append a list of integers - this should handle the ClassCastException
		// gracefully
		List<Integer> intList = new ArrayList<>(Arrays.asList(1, 2, 3));
		try
		{
			Object prev = map.put(10, intList);
			// If we get here, the implementation should have handled the type mismatch
			assertSame(stringList, prev);
		}
		catch (ClassCastException e)
		{
			// This is also acceptable behavior - the implementation throws when types don't
			// match
			// In this case, verify the original value is still there
			assertSame(stringList, map.get(10));
		}
	}

	@Test
	public void bucketGrowthIntegerOverflow()
	{
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(8);

		// This test ensures that bucket growth doesn't cause integer overflow
		// We can't easily test the actual overflow case, but we can test large bucket
		// growth
		for (int i = 0; i < 1000; i++)
		{
			map.put(i, "value" + i);
		}

		// Verify all values are still accessible after many bucket growth operations
		for (int i = 0; i < 1000; i++)
		{
			assertEquals("value" + i, map.get(i));
		}
		assertEquals(1000, map.size());
	}

	@Test
	public void constructorHandlesNegativeInitialSize()
	{
		PrimitiveIntHashMap<String> map = new PrimitiveIntHashMap<>(-5);
		assertNull(map.get(1));
		map.put(1, "a");
		map.put(2, "b");
		assertEquals("a", map.get(1));
		assertEquals("b", map.get(2));
		assertEquals(2, map.size());
	}

	@Test
	public void appendToUnmodifiableCollectionReplaces()
	{
		PrimitiveIntHashMap<List<String>> map = new PrimitiveIntHashMap<>(8);
		List<String> fixed = Arrays.asList("x", "y"); // fixed-size list => addAll throws UnsupportedOperationException
		List<String> replacement = new ArrayList<>(Arrays.asList("a", "b", "c"));

		assertNull(map.put(42, fixed));
		List<String> prev = map.put(42, replacement);

		// Should have replaced rather than appended due to
		// UnsupportedOperationException
		assertSame(fixed, prev);
		assertSame(replacement, map.get(42));
		assertEquals(Arrays.asList("a", "b", "c"), map.get(42));
		assertEquals(1, map.size());
	}

	@Test
	public void getOrDefaultAllowsNullDefault()
	{
		PrimitiveIntHashMap<Integer> map = new PrimitiveIntHashMap<>(8);
		assertNull(map.getOrDefault(999, null));
		map.put(999, 123);
		assertEquals(Integer.valueOf(123), map.getOrDefault(999, null));
	}

	@Test
	public void selfCollectionAppendDuplicatesSafely()
	{
		PrimitiveIntHashMap<List<Integer>> map = new PrimitiveIntHashMap<>(8);
		List<Integer> list = new ArrayList<>(Arrays.asList(1, 2));
		map.put(7, list);
		// Appending the same instance to itself should not crash and should duplicate
		// elements
		List<Integer> prev = map.put(7, list);
		assertSame(list, prev);
		assertSame(list, map.get(7));
		assertEquals(4, map.get(7).size());
		assertEquals(Arrays.asList(1, 2, 1, 2), map.get(7));
		assertEquals(1, map.size());
	}

	@Test
	public void zeroLoadFactorStress()
	{
		PrimitiveIntHashMap<Integer> map = new PrimitiveIntHashMap<>(8, 0.0f);
		// Keep this small to avoid exponential rehash growth with loadFactor=0.0
		for (int i = 0; i < 16; i++)
		{
			map.put(i, i);
		}
		for (int i = 0; i < 16; i++)
		{
			assertEquals(Integer.valueOf(i), map.get(i));
		}
		assertEquals(16, map.size());
	}
}

package gps;

import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.when;

/** PRODUCTION-PATH measurement: real generate(), real diagnostics, three pin classes. */
@RunWith(MockitoJUnitRunner.Silent.class)
public class WaterPinGenerationProbeTest
{
	private static final int START = WorldPointUtil.packWorldPoint(3222, 3218, 0);

	@Mock
	Client client;
	@Mock
	ClientThread clientThread;
	@Mock
	ItemContainer inventory;
	@Mock
	ShortestPathConfig config;

	@Before
	public void before()
	{
		when(config.calculationCutoff()).thenReturn(30);
		when(config.currencyThreshold()).thenReturn(10000000);
		when(config.useTeleportationSpells()).thenReturn(true);
		when(config.useSailing()).thenReturn(true);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.NONE);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenAnswer(invocation -> Thread.currentThread());
		when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);
		doReturn(new Item[]{
			new Item(ItemID.LAWRUNE, 10),
			new Item(ItemID.AIRRUNE, 30),
			new Item(ItemID.FIRERUNE, 10),
		}).when(inventory).getItems();
		when(client.getItemContainer(InventoryID.INV)).thenReturn(inventory);
		doAnswer(invocation ->
		{
			((Runnable) invocation.getArgument(0)).run();
			return null;
		}).when(clientThread).invokeLater(any(Runnable.class));
	}

	private void scenario(String label, int pin) throws Exception
	{
		PathfinderConfig planning = new TestPathfinderConfig(client, config)
			.copyForPlanning();
		AlternativeRoutesService service = new AlternativeRoutesService(clientThread, planning);
		CountDownLatch done = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>(List.of());
		long start = System.nanoTime();
		service.generate(START, Set.of(pin), Set.of(), AlternativeRoutesMode.OWNED_INVENTORY, 10,
			(routes, catalog, unavailable, isDone) ->
			{
				if (isDone)
				{
					out.set(routes);
					done.countDown();
				}
			});
		done.await(180, TimeUnit.SECONDS);
		long wallMs = (System.nanoTime() - start) / 1_000_000;
		service.shutdown();
		System.out.println("=== " + label + " (" + WorldPointUtil.unpackWorldX(pin) + ","
			+ WorldPointUtil.unpackWorldY(pin) + ") sailable=" + SailingSea.isSailable(pin)
			+ " wallMs=" + wallMs + " routes=" + out.get().size());
		long cpu = 0;
		int blind = 0, guided = 0;
		for (AlternativeRoutesService.SearchRecord r : service.getLastSearchRecords())
		{
			cpu += r.cpuMs;
			if (r.astar)
			{
				guided++;
			}
			else
			{
				blind++;
			}
		}
		System.out.println("  searches guided=" + guided + " blind=" + blind
			+ " totalCpuMs=" + cpu);
		for (AlternativeRoutesService.SearchRecord r : service.getLastSearchRecords())
		{
			System.out.println("    " + (r.astar ? "A*" : "DIJK") + " nodes=" + r.nodesChecked
				+ " cpuMs=" + r.cpuMs + " " + r.label);
		}
	}

	@Test
	public void measure() throws Exception
	{
		scenario("LAND Dognose", WorldPointUtil.packWorldPoint(3048, 2648, 0));
		scenario("WATER off Dognose", WorldPointUtil.packWorldPoint(3036, 2652, 0));
		scenario("WATER mid-ocean", WorldPointUtil.packWorldPoint(2894, 2637, 0));
	}
}

package gps;

import gps.transport.TransportType;
import java.lang.reflect.Field;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * The RimWorld-style method priority system: tiers shift a route's EFFECTIVE rank (cost plus
 * seconds-based adjustments) without touching the search; the walk preference gives the plain
 * walking route ranking slack; excluded methods read back as the EXCLUDED tier.
 */
public class MethodPriorityTest
{
	@Test
	public void secondsConvertToCostUnits()
	{
		// 1 tick = 0.6s, 2 units per tick.
		assertEquals(17, MethodPriority.unitsFromSeconds(5));
		assertEquals(33, MethodPriority.unitsFromSeconds(10));
		assertEquals(67, MethodPriority.unitsFromSeconds(20));
		assertEquals(-17, MethodPriority.unitsFromSeconds(-5));
		assertEquals(0, MethodPriority.unitsFromSeconds(0));
	}

	@Test
	public void chipTextIsSignedSeconds()
	{
		assertEquals("−10s", MethodPriority.PREFER_2.chipText());
		assertEquals("+5s", MethodPriority.AVOID_1.chipText());
		assertEquals("", MethodPriority.NORMAL.chipText());
	}

	private static RouteOption route(int cost, TeleportMethod... methods)
	{
		return new RouteOption(List.of(), List.of(methods), List.of(), List.of(),
			cost, cost, true, Set.of(), List.of(), 0);
	}

	@SuppressWarnings("unchecked")
	private static ShortestPathPlugin pluginWith(Map<TeleportMethod, MethodPriority> priorities,
		int walkPreferenceSeconds, Set<TeleportMethod> exclusions) throws Exception
	{
		ShortestPathPlugin plugin = new ShortestPathPlugin();
		Field priorityField = ShortestPathPlugin.class.getDeclaredField("methodPriorities");
		priorityField.setAccessible(true);
		((Map<TeleportMethod, MethodPriority>) priorityField.get(plugin)).putAll(priorities);
		Field walkField = ShortestPathPlugin.class.getDeclaredField("cachedWalkPreferenceSeconds");
		walkField.setAccessible(true);
		walkField.setInt(plugin, walkPreferenceSeconds);
		Field exclusionField = ShortestPathPlugin.class.getDeclaredField("userExclusions");
		exclusionField.setAccessible(true);
		((Set<TeleportMethod>) exclusionField.get(plugin)).addAll(exclusions);
		return plugin;
	}

	@Test
	public void preferredMethodOutranksARawFasterRoute() throws Exception
	{
		TeleportMethod cloak = new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Ardougne cloak", 1);
		TeleportMethod minigame = new TeleportMethod(TransportType.TELEPORTATION_MINIGAME, "Rat Pits", 2);
		ShortestPathPlugin plugin = pluginWith(
			Map.of(cloak, MethodPriority.PREFER_2), 0, Set.of());

		RouteOption cloakRoute = route(300, cloak);      // effective 300 - 33 = 267
		RouteOption minigameRoute = route(280, minigame); // effective 280
		List<RouteOption> sorted = plugin.sortByEffectiveOrder(List.of(minigameRoute, cloakRoute));

		assertEquals(cloakRoute, sorted.get(0));
		assertEquals(-10, plugin.routeAdjustmentSeconds(cloakRoute));
		assertEquals(0, plugin.routeAdjustmentSeconds(minigameRoute));
	}

	@Test
	public void avoidedMethodSinksBelowASlowerRoute() throws Exception
	{
		TeleportMethod fairy = new TeleportMethod(TransportType.FAIRY_RING, "C L S", 3);
		TeleportMethod tree = new TeleportMethod(TransportType.SPIRIT_TREE, "Tree", 4);
		ShortestPathPlugin plugin = pluginWith(Map.of(fairy, MethodPriority.AVOID_3), 0, Set.of());

		RouteOption fairyRoute = route(250, fairy); // effective 250 + 67 = 317
		RouteOption treeRoute = route(300, tree);   // effective 300
		List<RouteOption> sorted = plugin.sortByEffectiveOrder(List.of(fairyRoute, treeRoute));

		assertEquals(treeRoute, sorted.get(0));
		assertEquals(20, plugin.routeAdjustmentSeconds(fairyRoute));
	}

	@Test
	public void walkPreferenceGivesThePureWalkRouteSlack() throws Exception
	{
		TeleportMethod tab = new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Tablet", 5);
		ShortestPathPlugin plugin = pluginWith(Map.of(), 15, Set.of());

		RouteOption walk = route(320);          // effective 320 - 50 = 270
		RouteOption teleport = route(280, tab); // effective 280
		List<RouteOption> sorted = plugin.sortByEffectiveOrder(List.of(teleport, walk));

		assertEquals("walking wins: the method is not 15s better", walk, sorted.get(0));
		assertEquals(-15, plugin.routeAdjustmentSeconds(walk));

		RouteOption fastTeleport = route(240, tab); // effective 240 beats 270
		assertEquals(fastTeleport,
			plugin.sortByEffectiveOrder(List.of(walk, fastTeleport)).get(0));
	}

	@Test
	public void bankBiasShiftsViaBankRoutes() throws Exception
	{
		TeleportMethod tab = new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Tablet", 10);
		ShortestPathPlugin plugin = pluginWith(Map.of(), 0, Set.of());
		Field bankField = ShortestPathPlugin.class.getDeclaredField("cachedBankPreferenceSeconds");
		bankField.setAccessible(true);
		bankField.setInt(plugin, 10); // prefer bank routes by 10s

		RouteOption viaBank = new RouteOption(List.of(), List.of(tab), List.of(), List.of(),
			300, 300, true, Set.of(tab), List.of(), 0);
		RouteOption direct = route(280, tab);
		assertEquals(-10, plugin.routeAdjustmentSeconds(viaBank));
		assertEquals("bank route effective 267 beats direct 280",
			viaBank, plugin.sortByEffectiveOrder(List.of(direct, viaBank)).get(0));

		bankField.setInt(plugin, -10); // avoid bank routes
		assertEquals(10, plugin.routeAdjustmentSeconds(viaBank));
		assertEquals(direct, plugin.sortByEffectiveOrder(List.of(viaBank, direct)).get(0));
	}

	@Test
	public void adjustmentsNeverPromoteAnUnreachedRoute() throws Exception
	{
		TeleportMethod tab = new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Tablet", 6);
		ShortestPathPlugin plugin = pluginWith(Map.of(tab, MethodPriority.PREFER_3), 0, Set.of());

		RouteOption unreachedPreferred = new RouteOption(List.of(), List.of(tab), List.of(),
			List.of(), 100, 100, false, Set.of(), List.of(), 0);
		RouteOption reachedPlain = route(500);
		assertEquals(reachedPlain,
			plugin.sortByEffectiveOrder(List.of(unreachedPreferred, reachedPlain)).get(0));
	}

	@Test
	public void excludedMethodsReadBackAsTheExcludedTier() throws Exception
	{
		TeleportMethod tab = new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Tablet", 7);
		ShortestPathPlugin plugin = pluginWith(Map.of(), 0, Set.of(tab));
		assertEquals(MethodPriority.EXCLUDED, plugin.getMethodPriority(tab));
		assertEquals(MethodPriority.NORMAL, plugin.getMethodPriority(
			new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Other", 8)));
	}

	@Test
	public void exclusionMasksButDoesNotEraseTheTier() throws Exception
	{
		// Set a tier, then exclude (as the category toggle or the menu would): the tier is
		// shadowed while excluded and restored the moment the exclusion lifts.
		TeleportMethod tab = new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Tablet", 9);
		ShortestPathPlugin plugin = pluginWith(Map.of(tab, MethodPriority.PREFER_2), 0, Set.of());
		assertEquals(MethodPriority.PREFER_2, plugin.getMethodPriority(tab));

		Field exclusionField = ShortestPathPlugin.class.getDeclaredField("userExclusions");
		exclusionField.setAccessible(true);
		@SuppressWarnings("unchecked")
		Set<TeleportMethod> exclusions = (Set<TeleportMethod>) exclusionField.get(plugin);
		exclusions.add(tab);
		assertEquals(MethodPriority.EXCLUDED, plugin.getMethodPriority(tab));

		exclusions.remove(tab);
		assertEquals("re-inclusion must restore the stored tier",
			MethodPriority.PREFER_2, plugin.getMethodPriority(tab));
	}
}

package gps;

import java.lang.reflect.Proxy;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;

/**
 * The hybrid band edge: in-band routes are always shown, and past the band the page keeps filling
 * while the next route's cost stays within a modest gap of the acceptance region — so a first page
 * never cuts a dense cost cluster in half (the 105-shown/107-hidden capture that motivated this),
 * while a genuine cost cliff still ends the page.
 */
@RunWith(MockitoJUnitRunner.class)
public class HybridPageFillTest
{
	@Test
	public void ceilingFollowsAClusterAcrossTheBandEdge()
	{
		// The user capture: best 27, band 105, next cluster starts at 107 — 2 past the band edge.
		assertTrue("107 must be accepted (cluster straddles the band edge)",
			107 <= AlternativeRoutesService.pageFillCeiling(27, 105, 3));
		// The Barrows shape: best 32, band 105, costliest accepted 86, next cluster at 106 — the gap
		// from the last route is 20, but from the band edge it is 1.
		assertTrue("106 must be accepted (cluster starts just past the band)",
			106 <= AlternativeRoutesService.pageFillCeiling(32, 86, 3));
		// A genuine cliff is still a stop.
		assertTrue("a far outlier must not be dragged onto the page",
			400 > AlternativeRoutesService.pageFillCeiling(27, 112, 3));
		// The ceiling ratchets with accepted fill routes, following a dense cluster.
		assertTrue("the ceiling must ratchet as fill routes are accepted",
			AlternativeRoutesService.pageFillCeiling(27, 134, 3)
				> AlternativeRoutesService.pageFillCeiling(27, 107, 3));
	}

	// --- End-to-end on the real map -----------------------------------------------------------

	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	private static final int BARROWS = WorldPointUtil.packWorldPoint(3566, 3291, 0);

	private AlternativeRoutesService service;

	public static Object defaultValue(Class<?> t)
	{
		if (t == int.class || t == short.class || t == byte.class)
		{
			return 0;
		}
		if (t == long.class)
		{
			return 0L;
		}
		if (t == boolean.class)
		{
			return false;
		}
		if (t == double.class)
		{
			return 0.0;
		}
		if (t == float.class)
		{
			return 0f;
		}
		if (t == char.class)
		{
			return (char) 0;
		}
		return null;
	}

	@Before
	public void before()
	{
		final Thread clientThread = Thread.currentThread();
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState":
						return GameState.LOGGED_IN;
					case "getClientThread":
						return clientThread;
					case "getBoostedSkillLevel":
						return 99;
					default:
						return defaultValue(method.getReturnType());
				}
			});
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		PathfinderConfig config = new TestPathfinderConfig(client, cfg).copyForPlanning();
		config.refresh();
		ClientThread ct = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(Mockito.any(Runnable.class));
		service = new AlternativeRoutesService(ct, config);
	}

	@org.junit.After
	public void after()
	{
		service.shutdown();
	}

	/**
	 * Keldagrim station -> Giants' Foundry (user capture): the minigame teleport (46) is far cheaper
	 * than every alternative (157+), so the band/cliff gates alone produced a ONE-route page. The
	 * minimum page size must surface alternatives anyway, and none of them may ride the Keldagrim
	 * train to White Wolf Mountain and back as a "free" shortcut (the rides had no duration, so the
	 * search priced them at zero).
	 */
	@Test
	public void minimumPageSurvivesACheapBestRoute() throws Exception
	{
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(WorldPointUtil.packWorldPoint(2927, 10165, 0),
			Set.of(WorldPointUtil.packWorldPoint(3361, 3149, 0)), Set.of(),
			AlternativeRoutesMode.ALL_EVERYTHING, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue("generation must finish", latch.await(60, TimeUnit.SECONDS));
		List<RouteOption> routes = out.get();
		assertNotNull(routes);
		assertTrue("a cheap best route must not collapse the page to one entry (got "
			+ routes.size() + ")", routes.size() >= 4);
		for (RouteOption route : routes)
		{
			long trainRides = route.getMethods().stream()
				.filter(m -> gps.transport.TransportType.MINECART.equals(m.getType())
					&& m.label().contains("White Wolf Mountain"))
				.count();
			assertTrue("no route may detour via the White Wolf Mountain train from Keldagrim",
				trainRides == 0);
		}
	}

	/**
	 * Locked in a sealed quest cell (user capture: start 3054,9841 is a ~76-tile pocket with no
	 * transports out) targeting a through-the-bars tile in the Port Sarim jail (3014,3194 — also
	 * sealed). The goal-rooted field floods only the target's pocket, so every finite-capped
	 * chain/seed search used to gate-prune its own start (h effectively infinite) and the page
	 * collapsed to ONE escape route. The degenerate-heuristic fallback must keep the chain alive:
	 * several closest-point routes with distinct escape methods, none of them "reached".
	 */
	@Test
	public void sealedTargetStillEnumeratesEscapeAlternatives() throws Exception
	{
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(WorldPointUtil.packWorldPoint(3054, 9841, 0),
			Set.of(WorldPointUtil.packWorldPoint(3014, 3194, 0),
				WorldPointUtil.packWorldPoint(3014, 3195, 0),
				WorldPointUtil.packWorldPoint(3015, 3195, 0)),
			Set.of(), AlternativeRoutesMode.ALL_EVERYTHING, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue("generation must finish", latch.await(120, TimeUnit.SECONDS));
		List<RouteOption> routes = out.get();
		assertNotNull(routes);
		assertTrue("a sealed target must still get a menu of escape routes (got "
			+ routes.size() + ")", routes.size() >= 2);
		java.util.Set<String> firstMethods = new java.util.HashSet<>();
		for (RouteOption route : routes)
		{
			assertTrue("no route can actually reach a sealed target", !route.isReached());
			if (!route.getMethods().isEmpty())
			{
				firstMethods.add(route.getMethods().get(0).label());
			}
		}
		assertTrue("the escape routes must use distinct methods (got " + firstMethods + ")",
			firstMethods.size() >= 2);
	}

	/**
	 * Lumbridge -> Barrows in everything mode: four routes sit under the bare 105 band (32/32/86/86)
	 * and a straggler cluster sits just past its edge (118, 122) before a genuine cliff (the next
	 * route costs 176). The bare band cut mid-cluster and showed 4; the hybrid must show the whole
	 * cluster (6) and still stop at the cliff rather than dragging the 176+ outliers onto the page.
	 */
	@Test
	public void barrowsFirstPageCrossesTheBandEdgeAndStopsAtTheCliff() throws Exception
	{
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(LUMBRIDGE, Set.of(BARROWS), Set.of(), AlternativeRoutesMode.ALL_EVERYTHING,
			10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		assertTrue("generation must finish", latch.await(60, TimeUnit.SECONDS));
		List<RouteOption> routes = out.get();
		assertNotNull(routes);
		assertTrue("the page must fill past the bare band's 4 routes, got " + routes.size(),
			routes.size() > 4);
		int best = routes.get(0).getTotalCost();
		long band = 3L * Math.max(best, 35);
		int costliest = 0;
		for (RouteOption route : routes)
		{
			costliest = Math.max(costliest, route.getTotalCost());
			assertTrue("route cost " + route.getTotalCost() + " must stay under the sanity ceiling",
				route.getTotalCost() <= 2 * band);
		}
		assertTrue("fill must actually cross the band edge (costliest " + costliest + " vs band " + band + ")",
			costliest > band);
		assertTrue("the page must stop at the cliff: nothing at or past the next cluster (176+)",
			costliest < 176);
	}
}

package gps;

import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The destination search's fuzzy matcher and persisted history: tier ordering (exact &gt; prefix
 * &gt; word prefixes &gt; substring &gt; subsequence), the abbreviation cases the fuzziness exists
 * for, and the history's dedupe/cap/round-trip behaviour.
 */
public class SearchMatcherTest
{
	@Test
	public void tiersRankTighterMatchesHigher()
	{
		int exact = SearchMatcher.score("Varrock", "varrock");
		int prefix = SearchMatcher.score("Varrock Palace", "varrock");
		int wordPrefix = SearchMatcher.score("East Varrock Mine", "var mine");
		int substring = SearchMatcher.score("East Varrock", "arrock");
		int subsequence = SearchMatcher.score("Varrock", "vrck");
		assertTrue("exact > prefix", exact > prefix);
		assertTrue("prefix > word prefix", prefix > wordPrefix);
		assertTrue("word prefix > substring", wordPrefix > substring);
		assertTrue("substring > subsequence", substring > subsequence);
		assertTrue("subsequence still matches", subsequence > 0);
	}

	@Test
	public void wordPrefixesMatchInOrder()
	{
		assertTrue(SearchMatcher.score("Varrock Palace", "var pal") > 0);
		assertTrue(SearchMatcher.score("Seers' Village Rooftop Course", "seers roof") > 0);
		assertEquals("tokens out of order must not match as word prefixes or better",
			0, SearchMatcher.score("Varrock Palace", "pal var"));
	}

	@Test
	public void subsequenceToleratesDroppedLetters()
	{
		assertTrue(SearchMatcher.score("Brimhaven Agility Arena", "brmhvn") > 0);
		assertTrue(SearchMatcher.score("Gemstone crabs (Tal Teklan)", "gmstn crb") > 0);
		assertEquals("letters out of order never match", 0, SearchMatcher.score("Brimhaven", "nvhmrb"));
		assertEquals("too-short queries don't subsequence-match", 0, SearchMatcher.score("Brimhaven", "bn"));
	}

	@Test
	public void shorterNamesWinWithinATier()
	{
		assertTrue(SearchMatcher.score("Varrock", "var") > SearchMatcher.score("Varrock Palace", "var"));
	}

	@Test
	public void historyPushDedupesAndCaps()
	{
		List<Destinations.Entry> history = List.of();
		for (int i = 0; i < 15; i++)
		{
			history = SearchHistory.push(history, new Destinations.Entry("place", "Place " + i, i));
		}
		assertEquals(SearchHistory.LIMIT, history.size());
		assertEquals("Place 14", history.get(0).name);

		// Re-selecting an existing entry moves it to the front without duplicating it.
		history = SearchHistory.push(history, new Destinations.Entry("place", "Place 12", 12));
		assertEquals(SearchHistory.LIMIT, history.size());
		assertEquals("Place 12", history.get(0).name);
		assertEquals(1, history.stream().filter(e -> e.name.equals("Place 12")).count());
	}

	@Test
	public void historySurvivesARoundTrip()
	{
		List<Destinations.Entry> history = List.of(
			new Destinations.Entry("training", "Brimhaven Agility Arena", 12345),
			new Destinations.Entry("place", "Seers' Village", -99));
		List<Destinations.Entry> back = SearchHistory.deserialize(SearchHistory.serialize(history));
		assertEquals(2, back.size());
		assertEquals("Brimhaven Agility Arena", back.get(0).name);
		assertEquals("training", back.get(0).category);
		assertEquals(12345, back.get(0).packedPosition);
		assertEquals(-99, back.get(1).packedPosition);
	}

	@Test
	public void deserializeToleratesJunk()
	{
		assertTrue(SearchHistory.deserialize(null).isEmpty());
		assertTrue(SearchHistory.deserialize("").isEmpty());
		assertEquals(1, SearchHistory.deserialize("place\tValid\t5\ngarbage line\nplace\tNaN\tx").size());
	}
}

package gps;

import gps.transport.TransportType;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The nested-route filter (AlternativeRoutesService.nestsAKeptRoute): a candidate that detours
 * and then runs an already-kept route anyway ("dueling ring + glory + carts" next to
 * "glory + carts") is noise and must be dropped — a field capture showed seven such wrappers
 * around one Keldagrim route. Walking never dominates, and bank-fetch candidates are spared.
 */
public class RouteNestingTest
{
	private static final TeleportMethod GLORY =
		new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Amulet of glory: Edgeville", 1);
	private static final TeleportMethod CARTS =
		new TeleportMethod(TransportType.MINECART, "Keldagrim", 2);
	private static final TeleportMethod DUELING =
		new TeleportMethod(TransportType.TELEPORTATION_ITEM, "Ring of dueling: Castle Wars", 3);
	private static final TeleportMethod VARROCK =
		new TeleportMethod(TransportType.TELEPORTATION_SPELL, "Varrock Teleport", 4);

	private static RouteOption route(List<TeleportMethod> methods, Set<TeleportMethod> bankMethods)
	{
		return new RouteOption(List.of(), methods, List.of(), List.of(), 100, 100, true,
			bankMethods, List.of(), 0);
	}

	@Test
	public void detourPlusKeptRouteIsNested()
	{
		List<RouteOption> kept = List.of(route(List.of(GLORY, CARTS), Set.of()));
		assertTrue(AlternativeRoutesService.nestsAKeptRoute(
			List.of(DUELING, GLORY, CARTS), false, kept));
		assertTrue("double-teleport prefix still nests", AlternativeRoutesService.nestsAKeptRoute(
			List.of(VARROCK, DUELING, GLORY, CARTS), false, kept));
	}

	@Test
	public void genuinelyDifferentEndingsSurvive()
	{
		List<RouteOption> kept = List.of(route(List.of(GLORY, CARTS), Set.of()));
		// Varrock -> carts: same carts, different opening — carts alone is not the kept SEQUENCE.
		assertFalse(AlternativeRoutesService.nestsAKeptRoute(
			List.of(VARROCK, CARTS), false, kept));
		// Same length = same signature territory, not nesting.
		assertFalse(AlternativeRoutesService.nestsAKeptRoute(
			List.of(DUELING, CARTS), false, kept));
	}

	@Test
	public void walkOnlyNeverDominatesAndBankFetchIsSpared()
	{
		// A walk-only kept route has an empty sequence — matching "every suffix" would kill all.
		List<RouteOption> keptWalk = List.of(route(List.of(), Set.of()));
		assertFalse(AlternativeRoutesService.nestsAKeptRoute(
			List.of(GLORY, CARTS), false, keptWalk));
		// Bank-fetching candidate vs a non-bank kept route: the detour withdraws the item — real.
		List<RouteOption> kept = List.of(route(List.of(GLORY, CARTS), Set.of()));
		assertFalse(AlternativeRoutesService.nestsAKeptRoute(
			List.of(DUELING, GLORY, CARTS), true, kept));
		// But bank candidate vs bank kept route: nested is nested.
		List<RouteOption> keptBank = List.of(route(List.of(GLORY, CARTS), Set.of(GLORY)));
		assertTrue(AlternativeRoutesService.nestsAKeptRoute(
			List.of(DUELING, GLORY, CARTS), true, keptBank));
	}
}

