package gps;

import gps.pathfinder.DistanceField;
import gps.pathfinder.Pathfinder;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.mockito.Mockito.when;

/** MEASUREMENT, not theory: field values + search mode for land-on-island vs water-off-island. */
@RunWith(MockitoJUnitRunner.Silent.class)
public class WaterPinFieldProbeTest
{
	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	private PathfinderConfig planning(int targetPacked)
	{
		when(config.calculationCutoff()).thenReturn(120);
		when(config.useTeleportationItems()).thenReturn(TeleportationItem.ALL);
		when(config.useSailing()).thenReturn(true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		PathfinderConfig planning = new TestPathfinderConfig(client, config).copyForPlanning();
		planning.refresh();
		planning.setExtraTransports(SailingSea.seaLegTransports(targetPacked, 6));
		planning.rebuildAvailabilityWithExclusions(Set.of());
		return planning;
	}

	private void scenario(String label, int pin)
	{
		System.out.println("=== " + label + " pin " + WorldPointUtil.unpackWorldX(pin) + ","
			+ WorldPointUtil.unpackWorldY(pin) + " sailable=" + SailingSea.isSailable(pin));
		PathfinderConfig planning = planning(pin);
		System.out.println("  extras: " + SailingSea.seaLegTransports(pin, 6).size());
		long start = System.nanoTime();
		DistanceField field = DistanceField.build(planning, Set.of(pin));
		System.out.println("  field build ms: " + (System.nanoTime() - start) / 1_000_000);
		int[][] probes = {{3222, 3218}, {3029, 3217}, {2951, 3146}, {1634, 3038}};
		for (int[] p : probes)
		{
			int d = field.distance(WorldPointUtil.packWorldPoint(p[0], p[1], 0));
			System.out.println("  field@" + p[0] + "," + p[1] + ": "
				+ (d == DistanceField.UNREACHED ? "UNREACHED" : d));
		}
		// The PRODUCTION sequence: bounded field + the start-gated heuristic.
		DistanceField bounded = DistanceField.buildIfCompact(planning, Set.of(pin), 6);
		System.out.println("  bounded field null: " + (bounded == null));
		if (bounded != null)
		{
			int[][] probes2 = {{3222, 3218}, {3029, 3217}};
			for (int[] p2 : probes2)
			{
				int d = bounded.distance(WorldPointUtil.packWorldPoint(p2[0], p2[1], 0));
				System.out.println("  bounded@" + p2[0] + "," + p2[1] + ": "
					+ (d == DistanceField.UNREACHED ? "UNREACHED" : d));
			}
			gps.pathfinder.SearchHeuristic h = gps.pathfinder.SearchHeuristic.buildWithField(
				planning, bounded, WorldPointUtil.packWorldPoint(3222, 3218, 0));
			System.out.println("  heuristic null: " + (h == null));
			if (h != null)
			{
				long t0 = System.nanoTime();
				Pathfinder seedStyle = new Pathfinder(planning,
					WorldPointUtil.packWorldPoint(3212, 3428, 0), Set.of(pin),
					Integer.MAX_VALUE, h);
				seedStyle.run();
				System.out.println("  seed-style search: reached="
					+ seedStyle.getResult().isReached()
					+ " ms=" + (System.nanoTime() - t0) / 1_000_000);
			}
		}
	}

	@Test
	public void measure()
	{
		scenario("LAND on Dognose", WorldPointUtil.packWorldPoint(3048, 2648, 0));
		scenario("WATER off Dognose", WorldPointUtil.packWorldPoint(3036, 2652, 0));
		scenario("WATER mid-ocean", WorldPointUtil.packWorldPoint(2894, 2637, 0));
	}
}

package gps;

import gps.pathfinder.PathStep;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import gps.transport.Transport;
import java.lang.reflect.Proxy;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import org.junit.Assume;
import org.junit.Test;
import org.mockito.Mockito;

/** Probe (-Dgps.apeProbe=true): what the Grand Tree -> Ape Atoll routes carry as methods vs plain steps. */
public class ApeAtollProbeTest
{
	private static Client client()
	{
		final Thread ct = Thread.currentThread();
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState": return GameState.LOGGED_IN;
					case "getClientThread": return ct;
					case "getBoostedSkillLevel": return 99;
					default: return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
	}

	@Test
	public void grandTreeToApeAtoll() throws Exception
	{
		Assume.assumeTrue(Boolean.getBoolean("gps.apeProbe"));
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		Mockito.when(cfg.currencyThreshold()).thenReturn(10000000);
		Mockito.when(cfg.useTeleportationItems()).thenReturn(TeleportationItem.INVENTORY);
		for (String name : new String[]{"useBoats", "useShips", "useCharterShips", "useGnomeGliders", "useFairyRings",
			"useSpiritTrees", "useTeleportationSpells", "useAgilityShortcuts", "useTeleportationPortals"})
		{
			Mockito.when((Boolean) ShortestPathConfig.class.getMethod(name).invoke(cfg)).thenReturn(true);
		}
		PathfinderConfig config = new TestPathfinderConfig(client(), cfg).copyForPlanning();
		config.refresh();
		ClientThread ct = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(Mockito.any(Runnable.class));
		AlternativeRoutesService service = new AlternativeRoutesService(ct, config);
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		service.generate(WorldPointUtil.packWorldPoint(2465, 3496, 0),
			Set.of(WorldPointUtil.packWorldPoint(2803, 2706, 0)), Set.of(),
			AlternativeRoutesMode.ALL_EVERYTHING, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		latch.await(120, TimeUnit.SECONDS);
		StringBuilder sb = new StringBuilder("\nPROBE ape atoll\n");
		for (RouteOption route : out.get())
		{
			sb.append(String.format("cost %d walkOnly=%s methods=%s%n", route.getTotalCost(), route.isWalkOnly(), route.getMethods()));
			List<PathStep> path = route.getPath();
			for (int i = 1; i < path.size(); i++)
			{
				int a = path.get(i - 1).getPackedPosition(), b = path.get(i).getPackedPosition();
				if (WorldPointUtil.distanceBetween(a, b) > 1 || WorldPointUtil.unpackWorldPlane(a) != WorldPointUtil.unpackWorldPlane(b))
				{
					List<Transport> rows = config.transportsOnEdge(a, b);
					sb.append(String.format("   jump@%d %d,%d,%d -> %d,%d,%d : %s%n", i,
						WorldPointUtil.unpackWorldX(a), WorldPointUtil.unpackWorldY(a), WorldPointUtil.unpackWorldPlane(a),
						WorldPointUtil.unpackWorldX(b), WorldPointUtil.unpackWorldY(b), WorldPointUtil.unpackWorldPlane(b),
						rows.stream().map(t -> t.getType() + "/" + t.getObjectInfo() + "/" + t.getDisplayInfo()).collect(java.util.stream.Collectors.toList())));
				}
			}
		}
		System.out.println(sb);
		service.shutdown();
	}
}

package gps;

import gps.pathfinder.Pathfinder;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import java.lang.reflect.Proxy;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import org.junit.Assume;
import org.junit.Test;
import org.mockito.Mockito;

/** Issue probes (-Dgps.issueProbe=true): #21 Kharazi walkability, #15 Brittle Isle generation time. */
public class IssueProbesTest
{
	private static Client client()
	{
		final Thread ct = Thread.currentThread();
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState": return GameState.LOGGED_IN;
					case "getClientThread": return ct;
					case "getBoostedSkillLevel": return 99;
					default: return HybridPageFillTest.defaultValue(method.getReturnType());
				}
			});
	}

	@Test
	public void kharaziWalkOnly()
	{
		Assume.assumeTrue(Boolean.getBoolean("gps.issueProbe"));
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(60);
		PathfinderConfig config = new TestPathfinderConfig(client(), cfg).copyForPlanning();
		config.refresh();
		Pathfinder pathfinder = new Pathfinder(config,
			WorldPointUtil.packWorldPoint(2825, 2997, 0),
			Set.of(WorldPointUtil.packWorldPoint(2950, 2902, 0)));
		pathfinder.run();
		List<gps.pathfinder.PathStep> path = pathfinder.getPath();
		int transports = 0;
		for (int i = 1; i < path.size(); i++)
		{
			if (WorldPointUtil.distanceBetween(path.get(i - 1).getPackedPosition(),
				path.get(i).getPackedPosition()) > 1)
			{
				transports++;
			}
		}
		System.out.println("PROBE #21 kharazi reached=" + pathfinder.getResult().isReached()
			+ " steps=" + path.size() + " jumps(transports)=" + transports);
	}

	@Test
	public void kharaziInteriorWalkOnly()
	{
		Assume.assumeTrue(Boolean.getBoolean("gps.issueProbe"));
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(60);
		PathfinderConfig config = new TestPathfinderConfig(client(), cfg).copyForPlanning();
		config.refresh();
		// Issue 21's second snapshot: 2925,2944 -> 2950,2902 came back as a 95-cost WALK with no methods.
		Pathfinder pathfinder = new Pathfinder(config,
			WorldPointUtil.packWorldPoint(2925, 2944, 0),
			Set.of(WorldPointUtil.packWorldPoint(2950, 2902, 0)));
		pathfinder.run();
		List<gps.pathfinder.PathStep> path = pathfinder.getPath();
		int jumps = 0;
		StringBuilder jumpAt = new StringBuilder();
		for (int i = 1; i < path.size(); i++)
		{
			int a = path.get(i - 1).getPackedPosition();
			int b = path.get(i).getPackedPosition();
			if (WorldPointUtil.distanceBetween(a, b) > 1)
			{
				jumps++;
				jumpAt.append(' ').append(WorldPointUtil.unpackWorldX(a)).append(',').append(WorldPointUtil.unpackWorldY(a));
			}
		}
		System.out.println("PROBE #21b interior reached=" + pathfinder.getResult().isReached()
			+ " steps=" + path.size() + " jumps=" + jumps + jumpAt);
	}

	/** Collision-only BFS (no transports at all): can the interior be WALKED? */
	@Test
	public void kharaziInteriorCollisionOnly()
	{
		Assume.assumeTrue(Boolean.getBoolean("gps.issueProbe"));
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(60);
		PathfinderConfig config = new TestPathfinderConfig(client(), cfg).copyForPlanning();
		config.refresh();
		gps.pathfinder.CollisionMap map = config.getMap();
		int start = WorldPointUtil.packWorldPoint(2925, 2944, 0);
		int goal = WorldPointUtil.packWorldPoint(2950, 2902, 0);
		java.util.ArrayDeque<Integer> queue = new java.util.ArrayDeque<>();
		java.util.HashSet<Integer> seen = new java.util.HashSet<>();
		queue.add(start);
		seen.add(start);
		boolean reached = false;
		while (!queue.isEmpty() && seen.size() < 200000)
		{
			int at = queue.poll();
			if (at == goal)
			{
				reached = true;
				break;
			}
			int x = WorldPointUtil.unpackWorldX(at);
			int y = WorldPointUtil.unpackWorldY(at);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					int next = WorldPointUtil.packWorldPoint(x + dx, y + dy, 0);
					if ((dx != 0 || dy != 0) && map.canStep(at, next) && seen.add(next))
					{
						queue.add(next);
					}
				}
			}
		}
		System.out.println("PROBE #21c collision-only walk reached=" + reached + " flooded=" + seen.size());
	}

	@Test
	public void brittleIsleGenerationTime() throws Exception
	{
		Assume.assumeTrue(Boolean.getBoolean("gps.issueProbe"));
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class, Mockito.withSettings().stubOnly());
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		Mockito.when(cfg.useSailing()).thenReturn(true);
		PathfinderConfig config = new TestPathfinderConfig(client(), cfg).copyForPlanning();
		config.refresh();
		ClientThread ct = Mockito.mock(ClientThread.class, Mockito.withSettings().stubOnly());
		Mockito.doAnswer(i ->
		{
			((Runnable) i.getArgument(0)).run();
			return null;
		}).when(ct).invokeLater(Mockito.any(Runnable.class));
		AlternativeRoutesService service = new AlternativeRoutesService(ct, config);
		CountDownLatch latch = new CountDownLatch(1);
		AtomicReference<List<RouteOption>> out = new AtomicReference<>();
		long start = System.nanoTime();
		service.generate(WorldPointUtil.packWorldPoint(2936, 3281, 0),
			Set.of(WorldPointUtil.packWorldPoint(1947, 4067, 0)), Set.of(),
			AlternativeRoutesMode.ALL_EVERYTHING, 10, 3, false,
			(routes, catalog, unavailable, done) ->
			{
				if (done)
				{
					out.set(routes);
					latch.countDown();
				}
			});
		boolean finished = latch.await(180, TimeUnit.SECONDS);
		long ms = (System.nanoTime() - start) / 1_000_000;
		System.out.println("PROBE #15 brittle isle finished=" + finished + " in " + ms + " ms, routes="
			+ (out.get() == null ? -1 : out.get().size())
			+ (out.get() != null && !out.get().isEmpty() ? " best=" + out.get().get(0).getTotalCost() + " " + out.get().get(0).getMethods() : ""));
		service.shutdown();
	}
}

package gps;

import gps.pathfinder.CollisionMap;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TestPathfinderConfig;
import gps.transport.Transport;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import org.junit.BeforeClass;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * DATA INVARIANT: every searchable destination must be somewhere a player can actually get to.
 *
 * A pin on an unreachable tile is worse than a missing pin — the search explores the whole map,
 * gives up, and drops the player at "the closest reachable point", which is the pathology that
 * produced the Kingdom Divided report. Rather than pathfind to thousands of pins (minutes), this
 * floods ONCE from Lumbridge across walking edges plus every transport, then asserts each
 * destination's {@link Destinations#walkableTargets} set intersects that reachable region — the
 * same expansion the real search performs, so a pin on a fence still passes if its surroundings
 * are reachable.
 *
 * Failures are reported in bulk with coordinates, so a bad import is one glance to triage.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class DestinationsReachableTest
{
	private static final int LUMBRIDGE = WorldPointUtil.packWorldPoint(3222, 3218, 0);
	/** Instanced template bands: pins there are scenery copies, not places (POH, raids, cutscenes). */
	private static final int INSTANCE_MIN_Y = 4160;
	private static final int INSTANCE_MAX_Y = 8000;

	private static Set<Integer> reachable;
	private static CollisionMap map;

	@Mock
	Client client;
	@Mock
	ShortestPathConfig config;

	@BeforeClass
	public static void beforeClass()
	{
		reachable = null;
	}

	private void flood()
	{
		if (reachable != null)
		{
			return;
		}
		when(config.calculationCutoff()).thenReturn(120);
		when(config.useTeleportationItems()).thenReturn(gps.TeleportationItem.ALL);
		when(config.useSailing()).thenReturn(true);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getClientThread()).thenReturn(Thread.currentThread());
		TestPathfinderConfig testConfig = new TestPathfinderConfig(client, config);
		// Universal bank: reachable means "a player CAN get there" — any obtainable item is
		// assumed owned (dashboard's BANK-preset pattern), else item-gated teleports like the
		// Sailors' amulet would wrongly strand their destinations (Port Roberts).
		net.runelite.api.ItemContainer universalBank = mock(net.runelite.api.ItemContainer.class);
		net.runelite.api.Item[] everyItem = new net.runelite.api.Item[40000];
		for (int i = 0; i < everyItem.length; i++)
		{
			everyItem[i] = new net.runelite.api.Item(i, 1000);
		}
		when(universalBank.getItems()).thenReturn(everyItem);
		testConfig.bank = universalBank;
		PathfinderConfig planning = testConfig.copyForPlanning();
		planning.refresh();
		map = planning.getMap();

		// Transport edges by origin, so the flood can jump the way a route can. Bank-visited
		// availability is the superset (it also offers banked-item teleports).
		PrimitiveIntHashMap<Transport[]> transports = planning.getTransportsPacked(true);
		Set<Integer> seen = new HashSet<>(1 << 20);
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		seen.add(LUMBRIDGE);
		queue.add(LUMBRIDGE);
		// ORIGIN-LESS teleports (jewellery, tablets, spells) are usable ANYWHERE, so their
		// landing tiles are reachable outright. Keyed under UNDEFINED_ORIGIN rather than a
		// tile, they were invisible to a walk-the-graph flood — which made every
		// teleport-only destination, Port Roberts included, look sealed.
		Transport[] anywhere = transports.get(Transport.UNDEFINED_ORIGIN);
		if (anywhere != null)
		{
			for (Transport transport : anywhere)
			{
				if (transport.getDestination() != WorldPointUtil.UNDEFINED
					&& seen.add(transport.getDestination()))
				{
					queue.add(transport.getDestination());
				}
			}
		}
		while (!queue.isEmpty())
		{
			int at = queue.poll();
			int x = WorldPointUtil.unpackWorldX(at);
			int y = WorldPointUtil.unpackWorldY(at);
			int plane = WorldPointUtil.unpackWorldPlane(at);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if (dx == 0 && dy == 0)
					{
						continue;
					}
					int next = WorldPointUtil.packWorldPoint(x + dx, y + dy, plane);
					// Transport origins may be collision-blocked (a fairy ring blocks its
					// own tile); the engine admits them via isTransportOrigin, so the flood
					// must too — without this, ALL ring-only content (Zanaris) reads sealed.
					// ...and symmetrically OFF one: a transport delivers you ONTO its
					// blocked destination ring; without the exit clause Zanaris's hub ring
					// was a trap node and the whole realm stayed sealed.
					if (!seen.contains(next)
						&& (map.canStep(at, next) || transports.get(next) != null
							|| (transports.get(at) != null && !map.isBlocked(x + dx, y + dy, plane))))
					{
						seen.add(next);
						queue.add(next);
					}
				}
			}
			Transport[] fromHere = transports.get(at);
			if (fromHere != null)
			{
				for (Transport transport : fromHere)
				{
					int destination = transport.getDestination();
					if (destination != WorldPointUtil.UNDEFINED && seen.add(destination))
					{
						queue.add(destination);
					}
				}
			}
		}
		reachable = seen;
	}

	/**
	 * Curated pins whose ENTRANCE has no transport row yet — real data gaps, not bad pins, each
	 * needing the cave/dungeon entrance mapped (audit field capture). Shrink this list; never
	 * add to it. Found by this test on 2026-07-27.
	 */
	private static final Set<String> KNOWN_GAPS = Set.of(
		"Ferox Enclave Dungeon", "Mogre Camp", "Ruins of Mokhaiotl", "Kendal's Lair");

	/**
	 * Known-unreachable IMPORTED pins; drive it down, never up. Re-based 647 -> 733 on
	 * 2026-07-29 when the collision substrate fix sealed the sailable ocean (the buoy-network
	 * flood, exactly): 86 pins had been reachable only by WALKING ON THE SEA. The honest
	 * backlog shrinks via the snap pass and island landings.
	 */
	// 733 -> 747 with the 2026-07-30 cache refresh (rev 2644): a world update legitimately
	// moves this number; the ratchet exists to catch OUR data regressions between refreshes.
	private static final int RATCHET = 738;

	/**
	 * Real content living inside the instance template band, enforced by the invariant like
	 * anywhere else. The band is MOSTLY scenery copies (POH layouts, cutscenes), but a few
	 * genuine places are built there — the blanket skip hid a fully sealed Motherlode Mine
	 * pin. Transport-proximity was tried and over-matched (POH portal rows qualified whole
	 * template houses); an explicit box per known place is honest and auditable.
	 */
	private static final int[][] BAND_CONTENT_BOXES = {
		{3700, 5620, 3780, 5710}, // Motherlode Mine
		{2360, 4340, 2500, 4480}, // Zanaris
	};

	private boolean bandContent(int packed)
	{
		int x = WorldPointUtil.unpackWorldX(packed);
		int y = WorldPointUtil.unpackWorldY(packed);
		for (int[] box : BAND_CONTENT_BOXES)
		{
			if (x >= box[0] && y >= box[1] && x <= box[2] && y <= box[3])
			{
				return true;
			}
		}
		return false;
	}

	private boolean anyReachable(int packed)
	{
		for (int target : Destinations.walkableTargets(map, packed))
		{
			if (reachable.contains(target))
			{
				return true;
			}
		}
		return false;
	}

	/** The hand-curated pins are ours to author, so the bar is zero unreachable. */
	@Test
	public void everyCuratedDestinationIsReachable() throws java.io.IOException
	{
		flood();
		List<String> unreachable = new ArrayList<>();
		int checked = 0;
		try (java.io.InputStream in =
			ShortestPathPlugin.class.getResourceAsStream("/destinations-curated.tsv"))
		{
			java.util.Scanner scanner = new java.util.Scanner(in, "UTF-8");
			scanner.nextLine(); // header
			while (scanner.hasNextLine())
			{
				String[] fields = scanner.nextLine().split("\t");
				if (fields.length < 5 || fields[0].startsWith("#"))
				{
					continue;
				}
				int packed = WorldPointUtil.packWorldPoint(Integer.parseInt(fields[2].trim()),
					Integer.parseInt(fields[3].trim()), Integer.parseInt(fields[4].trim()));
				int py = WorldPointUtil.unpackWorldY(packed);
				if (py >= INSTANCE_MIN_Y && py <= INSTANCE_MAX_Y || KNOWN_GAPS.contains(fields[1]))
				{
					continue;
				}
				checked++;
				if (!anyReachable(packed))
				{
					unreachable.add(fields[1] + " @" + fields[2] + "," + fields[3] + "," + fields[4]);
				}
			}
		}
		assertTrue("expected the curated pins to load", checked > 20);
		assertTrue("curated destinations must be reachable, these are not:\n  "
			+ String.join("\n  ", unreachable), unreachable.isEmpty());
	}

	/**
	 * The bulk imports (wiki + amenity dumps) carry known debt — 1166 of 5598 when written,
	 * largely upper-floor altars whose staircases have no transport row. A RATCHET rather than a
	 * hard zero, so imports can't quietly add unreachable pins while the backlog is worked down.
	 */
	@Test
	public void importedDestinationsDoNotRegress()
	{
		flood();
		List<String> unreachable = new ArrayList<>();
		int checked = 0;
		for (Destinations.Entry entry : Destinations.resourceEntries())
		{
			int y = WorldPointUtil.unpackWorldY(entry.packedPosition);
			if (y >= INSTANCE_MIN_Y && y <= INSTANCE_MAX_Y && !bandContent(entry.packedPosition))
			{
				continue; // template junk: no transports anywhere near
			}
			checked++;
			if (!anyReachable(entry.packedPosition))
			{
				unreachable.add(entry.category + " / " + entry.name + " @"
					+ WorldPointUtil.unpackWorldX(entry.packedPosition) + ","
					+ WorldPointUtil.unpackWorldY(entry.packedPosition) + ","
					+ WorldPointUtil.unpackWorldPlane(entry.packedPosition));
			}
		}
		assertTrue("checked at least a few hundred destinations", checked > 200);
		// Band-content offenders get named first: they are enforced by an explicit box, so
		// a failure here is either a data gap in a REAL band place or a wrong box.
		List<String> bandOffenders = new ArrayList<>();
		for (String entry : unreachable)
		{
			String[] at = entry.substring(entry.lastIndexOf('@') + 1).split(",");
			int y = Integer.parseInt(at[1]);
			if (y >= INSTANCE_MIN_Y && y <= INSTANCE_MAX_Y)
			{
				bandOffenders.add(entry);
			}
		}
		assertTrue("BAND-CONTENT offenders (" + bandOffenders.size() + "): "
			+ String.join("; ", bandOffenders) + " ||| "
			+ unreachable.size() + " of " + checked + " imported destinations are unreachable"
			+ " (ratchet: " + RATCHET + "). New unreachable pins are not acceptable; the existing"
			+ " backlog is being worked down. First offenders:\n  "
			+ String.join("\n  ", unreachable.subList(0, Math.min(40, unreachable.size()))),
			unreachable.size() <= RATCHET);
	}
}

