package gps.transport.parser;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Every requirement the field parsers could not read, kept so a test can FAIL on them. A
 * parse failure drops the gate entirely — the transport becomes usable without its item,
 * level or var — and for weeks that only showed as log noise (an Underground Pass dig was
 * free because its row spelled "Spade"; the Motherlode ladders lost their durations to
 * the varbit column). Recorded alongside the log line; drained by the data lint test.
 */
public final class ParseErrors
{
	private static final List<String> RECORDED = Collections.synchronizedList(new ArrayList<>());

	private ParseErrors()
	{
	}

	static void record(String what, String value)
	{
		RECORDED.add(what + ": " + value);
	}

	/** Returns everything recorded since the last drain, and clears. */
	public static List<String> drain()
	{
		synchronized (RECORDED)
		{
			List<String> out = new ArrayList<>(RECORDED);
			RECORDED.clear();
			return out;
		}
	}
}

package gps.transport.parser;

import java.util.Map;

import lombok.Getter;

/**
 * Represents a variable-based requirement for a transport.
 * This can be either a varbit or a varplayer requirement.
 *
 * <p>
 * Consolidates the previously separate TransportVarbit and TransportVarPlayer
 * classes which had identical logic.
 * </p>
 */
@Getter
public class VarRequirement
{

	private final VarType varType;
	private final int id;
	private final int value;
	private final VarCheckType checkType;

	public VarRequirement(VarType varType, int id, int value, VarCheckType checkType)
	{
		this.varType = varType;
		this.id = id;
		this.value = value;
		this.checkType = checkType;
	}

	/**
	 * Creates a varbit requirement.
	 */
	public static VarRequirement varbit(int id, int value, VarCheckType checkType)
	{
		return new VarRequirement(VarType.VARBIT, id, value, checkType);
	}

	/**
	 * Creates a varplayer requirement.
	 */
	public static VarRequirement varPlayer(int id, int value, VarCheckType checkType)
	{
		return new VarRequirement(VarType.VARPLAYER, id, value, checkType);
	}

	/**
	 * Checks if this requirement is satisfied given the current variable values.
	 *
	 * @param values A map of variable IDs to their current values
	 * @return true if the requirement is satisfied
	 */
	public boolean check(Map<Integer, Integer> values)
	{
		Integer currentValue = values.get(id);
		if (currentValue == null)
		{
			return false;
		}
		return checkValue(currentValue);
	}

	/**
	 * Same logic as {@link #check(Map)} but with the variable value already resolved (e.g. from the client).
	 */
	public boolean checkValue(int currentValue)
	{
		switch (checkType)
		{
			case EQUAL:
				return currentValue == value;
			case GREATER:
				return currentValue > value;
			case SMALLER:
				return currentValue < value;
			case BIT_SET:
				return (currentValue & value) > 0;
			case COOLDOWN_MINUTES:
				return ((System.currentTimeMillis() / 60000) - currentValue) > value;
			default:
				return false;
		}
	}

	public boolean isVarbit()
	{
		return varType == VarType.VARBIT;
	}

	public boolean isVarPlayer()
	{
		return varType == VarType.VARPLAYER;
	}

	@Override
	public int hashCode()
	{
		int result = varType.hashCode();
		result = 31 * result + id;
		result = 31 * result + value;
		result = 31 * result + checkType.hashCode();
		return result;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (o == null || getClass() != o.getClass())
		{
			return false;
		}
		VarRequirement that = (VarRequirement) o;
		return id == that.id && value == that.value && varType == that.varType && checkType == that.checkType;
	}

	@Override
	public String toString()
	{
		return varType + "[" + id + " " + checkType.getCode() + " " + value + "]";
	}

	/**
	 * The type of variable this requirement checks.
	 */
	public enum VarType
	{
		VARBIT,
		VARPLAYER
	}
}

package gps.transport.parser;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

import lombok.extern.slf4j.Slf4j;
import gps.ItemVariations;
import gps.Util;
import gps.transport.requirement.ItemRequirement;
import gps.transport.requirement.TransportItems;

/**
 * Parses item requirements from TSV field values.
 *
 * <p>
 * Format: {@code ITEM_NAME=quantity} with AND (&amp;) and OR (|) operators
 * </p>
 * <p>
 * Example: {@code AIR_RUNE=3&FIRE_RUNE=2} (need both)
 * </p>
 * <p>
 * Example: {@code DRAMEN_STAFF=1|LUNAR_STAFF=1} (need either)
 * </p>
 */
@Slf4j
public class ItemRequirementParser implements FieldParser<TransportItems>
{
	private static final String DELIM_STATE = "=";
	private static final String DELIM_AND = "&";
	private static final String DELIM_OR = "|";

	@Override
	public TransportItems parse(String value)
	{
		if (value == null || value.isEmpty())
		{
			return null;
		}

		// Normalize the input
		String normalized = value.replace(" ", "")
			.replace(DELIM_AND + DELIM_AND, DELIM_AND)
			.replace(DELIM_OR + DELIM_OR, DELIM_OR)
			.toUpperCase();

		List<ItemRequirement> requirements = new ArrayList<>();

		try
		{
			// Split by AND to get individual requirements
			String[] andParts = normalized.split(DELIM_AND);

			for (String andPart : andParts)
			{
				ItemRequirement requirement = parseRequirement(andPart);
				requirements.add(requirement);
			}

			return requirements.isEmpty() ? null : new TransportItems(requirements);
		}
		catch (NumberFormatException e)
		{
			log.error("Invalid item or quantity: {}", value);
			ParseErrors.record("item", value);
			return null;
		}
	}

	/**
	 * Parses a single requirement which may have OR alternatives.
	 * Example: "AIR_RUNE=3|DUST_RUNE=3"
	 */
	private ItemRequirement parseRequirement(String part)
	{
		String[] orParts = part.split(Pattern.quote(DELIM_OR));

		List<int[]> itemIdsList = new ArrayList<>();
		List<int[]> stavesList = new ArrayList<>();
		List<int[]> offhandsList = new ArrayList<>();
		int maxQuantity = -1;

		for (String orPart : orParts)
		{
			String[] itemAndQuantity = orPart.split(DELIM_STATE);
			if (itemAndQuantity.length != 2)
			{
				throw new NumberFormatException("Invalid format: " + part);
			}

			String itemName = itemAndQuantity[0];
			int quantity = Integer.parseInt(itemAndQuantity[1]);
			maxQuantity = Math.max(maxQuantity, quantity);

			ItemVariations variation = ItemVariations.fromName(itemName);
			if (variation != null)
			{
				itemIdsList.add(variation.getIds());
				stavesList.add(ItemVariations.staves(variation));
				offhandsList.add(ItemVariations.offhands(variation));
			}
			else
			{
				// Try parsing as raw item ID
				itemIdsList.add(new int[]{Integer.parseInt(itemName)});
				stavesList.add(new int[0]);
				offhandsList.add(new int[0]);
			}
		}

		return new ItemRequirement(
			Util.concatenate(itemIdsList.toArray(new int[0][])),
			Util.concatenate(stavesList.toArray(new int[0][])),
			Util.concatenate(offhandsList.toArray(new int[0][])),
			maxQuantity);
	}
}

package gps.transport.parser;

import java.util.HashSet;
import java.util.Set;
import java.util.regex.Pattern;

import lombok.extern.slf4j.Slf4j;

/**
 * Parses variable requirement strings into VarRequirement objects.
 * Supports both varbit and varplayer requirements.
 *
 * <p>
 * Format: {@code <id><check><value>} where check is one of: = > < & @
 * </p>
 * <p>
 * Multiple requirements are separated by semicolons.
 * </p>
 * <p>
 * Example: {@code 1234=1;5678>10}
 * </p>
 */
@Slf4j
public class VarRequirementParser implements FieldParser<Set<VarRequirement>>
{
	private static final String DELIM_MULTI = ";";

	private final VarRequirement.VarType varType;

	/**
	 * Creates a parser for the specified variable type.
	 */
	public VarRequirementParser(VarRequirement.VarType varType)
	{
		this.varType = varType;
	}

	/**
	 * Creates a parser for varbit requirements.
	 */
	public static VarRequirementParser forVarbits()
	{
		return new VarRequirementParser(VarRequirement.VarType.VARBIT);
	}

	/**
	 * Creates a parser for varplayer requirements.
	 */
	public static VarRequirementParser forVarPlayers()
	{
		return new VarRequirementParser(VarRequirement.VarType.VARPLAYER);
	}

	@Override
	public Set<VarRequirement> parse(String value)
	{
		Set<VarRequirement> result = new HashSet<>();
		if (value == null || value.isEmpty())
		{
			return result;
		}

		try
		{
			for (String requirement : value.split(DELIM_MULTI))
			{
				if (requirement.isEmpty())
				{
					continue;
				}

				VarRequirement parsed = parseRequirement(requirement);
				if (parsed != null)
				{
					result.add(parsed);
				}
			}
		}
		catch (NumberFormatException e)
		{
			log.error("Invalid var requirement: {}", value);
			ParseErrors.record("var", value);
		}
		return result;
	}

	private VarRequirement parseRequirement(String requirement)
	{
		for (VarCheckType checkType : VarCheckType.values())
		{
			String[] parts = requirement.split(Pattern.quote(checkType.getCode()));
			if (parts.length == 2)
			{
				int id = Integer.parseInt(parts[0]);
				int val = Integer.parseInt(parts[1]);
				return new VarRequirement(varType, id, val, checkType);
			}
		}
		log.error("Invalid var requirement: '{}'", requirement);
		ParseErrors.record("var", requirement);
		return null;
	}
}

package gps.transport.parser;

import java.util.HashSet;
import java.util.Set;

import net.runelite.api.Quest;

/**
 * Parses quest requirements from TSV field values.
 *
 * <p>
 * Format: Quest names separated by semicolons
 * </p>
 * <p>
 * Example: {@code Dragon Slayer I;Recipe for Disaster}
 * </p>
 */
public class QuestParser implements FieldParser<Set<Quest>>
{
	private static final String DELIM_MULTI = ";";

	@Override
	public Set<Quest> parse(String value)
	{
		Set<Quest> quests = new HashSet<>();
		if (value == null || value.isEmpty())
		{
			return quests;
		}

		String[] questNames = value.split(DELIM_MULTI);
		for (String questName : questNames)
		{
			for (Quest quest : Quest.values())
			{
				if (quest.getName().equals(questName))
				{
					quests.add(quest);
					break;
				}
			}
		}
		return quests;
	}
}

package gps.transport;

import java.util.Collections;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;

import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import gps.WorldPointUtil;
import gps.leagues.LeagueRegion;
import gps.transport.parser.FieldParser;
import gps.transport.parser.ItemRequirementParser;
import gps.transport.parser.QuestParser;
import gps.transport.parser.SkillRequirementParser;
import gps.transport.parser.TransportRecord;
import gps.transport.parser.VarRequirement;
import gps.transport.parser.VarRequirementParser;
import gps.transport.parser.WorldPointParser;
import gps.transport.requirement.TransportItems;

/**
 * This class represents a travel point between two WorldPoints.
 */
@Slf4j
public class Transport
{
	public static final int UNDEFINED_ORIGIN = WorldPointUtil.UNDEFINED;
	public static final int UNDEFINED_DESTINATION = WorldPointUtil.UNDEFINED;
	/**
	 * A location placeholder different from null to use for permutation transports
	 */
	public static final int LOCATION_PERMUTATION = WorldPointUtil.packWorldPoint(-1, -1, 1);
	/** Minimum ticks for an object transport (stairs/door/gate/portal) that carries no explicit duration. */
	private static final int OBJECT_TRANSPORT_MIN_DURATION = 1;
	/**
	 * Shared, never-mutated all-zero skill array. Most transports require no skills, so they point
	 * at this singleton instead of each allocating their own {@code int[]} (issue #491).
	 */
	private static final int[] NO_SKILLS = new int[Skill.values().length + 3];
	/**
	 * The skill levels, total level, combat level and quest points required to use
	 * this transport. Defaults to {@link #NO_SKILLS} until real requirements are set.
	 */
	@Getter
	private int[] skillLevels = NO_SKILLS;
	/**
	 * Variable requirements (varbits and varplayers) for the transport to be valid.
	 * All must pass.
	 */
	// Defaults to a shared immutable empty set; only transports that actually declare var
	// requirements pay for a real Set. Most transports declare none, so this avoids ~one
	// HashSet (+ its HashMap) per transport (issue #491).
	@Getter
	private Set<VarRequirement> varRequirements = Collections.emptySet();
	/**
	 * The starting point of this transport
	 */
	@Getter
	private int origin = UNDEFINED_ORIGIN;
	/**
	 * The ending point of this transport
	 */
	@Setter
	@Getter
	private int destination = UNDEFINED_DESTINATION;

	/**
	 * The quests required to use this transport
	 */
	// Shared immutable empty set by default; see varRequirements above.
	@Getter
	private Set<Quest> quests = Collections.emptySet();
	/**
	 * The item requirements to use this transport
	 */
	@Getter
	private TransportItems itemRequirements;
	/**
	 * The type of transport
	 */
	@Getter
	private TransportType type;
	/**
	 * The travel waiting time in number of ticks
	 */
	@Getter
	private int duration;
	/**
	 * Info to display for this transport. For spirit trees, fairy rings,
	 * and others, this is the destination option to pick.
	 */
	@Getter
	private String displayInfo = null;
	/**
	 * If this is an item transport, this tracks if it is consumable (as opposed to
	 * having infinite uses)
	 */
	@Getter
	private boolean isConsumable = false;
	/**
	 * The maximum wilderness level that the transport can be used in
	 */
	@Getter
	private int maxWildernessLevel = -1;
	/**
	 * Object information for this transport
	 */
	@Getter
	private String objectInfo = null;
	/**
	 * Advisory note shown to the player on the route step ("fire arrow needed", "can fail").
	 * Purely informational — never gates the transport out of routing.
	 */
	@Getter
	private String note = null;
	/**
	 * Per-transport seasonal-league region override. When set, the league-mode
	 * region gate ({@code PathfinderConfig#isTransportRegionAllowed}) uses
	 * this region for the destination chunk instead of the result of
	 * {@code LeagueRegionChecker#getRegion(destination)}. Used for shortcuts
	 * whose destination tile sits in a chunk that the wiki classifies under
	 * a different region (e.g. Trollheim Wilderness climb — destination chunk
	 * is Wilderness, but the wiki lists the shortcut under Asgarnia).
	 */
	@Getter
	private LeagueRegion regionOverride = null;

	/**
	 * Creates a new transport from an origin-only transport
	 * and a destination-only transport, and merges requirements
	 */
	Transport(Transport origin, Transport destination)
	{
		TransportBuilder builder = new TransportBuilder()
			.origin(origin.origin)
			.destination(destination.destination)
			.type(origin.type)
			.startSkillLevels(origin.skillLevels)
			.startSkillLevels(destination.skillLevels)
			.quests(origin.quests)
			.quests(destination.quests)
			.itemRequirements(TransportItems.merge(origin.itemRequirements, destination.itemRequirements))
			.duration(Math.max(origin.duration, destination.duration))
			.displayInfo(destination.displayInfo)
			.isConsumable(origin.isConsumable || destination.isConsumable)
			.maxWildernessLevel(Math.max(origin.maxWildernessLevel, destination.maxWildernessLevel))
			.objectInfo(origin.objectInfo)
			.note(destination.note != null ? destination.note : origin.note)
			.varRequirements(origin.varRequirements)
			.varRequirements(destination.varRequirements)
			.regionOverride(destination.regionOverride != null ? destination.regionOverride : origin.regionOverride);

		Transport builtTransport = builder.build();

		this.origin = builtTransport.origin;
		this.destination = builtTransport.destination;
		this.skillLevels = builtTransport.skillLevels;
		this.quests = builtTransport.quests;
		this.itemRequirements = builtTransport.itemRequirements;
		this.type = builtTransport.type;
		this.duration = builtTransport.duration;
		this.displayInfo = builtTransport.displayInfo;
		this.isConsumable = builtTransport.isConsumable;
		this.maxWildernessLevel = builtTransport.maxWildernessLevel;
		this.objectInfo = builtTransport.objectInfo;
		this.note = builtTransport.note;
		this.varRequirements = builtTransport.varRequirements;
	}

	Transport(TransportRecord record, TransportType transportType)
	{
		TransportBuilder builder = new TransportBuilder();
		builder.type(transportType);

		// Origin/Destination use hasKey because empty string means LOCATION_PERMUTATION
		if (record.hasKey(TransportRecord.Fields.ORIGIN))
		{
			builder.origin(record.getOrigin());
		}
		if (record.hasKey(TransportRecord.Fields.DESTINATION))
		{
			builder.destination(record.getDestination());
		}
		if (record.has(TransportRecord.Fields.SKILLS))
		{
			builder.skillLevels(record.getSkills());
		}
		if (record.has(TransportRecord.Fields.ITEMS))
		{
			builder.itemRequirements(record.getItems());
		}
		if (record.has(TransportRecord.Fields.QUESTS))
		{
			builder.quests(record.getQuests());
		}
		if (record.has(TransportRecord.Fields.DURATION))
		{
			builder.duration(record.getDuration());
		}
		else if (transportType == TransportType.TRANSPORT)
		{
			// Object transports (stairs, ladders, doors, gates, dungeon portals, passages) without an
			// explicit duration are NOT free: interacting with the object and crossing takes at least a
			// tick. Pricing them at zero let the search treat them as free shortcuts — e.g. hopping out
			// of a dungeon and back through an exit that shares its surface tile (Stronghold of
			// Security). Specific transports still override this with a larger duration in the data.
			builder.duration(OBJECT_TRANSPORT_MIN_DURATION);
		}
		if (record.has(TransportRecord.Fields.DISPLAY_INFO))
		{
			builder.displayInfo(record.getDisplayInfo());
		}
		if (record.has(TransportRecord.Fields.CONSUMABLE))
		{
			builder.isConsumable(record.getConsumable());
		}
		if (record.has(TransportRecord.Fields.WILDERNESS_LEVEL))
		{
			builder.maxWildernessLevel(record.getWildernessLevel());
		}
		if (record.has(TransportRecord.Fields.OBJECT_INFO))
		{
			builder.objectInfo(record.getObjectInfo());
		}
		if (record.has(TransportRecord.Fields.NOTE))
		{
			builder.note(record.getNote());
		}
		if (record.has(TransportRecord.Fields.VARBITS))
		{
			builder.varbits(record.getVarbits());
		}
		if (record.has(TransportRecord.Fields.VAR_PLAYERS))
		{
			builder.varPlayers(record.getVarPlayers());
		}
		if (record.has(TransportRecord.Fields.REGION_OVERRIDE))
		{
			builder.regionOverride(record.getRegionOverride());
		}

		Transport builtTransport = builder.build();
		this.origin = builtTransport.origin;
		this.destination = builtTransport.destination;
		this.skillLevels = builtTransport.skillLevels;
		this.quests = builtTransport.quests;
		this.itemRequirements = builtTransport.itemRequirements;
		this.type = builtTransport.type;
		this.duration = builtTransport.duration;
		this.displayInfo = builtTransport.displayInfo;
		this.isConsumable = builtTransport.isConsumable;
		this.maxWildernessLevel = builtTransport.maxWildernessLevel;
		this.objectInfo = builtTransport.objectInfo;
		this.note = builtTransport.note;
		this.varRequirements = builtTransport.varRequirements;
		this.regionOverride = builtTransport.regionOverride;
	}

	private Transport()
	{
	}

	/**
	 * Hands back a shared immutable empty set when the builder accumulated nothing, so empty
	 * requirement sets do not allocate a {@code HashSet}/{@code HashMap} per transport. A non-empty
	 * builder set is handed over directly (the single-use builder is discarded afterwards).
	 */
	private static <T> Set<T> compact(Set<T> set)
	{
		return set.isEmpty() ? Collections.emptySet() : set;
	}

	/**
	 * Quest requirements are keyed on the {@link Quest} enum, so a non-empty set is stored as a
	 * compact {@link EnumSet} (a single bitmask object) rather than a HashSet plus its HashMap and
	 * per-element nodes (issue #491). The empty case keeps the shared immutable empty set.
	 */
	private static Set<Quest> compactQuests(Set<Quest> quests)
	{
		return quests.isEmpty() ? Collections.emptySet() : EnumSet.copyOf(quests);
	}

	/**
	 * Hands back the shared {@link #NO_SKILLS} singleton when no skill requirement is set, so
	 * all-zero skill arrays do not allocate a per-transport {@code int[]}. A non-empty builder array
	 * is handed over directly (the single-use builder is discarded afterwards).
	 */
	private static int[] compactSkills(int[] skills)
	{
		for (int level : skills)
		{
			if (level != 0)
			{
				return skills;
			}
		}
		return NO_SKILLS;
	}

	/**
	 * Load-time flyweight: replaces this transport's requirement objects with shared canonical
	 * instances from the supplied pools, so transports with identical item or var requirements share
	 * one {@code TransportItems}/{@code VarRequirement} instance (and the int[] arrays inside them)
	 * rather than each holding a distinct copy (issue #491). Identical requirements are extremely
	 * common across the permuted transport rows. The pools are local to loading and discarded after.
	 */
	void internRequirements(LoadInterner interner)
	{
		itemRequirements = interner.intern(itemRequirements);
		displayInfo = interner.internString(displayInfo);
		objectInfo = interner.internString(objectInfo);
		if (!varRequirements.isEmpty())
		{
			Set<VarRequirement> interned = new HashSet<>(varRequirements.size() * 2);
			for (VarRequirement requirement : varRequirements)
			{
				interned.add(interner.intern(requirement));
			}
			// Transports with identical var requirements (very common across permutations) share one
			// read-only Set instead of each keeping a copy.
			varRequirements = interner.internVarSet(interned);
		}
		if (!quests.isEmpty())
		{
			quests = interner.internQuestSet(quests);
		}
	}

	@Override
	public String toString()
	{
		return ("(" +
			WorldPointUtil.unpackWorldX(origin) + ", " +
			WorldPointUtil.unpackWorldY(origin) + ", " +
			WorldPointUtil.unpackWorldPlane(origin) + ") to (" +
			WorldPointUtil.unpackWorldX(destination) + ", " +
			WorldPointUtil.unpackWorldY(destination) + ", " +
			WorldPointUtil.unpackWorldPlane(destination) + ")");
	}

	/**
	 * Whether the transport has one or more quest requirements
	 */
	public boolean isQuestLocked()
	{
		return !quests.isEmpty();
	}

	/**
	 * Whether this transport is of the given type.
	 */
	public boolean isType(TransportType type)
	{
		return type.equals(this.type);
	}

	/**
	 * Whether this transport's display info contains the given substring.
	 * Returns false if displayInfo is null.
	 */
	public boolean hasDisplayInfo(String substring)
	{
		return displayInfo != null && displayInfo.contains(substring);
	}

	/**
	 * Whether this transport can be used at the given wilderness level.
	 */
	public boolean isUsableAtWildernessLevel(int wildernessLevel)
	{
		return !type.isTeleport() || wildernessLevel <= maxWildernessLevel;
	}

	/**
	 * Gets varbit requirements (filtered from varRequirements).
	 * For backward compatibility with code that needs separate varbit access.
	 */
	public Set<VarRequirement> getVarbits()
	{
		Set<VarRequirement> varbits = new HashSet<>();
		for (VarRequirement req : varRequirements)
		{
			if (req.isVarbit())
			{
				varbits.add(req);
			}
		}
		return varbits;
	}

	/**
	 * Whether this transport has a varbit requirement with the given ID.
	 */
	public boolean hasVarbit(int varbitId)
	{
		for (VarRequirement req : varRequirements)
		{
			if (req.isVarbit() && req.getId() == varbitId)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Gets varplayer requirements (filtered from varRequirements).
	 * For backward compatibility with code that needs separate varplayer access.
	 */
	public Set<VarRequirement> getVarPlayers()
	{
		Set<VarRequirement> varPlayers = new HashSet<>();
		for (VarRequirement req : varRequirements)
		{
			if (req.isVarPlayer())
			{
				varPlayers.add(req);
			}
		}
		return varPlayers;
	}

	public static class TransportBuilder
	{
		private final int[] skillLevels = new int[Skill.values().length + 3];
		private final Set<VarRequirement> varRequirements = new HashSet<>();
		private final FieldParser<int[]> skillParser = new SkillRequirementParser();
		private final FieldParser<TransportItems> itemParser = new ItemRequirementParser();
		private final FieldParser<Set<Quest>> questParser = new QuestParser();
		private final VarRequirementParser varbitParser = VarRequirementParser.forVarbits();
		private final VarRequirementParser varPlayerParser = VarRequirementParser.forVarPlayers();
		private final FieldParser<Integer> worldPointParser = new WorldPointParser();
		private final Set<Quest> quests = new HashSet<>();
		private int origin = UNDEFINED_ORIGIN;
		private int destination = UNDEFINED_DESTINATION;
		private TransportItems itemRequirements;
		private TransportType type;
		private int duration;
		private String displayInfo = null;
		private boolean isConsumable = false;
		private int maxWildernessLevel = -1;
		private String objectInfo = null;
		private String note = null;
		private LeagueRegion regionOverride = null;

		public TransportBuilder origin(int origin)
		{
			this.origin = origin;
			return this;
		}

		public TransportBuilder origin(String value)
		{
			this.origin = worldPointParser.parse(value);
			return this;
		}

		public TransportBuilder destination(int destination)
		{
			this.destination = destination;
			return this;
		}

		public TransportBuilder destination(String value)
		{
			this.destination = worldPointParser.parse(value);
			return this;
		}

		public TransportBuilder skillLevels(String value)
		{
			int[] parsedSkills = skillParser.parse(value);
			for (int i = 0; i < skillLevels.length; i++)
			{
				if (parsedSkills[i] > 0)
				{
					skillLevels[i] = parsedSkills[i];
				}
			}
			return this;
		}

		public TransportBuilder startSkillLevels(int[] otherSkillLevels)
		{
			for (int i = 0; i < skillLevels.length; i++)
			{
				this.skillLevels[i] = Math.max(this.skillLevels[i], otherSkillLevels[i]);
			}
			return this;
		}

		public TransportBuilder quests(Set<Quest> quests)
		{
			this.quests.addAll(quests);
			return this;
		}

		public TransportBuilder quests(String value)
		{
			this.quests.addAll(questParser.parse(value));
			return this;
		}

		public TransportBuilder itemRequirements(TransportItems itemRequirements)
		{
			this.itemRequirements = itemRequirements;
			return this;
		}

		public TransportBuilder itemRequirements(String value)
		{
			this.itemRequirements = itemParser.parse(value);
			return this;
		}

		public TransportBuilder type(TransportType type)
		{
			this.type = type;
			return this;
		}

		public TransportBuilder duration(int duration)
		{
			this.duration = Math.max(this.duration, duration);
			return this;
		}

		public TransportBuilder duration(String value)
		{
			if (value != null && !value.isEmpty())
			{
				try
				{
					this.duration = Integer.parseInt(value);
				}
				catch (NumberFormatException e)
				{
					log.error("Invalid tick duration: {}", value);
				}
			}
			return this;
		}

		public TransportBuilder displayInfo(String displayInfo)
		{
			this.displayInfo = displayInfo;
			return this;
		}

		public TransportBuilder note(String note)
		{
			this.note = (note == null || note.isEmpty()) ? null : note;
			return this;
		}

		public TransportBuilder isConsumable(boolean isConsumable)
		{
			this.isConsumable |= isConsumable;
			return this;
		}

		public TransportBuilder isConsumable(String value)
		{
			this.isConsumable = "T".equals(value) || "yes".equalsIgnoreCase(value);
			return this;
		}

		public TransportBuilder maxWildernessLevel(int maxWildernessLevel)
		{
			this.maxWildernessLevel = Math.max(this.maxWildernessLevel, maxWildernessLevel);
			return this;
		}

		public TransportBuilder maxWildernessLevel(String value)
		{
			if (value != null && !value.isEmpty())
			{
				try
				{
					this.maxWildernessLevel = Integer.parseInt(value);
				}
				catch (NumberFormatException e)
				{
					log.error("Invalid wilderness level: {}", value);
				}
			}
			return this;
		}

		public TransportBuilder objectInfo(String objectInfo)
		{
			this.objectInfo = objectInfo;
			return this;
		}

		public TransportBuilder regionOverride(LeagueRegion regionOverride)
		{
			if (regionOverride != null)
			{
				this.regionOverride = regionOverride;
			}
			return this;
		}

		public TransportBuilder regionOverride(String value)
		{
			if (value != null && !value.isEmpty())
			{
				try
				{
					this.regionOverride = LeagueRegion.valueOf(value.trim().toUpperCase());
				}
				catch (IllegalArgumentException e)
				{
					log.error("Invalid region override: {}", value);
				}
			}
			return this;
		}

		public TransportBuilder varRequirements(Set<VarRequirement> requirements)
		{
			this.varRequirements.addAll(requirements);
			return this;
		}

		public TransportBuilder varbits(String value)
		{
			this.varRequirements.addAll(varbitParser.parse(value));
			return this;
		}

		public TransportBuilder varPlayers(String value)
		{
			this.varRequirements.addAll(varPlayerParser.parse(value));
			return this;
		}

		public Transport build()
		{
			Transport transport = new Transport();
			transport.origin = this.origin;
			transport.destination = this.destination;
			transport.skillLevels = compactSkills(this.skillLevels);
			transport.quests = compactQuests(this.quests);
			transport.itemRequirements = this.itemRequirements;
			transport.type = this.type;
			transport.duration = this.duration;
			transport.displayInfo = this.displayInfo;
			transport.isConsumable = this.isConsumable;
			transport.maxWildernessLevel = this.maxWildernessLevel;
			transport.objectInfo = this.objectInfo;
			transport.note = this.note;
			transport.varRequirements = compact(this.varRequirements);
			transport.regionOverride = this.regionOverride;

			// Post-build validation/refinement
			if (transport.type != null && transport.type.isTeleport())
			{
				transport.duration = Math.max(transport.duration, 1);
			}

			if (transport.type != null)
			{
				transport.type = transport.type.refine(transport.skillLevels);
			}

			return transport;
		}
	}
}

package gps.transport.requirement;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import lombok.Getter;

/**
 * Represents all item requirements for a transport.
 * All requirements must be satisfied.
 */
@Getter
public class TransportItems
{
	private final List<ItemRequirement> requirements;

	public TransportItems(List<ItemRequirement> requirements)
	{
		this.requirements = List.copyOf(requirements);
	}

	/**
	 * Creates TransportItems from legacy array format for backwards compatibility.
	 */
	public TransportItems(int[][] items, int[][] staves, int[][] offhands, int[] quantities)
	{
		List<ItemRequirement> reqs = new ArrayList<>();
		for (int i = 0; i < items.length; i++)
		{
			reqs.add(new ItemRequirement(
				items[i],
				staves != null && i < staves.length ? staves[i] : new int[0],
				offhands != null && i < offhands.length ? offhands[i] : new int[0],
				quantities[i]));
		}
		this.requirements = Collections.unmodifiableList(reqs);
	}

	/**
	 * Merges two TransportItems, combining all requirements from both.
	 * If either is null, returns the other.
	 */
	public static TransportItems merge(TransportItems first, TransportItems second)
	{
		if (first == null)
		{
			return second;
		}
		if (second == null)
		{
			return first;
		}
		List<ItemRequirement> merged = new ArrayList<>();
		merged.addAll(first.requirements);
		merged.addAll(second.requirements);
		return new TransportItems(merged);
	}

	/**
	 * Gets the number of item requirements.
	 */
	public int size()
	{
		return requirements.size();
	}

	// Legacy getters for backwards compatibility
	public int[][] getItems()
	{
		int[][] items = new int[requirements.size()][];
		for (int i = 0; i < requirements.size(); i++)
		{
			items[i] = requirements.get(i).getItemIds();
		}
		return items;
	}

	public int[][] getStaves()
	{
		int[][] staves = new int[requirements.size()][];
		for (int i = 0; i < requirements.size(); i++)
		{
			staves[i] = requirements.get(i).getStaffIds();
		}
		return staves;
	}

	public int[][] getOffhands()
	{
		int[][] offhands = new int[requirements.size()][];
		for (int i = 0; i < requirements.size(); i++)
		{
			offhands[i] = requirements.get(i).getOffhandIds();
		}
		return offhands;
	}

	public int[] getQuantities()
	{
		int[] quantities = new int[requirements.size()];
		for (int i = 0; i < requirements.size(); i++)
		{
			quantities[i] = requirements.get(i).getQuantity();
		}
		return quantities;
	}

	private String toString(int[][] array)
	{
		StringBuilder text = new StringBuilder();
		for (int[] inner : array)
		{
			text.append((text.length() == 0) ? "" : ", ").append(Arrays.toString(inner));
		}
		return "[" + text + "]";
	}

	@Override
	public int hashCode()
	{
		return requirements.hashCode();
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (o == null || getClass() != o.getClass())
		{
			return false;
		}
		TransportItems that = (TransportItems) o;
		if (requirements.size() != that.requirements.size())
		{
			return false;
		}
		for (int i = 0; i < requirements.size(); i++)
		{
			if (!requirements.get(i).equals(that.requirements.get(i)))
			{
				return false;
			}
		}
		return true;
	}

	@Override
	public String toString()
	{
		return "[" +
			toString(getItems()) + ", " +
			toString(getStaves()) + ", " +
			toString(getOffhands()) + ", " +
			Arrays.toString(getQuantities()) + "]";
	}
}

package gps.transport.requirement;

import java.util.Arrays;

import lombok.Getter;

/**
 * Represents an item requirement with its variations and quantity.
 * For example: AIR_RUNE=3 where AIR_RUNE can be substituted by DUST_RUNE,
 * SMOKE_RUNE, etc.
 */
@Getter
public class ItemRequirement
{
	/**
	 * The item IDs that satisfy this requirement (variations)
	 */
	private final int[] itemIds;

	/**
	 * Staff IDs that can substitute runes for this requirement
	 */
	private final int[] staffIds;

	/**
	 * Offhand IDs that can substitute for this requirement
	 */
	private final int[] offhandIds;

	/**
	 * The quantity required
	 */
	private final int quantity;

	public ItemRequirement(int[] itemIds, int[] staffIds, int[] offhandIds, int quantity)
	{
		this.itemIds = itemIds;
		this.staffIds = staffIds;
		this.offhandIds = offhandIds;
		this.quantity = quantity;
	}

	@Override
	public int hashCode()
	{
		int result = Arrays.hashCode(itemIds);
		result = 31 * result + Arrays.hashCode(staffIds);
		result = 31 * result + Arrays.hashCode(offhandIds);
		result = 31 * result + quantity;
		return result;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (o == null || getClass() != o.getClass())
		{
			return false;
		}
		ItemRequirement that = (ItemRequirement) o;
		return quantity == that.quantity &&
			Arrays.equals(itemIds, that.itemIds) &&
			Arrays.equals(staffIds, that.staffIds) &&
			Arrays.equals(offhandIds, that.offhandIds);
	}
}

package gps.transport;

import java.util.EnumMap;
import java.util.Map;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import gps.ShortestPathConfig;
import gps.ShortestPathPlugin;
import gps.TeleportationItem;

/**
 * Manages the enabled/disabled state and cost thresholds of each TransportType
 * based on config.
 * This centralizes the config reading logic and automatically wires config
 * methods
 * from TransportType to ShortestPathConfig.
 *
 * <p>
 * When adding a new TransportType with config options, you only need to:
 * <ol>
 * <li>Add the config methods to ShortestPathConfig</li>
 * <li>Add the enum entry to TransportType with method references for the
 * enabledGetter and costGetter</li>
 * </ol>
 * This class will automatically pick up the new config getters.
 *
 * <p>
 * <b>Special cases:</b>
 * <ul>
 * <li>{@link TransportType#TELEPORTATION_ITEM} and
 * {@link TransportType#TELEPORTATION_BOX}
 * have no enabledGetter because they are controlled by the
 * {@link TeleportationItem} enum
 * via {@code useTeleportationItems} config. The per-transport filtering is
 * handled
 * in {@code PathfinderConfig.checkTeleportationItemRules()}.</li>
 * <li>{@link TransportType#TRANSPORT} has no enabledGetter because it's the
 * base transport
 * type and is always enabled.</li>
 * </ul>
 */
@Slf4j
public class TransportTypeConfig
{
	private final Map<TransportType, Boolean> enabledStates = new EnumMap<>(TransportType.class);
	private final Map<TransportType, Integer> costThresholds = new EnumMap<>(TransportType.class);
	private final ShortestPathConfig config;
	@Getter
	private TeleportationItem teleportationItemSetting;

	public TransportTypeConfig(ShortestPathConfig config)
	{
		this.config = config;
		refresh();
	}

	/**
	 * Refreshes all transport type enabled states and cost thresholds from config.
	 * Uses the functional getters defined in TransportType to read config values.
	 */
	public void refresh()
	{
		// Cache the teleportation item setting
		teleportationItemSetting = ShortestPathPlugin.override("useTeleportationItems", config.useTeleportationItems());

		for (TransportType type : TransportType.values())
		{
			enabledStates.put(type, getEnabledState(type));
			int cost = getCostThreshold(type);
			costThresholds.put(type, cost);
		}
	}

	/**
	 * Determines the enabled state for a transport type.
	 * Uses the enabledGetter function from TransportType to look up the config
	 * value.
	 *
	 * <p>
	 * Special handling for teleportation item types which are controlled by
	 * the TeleportationItem enum rather than a simple boolean.
	 */
	private boolean getEnabledState(TransportType type)
	{
		// Special handling for teleportation item types
		if (type == TransportType.TELEPORTATION_ITEM || type == TransportType.TELEPORTATION_BOX)
		{
			// These are enabled unless TeleportationItem is NONE
			// The detailed filtering (consumable, inventory, etc.) is done in
			// PathfinderConfig
			return teleportationItemSetting != TeleportationItem.NONE;
		}

		// No enabled getter means always enabled (controlled elsewhere or not
		// configurable)
		if (!type.hasEnabledGetter())
		{
			return true;
		}

		boolean configValue = type.getEnabledGetter().apply(config);
		return ShortestPathPlugin.override(type, configValue);
	}

	/**
	 * Determines the cost threshold for a transport type.
	 * Uses the costGetter function from TransportType to look up the config value.
	 */
	private int getCostThreshold(TransportType type)
	{
		// No cost getter means no additional cost
		if (!type.hasCostGetter())
		{
			return 0;
		}

		int configValue = type.getCostGetter().apply(config);
		return ShortestPathPlugin.override(type, configValue);
	}

	/**
	 * Checks if a transport type is enabled in config.
	 */
	public boolean isEnabled(TransportType type)
	{
		return enabledStates.getOrDefault(type, true);
	}

	/**
	 * Gets the cost threshold for a transport type.
	 */
	public int getCost(TransportType type)
	{
		return costThresholds.getOrDefault(type, 0);
	}

	/**
	 * Overrides the teleportation-item setting (used by the alternative-routes planning copy to force a
	 * mode independent of the user's config). Keeps the teleport-item/box enabled states consistent.
	 */
	public void setTeleportationItemSetting(TeleportationItem setting)
	{
		this.teleportationItemSetting = setting;
		boolean enabled = setting != TeleportationItem.NONE;
		enabledStates.put(TransportType.TELEPORTATION_ITEM, enabled);
		enabledStates.put(TransportType.TELEPORTATION_BOX, enabled);
	}

	/**
	 * Sets the enabled state for a transport type.
	 * Used for runtime modifications (e.g., disabling fairy rings without dramen
	 * staff).
	 */
	public void setEnabled(TransportType type, boolean enabled)
	{
		enabledStates.put(type, enabled);
	}

	/**
	 * Disables a transport type unless a condition is met.
	 * If the condition is false, the type is disabled.
	 * If the condition is true, the current enabled state is preserved (not
	 * changed).
	 * Useful for quest/item requirements that can only restrict, not enable.
	 */
	/**
	 * The user's checkbox alone: the raw config value for this type, WITHOUT the quest-progress
	 * {@link #disableUnless} overlay. The catalog's "switched off in Travel options" lock reason
	 * must not fire for a type that is merely quest-locked (that classifies MISSING_QUEST).
	 */
	public boolean isEnabledInConfig(TransportType type)
	{
		return getEnabledState(type);
	}

	public void disableUnless(TransportType type, boolean condition)
	{
		if (!condition)
		{
			enabledStates.put(type, false);
		}
	}
}

package gps.transport;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import gps.transport.parser.VarRequirement;
import gps.transport.requirement.TransportItems;

/**
 * Load-scoped deduplication pools for transport requirement objects and display strings (issue
 * #491). Identical requirements and labels are extremely common across the permuted transport rows,
 * so a single canonical instance is shared. The interner is local to a {@code loadAllFromResources}
 * call and discarded afterwards, so the pools themselves are never retained.
 */
final class LoadInterner
{
	private final Map<TransportItems, TransportItems> items = new HashMap<>();
	private final Map<VarRequirement, VarRequirement> vars = new HashMap<>();
	private final Map<Set<VarRequirement>, Set<VarRequirement>> varSets = new HashMap<>();
	private final Map<Set<Quest>, Set<Quest>> questSets = new HashMap<>();
	private final Map<String, String> strings = new HashMap<>();

	TransportItems intern(TransportItems value)
	{
		return value == null ? null : items.computeIfAbsent(value, v -> v);
	}

	VarRequirement intern(VarRequirement value)
	{
		return vars.computeIfAbsent(value, v -> v);
	}

	Set<VarRequirement> internVarSet(Set<VarRequirement> value)
	{
		return varSets.computeIfAbsent(value, v -> v);
	}

	Set<Quest> internQuestSet(Set<Quest> value)
	{
		return questSets.computeIfAbsent(value, v -> v);
	}

	String internString(String value)
	{
		return value == null ? null : strings.computeIfAbsent(value, v -> v);
	}
}

package gps.transport;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

import lombok.extern.slf4j.Slf4j;
import gps.ShortestPathPlugin;
import gps.Util;
import gps.WorldPointUtil;
import gps.transport.parser.TransportRecord;
import gps.transport.parser.TsvParser;

@Slf4j
public class TransportLoader
{
	private static final TsvParser tsvParser = new TsvParser();

	private static void addTransports(
		Map<Integer, Set<Transport>> transports, String path, TransportType transportType,
		int radiusThreshold)
	{
		try
		{
			String s = new String(
				Util.readAllBytes(Objects.requireNonNull(ShortestPathPlugin.class.getResourceAsStream(path))),
				StandardCharsets.UTF_8);
			addTransportsFromContents(transports, s, transportType, radiusThreshold);
		}
		catch (IOException e)
		{
			throw new RuntimeException(e);
		}
	}

	public static void addTransportsFromContents(
		Map<Integer, Set<Transport>> transports,
		String contents,
		TransportType transportType,
		int radiusThreshold)
	{
		List<TransportRecord> records = tsvParser.parse(contents);

		Set<Transport> newTransports = new HashSet<>();
		for (TransportRecord record : records)
		{
			Transport transport = new Transport(record, transportType);
			newTransports.add(transport);
		}

		/*
		 * A transport with origin A and destination B is one-way and must
		 * be duplicated as origin B and destination A to become two-way.
		 * Example: key-locked doors
		 *
		 * A transport with origin A and a missing destination is one-way,
		 * but can go from origin A to all destinations with a missing origin.
		 * Example: fairy ring AIQ -> <blank>
		 *
		 * A transport with a missing origin and destination B is one-way,
		 * but can go from all origins with a missing destination to destination B.
		 * Example: fairy ring <blank> -> AIQ
		 *
		 * Identical transports from origin A to destination A are skipped, and
		 * non-identical transports from origin A to destination A can be skipped
		 * by specifying a radius threshold to ignore almost identical coordinates.
		 * Example: fairy ring AIQ -> AIQ
		 */
		Set<Transport> transportOrigins = new HashSet<>();
		Set<Transport> transportDestinations = new HashSet<>();
		for (Transport transport : newTransports)
		{
			int origin = transport.getOrigin();
			int destination = transport.getDestination();
			// Logic to determine ordinary transport vs teleport vs permutation (e.g. fairy
			// ring)
			if ((origin == Transport.UNDEFINED_ORIGIN && destination == Transport.UNDEFINED_DESTINATION)
				|| (origin == Transport.LOCATION_PERMUTATION && destination == Transport.LOCATION_PERMUTATION))
			{
				continue;
			}
			else if (origin != Transport.LOCATION_PERMUTATION && origin != Transport.UNDEFINED_ORIGIN
				&& destination == Transport.LOCATION_PERMUTATION)
			{
				transportOrigins.add(transport);
			}
			else if (origin == Transport.LOCATION_PERMUTATION && destination != Transport.UNDEFINED_DESTINATION)
			{
				transportDestinations.add(transport);
			}
			if (origin != Transport.LOCATION_PERMUTATION
				&& destination != Transport.UNDEFINED_DESTINATION && destination != Transport.LOCATION_PERMUTATION
				&& (origin == Transport.UNDEFINED_ORIGIN || origin != destination))
			{
				transports.computeIfAbsent(origin, k -> new HashSet<>()).add(transport);
			}
		}
		for (Transport origin : transportOrigins)
		{
			for (Transport destination : transportDestinations)
			{
				// The radius threshold prevents transport permutations from including (almost)
				// same origin and destination
				if (WorldPointUtil.distanceBetween2D(origin.getOrigin(), destination.getDestination()) > radiusThreshold)
				{
					Transport combined = new Transport(origin, destination);
					transports
						.computeIfAbsent(origin.getOrigin(), k -> new HashSet<>())
						.add(combined);
				}
			}
		}
	}

	public static HashMap<Integer, Set<Transport>> loadAllFromResources()
	{
		HashMap<Integer, Set<Transport>> transports = new HashMap<>();

		for (TransportType type : TransportType.values())
		{
			if (type.hasResourcePath())
			{
				addTransports(transports, type.getResourcePath(), type,
					type.hasRadiusThreshold() ? type.getRadiusThreshold() : 0);
			}
		}

		internRequirements(transports);

		return transports;
	}

	/**
	 * Deduplicates the requirement objects shared across the loaded transports, so identical
	 * {@code TransportItems}/{@code VarRequirement} requirements point at one shared instance
	 * instead of a per-transport copy (issue #491). The interning pools are local and discarded
	 * once loading finishes.
	 */
	private static void internRequirements(Map<Integer, Set<Transport>> transports)
	{
		LoadInterner interner = new LoadInterner();
		Set<Transport> visited = Collections.newSetFromMap(new IdentityHashMap<>());
		for (Set<Transport> set : transports.values())
		{
			for (Transport transport : set)
			{
				if (visited.add(transport))
				{
					transport.internRequirements(interner);
				}
			}
		}
	}
}

