package gps.transport;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import gps.ItemVariations;
import gps.pathfinder.PathStep;
import gps.pathfinder.PathfinderConfig;
import gps.pathfinder.TransportAvailability;
import gps.transport.requirement.ItemRequirement;

/**
 * Determines what items need to be picked up from the bank for a given path.
 * This handles transport-specific requirements like the Dramen staff for fairy rings.
 * Multiple transports that connect the same edge are treated as alternatives (OR):
 * if the player can satisfy any one of them, no pickup is needed; otherwise the
 * cheapest single alternative that can be filled from the bank is chosen.
 */
@SuppressWarnings("unused") // Only static methods are used, incorrectly flagged
public final class BankPickupRequirements
{

	/**
	 * Gets a list of items that need to be picked up from the bank at a given path step.
	 *
	 * @param client           The game client
	 * @param bank             The bank ItemContainer
	 * @param pathfinderConfig The pathfinder config for bank-aware transport lookups
	 * @param bankLocations    Set of bank location coordinates
	 * @param path             The current path
	 * @param pathIndex        The current step index in the path
	 * @return List of item names to pick up, or empty list if none needed
	 */
	public static List<String> getRequiredBankItems(
		Client client,
		Item[] bankItems,
		PathfinderConfig pathfinderConfig,
		Set<Integer> bankLocations,
		List<PathStep> path,
		int pathIndex)
	{

		List<String> requiredItems = new ArrayList<>();

		if (bankItems == null || path == null || pathIndex < 0 || pathIndex >= path.size())
		{
			return requiredItems;
		}

		// Check if this is a bank step
		int currentPoint = path.get(pathIndex).getPackedPosition();
		if (!bankLocations.contains(currentPoint))
		{
			return requiredItems;
		}

		// Snapshot bank contents.
		Map<Integer, Integer> bankHas = new HashMap<>();
		for (Item bankItem : bankItems)
		{
			if (bankItem.getId() >= 0 && bankItem.getQuantity() > 0)
			{
				bankHas.merge(bankItem.getId(), bankItem.getQuantity(), Integer::sum);
			}
		}

		// Map runeId → pouchId for any rune pouch sitting in the bank.
		// Used so computeBankPickups can show "pick up rune pouch" instead of individual runes.
		Map<Integer, Integer> bankPouchRunes = buildBankPouchRunes(client, bankHas);

		// Snapshot what the player already has on them (inventory + equipment + rune pouch in hand).
		Map<Integer, Integer> playerHas = collectPlayerItems(client);

		// Each entry is one edge's pickup phrase, e.g. "Air rune (3), Law rune or Varrock teleport".
		// A LinkedHashSet preserves order while deduplicating identical phrases across edges.
		LinkedHashSet<String> phrases = new LinkedHashSet<>();
		boolean usesFairyRing = false;

		// Walk each edge in the remaining path and collect alternative transports per edge.
		for (int i = pathIndex; i < path.size() - 1; i++)
		{
			int stepPoint = path.get(i).getPackedPosition();
			int nextPoint = path.get(i + 1).getPackedPosition();
			boolean banked = path.get(i + 1).isBankVisited();
			TransportAvailability availability = pathfinderConfig.getTransportAvailability(banked);

			List<Transport> edgeAlternatives = new ArrayList<>();
			for (Transport t : availability.getTransportsAt(stepPoint))
			{
				if (t.getDestination() == nextPoint)
				{
					edgeAlternatives.add(t);
				}
			}
			for (Transport t : availability.getUsableTeleports())
			{
				if (t.getDestination() == nextPoint)
				{
					edgeAlternatives.add(t);
				}
			}
			if (edgeAlternatives.isEmpty())
			{
				continue;
			}

			// Fairy rings handled once globally via the staff requirement below.
			List<Transport> nonFairy = new ArrayList<>();
			for (Transport t : edgeAlternatives)
			{
				if (TransportType.FAIRY_RING.equals(t.getType()))
				{
					usesFairyRing = true;
				}
				else
				{
					nonFairy.add(t);
				}
			}
			if (nonFairy.isEmpty())
			{
				continue;
			}

			// If at least one alternative requires no items, nothing to pick up for this edge.
			boolean anyAlternativeIsFree = false;
			for (Transport t : nonFairy)
			{
				if (t.getItemRequirements() == null || t.getItemRequirements().size() == 0)
				{
					anyAlternativeIsFree = true;
					break;
				}
			}
			if (anyAlternativeIsFree)
			{
				continue;
			}

			// If any alternative is fully satisfied by the player already, no pickup needed.
			boolean satisfied = false;
			for (Transport t : nonFairy)
			{
				if (transportSatisfiedBy(t, playerHas))
				{
					satisfied = true;
					break;
				}
			}
			if (satisfied)
			{
				continue;
			}

			// Otherwise, surface every alternative the bank can fully supply, joined, bankPouchRunes by " or ".
			// Deduplicate alternatives that resolve to the exact same set of bank items.
			LinkedHashSet<String> altStrings = new LinkedHashSet<>();
			for (Transport t : nonFairy)
			{
				Map<Integer, Long> pickups = computeBankPickups(t, playerHas, bankHas, bankPouchRunes);
				if (pickups == null || pickups.isEmpty())
				{
					continue; // bank can't satisfy this alternative
				}
				altStrings.add(formatPickups(client, pickups));
			}
			if (altStrings.isEmpty())
			{
				continue;
			}
			phrases.add(String.join(" or ", altStrings));
		}

		// Fairy ring staff (Dramen / Lunar) is a single OR requirement across the whole trip.
		// Not needed if the Lumbridge Elite diary is complete.
		if (usesFairyRing && client.getVarbitValue(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) != 1)
		{
			int[] staffIds = ItemVariations.DRAMEN_STAFF.getIds();
			if (!hasAnyItem(playerHas, staffIds, 1))
			{
				int foundId = findItemIdInBank(bankHas, staffIds, 1);
				if (foundId != -1)
				{
					Map<Integer, Long> single = new LinkedHashMap<>();
					single.put(foundId, 1L);
					phrases.add(formatPickups(client, single));
				}
			}
		}

		requiredItems.addAll(phrases);
		return requiredItems;
	}

	/**
	 * Formats a pickup map (item id → quantity) as a comma-separated, human-readable string.
	 */
	private static String formatPickups(Client client, Map<Integer, Long> pickups)
	{
		List<String> parts = new ArrayList<>(pickups.size());
		for (Map.Entry<Integer, Long> entry : pickups.entrySet())
		{
			int itemId = entry.getKey();
			long qty = entry.getValue();
			String itemName = client.getItemDefinition(itemId).getName();
			if (itemName == null || itemName.isEmpty() || "null".equals(itemName))
			{
				itemName = "Unknown item";
			}
			boolean isCurrency = PathfinderConfig.CURRENCIES.contains(itemId);
			if (isCurrency)
			{
				if (qty > 1)
				{
					itemName += " (" + String.format("%,d", qty) + ")";
				}
			}
			else
			{
				itemName = qty + " " + itemName;
			}
			parts.add(itemName);
		}
		return String.join(", ", parts);
	}

	/**
	 * Returns true if the player has at least {@code requiredQty} of any id in {@code itemIds}
	 * across inventory/equipment/rune-pouch.
	 */
	private static boolean hasAnyItem(Map<Integer, Integer> playerHas, int[] itemIds, int requiredQty)
	{
		if (itemIds == null)
		{
			return false;
		}
		for (int id : itemIds)
		{
			if (playerHas.getOrDefault(id, 0) >= requiredQty)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Returns the item ID from {@code itemIds} present in the bank with at least
	 * {@code requiredQty}, or -1 if none qualifies.
	 */
	private static int findItemIdInBank(Map<Integer, Integer> bankHas, int[] itemIds, int requiredQty)
	{
		if (itemIds == null)
		{
			return -1;
		}
		for (int id : itemIds)
		{
			if (bankHas.getOrDefault(id, 0) >= requiredQty)
			{
				return id;
			}
		}
		return -1;
	}

	/**
	 * Returns true if every requirement of the transport is already met by the player's
	 * inventory/equipment/rune-pouch (taking item-id, staff and offhand variations into account).
	 */
	public static boolean transportSatisfiedBy(Transport transport, Map<Integer, Integer> playerHas)
	{
		if (transport.getItemRequirements() == null)
		{
			return true;
		}
		for (ItemRequirement req : transport.getItemRequirements().getRequirements())
		{
			int qty = req.getQuantity() > 0 ? req.getQuantity() : 1;
			if (hasAnyItem(playerHas, req.getItemIds(), qty)
				|| hasAnyItem(playerHas, req.getStaffIds(), 1)
				|| hasAnyItem(playerHas, req.getOffhandIds(), 1))
			{
				continue;
			}
			return false;
		}
		return true;
	}

	/**
	 * For an unsatisfied transport, returns the items (id → qty) that need to be picked up
	 * from the bank to satisfy it, or null if the bank can't supply them.
	 * When a required rune is only available via a bank rune pouch, the pouch itself is
	 * returned as the pickup item (qty 1, deduped across multiple rune requirements).
	 */
	private static Map<Integer, Long> computeBankPickups(Transport transport,
		Map<Integer, Integer> playerHas,
		Map<Integer, Integer> bankHas,
		Map<Integer, Integer> bankPouchRunes)
	{
		Map<Integer, Long> pickups = new LinkedHashMap<>();
		Set<Integer> addedPouches = new HashSet<>(); // tracks pouch IDs already added to pickups
		if (transport.getItemRequirements() == null)
		{
			return pickups;
		}
		for (ItemRequirement req : transport.getItemRequirements().getRequirements())
		{
			int qty = req.getQuantity() > 0 ? req.getQuantity() : 1;
			// Already satisfied by player?
			if (hasAnyItem(playerHas, req.getItemIds(), qty)
				|| hasAnyItem(playerHas, req.getStaffIds(), 1)
				|| hasAnyItem(playerHas, req.getOffhandIds(), 1))
			{
				continue;
			}
			// Prefer bank rune pouch over individual runes. This avoids surfacing combination
			// rune variants (mist, dust, etc.) when the pouch already covers the requirement.
			boolean satisfied = false;
			if (req.getItemIds() != null)
			{
				for (int itemId : req.getItemIds())
				{
					Integer pouchId = bankPouchRunes.get(itemId);
					if (pouchId != null)
					{
						if (!addedPouches.contains(pouchId))
						{
							addedPouches.add(pouchId);
							pickups.put(pouchId, 1L);
						}
						satisfied = true;
						break;
					}
				}
			}
			if (satisfied)
			{
				continue;
			}
			// Try to satisfy from bank directly. Use the canonical (first) item ID for display
			// so we show "Air rune" rather than a combination rune variant like "Mist rune".
			int foundId = findItemIdInBank(bankHas, req.getItemIds(), qty);
			if (foundId != -1)
			{
				pickups.merge(req.getItemIds()[0], (long) qty, Long::sum);
				continue;
			}
			foundId = findItemIdInBank(bankHas, req.getStaffIds(), 1);
			if (foundId == -1)
			{
				foundId = findItemIdInBank(bankHas, req.getOffhandIds(), 1);
			}
			if (foundId == -1)
			{
				return null; // bank can't satisfy this requirement
			}
			pickups.merge(foundId, 1L, Long::sum);
		}
		return pickups;
	}

	/**
	 * Builds a map of runeId → pouchId for every rune stored inside any rune pouch in the bank.
	 * The varbits that encode pouch contents are always current regardless of pouch location.
	 */
	private static Map<Integer, Integer> buildBankPouchRunes(Client client, Map<Integer, Integer> bankHas)
	{
		Map<Integer, Integer> bankPouchRunes = new HashMap<>();
		for (Integer pouchId : PathfinderConfig.RUNE_POUCHES)
		{
			if (!bankHas.containsKey(pouchId))
			{
				continue;
			}
			EnumComposition runePouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
			if (runePouchEnum == null)
			{
				break;
			}
			for (int i = 0; i < PathfinderConfig.RUNE_POUCH_RUNE_VARBITS.length; i++)
			{
				int runeEnumId = client.getVarbitValue(PathfinderConfig.RUNE_POUCH_RUNE_VARBITS[i]);
				int runeId = runeEnumId > 0 ? runePouchEnum.getIntValue(runeEnumId) : 0;
				int runeAmount = client.getVarbitValue(PathfinderConfig.RUNE_POUCH_AMOUNT_VARBITS[i]);
				if (runeId > 0 && runeAmount > 0)
				{
					bankPouchRunes.put(runeId, pouchId);
				}
			}
			break; // one pouch per bank
		}
		return bankPouchRunes;
	}

	/**
	 * Snapshots what the player already has on them (inventory + equipment + rune pouch
	 * contents if the pouch is in inventory or equipped).
	 */
	public static Map<Integer, Integer> collectPlayerItems(Client client)
	{
		Map<Integer, Integer> totals = new HashMap<>();

		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory != null)
		{
			for (Item item : inventory.getItems())
			{
				if (item.getId() >= 0 && item.getQuantity() > 0)
				{
					totals.merge(item.getId(), item.getQuantity(), Integer::sum);
				}
			}
		}

		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment != null)
		{
			for (Item item : equipment.getItems())
			{
				if (item.getId() >= 0 && item.getQuantity() > 0)
				{
					totals.merge(item.getId(), item.getQuantity(), Integer::sum);
				}
			}
		}

		// Rune pouch contents — only when the pouch is actually on the player.
		boolean hasPouch = false;
		for (Integer pouchId : PathfinderConfig.RUNE_POUCHES)
		{
			if (totals.containsKey(pouchId))
			{
				hasPouch = true;
				break;
			}
		}
		if (hasPouch)
		{
			EnumComposition runePouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
			if (runePouchEnum != null)
			{
				for (int i = 0; i < PathfinderConfig.RUNE_POUCH_RUNE_VARBITS.length; i++)
				{
					int runeEnumId = client.getVarbitValue(PathfinderConfig.RUNE_POUCH_RUNE_VARBITS[i]);
					int runeId = runeEnumId > 0 ? runePouchEnum.getIntValue(runeEnumId) : 0;
					int runeAmount = client.getVarbitValue(PathfinderConfig.RUNE_POUCH_AMOUNT_VARBITS[i]);
					if (runeId > 0 && runeAmount > 0)
					{
						totals.merge(runeId, runeAmount, Integer::sum);
					}
				}
			}
		}

		return totals;
	}
}

package gps;

import com.google.inject.Inject;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.geom.Rectangle2D;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import gps.pathfinder.PathStep;
import gps.transport.BankPickupRequirements;
import gps.transport.Transport;

public class PathTileOverlay extends Overlay
{
	private static final int TRANSPORT_LABEL_GAP = 3;
	// The flowing highlight on the drawn line: a train of small ripples travelling towards the
	// destination — one every WAVE_SPACING steps, each fading over WAVE_HALF_WIDTH steps to either
	// side, moving at WAVE_TILES_PER_SECOND.
	private static final double WAVE_TILES_PER_SECOND = 20;
	private static final double WAVE_SPACING = 60;
	private static final double WAVE_HALF_WIDTH = 4;
	// Half-size of the window the debug off-route bands are computed over, in tiles. Bounds the cost and
	// keeps the render on-screen even when the configured recalculate distance is very large.
	private static final int BAND_WINDOW = 32;
	private final Client client;
	private final ShortestPathPlugin plugin;
	private int playerTileLabelOffset = 0;
	// Door tiles already hinted this frame — a door can sit on two path edges (a diagonal
	// approach then the straight crossing), which would otherwise stack "Open Door" twice.
	private final Set<Integer> hintedDoorTiles = new HashSet<>();

	@Inject
	public PathTileOverlay(Client client, ShortestPathPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		playerTileLabelOffset = 0;
		hintedDoorTiles.clear();

		if (plugin.drawRecalculationRanges)
		{
			drawArrivalTiles(graphics);
			drawRecalculationRanges(graphics);
		}

		if (plugin.drawTiles && !plugin.getDisplayPath().isEmpty())
		{
			Color pathColor = plugin.getPathColor();
			Color color = new Color(
				pathColor.getRed(),
				pathColor.getGreen(),
				pathColor.getBlue(),
				pathColor.getAlpha() / 2);
			Color blockedColor = new Color(
				plugin.colourPathBlocked.getRed(),
				plugin.colourPathBlocked.getGreen(),
				plugin.colourPathBlocked.getBlue(),
				plugin.colourPathBlocked.getAlpha() / 2);
			// The stretch the player has already covered is greyed out — the live part is what's ahead.
			Color doneColor = new Color(0x80, 0x80, 0x80, pathColor.getAlpha() / 2);

			List<PathStep> path = plugin.getDisplayPath();
			// The path beyond the first door not yet seen open renders in the blocked colour: the
			// route assumes doors are passable, this marks the part the player can't walk yet.
			int blockedFrom = plugin.blockedFromIndex(path);
			// Progress along the displayed route: edges up to here are done (greyed).
			int progress = plugin.displayedRouteProgress();
			// Repeating ripples flow along the line towards the destination: each edge's glow is
			// its proximity to the nearest ripple centre in a train spaced WAVE_SPACING apart.
			double waveOffset = ((System.currentTimeMillis() % 600_000L) / 1000.0 * WAVE_TILES_PER_SECOND)
				% WAVE_SPACING;
			java.util.Set<Integer> sailingEdges = plugin.getDisplaySailingEdges();
			for (int i = 1; i < path.size(); i++)
			{
				PathStep currentStep = path.get(i - 1);
				PathStep nextStep = path.get(i);
				// A non-adjacent pair is a teleport/transport jump, not a walkable edge.
				boolean jump = WorldPointUtil.distanceBetween(
					currentStep.getPackedPosition(), nextStep.getPackedPosition()) > 1;
				// Sailing legs draw their sea track through the scene: the jump's endpoints
				// are ports/pins far outside the loaded scene mid-voyage, so the dashed beam
				// below rendered NOTHING while actually sailing. Track segments near the boat
				// project fine; drawLine skips the rest.
				if (jump && sailingEdges.contains(i - 1))
				{
					int[] track = SailingSea.seaPath(
						currentStep.getPackedPosition(), nextStep.getPackedPosition());
					if (track != null && track.length > 1)
					{
						boolean done = i <= progress;
						// The sailed stretch greys waypoint by waypoint behind the boat: the
						// aboard position scored against the track, same rule the tracker uses.
						int sailedUpTo = -1;
						if (!done && client.getVarbitValue(
							net.runelite.api.gameval.VarbitID.SAILING_BOARDED_BOAT) != 0)
						{
							int playerPacked = WorldPointUtil.fromLocalInstance(
								client, client.getLocalPlayer());
							if (playerPacked != WorldPointUtil.UNDEFINED)
							{
								int nearestDistance = Integer.MAX_VALUE;
								for (int w = 0; w < track.length; w++)
								{
									int d = WorldPointUtil.distanceBetween(playerPacked, track[w]);
									if (d < nearestDistance)
									{
										nearestDistance = d;
										sailedUpTo = w;
									}
								}
								if (nearestDistance > 30)
								{
									sailedUpTo = -1; // aboard on a DIFFERENT leg: grey nothing here
								}
							}
						}
						Color sail = plugin.getSailingPathColor();
						Color sailColor = new Color(sail.getRed(), sail.getGreen(), sail.getBlue(),
							sail.getAlpha() / 2);
						for (int s = 1; s < track.length; s++)
						{
							Color segment = done || s <= sailedUpTo ? doneColor
								: (i >= blockedFrom ? blockedColor : sailColor);
							drawLine(graphics, track[s - 1], track[s], segment,
								s == track.length - 1, 0, false);
						}
						drawTransportInfo(graphics, currentStep, nextStep, path, i - 1);
						continue;
					}
				}
				// Arrowheads only where they carry information: at direction changes and the end.
				boolean head = i == path.size() - 1
					|| directionChanges(currentStep.getPackedPosition(), nextStep.getPackedPosition(),
						path.get(i + 1).getPackedPosition());
				double phase = (i - waveOffset) % WAVE_SPACING;
				if (phase < 0)
				{
					phase += WAVE_SPACING;
				}
				double waveDistance = Math.min(phase, WAVE_SPACING - phase);
				// Edge i covers path[i-1]->path[i]; it's done once progress has reached path[i].
				boolean done = i <= progress;
				double glow = jump || done ? 0 : Math.max(0, 1 - waveDistance / WAVE_HALF_WIDTH);
				Color edgeColor = done ? doneColor : (i >= blockedFrom ? blockedColor : color);
				drawLine(graphics, currentStep.getPackedPosition(), nextStep.getPackedPosition(),
					edgeColor, head, glow, jump);
				drawTransportInfo(graphics, currentStep, nextStep, path, i - 1);
			}

			// GPS decorations for the displayed route: a small waypoint dot where each section ends
			// (walk up to here, then do the next step) and a growing green pulse on the destination.
			RouteOption displayedRoute = plugin.getDisplayedRoute();
			if (displayedRoute != null && plugin.showDirections)
			{
				drawGpsMarkers(graphics, displayedRoute);
			}

			if (plugin.isPathUnreachable())
			{
				playerTileLabelOffset += drawLabelOnPlayerTile(graphics, plugin.unreachableText, playerTileLabelOffset);
			}
		}

		return null;
	}

	/**
	 * The hint for a door/gate transport on the path, shown only while it needs opening: when the
	 * closed door object (whose id is the trailing token of the objectInfo, e.g. "Open Door 9398")
	 * is still standing at either end of the edge. Opening the door replaces the object, so the hint
	 * disappears by itself. Null for non-door transports and doors that are already open.
	 */
	private String closedDoorText(Transport transport)
	{
		String objectInfo = transport.getObjectInfo();
		if (objectInfo == null || !objectInfo.startsWith("Open "))
		{
			return null;
		}
		int lastSpace = objectInfo.lastIndexOf(' ');
		if (lastSpace <= 0)
		{
			return null;
		}
		String idText = objectInfo.substring(lastSpace + 1);
		if (idText.isEmpty() || !idText.chars().allMatch(Character::isDigit))
		{
			return null;
		}
		int objectId = Integer.parseInt(idText);
		if (objectPresent(transport.getOrigin(), objectId) || objectPresent(transport.getDestination(), objectId))
		{
			return objectInfo.substring(0, lastSpace);
		}
		return null;
	}

	private boolean objectPresent(int packedLocation, int objectId)
	{
		return SceneObjects.objectPresent(client, packedLocation, objectId);
	}

	private void drawGpsMarkers(Graphics2D graphics, RouteOption route)
	{
		List<RouteDirections.Step> steps = plugin.getRouteDirections(route);
		List<PathStep> path = route.getPath();
		if (steps.isEmpty() || path.isEmpty())
		{
			return;
		}
		int destinationIndex = path.size() - 1;
		Set<Integer> marked = new HashSet<>();
		for (RouteDirections.Step step : steps)
		{
			int end = step.getEndIndex();
			if (end <= 0 || end >= destinationIndex)
			{
				continue; // the destination gets the pulse, not a dot
			}
			int packed = path.get(end).getPackedPosition();
			if (marked.add(packed))
			{
				drawSectionMarker(graphics, packed);
			}
		}
		// A round trip's halfway point (the bank) pulses GOLD while the outbound leg is being
		// walked — reach it and the beacon vanishes, leaving the green home pulse for the way back.
		RouteOption displayed = plugin.getDisplayedRoute();
		if (displayed != null && displayed.isRoundTrip())
		{
			int turnaround = displayed.getTurnaroundIndex();
			if (turnaround > 0 && turnaround < path.size()
				&& plugin.displayedRouteProgress() < turnaround - 2)
			{
				drawDestinationPulse(graphics, path.get(turnaround).getPackedPosition(), PULSE_TURNAROUND);
			}
		}
		drawDestinationPulse(graphics, path.get(destinationIndex).getPackedPosition());
	}

	/**
	 * A small waypoint dot on the tile where a route section ends: white ring with a path-coloured
	 * core, so the "walk up to here" points stand out along the drawn line.
	 */
	private void drawSectionMarker(Graphics2D graphics, int location)
	{
		PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, location);
		for (int i = 0; i < points.size(); i++)
		{
			LocalPoint lp = WorldPointUtil.toLocalPoint(client, points.get(i));
			if (lp == null)
			{
				continue;
			}
			Polygon poly = Perspective.getCanvasTilePoly(client, lp);
			if (poly == null)
			{
				continue;
			}
			final double cx = poly.getBounds().getCenterX();
			final double cy = poly.getBounds().getCenterY();
			graphics.setColor(Color.WHITE);
			graphics.fill(new Ellipse2D.Double(cx - 4.5, cy - 4.5, 9, 9));
			Color pathColour = plugin.getPathColor();
			graphics.setColor(new Color(pathColour.getRed(), pathColour.getGreen(), pathColour.getBlue()));
			graphics.fill(new Ellipse2D.Double(cx - 3, cy - 3, 6, 6));
		}
	}

	/**
	 * The journey's end: a green circle growing out of the destination tile and fading, looping —
	 * the same rhythm as the teleport pulse. The flattening follows the camera: a circle drawn on
	 * the ground plane projects to an ellipse with the same height/width ratio as the projected
	 * tile itself (the yaw factor cancels out of a square tile's bounding box, leaving only the
	 * pitch compression) — so it's a perfect circle seen top-down and flattens as the camera drops.
	 */
	/**
	 * Debug view of the off-route bands, drawn as contours hugging the PATH (not the player): tiles
	 * exactly the warning distance from the nearest path tile are tinted yellow and those exactly the
	 * recalculate distance red — the same Chebyshev metric the recalc check uses, so the two thresholds
	 * trace the corridor the player must stay inside. Computed over a bounded window around the player
	 * (the on-screen stretch) so a large configured distance can't blow up the render. A label reports
	 * the live distance from the path.
	 */
	private void drawRecalculationRanges(Graphics2D graphics)
	{
		final Player player = client.getLocalPlayer();
		final int recalc = plugin.getRecalculateDistance();
		final List<PathStep> path = plugin.getDisplayPath();
		if (player == null || recalc < 0 || path == null || path.isEmpty())
		{
			return;
		}
		final int warn = plugin.getOffRouteWarnDistance();
		final int centre = WorldPointUtil.fromLocalInstance(client, player);
		final int cx = WorldPointUtil.unpackWorldX(centre);
		final int cy = WorldPointUtil.unpackWorldY(centre);
		final int plane = WorldPointUtil.unpackWorldPlane(centre);
		final int window = Math.min(recalc + 1, BAND_WINDOW);

		// Path tiles near enough to be some window tile's nearest (within window of a tile within window).
		final int[] near = new int[path.size()];
		int nearCount = 0;
		for (PathStep step : path)
		{
			final int p = step.getPackedPosition();
			if (WorldPointUtil.unpackWorldPlane(p) == plane
				&& WorldPointUtil.distanceBetween(centre, p) <= 2 * window)
			{
				near[nearCount++] = p;
			}
		}
		if (nearCount > 0)
		{
			final Color warnFill = new Color(0xFF, 0xE0, 0x00, 70);
			final Color warnLine = new Color(0xFF, 0xE0, 0x00, 200);
			final Color recalcFill = new Color(0xFF, 0x3C, 0x3C, 70);
			final Color recalcLine = new Color(0xFF, 0x3C, 0x3C, 200);
			for (int dx = -window; dx <= window; dx++)
			{
				for (int dy = -window; dy <= window; dy++)
				{
					final int tile = WorldPointUtil.packWorldPoint(cx + dx, cy + dy, plane);
					int dmin = Integer.MAX_VALUE;
					for (int k = 0; k < nearCount; k++)
					{
						final int dist = WorldPointUtil.distanceBetween(tile, near[k]);
						if (dist < dmin)
						{
							dmin = dist;
						}
						if (dmin < warn)
						{
							break; // interior to the warning band — not a boundary tile
						}
					}
					// Only the two contour lines; the recalc boundary wins a tie with the warn boundary.
					if (dmin == recalc)
					{
						highlightWorldTile(graphics, tile, recalcFill, recalcLine);
					}
					else if (dmin == warn)
					{
						highlightWorldTile(graphics, tile, warnFill, warnLine);
					}
				}
			}
		}

		final int d = plugin.getPathDistance();
		final Point anchor = Perspective.localToCanvas(client, player.getLocalLocation(), plane);
		if (anchor != null)
		{
			final String label = "off-route: " + (d < 0 ? "?" : d)
				+ " (warn " + warn + " / recalc " + recalc + ")";
			graphics.setColor(plugin.isOffRouteWarning() ? new Color(0xFF, 0x4C, 0x4C) : Color.WHITE);
			graphics.drawString(label, anchor.getX() + 6, anchor.getY());
		}
	}

	private void highlightWorldTile(Graphics2D graphics, int location, Color fill, Color outline)
	{
		final PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, location);
		for (int i = 0; i < points.size(); i++)
		{
			final LocalPoint lp = WorldPointUtil.toLocalPoint(client, points.get(i));
			if (lp == null)
			{
				continue;
			}
			final Polygon poly = Perspective.getCanvasTilePoly(client, lp);
			if (poly == null)
			{
				continue;
			}
			graphics.setColor(fill);
			graphics.fill(poly);
			graphics.setColor(outline);
			graphics.draw(poly);
		}
	}

	/**
	 * Tint the ACTUAL arrival tiles green: the plugin's arrival zone, i.e. every walkable tile within
	 * the finish distance of the destination (flooded over the collision map). This is the exact set
	 * the arrival check tests membership of — standing on any tinted tile completes the journey.
	 */
	private void drawArrivalTiles(Graphics2D graphics)
	{
		final Color fill = new Color(0x3C, 0xC8, 0x6A, 60);
		final Color outline = new Color(0x3C, 0xC8, 0x6A, 170);
		for (int tile : plugin.getArrivalTiles())
		{
			highlightWorldTile(graphics, tile, fill, outline);
		}
	}

	// The two pulse colours: green marks the journey's end; gold marks a round trip's turnaround
	// (the bank) while the outbound leg is being walked — an "arrive here first" beacon that
	// disappears once the player reaches it and the trip continues home.
	private static final Color PULSE_DESTINATION = new Color(0, 220, 90);
	private static final Color PULSE_TURNAROUND = new Color(255, 196, 64);

	private void drawDestinationPulse(Graphics2D graphics, int location)
	{
		drawDestinationPulse(graphics, location, PULSE_DESTINATION);
	}

	private void drawDestinationPulse(Graphics2D graphics, int location, Color colour)
	{
		PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, location);
		for (int i = 0; i < points.size(); i++)
		{
			LocalPoint lp = WorldPointUtil.toLocalPoint(client, points.get(i));
			if (lp == null)
			{
				continue;
			}
			Polygon poly = Perspective.getCanvasTilePoly(client, lp);
			if (poly == null)
			{
				continue;
			}
			final double cx = poly.getBounds().getCenterX();
			final double cy = poly.getBounds().getCenterY();
			final double tileWidth = Math.max(8, poly.getBounds().getWidth());
			// Ground-plane flattening from the tile's own projection; clamped for degenerate polys.
			final double flatten = Math.min(1.0, Math.max(0.1,
				poly.getBounds().getHeight() / Math.max(1.0, poly.getBounds().getWidth())));

			final long period = 1400L;
			final int rings = 2;
			final Stroke previousStroke = graphics.getStroke();
			graphics.setStroke(new BasicStroke(2.2f));
			for (int r = 0; r < rings; r++)
			{
				double phase = ((System.currentTimeMillis() + (long) (r * period / (double) rings)) % period)
					/ (double) period;
				double radius = tileWidth * (0.25 + phase * 1.1);
				int alpha = (int) Math.round(180 * (1.0 - phase));
				if (alpha <= 0)
				{
					continue;
				}
				graphics.setColor(new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), alpha));
				graphics.draw(new Ellipse2D.Double(
					cx - radius, cy - radius * flatten, radius * 2, radius * 2 * flatten));
			}
			graphics.setStroke(previousStroke);
		}
	}

	private static boolean directionChanges(int previous, int current, int next)
	{
		int dx1 = WorldPointUtil.unpackWorldX(current) - WorldPointUtil.unpackWorldX(previous);
		int dy1 = WorldPointUtil.unpackWorldY(current) - WorldPointUtil.unpackWorldY(previous);
		int dx2 = WorldPointUtil.unpackWorldX(next) - WorldPointUtil.unpackWorldX(current);
		int dy2 = WorldPointUtil.unpackWorldY(next) - WorldPointUtil.unpackWorldY(current);
		return dx1 != dx2 || dy1 != dy2;
	}

	private void drawLine(Graphics2D graphics, int startLoc, int endLoc, Color color, boolean arrowHead,
		double glow, boolean jump)
	{
		PrimitiveIntList starts = WorldPointUtil.toLocalInstance(client, startLoc);
		PrimitiveIntList ends = WorldPointUtil.toLocalInstance(client, endLoc);

		if (starts.isEmpty() || ends.isEmpty())
		{
			return;
		}

		int start = starts.get(0);
		int end = ends.get(0);

		final int z = client.getTopLevelWorldView().getPlane();
		if (WorldPointUtil.unpackWorldPlane(start) != z)
		{
			return;
		}

		LocalPoint lpStart = WorldPointUtil.toLocalPoint(client, start);
		LocalPoint lpEnd = WorldPointUtil.toLocalPoint(client, end);

		if (lpStart == null || lpEnd == null)
		{
			return;
		}

		final int startHeight = Perspective.getTileHeight(client, lpStart, z);
		final int endHeight = Perspective.getTileHeight(client, lpEnd, z);

		Point p1 = Perspective.localToCanvas(client, lpStart.getX(), lpStart.getY(), startHeight);
		Point p2 = Perspective.localToCanvas(client, lpEnd.getX(), lpEnd.getY(), endHeight);

		if (p1 == null || p2 == null)
		{
			return;
		}

		Line2D.Double line = new Line2D.Double(p1.getX(), p1.getY(), p2.getX(), p2.getY());

		graphics.setColor(color);
		if (jump)
		{
			// Teleport/transport jumps: a thin dashed hint, like the world map draws them —
			// a full solid beam across the scene reads as a walkable line, which it isn't.
			graphics.setStroke(new BasicStroke(2, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND,
				10f, new float[]{8, 8}, 0));
		}
		else
		{
			graphics.setStroke(new BasicStroke(5, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		}
		graphics.draw(line);
		if (arrowHead)
		{
			ArrowHead.draw(graphics, p1.getX(), p1.getY(), p2.getX(), p2.getY(), 12);
		}
		if (glow > 0)
		{
			// The flowing ripple: a subtly brighter core stroke — only a mild step towards white,
			// at the path colour's own opacity, so it reads as a sheen rather than a flash.
			graphics.setColor(new Color(
				color.getRed() + (int) ((255 - color.getRed()) * glow * 0.18),
				color.getGreen() + (int) ((255 - color.getGreen()) * glow * 0.18),
				color.getBlue() + (int) ((255 - color.getBlue()) * glow * 0.18),
				color.getAlpha()));
			graphics.setStroke(new BasicStroke(3, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			graphics.draw(line);
		}
	}

	private int drawLabelAtCanvasPoint(Graphics2D graphics, Point point, String text, int verticalOffset)
	{
		if (point == null || text == null || text.isEmpty())
		{
			return 0;
		}

		double height = drawLabel(graphics, point, text, verticalOffset);

		return (int) height + TRANSPORT_LABEL_GAP;
	}

	private int drawLabelAtPackedLocation(Graphics2D graphics, int location, String text, int verticalOffset)
	{
		PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, location);
		for (int i = 0; i < points.size(); i++)
		{
			LocalPoint lp = WorldPointUtil.toLocalPoint(client, points.get(i));
			if (lp == null)
			{
				continue;
			}

			Point p = Perspective.localToCanvas(client, lp, client.getTopLevelWorldView().getPlane());
			if (p == null)
			{
				continue;
			}

			verticalOffset += drawLabelAtCanvasPoint(graphics, p, text, verticalOffset);
		}
		return verticalOffset;
	}

	/**
	 * A pulsing "teleport from here" highlight: diamond rings expanding out from the tile and fading,
	 * looping. Drawn every frame (scene overlays repaint continuously) off wall-clock time, so the motion
	 * stays smooth regardless of game ticks. Anchored to the tile the player casts from — for a
	 * cast-from-anywhere teleport that sits under the player, drawing the eye to "teleport now".
	 */
	private void drawTeleportPulse(Graphics2D graphics, int location)
	{
		PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, location);
		for (int i = 0; i < points.size(); i++)
		{
			LocalPoint lp = WorldPointUtil.toLocalPoint(client, points.get(i));
			if (lp == null)
			{
				continue;
			}
			Polygon poly = Perspective.getCanvasTilePoly(client, lp);
			if (poly == null || poly.npoints == 0)
			{
				continue;
			}
			final double cx = poly.getBounds().getCenterX();
			final double cy = poly.getBounds().getCenterY();

			final long period = 1400L;
			final int rings = 2;
			final Color base = plugin.colourTeleportPulse;
			final Stroke previousStroke = graphics.getStroke();
			graphics.setStroke(new BasicStroke(2.2f));
			for (int r = 0; r < rings; r++)
			{
				// Stagger the two rings by half a period so one is always small/bright while the other
				// is large/faint — a continuous outward pulse.
				double phase = ((System.currentTimeMillis() + (long) (r * period / (double) rings)) % period)
					/ (double) period;
				double scale = 1.0 + phase * 2.6;
				int alpha = (int) Math.round(170 * (1.0 - phase));
				if (alpha <= 0)
				{
					continue;
				}
				Path2D ring = new Path2D.Double();
				for (int v = 0; v < poly.npoints; v++)
				{
					double x = cx + (poly.xpoints[v] - cx) * scale;
					double y = cy + (poly.ypoints[v] - cy) * scale;
					if (v == 0)
					{
						ring.moveTo(x, y);
					}
					else
					{
						ring.lineTo(x, y);
					}
				}
				ring.closePath();
				graphics.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), alpha));
				graphics.draw(ring);
			}
			graphics.setStroke(previousStroke);
		}
	}

	private double drawLabel(Graphics2D graphics, Point point, String text, int verticalOffset)
	{
		Rectangle2D textBounds = graphics.getFontMetrics().getStringBounds(text, graphics);
		double height = textBounds.getHeight();
		int x = (int) (point.getX() - textBounds.getWidth() / 2);
		int y = (int) (point.getY() - height) - verticalOffset;
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(plugin.colourText);
		graphics.drawString(text, x, y);
		return height;
	}

	private int drawLabelOnPlayerTile(Graphics2D graphics, String text, int verticalOffset)
	{
		if (client.getLocalPlayer() == null)
		{
			return 0;
		}

		Point playerPoint = Perspective.localToCanvas(client, client.getLocalPlayer().getLocalLocation(), client.getTopLevelWorldView().getPlane());
		return drawLabelAtCanvasPoint(graphics, playerPoint, text, verticalOffset);
	}

	private void drawTransportInfo(Graphics2D graphics, PathStep currentStep, PathStep nextStep, List<PathStep> path, int pathIndex)
	{
		int location = currentStep.getPackedPosition();
		if (nextStep == null || !plugin.showTransportInfo ||
			WorldPointUtil.unpackWorldPlane(location) != client.getTopLevelWorldView().getPlane())
		{
			return;
		}

		// Sailing: teleports are suppressed while aboard a boat. When the path is
		// unreachable as a result, show a one-time hint on the player tile.
		if (pathIndex == 0 && plugin.getPathfinderConfig().isOnSailingBoat()
			&& plugin.isPathUnreachable())
		{
			playerTileLabelOffset = drawLabelOnPlayerTile(graphics,
				"Disembark the boat to resume pathfinding", playerTileLabelOffset);
			return;
		}

		if (plugin.isPathUnreachable())
		{
			return;
		}
		int locationEnd = nextStep.getPackedPosition();

		// Workaround for weird pathing inside PoH to instead show info on the player
		// tile
		LocalPoint playerLocalPoint = client.getLocalPlayer().getLocalLocation();
		int playerPackedPoint = WorldPointUtil.fromLocalInstance(client, playerLocalPoint);
		int px = WorldPointUtil.unpackWorldX(playerPackedPoint);
		int py = WorldPointUtil.unpackWorldY(playerPackedPoint);
		int tx = WorldPointUtil.unpackWorldX(location);
		int ty = WorldPointUtil.unpackWorldY(location);
		boolean transportAndPlayerInsidePoh = ShortestPathPlugin.isInsidePoh(tx, ty)
			&& ShortestPathPlugin.isInsidePoh(px, py);
		Set<Transport> candidateTransports = plugin.transportsForEdge(currentStep, nextStep);

		// When inside POH, only show the POH exit info once (not per-transport)
		if (transportAndPlayerInsidePoh)
		{
			String pohExitInfo = plugin.getPohExitInfo(locationEnd, path, pathIndex);
			if (pohExitInfo == null)
			{
				return;
			}

			// Find the display name of the teleport that brought us to POH using bank-aware
			// lookup
			String text = null;
			for (Transport transport : candidateTransports)
			{
				text = transport.getDisplayInfo();
				if (text != null && !text.isEmpty())
				{
					break;
				}
			}
			if (text == null || text.isEmpty())
			{
				return;
			}
			text = text + " (Exit: " + pohExitInfo + ")";

			Point p = Perspective.localToCanvas(client, playerLocalPoint, client.getTopLevelWorldView().getPlane());
			if (p == null)
			{
				return;
			}

			drawLabel(graphics, p, text, 0);
			return;
		}

		// A doorway on a plain walk edge: the collision map bakes openable doors passable, so
		// the path assumes they are open. Hint while the door is actually closed (the closed
		// object still stands in the scene) — opening it replaces the object, so the hint
		// clears by itself. Edges with a mapped door transport are handled below instead.
		if (candidateTransports.isEmpty())
		{
			ClosedDoors.Door door = ClosedDoors.doorBetween(location, locationEnd);
			if (door != null && ClosedDoors.state(client, door) == ClosedDoors.State.CLOSED
				&& hintedDoorTiles.add(door.packedPosition))
			{
				playerTileLabelOffset = drawLabelAtPackedLocation(
					graphics, door.packedPosition, "Open " + door.name, playerTileLabelOffset);
			}
		}

		// Check if this is a bank step and items need to be picked up. The SNAPSHOT (live
		// contents once a bank opens, the previous session's persisted state before that)
		// stands in for the live container so the hint works from login.
		Set<Integer> bankLocations = plugin.getPathfinderConfig().getDestinations("bank");
		if (bankLocations != null && plugin.getPathfinderConfig().getBankSnapshot() != null)
		{
			List<String> bankPickupItems = BankPickupRequirements.getRequiredBankItems(
				client,
				plugin.getPathfinderConfig().getBankSnapshot(),
				plugin.getPathfinderConfig(),
				bankLocations,
				path,
				pathIndex
			);
			if (!bankPickupItems.isEmpty())
			{
				String pickupText = "Pick up: " + String.join(", ", bankPickupItems);
				playerTileLabelOffset = drawLabelAtPackedLocation(graphics, location, pickupText, playerTileLabelOffset);

				// By default, bank pickup info replaces the default transport hint text;
				// enable the option to show both
				if (!plugin.showBankPickupInfo)
				{
					return;
				}
			}
		}

		// Only show transports the player can currently use; fall back to all if none are usable.
		Map<Integer, Integer> playerHas = BankPickupRequirements.collectPlayerItems(client);
		List<Transport> usableTransports = new ArrayList<>();
		for (Transport t : candidateTransports)
		{
			if (BankPickupRequirements.transportSatisfiedBy(t, playerHas))
			{
				usableTransports.add(t);
			}
		}
		Collection<Transport> transportsToShow = usableTransports.isEmpty() ? candidateTransports : usableTransports;

		// Teleports ("use this item/spell") get a pulsing highlight on the tile you cast from, drawn
		// once for the edge even if several teleport options share it.
		boolean teleportEdge = false;
		for (Transport transport : transportsToShow)
		{
			if (transport.getType() != null && transport.getType().isTeleport())
			{
				teleportEdge = true;
				break;
			}
		}
		// Also pulse when the DISPLAYED route teleports on this edge but the config-derived lookup
		// above missed it — a charged jewellery leg under a "perm-only" teleport-item setting.
		if (!teleportEdge)
		{
			teleportEdge = plugin.displayedRouteTeleportsAt(pathIndex);
		}
		if (teleportEdge && plugin.showTeleportPulse)
		{
			drawTeleportPulse(graphics, location);
		}

		Set<String> shownTexts = new HashSet<>();
		for (Transport transport : transportsToShow)
		{
			String text = transport.getDisplayInfo();
			if (text == null || text.isEmpty())
			{
				// Stairs, ladders, agility shortcuts and other object transports have no display
				// info, so the drawn line just ends at them with no cue. Fall back to their menu
				// text ("Climb-up Staircase", "Walk-across Log balance") so the player is told to
				// use them. Doors are left to the closed-door hint below — an open door needs no
				// label.
				String objectText = RouteDirections.objectText(transport);
				if (objectText != null && !objectText.startsWith("Open "))
				{
					text = objectText;
				}
			}
			if (text == null || text.isEmpty())
			{
				// Doors/gates: hint only while the door is actually closed (the closed object still
				// stands in the scene) — an open door needs no cue, and labelling every doorway on
				// the path would be noise.
				text = closedDoorText(transport);
			}
			if (text == null || text.isEmpty() || !shownTexts.add(text))
			{
				continue;
			}

			// Check if this transport goes to POH - if so, look ahead to find the exit
			// transport
			String pohExitInfo = plugin.getPohExitInfo(locationEnd, path, pathIndex);
			if (pohExitInfo != null)
			{
				text = text + " (Exit: " + pohExitInfo + ")";
			}

			playerTileLabelOffset = drawLabelAtPackedLocation(graphics, location, text, playerTileLabelOffset);
		}

		// Fallback: the displayed route teleports here (e.g. a charged tablet/jewellery) but the
		// config-derived lookup above found no matching transport — its teleport-item setting
		// ("Inventory (perm)") excludes consumables. Label it straight from the route's method so
		// the world cue matches the pulse and the panel step.
		if (shownTexts.isEmpty())
		{
			TeleportMethod routeMethod = plugin.displayedRouteMethodAt(pathIndex);
			if (routeMethod != null && routeMethod.getType() != null && routeMethod.getType().isTeleport())
			{
				String label = routeMethod.label();
				if (label != null && !label.isEmpty())
				{
					playerTileLabelOffset = drawLabelAtPackedLocation(graphics, location, label, playerTileLabelOffset);
				}
			}
		}
	}

}

package gps;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import gps.transport.Transport;
import gps.transport.TransportType;

/**
 * The GPS search index: named places and curated amenities (bank, altar, water source,
 * furnace, ...) a player can navigate to by name or as "nearest X". The bulk is a bundled
 * resource dumped from the cache (destinations.tsv); fairy rings and spirit trees are added
 * from the live transport data because their world objects carry no name in the cache.
 */
@Slf4j
public final class Destinations
{
	private static final String RESOURCE_PATH = "/destinations.tsv";
	// Hand-curated additions (agility courses, skilling spots) kept OUT of the machine-dumped
	// resource above, so regenerating the dump never erases them.
	private static final String CURATED_PATH = "/destinations-curated.tsv";
	// Locations imported from the OSRS wiki's infobox map pins (see WikiLocationDumperTest):
	// searchable places that have no in-game world-map label, deduplicated against the above.
	private static final String WIKI_PATH = "/destinations-wiki.tsv";

	/** One searchable destination: a category, a display name, and a packed world tile. */
	public static final class Entry
	{
		public final String category;
		public final String name;
		public final int packedPosition;

		Entry(String category, String name, int packedPosition)
		{
			this.category = category;
			this.name = name;
			this.packedPosition = packedPosition;
		}
	}

	/** A "nearest X" amenity category offered as a quick option: its id and its display label. */
	public static final class NearestOption
	{
		public final String id;
		public final String label;

		NearestOption(String id, String label)
		{
			this.id = id;
			this.label = label;
		}
	}

	/**
	 * The amenity categories offered as "nearest X" options, in display order. Picking one routes
	 * to ALL tiles of that category at once — the alternative-routes engine then ranks the shortest
	 * paths (using available teleports), which may lead to different sites.
	 */
	public static final List<NearestOption> NEAREST_OPTIONS = List.of(
		new NearestOption("bank", "Bank"),
		new NearestOption("bank_round_trip", "Bank (and back)"),
		new NearestOption("altar", "Altar"),
		new NearestOption("water", "Water source"),
		new NearestOption("furnace", "Furnace"),
		new NearestOption("anvil", "Anvil"),
		new NearestOption("range", "Cooking range"),
		new NearestOption("spinning_wheel", "Spinning wheel"),
		new NearestOption("pottery", "Potter's wheel"),
		new NearestOption("fairy_ring", "Fairy ring"),
		new NearestOption("spirit_tree", "Spirit tree"));

	/** The named places (cities/towns/landmarks) from the bundled resource. */
	public static List<Entry> places()
	{
		List<Entry> places = new ArrayList<>();
		for (Entry entry : resourceEntries())
		{
			if ("place".equals(entry.category))
			{
				places.add(entry);
			}
		}
		return places;
	}

	/**
	 * The entries offered by the name search: named places and dungeons (from the bundled resource)
	 * plus minigames (from the live transport data). Amenities like banks and altars are reached via
	 * "nearest X" instead, so they're left out here to keep results focused.
	 */
	public static List<Entry> searchable(PrimitiveIntHashMap<Transport[]> transports)
	{
		List<Entry> out = new ArrayList<>();
		for (Entry entry : all(transports))
		{
			if ("place".equals(entry.category) || "landmark".equals(entry.category)
				|| "dungeon".equals(entry.category) || "minigame".equals(entry.category)
				|| "training".equals(entry.category))
			{
				out.add(entry);
			}
		}
		return out;
	}

	/**
	 * Every target tile of an amenity category — the target set for its "nearest X" search. The
	 * bundled rows ARE the access tiles: the dump emits, per amenity, the perimeter tiles whose
	 * shared edge with the object carries no wall (the collision map can't make that distinction
	 * at runtime — walls and object-filled neighbours clear the same edge bits — so a blind 3x3
	 * perimeter let "nearest water source" routes end one tile across a wall, OUTSIDE the
	 * building the trough stands in). Tiles occupied by other objects are harmless: never
	 * settled. Fairy rings and spirit trees come from the live transport data; their origins are
	 * the standing tiles themselves.
	 */
	public static Set<Integer> tilesForCategory(String category, PrimitiveIntHashMap<Transport[]> transports)
	{
		// The round-trip variant targets the same sites; the routing mode differs, not the tiles.
		String effective = "bank_round_trip".equals(category) ? "bank" : category;
		Set<Integer> tiles = new HashSet<>();
		boolean transportBacked = "fairy_ring".equals(effective) || "spirit_tree".equals(effective);
		for (Entry entry : transportBacked ? all(transports) : resourceEntries())
		{
			if (effective.equals(entry.category))
			{
				tiles.add(entry.packedPosition);
			}
		}
		return tiles;
	}

	/**
	 * The target set for an arbitrary single tile (a map pin, a Quest Helper NPC tile): the tile
	 * itself when it's walkable — exact semantics preserved — otherwise the tile plus the nearest
	 * ring of walkable tiles around it (radius up to {@code MAX_WALKABLE_RING}). A pin dropped on a
	 * fence, a piece of furniture or an NPC's own tile can never be settled by the search, which
	 * otherwise explores the entire map and falls back to a closest-tile path (the same pathology
	 * the amenity perimeter fixes). If no walkable tile exists within range (a pin mid-pond), the
	 * original tile is returned alone and the search keeps the old closest-tile behaviour.
	 */
	public static Set<Integer> walkableTargets(gps.pathfinder.CollisionMap map, int packed)
	{
		return walkableTargets(map, packed, null);
	}

	/**
	 * As above, but when {@code transportOrigin} is given and the blocked tile has a known
	 * transport ORIGIN within range, the origin tiles alone become the target set. A Quest
	 * Helper target on a cave's footprint would otherwise expand to whichever adjacent tile
	 * the route approaches first — including the BACK of the cave (captured at Trollheim's
	 * Troll Stronghold entrance: routed behind the mouth, then the game walked the long way
	 * around). The mapped transport's origin tile is, by definition, the interactable side.
	 */
	public static Set<Integer> walkableTargets(gps.pathfinder.CollisionMap map, int packed,
		java.util.function.IntPredicate transportOrigin)
	{
		packed = remapTemplateOnlyZones(packed);
		final int x = WorldPointUtil.unpackWorldX(packed);
		final int y = WorldPointUtil.unpackWorldY(packed);
		final int plane = WorldPointUtil.unpackWorldPlane(packed);
		if (map == null || !map.isBlocked(x, y, plane))
		{
			return Set.of(packed);
		}
		// Pass 1: a transport origin near the blocked tile beats plain proximity, even when it
		// sits a radius further out than the first walkable ring.
		if (transportOrigin != null)
		{
			for (int radius = 1; radius <= MAX_WALKABLE_RING; radius++)
			{
				Set<Integer> origins = new HashSet<>();
				for (int dx = -radius; dx <= radius; dx++)
				{
					for (int dy = -radius; dy <= radius; dy++)
					{
						if (Math.max(Math.abs(dx), Math.abs(dy)) != radius)
						{
							continue;
						}
						int tile = WorldPointUtil.packWorldPoint(x + dx, y + dy, plane);
						if (!map.isBlocked(x + dx, y + dy, plane) && transportOrigin.test(tile))
						{
							origins.add(tile);
						}
					}
				}
				if (!origins.isEmpty())
				{
					return origins;
				}
			}
		}
		for (int radius = 1; radius <= MAX_WALKABLE_RING; radius++)
		{
			Set<Integer> ring = new HashSet<>();
			for (int dx = -radius; dx <= radius; dx++)
			{
				for (int dy = -radius; dy <= radius; dy++)
				{
					if (Math.max(Math.abs(dx), Math.abs(dy)) != radius)
					{
						continue;
					}
					if (!map.isBlocked(x + dx, y + dy, plane))
					{
						ring.add(WorldPointUtil.packWorldPoint(x + dx, y + dy, plane));
					}
				}
			}
			if (!ring.isEmpty())
			{
				ring.add(packed);
				return ring;
			}
		}
		return Set.of(packed);
	}

	private static final int MAX_WALKABLE_RING = 5;

	/** A template-only zone: destinations inside the box snap to the anchor tile. */
	static final class Remap
	{
		final int minX;
		final int minY;
		final int maxX;
		final int maxY;
		final int plane;
		final int anchor;
		final String label;

		Remap(int minX, int minY, int maxX, int maxY, int plane, int anchor, String label)
		{
			this.minX = minX;
			this.minY = minY;
			this.maxX = maxX;
			this.maxY = maxY;
			this.plane = plane;
			this.anchor = anchor;
			this.label = label;
		}
	}

	private static List<Remap> remaps;

	/**
	 * Some map areas are pure scenery: instance templates visible from outside (Iban's Temple
	 * interior), display-only floors. A player can never stand there, so a destination inside
	 * one — a clue step, a Quest Helper tile, a curious map pin — would either error as
	 * unreachable or route to fake geometry. Those targets snap to the zone's anchor: the
	 * nearest known-good tile, usually the entrance. Data: destination-remaps.tsv.
	 */
	static int remapTemplateOnlyZones(int packed)
	{
		final int x = WorldPointUtil.unpackWorldX(packed);
		final int y = WorldPointUtil.unpackWorldY(packed);
		final int plane = WorldPointUtil.unpackWorldPlane(packed);
		for (Remap remap : loadRemaps())
		{
			if (plane == remap.plane && x >= remap.minX && x <= remap.maxX
				&& y >= remap.minY && y <= remap.maxY)
			{
				return remap.anchor;
			}
		}
		return packed;
	}

	private static synchronized List<Remap> loadRemaps()
	{
		if (remaps != null)
		{
			return remaps;
		}
		List<Remap> loaded = new ArrayList<>();
		try (InputStream in = ShortestPathPlugin.class.getResourceAsStream("/destination-remaps.tsv"))
		{
			if (in != null)
			{
				try (java.util.Scanner scanner = new java.util.Scanner(in, "UTF-8"))
				{
					while (scanner.hasNextLine())
					{
						String line = scanner.nextLine();
						if (line.startsWith("#") || line.isBlank())
						{
							continue;
						}
						String[] f = line.split("\t");
						if (f.length < 9)
						{
							continue;
						}
						loaded.add(new Remap(Integer.parseInt(f[0].trim()), Integer.parseInt(f[1].trim()),
							Integer.parseInt(f[2].trim()), Integer.parseInt(f[3].trim()),
							Integer.parseInt(f[4].trim()),
							WorldPointUtil.packWorldPoint(Integer.parseInt(f[5].trim()),
								Integer.parseInt(f[6].trim()), Integer.parseInt(f[7].trim())),
							f[8].trim()));
					}
				}
			}
		}
		catch (IOException | NumberFormatException e)
		{
			// A malformed remap file must never break routing — fall through with what parsed.
		}
		remaps = loaded;
		return remaps;
	}

	private static volatile List<Entry> resourceEntries;

	private Destinations()
	{
	}

	/** The static place + amenity entries from the bundled resource (loaded once). */
	public static List<Entry> resourceEntries()
	{
		List<Entry> snapshot = resourceEntries;
		if (snapshot == null)
		{
			synchronized (Destinations.class)
			{
				snapshot = resourceEntries;
				if (snapshot == null)
				{
					snapshot = load();
					resourceEntries = snapshot;
				}
			}
		}
		return snapshot;
	}

	/**
	 * The static entries plus destinations derived from the live transport data: one per fairy ring
	 * and spirit tree (deduplicated by origin — these objects have no cache name, so they're named by
	 * their transport display info like "Fairy ring AIQ"), and one per minigame (deduplicated by name,
	 * placed at the minigame's teleport destination and named from its display info, e.g. "Castle Wars").
	 */
	public static List<Entry> all(PrimitiveIntHashMap<Transport[]> transports)
	{
		List<Entry> entries = new ArrayList<>(resourceEntries());
		if (transports == null)
		{
			return entries;
		}
		PrimitiveIntList seen = new PrimitiveIntList();
		// Seed with the bundled minigame entries (curated rows), so a transport-derived duplicate
		// of the same minigame isn't added twice.
		Set<String> seenMinigames = new HashSet<>();
		for (Entry entry : entries)
		{
			if ("minigame".equals(entry.category))
			{
				seenMinigames.add(entry.name.toLowerCase(java.util.Locale.ROOT));
			}
		}
		for (int key : transports.keys())
		{
			Transport[] set = transports.get(key);
			if (set == null)
			{
				continue;
			}
			for (Transport transport : set)
			{
				TransportType type = transport.getType();
				if (type == TransportType.FAIRY_RING || type == TransportType.SPIRIT_TREE)
				{
					int origin = transport.getOrigin();
					if (origin == Transport.UNDEFINED_ORIGIN || seen.contains(origin))
					{
						continue;
					}
					seen.add(origin);
					String label = type == TransportType.FAIRY_RING ? "Fairy ring" : "Spirit tree";
					String info = transport.getDisplayInfo();
					String name = info != null && !info.isEmpty() ? label + " " + info : label;
					entries.add(new Entry(type == TransportType.FAIRY_RING ? "fairy_ring" : "spirit_tree",
						name, origin));
				}
				else if (type == TransportType.TELEPORTATION_MINIGAME)
				{
					int destination = transport.getDestination();
					String name = minigameName(transport.getDisplayInfo());
					if (destination == WorldPointUtil.UNDEFINED
						|| !seenMinigames.add(name.toLowerCase(java.util.Locale.ROOT)))
					{
						continue;
					}
					entries.add(new Entry("minigame", name, destination));
				}
			}
		}
		return entries;
	}

	/**
	 * A clean minigame label from a minigame-teleport's display info: drops the "Minigame Teleport"
	 * boilerplate and the numbered-variant prefix, e.g. "Castle Wars Minigame Teleport" -&gt;
	 * "Castle Wars", and "Rat Pits Minigame Teleport: 1. Ardougne" -&gt; "Rat Pits: Ardougne".
	 */
	private static String minigameName(String info)
	{
		if (info == null || info.isEmpty())
		{
			return "Minigame";
		}
		String name = info.replace("Minigame Teleport", " ").replaceAll("\\s+", " ").trim();
		name = name.replace(" :", ":").replaceAll(":\\s*\\d+\\.\\s*", ": ");
		return name.trim();
	}

	private static List<Entry> load()
	{
		List<Entry> entries = loadResource(RESOURCE_PATH);
		entries.addAll(loadResource(CURATED_PATH));
		entries.addAll(loadResource(WIKI_PATH));
		return entries;
	}

	private static List<Entry> loadResource(String path)
	{
		try (InputStream in = ShortestPathPlugin.class.getResourceAsStream(path))
		{
			if (in == null)
			{
				log.warn("Destinations resource not found at {}", path);
				return new ArrayList<>();
			}
			return parse(new String(Util.readAllBytes(in), StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			log.error("Failed to load destinations from {}", path, e);
			return new ArrayList<>();
		}
	}

	private static List<Entry> parse(String tsv)
	{
		List<Entry> entries = new ArrayList<>();
		boolean header = true;
		for (String line : tsv.split("\\R"))
		{
			if (header)
			{
				header = false;
				continue;
			}
			if (line.isEmpty())
			{
				continue;
			}
			// category, name, x, y, plane [, verified_source, verified_date] — the trailing
			// verification columns are metadata for maintenance and are ignored at load time.
			String[] fields = line.split("\t");
			if (fields.length < 5)
			{
				continue;
			}
			try
			{
				int packed = WorldPointUtil.packWorldPoint(
					Integer.parseInt(fields[2]), Integer.parseInt(fields[3]), Integer.parseInt(fields[4]));
				entries.add(new Entry(fields[0], fields[1], packed));
			}
			catch (NumberFormatException e)
			{
				log.warn("Skipping malformed destination row: '{}'", line);
			}
		}
		return entries;
	}
}

package gps;

import java.io.InputStream;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

/**
 * The game's boat-location registry: SAILING_BOAT_N_PORT varbit values joined to this
 * plugin's mooring tiles (shipped sailing-ports.tsv, ids adapted from the 'Dude, Where's
 * My Boat?' hub plugin). A port may span several moorings; the first is the primary
 * (teleport landing) berth. Special values: 254 = capsized, 255 = bottled — no mooring.
 */
public final class SailingPorts
{
	public static final int PORT_CAPSIZED = 254;
	public static final int PORT_BOTTLED = 255;

	private static volatile SailingPorts instance;

	private final Map<Integer, String> names = new HashMap<>();
	/** Packed mooring land tiles per port id; first entry is the primary berth. */
	private final Map<Integer, List<Integer>> moorings = new HashMap<>();

	private SailingPorts()
	{
		try (InputStream in = SailingPorts.class.getResourceAsStream("/sailing-ports.tsv");
			Scanner scanner = new Scanner(in, "UTF-8"))
		{
			while (scanner.hasNextLine())
			{
				String[] fields = scanner.nextLine().split("\t");
				if (fields.length < 4 || fields[0].startsWith("#") || "portId".equals(fields[0]))
				{
					continue;
				}
				int id = Integer.parseInt(fields[0]);
				names.putIfAbsent(id, fields[1].trim());
				moorings.computeIfAbsent(id, k -> new ArrayList<>()).add(WorldPointUtil.packWorldPoint(
					Integer.parseInt(fields[2]), Integer.parseInt(fields[3]), 0));
			}
		}
		catch (java.io.IOException | RuntimeException e)
		{
			// A missing registry only disables boat-location awareness, never routing.
		}
	}

	private static SailingPorts get()
	{
		SailingPorts loaded = instance;
		if (loaded == null)
		{
			synchronized (SailingPorts.class)
			{
				loaded = instance;
				if (loaded == null)
				{
					instance = loaded = new SailingPorts();
				}
			}
		}
		return loaded;
	}

	/** Packed mooring land tiles of the port, empty for capsized/bottled/unknown ids. */
	public static List<Integer> portMoorings(int portId)
	{
		return get().moorings.getOrDefault(portId, List.of());
	}

	/** Display name for a port id; capsized/bottled and unknown ids get honest fallbacks. */
	public static String portName(int portId)
	{
		if (portId == PORT_CAPSIZED)
		{
			return "capsized";
		}
		if (portId == PORT_BOTTLED)
		{
			return "in a bottle";
		}
		String name = get().names.get(portId);
		return name != null ? name : "port " + portId;
	}
}

package gps;

import com.google.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.Area;
import java.util.Objects;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import gps.pathfinder.PathStep;

public class PathMapOverlay extends Overlay
{
	private final Client client;
	private final ShortestPathPlugin plugin;

	@Inject
	private PathMapOverlay(Client client, ShortestPathPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.MANUAL);
		drawAfterLayer(InterfaceID.Worldmap.MAP_CONTAINER);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.drawMap)
		{
			return null;
		}

		if (client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER) == null)
		{
			return null;
		}

		Rectangle worldMapRectangle = Objects.requireNonNull(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).getBounds();
		Area worldMapClipArea = getWorldMapClipArea(worldMapRectangle);
		graphics.setClip(worldMapClipArea);



		if (plugin.hasPathTargets())
		{
			Color colour = plugin.getPathColor();
			java.util.List<PathStep> path = plugin.getDisplayPath();
			Point cursorPos = client.getMouseCanvasPosition();
			graphics.setColor(colour);
			drawArrowPath(graphics, path, plugin.getDisplaySailingEdges());
			for (int target : plugin.getPathTargets())
			{
				if (!path.isEmpty() && target != path.get(path.size() - 1).getPackedPosition())
				{
					graphics.setColor(plugin.colourPathCalculating);
					drawOnMap(graphics, target, true, cursorPos);
				}
			}
		}

		return null;
	}

	/**
	 * Draws the path as a directed polyline: consecutive same-direction walking steps are compressed
	 * into one straight segment, each segment ends in a small arrowhead showing travel direction, and
	 * teleport/transport jumps are dashed. (Arrowhead technique adapted from Quest Helper's
	 * DirectionArrow, see {@link ArrowHead}.)
	 */
	private void drawArrowPath(Graphics2D graphics, java.util.List<PathStep> path,
		java.util.Set<Integer> sailingEdges)
	{
		final java.awt.Stroke walkStroke = new BasicStroke(2, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
		final java.awt.Stroke jumpStroke = new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_BEVEL, 0, new float[]{9}, 0);

		int i = 0;
		while (i < path.size() - 1)
		{
			int from = path.get(i).getPackedPosition();
			int next = path.get(i + 1).getPackedPosition();

			if (WorldPointUtil.distanceBetween(from, next) > 1)
			{
				// Sailing leg: draw the actual sea track (bounded Dijkstra over the shipped
				// ocean, cached per leg) as a solid line; anything else — and any sailing leg
				// whose track cannot be computed — stays the dashed jump hint.
				// sailingEdges holds DEPARTURE indexes (RouteOption.sailingJumpDepartures
				// owns the arrival->departure arithmetic, pinned by its unit test).
				int[] track = sailingEdges.contains(i) ? SailingSea.seaPath(from, next) : null;
				if (track != null)
				{
					// Sea legs draw in their own (configurable) colour: amber reads over both
					// the ocean and the cyan walking path, then the path colour is restored
					// for the legs that follow.
					java.awt.Color pathColour = graphics.getColor();
					graphics.setColor(plugin.getSailingPathColor());
					for (int s = 0; s < track.length - 1; s++)
					{
						drawMapSegment(graphics, track[s], track[s + 1], walkStroke);
					}
					graphics.setColor(pathColour);
				}
				else
				{
					drawMapSegment(graphics, from, next, jumpStroke);
				}
				i++;
				continue;
			}

			// Extend the straight walking run while the direction stays the same.
			int dx = WorldPointUtil.unpackWorldX(next) - WorldPointUtil.unpackWorldX(from);
			int dy = WorldPointUtil.unpackWorldY(next) - WorldPointUtil.unpackWorldY(from);
			int j = i + 1;
			while (j < path.size() - 1)
			{
				int a = path.get(j).getPackedPosition();
				int b = path.get(j + 1).getPackedPosition();
				if (WorldPointUtil.distanceBetween(a, b) > 1
					|| WorldPointUtil.unpackWorldX(b) - WorldPointUtil.unpackWorldX(a) != dx
					|| WorldPointUtil.unpackWorldY(b) - WorldPointUtil.unpackWorldY(a) != dy)
				{
					break;
				}
				j++;
			}
			drawMapSegment(graphics, from, path.get(j).getPackedPosition(), walkStroke);
			i = j;
		}
	}

	private void drawMapSegment(Graphics2D graphics, int from, int to, java.awt.Stroke stroke)
	{
		int x1 = plugin.mapWorldPointToGraphicsPointX(from);
		int y1 = plugin.mapWorldPointToGraphicsPointY(from);
		int x2 = plugin.mapWorldPointToGraphicsPointX(to);
		int y2 = plugin.mapWorldPointToGraphicsPointY(to);
		if (x1 == Integer.MIN_VALUE || y1 == Integer.MIN_VALUE
			|| x2 == Integer.MIN_VALUE || y2 == Integer.MIN_VALUE)
		{
			return;
		}
		graphics.setStroke(stroke);
		graphics.drawLine(x1, y1, x2, y2);
		// Skip the head on segments too short to fit it (e.g. zoomed far out).
		if (Math.hypot(x2 - x1, y2 - y1) >= 10)
		{
			ArrowHead.draw(graphics, x1, y1, x2, y2, 7);
		}
	}

	private void drawOnMap(Graphics2D graphics, int point, boolean checkHover, Point cursorPos)
	{
		drawOnMap(graphics, point, WorldPointUtil.dxdy(point, 1, -1), checkHover, cursorPos);
	}

	private void drawOnMap(Graphics2D graphics, int point, int offsetPoint, boolean checkHover, Point cursorPos)
	{
		int startX = plugin.mapWorldPointToGraphicsPointX(point);
		int startY = plugin.mapWorldPointToGraphicsPointY(point);
		int endX = plugin.mapWorldPointToGraphicsPointX(offsetPoint);
		int endY = plugin.mapWorldPointToGraphicsPointY(offsetPoint);

		if (startX == Integer.MIN_VALUE || startY == Integer.MIN_VALUE ||
			endX == Integer.MIN_VALUE || endY == Integer.MIN_VALUE)
		{
			return;
		}

		int x = startX;
		int y = startY;
		final int width = endX - x;
		final int height = endY - y;
		x -= width / 2;
		y -= height / 2;

		if (WorldPointUtil.distanceBetween(point, offsetPoint) > 1)
		{
			graphics.setStroke(new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_BEVEL, 0, new float[]{9}, 0));
			graphics.drawLine(startX, startY, endX, endY);
		}
		else
		{
			if (checkHover && cursorPos != null &&
				cursorPos.getX() >= x && cursorPos.getX() <= (endX - width / 2) &&
				cursorPos.getY() >= y && cursorPos.getY() <= (endY - width / 2))
			{
				graphics.setColor(graphics.getColor().darker());
			}
			graphics.fillRect(x, y, width, height);
		}
	}

	private Area getWorldMapClipArea(Rectangle baseRectangle)
	{
		final Widget overview = client.getWidget(InterfaceID.Worldmap.OVERVIEW_CONTAINER);
		final Widget surfaceSelector = client.getWidget(InterfaceID.Worldmap.MAPLIST_BOX_GRAPHIC0);

		Area clipArea = new Area(baseRectangle);

		if (overview != null && !overview.isHidden())
		{
			clipArea.subtract(new Area(overview.getBounds()));
		}

		if (surfaceSelector != null && !surfaceSelector.isHidden())
		{
			clipArea.subtract(new Area(surfaceSelector.getBounds()));
		}

		return clipArea;
	}
}

package gps;

import gps.pathfinder.CollisionMap;
import gps.pathfinder.PathStep;
import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Pure route-progress selection: which path index the player has honestly reached. Extracted from
 * the directions overlay so the maze rules are unit-testable.
 * <p>
 * Straight-line proximity is wall-blind — standing one tile OUTSIDE a wall used to snap progress
 * onto an unreachable path tile, and maze corridors that double back within a few tiles teleported
 * the marker across walls. Eligibility is therefore based on WALKING distance (a small bounded BFS
 * through the collision map around the player): a candidate tile must be genuinely walkable-to in
 * roughly its straight-line distance, or it doesn't count. When no collision map is available yet,
 * the legacy straight-line rules apply unchanged.
 */
final class RouteProgress
{
	/** Max index drift per update for near-line matches (honest travel, not teleports). */
	static final int STEP_WINDOW = 8;
	/** Max straight-line distance for near-line matches. */
	static final int NEAR_DISTANCE = 10;
	/** Walking may exceed the straight line by this much before a match reads as through-a-wall. */
	static final int REACH_SLACK = 2;
	/** BFS radius: the largest walking distance any eligibility rule can accept. */
	static final int REACH_RADIUS = NEAR_DISTANCE + REACH_SLACK;

	private RouteProgress()
	{
	}

	/** A selection: the reached path index and the walking distance to it (for the ETA). */
	static final class Result
	{
		final int index;
		final int distance;

		Result(int index, int distance)
		{
			this.index = index;
			this.distance = distance;
		}
	}

	/**
	 * Walking distances (in steps, diagonals allowed) from the player to every tile within
	 * {@code radius} steps, honouring walls via {@link CollisionMap#canStep}. Null when no map is
	 * available (callers fall back to straight-line rules).
	 */
	static Map<Integer, Integer> walkDistances(CollisionMap map, int fromPacked, int radius)
	{
		if (map == null)
		{
			return null;
		}
		Map<Integer, Integer> distances = new HashMap<>();
		distances.put(fromPacked, 0);
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		queue.add(fromPacked);
		int x = WorldPointUtil.unpackWorldX(fromPacked);
		int y = WorldPointUtil.unpackWorldY(fromPacked);
		int plane = WorldPointUtil.unpackWorldPlane(fromPacked);
		while (!queue.isEmpty())
		{
			int tile = queue.poll();
			int steps = distances.get(tile);
			if (steps >= radius)
			{
				continue;
			}
			int tx = WorldPointUtil.unpackWorldX(tile);
			int ty = WorldPointUtil.unpackWorldY(tile);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					if (dx == 0 && dy == 0)
					{
						continue;
					}
					int next = WorldPointUtil.packWorldPoint(tx + dx, ty + dy, plane);
					if (!distances.containsKey(next)
						&& Math.max(Math.abs(tx + dx - x), Math.abs(ty + dy - y)) <= radius
						&& map.canStep(tile, next))
					{
						distances.put(next, steps + 1);
						queue.add(next);
					}
				}
			}
		}
		return distances;
	}

	/**
	 * The path index the player has reached, or null to hold the previous estimate.
	 *
	 * @param path        the route's tiles
	 * @param reachedIndex the previous selection (index drift is measured from here)
	 * @param doorGate    first path index at/past an uncrossed door — only exact on-tile presence
	 *                    counts from there on
	 * @param returnGate  first index of a round trip's return leg while still outbound
	 *                    ({@code Integer.MAX_VALUE} when not applicable)
	 * @param playerPacked the player's tile
	 * @param walk        walking distances around the player, or null for legacy straight-line rules
	 */
	static Result select(List<PathStep> path, int reachedIndex, int doorGate, int returnGate,
		int playerPacked, Map<Integer, Integer> walk)
	{
		int best = -1;
		int bestDistance = Integer.MAX_VALUE;
		int bestOffset = Integer.MAX_VALUE;
		for (int i = 0; i < path.size(); i++)
		{
			if (i > returnGate)
			{
				break;
			}
			int packed = path.get(i).getPackedPosition();
			// distanceBetween is MAX_VALUE across planes, so other-plane tiles filter out here.
			int straight = WorldPointUtil.distanceBetween(packed, playerPacked);
			Integer walked = walk != null ? walk.get(packed) : null;
			boolean beyondDoor = i >= doorGate;
			boolean eligible;
			int metric;
			if (walk != null)
			{
				// Wall-aware rules: same tile always counts; "on path" needs a genuinely walkable
				// single step; near-line matches must be walkable in about their straight-line
				// distance, or the "closeness" is through a wall.
				if (beyondDoor)
				{
					eligible = straight == 0;
				}
				else if (walked != null && walked <= 1)
				{
					eligible = true;
				}
				else
				{
					eligible = walked != null
						&& Math.abs(i - reachedIndex) <= STEP_WINDOW
						&& straight <= NEAR_DISTANCE
						&& walked <= straight + REACH_SLACK;
				}
				metric = walked != null ? walked : straight;
			}
			else
			{
				// Legacy straight-line rules (no collision map yet).
				boolean incremental = !beyondDoor && Math.abs(i - reachedIndex) <= STEP_WINDOW
					&& straight <= NEAR_DISTANCE;
				boolean onPath = straight <= (beyondDoor ? 0 : 1);
				eligible = incremental || onPath;
				metric = straight;
			}
			if (!eligible)
			{
				continue;
			}
			int offset = Math.abs(i - reachedIndex);
			if (metric < bestDistance || (metric == bestDistance && offset < bestOffset))
			{
				best = i;
				bestDistance = metric;
				bestOffset = offset;
			}
		}
		return best < 0 ? null : new Result(best, bestDistance);
	}
}

