package gps;

import gps.pathfinder.CostUnits;

/**
 * A user-set ranking bias for a travel method — RimWorld-style tiers. Priorities shift a route's
 * EFFECTIVE ETA (the sort key and the card's adjustment chip) by a fixed number of seconds per
 * prioritised method used; they never change the search itself, so adjusting them re-sorts the
 * existing list instantly with no recalculation. EXCLUDED is the terminal tier and delegates to
 * the existing exclusion machinery (which does affect the search).
 */
public enum MethodPriority
{
	PREFER_3(-20, "Strongly prefer"),
	PREFER_2(-10, "Prefer"),
	PREFER_1(-5, "Slightly prefer"),
	NORMAL(0, "Normal"),
	AVOID_1(5, "Slightly avoid"),
	AVOID_2(10, "Avoid"),
	AVOID_3(20, "Strongly avoid"),
	EXCLUDED(0, "Exclude");

	/** Seconds added to the route's effective ETA (negative = preferred, ranks earlier). */
	public final int adjustSeconds;
	public final String label;

	MethodPriority(int adjustSeconds, String label)
	{
		this.adjustSeconds = adjustSeconds;
		this.label = label;
	}

	/** The adjustment in search cost units (1 tick = 0.6s), rounded to the nearest unit. */
	public int adjustUnits()
	{
		return unitsFromSeconds(adjustSeconds);
	}

	/** Seconds -> cost units: seconds / 0.6s-per-tick * units-per-tick, away-from-zero rounding. */
	public static int unitsFromSeconds(int seconds)
	{
		return (int) Math.round(seconds / 0.6 * CostUnits.UNITS_PER_TICK);
	}

	/** The +Ns / -Ns chip text ("" for no adjustment). */
	public String chipText()
	{
		if (adjustSeconds == 0)
		{
			return "";
		}
		return (adjustSeconds > 0 ? "+" : "−") + Math.abs(adjustSeconds) + "s";
	}
}

package gps;

/**
 * Why a teleport method can or cannot be used right now, for the alternative-routes panel's per-method
 * status marker. Computed against live game state during the client-thread pathfinder refresh, so the
 * panel can explain (missing item, in the bank, missing level/quest, not unlocked) why an entry is
 * greyed out — in every mode, not just the possession-bypassing "All" modes.
 */
public enum MethodAvailability
{
	/** Usable right now from the inventory/equipment (all unlocks met). */
	AVAILABLE,
	/** Owned, but the required item is in the bank — withdraw it or use an "Inventory + bank" mode. */
	IN_BANK,
	/** Unlocked, but the required item isn't in the inventory, equipment or bank. */
	MISSING_ITEM,
	/** A skill level requirement isn't met. */
	MISSING_LEVEL,
	/** A quest requirement isn't met. */
	MISSING_QUEST,
	/** An unlock (diary, minigame, purchase, setting, ...) isn't met. */
	LOCKED;

	/**
	 * The more-available of two statuses (lower ordinal = more available). Used to collapse the several
	 * transports that can share one method identity down to a single, best-case status.
	 */
	public MethodAvailability best(MethodAvailability other)
	{
		if (other == null)
		{
			return this;
		}
		return ordinal() <= other.ordinal() ? this : other;
	}
}

package gps.pathfinder;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.util.Arrays;
import java.util.BitSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

import static net.runelite.api.Constants.REGION_SIZE;

import gps.ShortestPathPlugin;
import gps.Util;

public class SplitFlagMap
{
	private static final int FLAG_COUNT = 2;
	private static final int BITS_PER_PLANE = REGION_SIZE * REGION_SIZE * FLAG_COUNT;
	private static final int WORDS_PER_PLANE = BITS_PER_PLANE / Long.SIZE;
	private static final int REGION_MASK = REGION_SIZE - 1;

	@Getter
	private static RegionExtent regionExtents;

	private final byte[] regionMapPlaneCounts;
	// Every region's collision bits are packed into one shared word array instead of a separate
	// FlagMap + BitSet + long[] per region. regionWordOffset gives each region's start word, or -1
	// when the region has no collision data (issue #491).
	private final long[] flags;
	private final int[] regionWordOffset;
	private final int widthInclusive;

	public SplitFlagMap(Map<Integer, byte[]> compressedRegions)
	{
		widthInclusive = regionExtents.getWidth() + 1;
		final int heightInclusive = regionExtents.getHeight() + 1;
		final int regionCount = widthInclusive * heightInclusive;
		regionMapPlaneCounts = new byte[regionCount];
		regionWordOffset = new int[regionCount];
		Arrays.fill(regionWordOffset, -1);

		// First pass: decode each region and reserve it a slice of the shared word array.
		final Map<Integer, long[]> regionWords = new HashMap<>(compressedRegions.size());
		int totalWords = 0;
		for (Map.Entry<Integer, byte[]> entry : compressedRegions.entrySet())
		{
			final int pos = entry.getKey();
			final int index = getIndex(unpackX(pos), unpackY(pos));
			final BitSet bits = BitSet.valueOf(entry.getValue());
			// Same plane-count derivation the old FlagMap used.
			final int planeCount = (bits.size() + BITS_PER_PLANE - 1) / BITS_PER_PLANE;
			regionMapPlaneCounts[index] = (byte) planeCount;
			regionWordOffset[index] = totalWords;
			regionWords.put(index, bits.toLongArray());
			totalWords += planeCount * WORDS_PER_PLANE;
		}

		// Second pass: copy each region's words into its reserved slice (trailing zero words from
		// BitSet.toLongArray are left as the zero-filled remainder of the slice).
		flags = new long[totalWords];
		for (Map.Entry<Integer, long[]> entry : regionWords.entrySet())
		{
			final long[] words = entry.getValue();
			System.arraycopy(words, 0, flags, regionWordOffset[entry.getKey()], words.length);
		}
	}

	public static int unpackX(int position)
	{
		return position & 0xFFFF;
	}

	public static int unpackY(int position)
	{
		return (position >> 16) & 0xFFFF;
	}

	public static int packPosition(int x, int y)
	{
		return (x & 0xFFFF) | ((y & 0xFFFF) << 16);
	}

	public static SplitFlagMap fromResources()
	{
		Map<Integer, byte[]> compressedRegions = new HashMap<>();
		try (ZipInputStream in = new ZipInputStream(Objects.requireNonNull(ShortestPathPlugin.class.getResourceAsStream("/collision-map.zip"))))
		{
			int minX = Integer.MAX_VALUE;
			int minY = Integer.MAX_VALUE;
			int maxX = 0;
			int maxY = 0;

			ZipEntry entry;
			while ((entry = in.getNextEntry()) != null)
			{
				String[] n = entry.getName().split("_");
				final int x = Integer.parseInt(n[0]);
				final int y = Integer.parseInt(n[1]);
				minX = Math.min(minX, x);
				minY = Math.min(minY, y);
				maxX = Math.max(maxX, x);
				maxY = Math.max(maxY, y);

				compressedRegions.put(SplitFlagMap.packPosition(x, y), Util.readAllBytes(in));
			}

			regionExtents = new RegionExtent(minX, minY, maxX, maxY);
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}

		return new SplitFlagMap(compressedRegions);
	}

	public byte getRegionPlaneCounts(int index)
	{
		return regionMapPlaneCounts[index];
	}

	public boolean get(int x, int y, int z, int flag)
	{
		final int index = getIndex(x / REGION_SIZE, y / REGION_SIZE);
		if (index < 0 || index >= regionWordOffset.length)
		{
			return false;
		}

		final int wordOffset = regionWordOffset[index];
		if (wordOffset < 0 || z < 0 || z >= regionMapPlaneCounts[index])
		{
			return false;
		}

		// SplitFlagMap routes (x, y) to the region that contains it, so the in-region coordinates
		// are simply the low REGION_SIZE bits; this matches the old FlagMap.index arithmetic.
		final int localBit = (z * REGION_SIZE * REGION_SIZE
			+ (y & REGION_MASK) * REGION_SIZE
			+ (x & REGION_MASK)) * FLAG_COUNT + flag;
		return (flags[wordOffset + (localBit >> 6)] >>> (localBit & 63) & 1L) != 0L;
	}

	private int getIndex(int regionX, int regionY)
	{
		return (regionX - regionExtents.getMinX()) + (regionY - regionExtents.getMinY()) * widthInclusive;
	}

	@RequiredArgsConstructor
	@Getter
	public static class RegionExtent
	{
		public final int minX, minY, maxX, maxY;

		public int getWidth()
		{
			return maxX - minX;
		}

		public int getHeight()
		{
			return maxY - minY;
		}
	}
}

package gps.pathfinder;

public enum PathTerminationReason
{
	TARGET_REACHED,
	SEARCH_EXHAUSTED,
	CUTOFF_REACHED
}

package gps.pathfinder;

import java.util.List;
import java.util.Set;

import lombok.Getter;
import gps.PrimitiveIntList;
import gps.WorldPointUtil;
import gps.leagues.LeagueModeState;

public class Pathfinder implements Runnable
{
	private final PathfinderStats stats;
	private final int start;
	private final Set<Integer> targets;
	private final PathfinderConfig config;
	private final CollisionMap map;
	private final boolean targetInWilderness;
	private final boolean targetInBlockedRegion;
	// Nodes are stored structure-of-arrays style: each node is an int id into the graph, instead of
	// an object per explored tile. This keeps a whole search to a handful of arrays (issue #491).
	private final NodeGraph graph;
	// Capacities should be enough to store all nodes without requiring the queue to grow
	// They were found by checking the max queue size
	private final IntDeque boundary = new IntDeque(4096);
	private final IntMinHeap pending;
	// A* mode (heuristic attached): the ordering key is g + a consistent heuristic instead of g.
	private final boolean astar;
	// Heap mode: every node goes through a cost-ordered queue and visited-marking moves from
	// enqueue to dequeue (the first DEQUEUE of a state is via its cheapest parent; the first
	// ENQUEUE isn't necessarily). Engaged whenever the ordering can be non-uniform: a heuristic is
	// attached (A*), or ANY transport/teleport is usable — a popped transport feeds tiles back
	// into the FIFO at an arbitrary cost behind entries with larger costs, after which FIFO order
	// is no longer cost order and enqueue-marking claims tiles via non-cheapest parents (returning
	// non-minimal routes). The FIFO fast-path remains only for genuinely uniform-cost searches,
	// where its layer assumption actually holds.
	private final boolean heapMode;
	// The ordered queue for UNINFORMED heap-mode searches: a Dial's bucket queue keyed by g, whose
	// O(1) push/pop keeps the map-wide floods (nearest-X) at FIFO-era speed — the binary heap's
	// log n per node doubled their cpu. A* searches keep the heap: their key (g + h) can jump by
	// the heuristic delta, and the field heuristic already keeps them small.
	private final IntBucketQueue buckets;
	// Duplicate-enqueue pruner for the same searches: settle-dedup re-enqueues each tile from
	// every settled neighbour (~3-4x node volume); recording the best tentative cost per state
	// skips non-improving duplicates before their nodes are created. Improving duplicates still
	// go through, so costs stay exact.
	private final TentativeCosts tentative;
	private final VisitedTiles visited;
	// The node the search ended on (the reached target, or the best closest-tile candidate).
	private int bestLastNode = NodeGraph.NO_NODE;
	// Built once when the search finishes, before the node graph is released. The classic plugin
	// flow used to read a partial path progressively DURING the search; that machinery is retired -
	// every consumer now runs the search to completion and reads this snapshot.
	private volatile List<PathStep> finalPath = null;
	// Accumulated cost of the path to bestLastNode, captured before the node graph is released so
	// alternative-route ranking has a total cost without re-walking the (released) chain.
	private volatile int finalCost = -1;
	private volatile int closestReachedPoint = WorldPointUtil.UNDEFINED;
	private int bestRemainingDistance = Integer.MAX_VALUE;
	private int bestTravelledDistance = Integer.MAX_VALUE;
	private int bestX = Integer.MAX_VALUE;
	private int bestY = Integer.MAX_VALUE;
	private int reachedTarget = WorldPointUtil.UNDEFINED;
	private PathTerminationReason terminationReason;
	// The targets as a plain array: the closest-tile tracking compares every target, and iterating
	// the boxed set there was measurable with large target sets ("nearest bank" has ~150).
	private final int[] targetArray;
	// Hard cost ceiling: nodes above it are never expanded. Used by the alternative-routes engine to
	// bound every search at the walk-only cost (routes costlier than walking are never shown), which
	// keeps a useless seed teleport from flooding the map. MAX_VALUE = uncapped.
	private final int costCap;
	// Optional live ceiling polled on every pop, lowered mid-search from another thread. The walk-only
	// search uses it: it starts unbounded but drops to the best route's cost as soon as the chain finds
	// one, so a walk to an unreachable/far target stops flooding the map instead of exploring it whole.
	private java.util.function.IntSupplier dynamicCostCap;
	// Closest-tile tracking is O(targets) per node, so during the search it only runs on every
	// UNREACHABLE_TRACK_INTERVAL-th tile (enough for the cutoff extension and the progressively
	// rendered partial path); the exact best tile is recovered in one post-pass when the search
	// ends without reaching a target.
	private static final int UNREACHABLE_TRACK_INTERVAL = 16;
	// Test-only invariant check: in heap mode the settled orderCost sequence must never decrease
	// (Dijkstra/consistent-A* property). A decrease means the heuristic overestimated somewhere
	// (inadmissibility) or an ordering-only term crept into the key — the failure modes behind
	// returned-but-not-minimal routes. Off in production; the optimality tests switch it on.
	public static volatile boolean validateSettleOrder = false;
	private int lastSettledOrderCost = Integer.MIN_VALUE;
	private int unreachableTrackCounter = 0;
	/**
	 * Teleportation transports are updated when this changes.
	 * Can be either:
	 * 0 = all teleports can be used (e.g. Chronicle)
	 * 20 = most teleports can be used (e.g. Varrock Teleport)
	 * 30 = some teleports can be used (e.g. Amulet of Glory)
	 * 31 = no teleports can be used
	 */
	private int wildernessLevel;

	public Pathfinder(PathfinderConfig config, int start, Set<Integer> targets,
		int costCap, SearchHeuristic heuristic)
	{
		stats = new PathfinderStats();
		this.config = config;
		this.map = config.getMap();
		this.start = start;
		this.targets = targets;
		this.costCap = costCap;
		this.astar = heuristic != null;
		this.heapMode = astar || anyTransportsUsable(config);
		this.buckets = (heapMode && !astar) ? new IntBucketQueue() : null;
		this.tentative = buckets != null ? new TentativeCosts(map) : null;
		this.graph = new NodeGraph(1 << 14, heuristic);
		this.pending = new IntMinHeap(graph, astar ? 4096 : 256);
		visited = new VisitedTiles(map);
		targetInWilderness = WildernessChecker.isInWilderness(targets);
		targetInBlockedRegion = anyInBlockedRegion(config.getLeagueModeState(), targets);
		wildernessLevel = 31;
		targetArray = new int[targets.size()];
		int i = 0;
		for (int target : targets)
		{
			targetArray[i++] = target;
		}
	}

	/** Whether this search runs with an A* heuristic (identical costs, smaller exploration). */
	public boolean isAstar()
	{
		return astar;
	}

	/** Whether any transport or teleport is usable — the trigger for full heap ordering. */
	private static boolean anyTransportsUsable(PathfinderConfig config)
	{
		return config.getTransportsPacked(false).size() > 0
			|| config.getTransportsPacked(true).size() > 0
			|| config.getUsableTeleports(false).length > 0
			|| config.getUsableTeleports(true).length > 0;
	}

	private static boolean anyInBlockedRegion(LeagueModeState league, Set<Integer> packed)
	{
		if (!league.isSeasonal() || packed == null || packed.isEmpty())
		{
			return false;
		}
		for (Integer point : packed)
		{
			if (league.isInBlockedRegion(point))
			{
				return true;
			}
		}
		return false;
	}

	public Pathfinder(PathfinderConfig config, int start, Set<Integer> targets)
	{
		this(config, start, targets, Integer.MAX_VALUE, null);
	}

	/**
	 * Installs a live cost ceiling polled on every pop (in addition to the fixed {@code costCap}).
	 * Set before {@link #run()}; the supplier may be lowered from another thread during the search.
	 */
	public void setDynamicCostCap(java.util.function.IntSupplier dynamicCostCap)
	{
		this.dynamicCostCap = dynamicCostCap;
	}

	public PathfinderStats getStats()
	{
		if (stats.started && stats.ended)
		{
			return stats;
		}

		// Don't give incomplete results
		return null;
	}

	/** The finished search's path (empty before {@link #run()} completes). */
	public List<PathStep> getPath()
	{
		List<PathStep> finalised = finalPath;
		return finalised != null ? finalised : List.of();
	}

	public PathfinderResult getResult()
	{
		PathfinderStats currentStats = getStats();
		if (currentStats == null)
		{
			return null;
		}

		List<PathStep> currentPath = getPath();
		boolean reached = reachedTarget != WorldPointUtil.UNDEFINED;
		int target = reached ? reachedTarget : (targets.isEmpty() ? WorldPointUtil.UNDEFINED : targets.iterator().next());
		// getStats() only returns non-null once the search has ended, so the snapshot is set.
		return new PathfinderResult(
			start,
			target,
			reached,
			currentPath,
			closestReachedPoint,
			finalCost,
			currentStats.getNodesChecked(),
			currentStats.getTransportsChecked(),
			currentStats.getElapsedTimeNanos(),
			terminationReason
		);
	}

	private void addNeighbors(int node, boolean nodeIsTile, int nodePacked)
	{
		PrimitiveIntList nodes = map.getNeighbors(node, visited, config, wildernessLevel, targetInWilderness, graph, tentative);
		final int count = nodes.size();
		for (int i = 0; i < count; i++)
		{
			int neighbor = nodes.get(i);
			// Each graph.xxx(id) re-indexes a backing array, so read each neighbour field once and
			// reuse the loop-invariant node fields passed in (the JIT cached these for free when nodes
			// were objects, but not when they are int ids into structure-of-arrays storage).
			final boolean neighborIsTile = graph.isTile(neighbor);
			if (nodeIsTile && neighborIsTile)
			{
				final int neighborPacked = graph.packedPosition(neighbor);
				if (config.avoidWilderness(nodePacked, neighborPacked, targetInWilderness))
				{
					continue;
				}
				if (config.avoidBlockedRegion(nodePacked, neighborPacked, targetInBlockedRegion))
				{
					continue;
				}
			}

			final boolean neighborIsTransport = graph.isTransport(neighbor);
			// Heap mode: nothing is marked at enqueue (the pop dedups instead — see the run loop)
			// and every node is ordered through the cost-ordered queue — the g-keyed bucket queue
			// for uninformed searches, the (g+h)-keyed heap for A*. Stats are counted at settle
			// (pop) rather than here: enqueues include duplicates, so counting them would make the
			// explored-size numbers incomparable with the FIFO search.
			if (heapMode)
			{
				if (buckets != null)
				{
					buckets.add(neighbor, graph.cost(neighbor));
				}
				else
				{
					pending.add(neighbor);
				}
				continue;
			}
			visited.set(neighbor, graph);
			if (neighborIsTransport)
			{
				pending.add(neighbor);
				++stats.transportsChecked;
			}
			else
			{
				boundary.addLast(neighbor);
				++stats.nodesChecked;
			}
		}
	}

	/**
	 * Pathfinding to an unreachable target is slightly different from normal pathfinding.
	 * Straight-line movement before diagonal movement is no longer prioritized, because the
	 * original target is moved to the closest reachable tile. To avoid having to move the
	 * original target we instead do the following to favour the closest reachable tile:
	 * - 1) Pick the path with the minimum Euclidean distance (no need to use square root though)
	 * - 2) If a tie occurs, pick the path with minimum travelled distance
	 * - 3) If another tie occurs, pick the path with minimum x-coordinate
	 * - 4) If another tie occurs, pick the path with minimum y-coordinate
	 */
	private boolean updateBestPathWhenUnreachable(int node, int packedPosition)
	{
		boolean update = false;

		final int travelledDistance = graph.cost(node);
		for (int target : targetArray)
		{
			int remainingDistance = WorldPointUtil.distanceBetween(target, packedPosition, WorldPointUtil.EUCLIDEAN_SQUARED_DISTANCE_METRIC);
			int x = WorldPointUtil.unpackWorldX(packedPosition);
			int y = WorldPointUtil.unpackWorldY(packedPosition);
			if ((remainingDistance < bestRemainingDistance) ||
				(remainingDistance == bestRemainingDistance && travelledDistance < bestTravelledDistance) ||
				(remainingDistance == bestRemainingDistance && travelledDistance == bestTravelledDistance && x < bestX) ||
				(remainingDistance == bestRemainingDistance && travelledDistance == bestTravelledDistance && x == bestX && y < bestY))
			{
				bestRemainingDistance = remainingDistance;
				bestTravelledDistance = travelledDistance;
				bestX = x;
				bestY = y;
				bestLastNode = node;
				update = true;
			}
		}

		return update;
	}

	/**
	 * Update wilderness level based on the current node position.
	 */
	private void updateWildernessLevel(int packedPosition)
	{
		if (wildernessLevel > 0)
		{
			// These are overlapping boundaries, so if the node isn't in level 30, it's in 0-29
			// likewise, if the node isn't in level 20, it's in 0-19
			if (wildernessLevel > 30 && !WildernessChecker.isInLevel30Wilderness(packedPosition))
			{
				wildernessLevel = 30;
			}
			if (wildernessLevel > 20 && !WildernessChecker.isInLevel20Wilderness(packedPosition))
			{
				wildernessLevel = 20;
			}
			if (wildernessLevel > 0 && !WildernessChecker.isInWilderness(packedPosition))
			{
				wildernessLevel = 0;
			}
		}
	}

	@Override
	public void run()
	{
		stats.start();
		boundary.addFirst(graph.createStart(start));

		long cutoffDurationMillis = config.getCalculationCutoffMillis();
		long cutoffTimeMillis = System.currentTimeMillis() + cutoffDurationMillis;

		while (!boundary.isEmpty() || !pending.isEmpty()
			|| (buckets != null && !buckets.isEmpty()))
		{
			int boundaryHead = boundary.peekFirst();

			int node;
			boolean ordered;
			if (buckets != null)
			{
				// Uninformed heap mode: the boundary only ever holds the start; everything else
				// comes cost-ordered from the bucket queue.
				ordered = boundaryHead == NodeGraph.NO_NODE;
				node = ordered ? buckets.poll() : boundary.pollFirst();
			}
			else
			{
				int pendingHead = pending.peek();
				ordered = pendingHead != NodeGraph.NO_NODE
					&& (boundaryHead == NodeGraph.NO_NODE || graph.cost(pendingHead) < graph.cost(boundaryHead));
				node = ordered ? pending.poll() : boundary.pollFirst();
			}
			if (ordered)
			{
				// In heap mode EVERY node dedups here: nothing is marked at enqueue, and cost
				// ordering (plus a consistent heuristic in A* mode) makes the first dequeue optimal.
				if (heapMode)
				{
					if (visited.get(node, graph))
					{
						continue;
					}
					visited.set(node, graph);
				}
				if (validateSettleOrder && heapMode)
				{
					final int settledKey = graph.orderCost(node);
					if (settledKey < lastSettledOrderCost)
					{
						throw new IllegalStateException("Settle order violated: orderCost " + settledKey
							+ " settled after " + lastSettledOrderCost
							+ " — inadmissible heuristic or polluted ordering key");
					}
					lastSettledOrderCost = settledKey;
				}
				// Heap mode counts distinct settled states (enqueues include duplicates); the FIFO
				// search counts at enqueue, where marking makes every count unique.
				if (heapMode)
				{
					if (graph.isTransport(node))
					{
						++stats.transportsChecked;
					}
					else
					{
						++stats.nodesChecked;
					}
				}
			}
			if (node == NodeGraph.NO_NODE)
			{
				continue;
			}
			// Cost cap, checked against f = g + h (orderCost), not g alone: with an admissible h,
			// g + h > cap proves no completion within the cap exists through this node, so it can be
			// skipped long before its g reaches the ceiling. This is what keeps a capped search that
			// has nothing left to find (the chain's terminal "no further route within the band" probe)
			// from settling every tile the cap's g-ball can reach — with a near-exact heuristic the
			// probe collapses to almost nothing. For uninformed searches h = 0 and this degenerates to
			// the plain g check. The optional dynamic ceiling can tighten the cap mid-search (the walk
			// search drops it once the chain finds a cheaper route).
			int effectiveCap = costCap;
			if (dynamicCostCap != null)
			{
				int dynamic = dynamicCostCap.getAsInt();
				if (dynamic < effectiveCap)
				{
					effectiveCap = dynamic;
				}
			}
			if (effectiveCap != Integer.MAX_VALUE && graph.orderCost(node) > effectiveCap)
			{
				continue;
			}
			// Read the node's tile-ness and position once; every graph.xxx(id) re-indexes a backing
			// array, and these are used by several of the checks below.
			final boolean nodeIsTile = graph.isTile(node);
			final int nodePacked = nodeIsTile ? graph.packedPosition(node) : WorldPointUtil.UNDEFINED;
			if (nodeIsTile)
			{
				updateWildernessLevel(nodePacked);

				if (targets.contains(nodePacked))
				{
					bestLastNode = node;
					reachedTarget = nodePacked;
					terminationReason = PathTerminationReason.TARGET_REACHED;
					break;
				}

				// Sampled: this is O(targets) per call — with a big target set ("nearest bank" has
				// ~150) running it on every tile dominated the whole search. Every 16th tile is
				// enough to keep extending the cutoff and to grow the progressively rendered
				// partial path; the exact closest tile is recovered in the post-pass below.
				if ((++unreachableTrackCounter & (UNREACHABLE_TRACK_INTERVAL - 1)) == 0
					&& updateBestPathWhenUnreachable(node, nodePacked))
				{
					cutoffTimeMillis = System.currentTimeMillis() + cutoffDurationMillis;
				}
			}

			if (System.currentTimeMillis() > cutoffTimeMillis)
			{
				terminationReason = PathTerminationReason.CUTOFF_REACHED;
				break;
			}

			addNeighbors(node, nodeIsTile, nodePacked);
		}

		if (terminationReason == null)
		{
			terminationReason = PathTerminationReason.SEARCH_EXHAUSTED;
		}

		// The search ended without reaching a target: recover the exact closest tile (same
		// tie-breaking as the sampled in-loop tracking) in one pass over the explored nodes —
		// paying O(nodes × targets) once, instead of on every expansion.
		if (reachedTarget == WorldPointUtil.UNDEFINED && targetArray.length > 0)
		{
			for (int id = 0; id < graph.size(); id++)
			{
				if (graph.isTile(id))
				{
					updateBestPathWhenUnreachable(id, graph.packedPosition(id));
				}
			}
		}

		// Materialise the final path and closest reached tile, then release the large node graph.
		int lastNode = bestLastNode;
		if (lastNode != NodeGraph.NO_NODE)
		{
			finalPath = graph.getPathSteps(lastNode);
			closestReachedPoint = graph.getClosestTilePosition(lastNode);
			finalCost = graph.cost(lastNode);
		}
		else
		{
			finalPath = List.of();
			closestReachedPoint = start;
			finalCost = 0;
		}

		boundary.clear();
		visited.clear();
		pending.clear();
		if (buckets != null)
		{
			buckets.clear();
		}
		if (tentative != null)
		{
			tentative.clear();
		}
		graph.release();

		stats.end(); // Include cleanup in stats to get the total cost of pathfinding
	}

	public static class PathfinderStats
	{
		@Getter
		private int nodesChecked = 0, transportsChecked = 0;
		private long startNanos, endNanos;
		private volatile boolean started = false, ended = false;

		public int getTotalNodesChecked()
		{
			return nodesChecked + transportsChecked;
		}

		public long getElapsedTimeNanos()
		{
			return endNanos - startNanos;
		}

		private void start()
		{
			started = true;
			nodesChecked = 0;
			transportsChecked = 0;
			startNanos = System.nanoTime();
		}

		private void end()
		{
			endNanos = System.nanoTime();
			ended = true;
		}
	}
}

package gps.pathfinder;

import lombok.Getter;

@Getter
public final class PathStep
{
	private final int packedPosition;
	private final boolean bankVisited;

	public PathStep(int packedPosition, boolean bankVisited)
	{
		this.packedPosition = packedPosition;
		this.bankVisited = bankVisited;
	}
}

package gps.pathfinder;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import gps.WorldPointUtil;

/**
 * Structure-of-Arrays store for pathfinding nodes.
 * <p>
 * The previous design allocated one {@link Object} per explored tile (a {@code Node} or
 * {@code TransportNode}). Heavy searches explore hundreds of thousands of tiles, so this produced
 * hundreds of thousands of live objects, each carrying a ~16-byte header plus several object
 * references (issue #491). Here every node is instead an {@code int} index into parallel primitive
 * arrays, so a whole search holds only a handful of arrays regardless of how many nodes it visits.
 * <p>
 * The fields packed per node are: packed world position, the index of the previous node
 * ({@link #NO_NODE} for the start), accumulated cost, a set of boolean flags, and the
 * {@link AbstractNodeKind} ordinal for abstract nodes. The priority-queue ordering key is
 * EXACTLY the accumulated cost plus (in A* mode) a consistent heuristic — never anything else:
 * any ordering-only term breaks the first-settle-is-optimal invariant the searches rely on.
 * <p>
 * <strong>Threading.</strong> The search runs on a single worker thread, but the render thread
 * reads the partial path while the search is still running (progressive rendering via
 * {@code Pathfinder.getPath()}). Node data is write-once and is published to the render thread by
 * the single volatile {@code Pathfinder.bestLastNode} handoff rather than by marking these arrays
 * {@code volatile} (which would cripple the hot loop, see the field comment). The chain walks
 * ({@link #getPathSteps} / {@link #getClosestTilePosition}) snapshot the arrays into locals and
 * tolerate an index that is out of bounds or released. This means a walk concurrent with a
 * grow/release can never throw; at worst it yields a one-frame-stale path.
 */
public class NodeGraph
{
	public static final int NO_NODE = -1;

	private static final byte FLAG_BANK_VISITED = 1;       // bit0
	private static final byte FLAG_ABSTRACT = 1 << 1;      // bit1
	private static final byte FLAG_TRANSPORT = 1 << 3;     // bit3

	// Enum.values() copies on every call, so cache it for the abstractKind lookup.
	private static final AbstractNodeKind[] ABSTRACT_KINDS = AbstractNodeKind.values();

	// The node arrays are NOT volatile: making them volatile forces every accessor (packedPosition,
	// cost, isTile, orderCost, the append() writes, ...) to re-read the array reference on each
	// call and blocks the JIT from caching the base in a register or eliminating bounds checks. The
	// hot loop touches these hundreds of times per node, so volatile reads roughly halved field
	// throughput (~1.6x slower searches). Safe publication to the render thread is provided instead
	// by the single volatile Pathfinder.bestLastNode handoff: the worker writes the node data, then
	// volatile-writes bestLastNode; the render thread volatile-reads bestLastNode before walking,
	// which establishes happens-before for all the plain writes above it. The walk methods snapshot
	// the references into locals and tolerate a null (post-release) or stale-but-valid (mid-grow,
	// Arrays.copyOf preserves every index) array, so a concurrent grow/release never throws.
	private int[] packedPosition;
	private int[] previous;
	private int[] cost;
	// The priority-queue ordering key, precomputed at append time: the accumulated cost plus —
	// when a heuristic is attached (A* mode) — the node's heuristic value. With no heuristic it
	// equals the cost exactly, so Dijkstra-mode ordering is pure g.
	private int[] orderCost;
	private byte[] flags;
	private byte[] abstractKind;
	private int size;
	// Optional A* heuristic; null = uninformed (Dijkstra) ordering.
	private final SearchHeuristic heuristic;

	public NodeGraph(int initialCapacity)
	{
		this(initialCapacity, null);
	}

	public NodeGraph(int initialCapacity, SearchHeuristic heuristic)
	{
		final int capacity = Math.max(1, initialCapacity);
		packedPosition = new int[capacity];
		previous = new int[capacity];
		cost = new int[capacity];
		orderCost = new int[capacity];
		flags = new byte[capacity];
		abstractKind = new byte[capacity];
		this.heuristic = heuristic;
	}

	public int size()
	{
		return size;
	}

	private void ensureCapacity()
	{
		if (size < packedPosition.length)
		{
			return;
		}
		// Grow by 50% like ArrayList. Arrays.copyOf preserves every existing index, and node data
		// is write-once, so a render thread reading a pre-grow array still sees correct values for
		// the indices it walks.
		final int newCapacity = packedPosition.length + (packedPosition.length >> 1);
		packedPosition = Arrays.copyOf(packedPosition, newCapacity);
		previous = Arrays.copyOf(previous, newCapacity);
		cost = Arrays.copyOf(cost, newCapacity);
		orderCost = Arrays.copyOf(orderCost, newCapacity);
		flags = Arrays.copyOf(flags, newCapacity);
		abstractKind = Arrays.copyOf(abstractKind, newCapacity);
	}

	private int append(int packed, int prev, int nodeCost, byte flagBits, byte kind)
	{
		ensureCapacity();
		final int id = size;
		packedPosition[id] = packed;
		previous[id] = prev;
		cost[id] = nodeCost;
		orderCost[id] = nodeCost + (heuristic == null ? 0 : heuristic.of(packed));
		abstractKind[id] = kind;
		flags[id] = flagBits;
		size = id + 1;
		return id;
	}

	private int costOf(int id)
	{
		return id == NO_NODE ? 0 : cost[id];
	}

	/**
	 * The search root. Carries no previous node and zero cost.
	 */
	public int createStart(int packedPosition)
	{
		return append(packedPosition, NO_NODE, 0, (byte) 0, (byte) 0);
	}

	/**
	 * A concrete walkable tile. Travel cost is the walking distance from the previous node, but
	 * only when the previous node is itself a tile (mirrors the old {@code Node.cost}); reaching a
	 * tile from an abstract node adds no travel cost. {@code extraCost} is a one-off surcharge on this
	 * edge (used to charge the bank-pickup penalty on the step that first enters the banked state).
	 * The edge is clamped at free: configured weights may be negative (favoring), but a negative-cost
	 * edge would break the search's Dijkstra invariant.
	 */
	public int createTile(int packedPosition, int previous, boolean bankVisited, int extraCost)
	{
		final int travelTime = (previous != NO_NODE && isTile(previous))
			? WorldPointUtil.distanceBetween(this.packedPosition[previous], packedPosition)
			: 0;
		final byte flagBits = bankVisited ? FLAG_BANK_VISITED : 0;
		return append(packedPosition, previous, costOf(previous) + Math.max(0, travelTime + extraCost),
			flagBits, (byte) 0);
	}

	/**
	 * A transport destination tile. Cost is the previous cost plus the transport's travel time (in
	 * {@link CostUnits}) and any additional configured cost; there is no walking-distance term
	 * (mirrors the old {@code TransportNode}). The edge is clamped at free: a negative configured
	 * weight can make a transport free but never cheaper than free (Dijkstra needs non-negative edges).
	 */
	public int createTransport(int packedPosition, int previous, int travelTime, int additionalCost,
		boolean bankVisited)
	{
		byte flagBits = FLAG_TRANSPORT;
		if (bankVisited)
		{
			flagBits |= FLAG_BANK_VISITED;
		}
		return append(packedPosition, previous, costOf(previous) + Math.max(0, travelTime + additionalCost),
			flagBits, (byte) 0);
	}

	/**
	 * An abstract search-state node (global teleports). Has no world position and inherits the
	 * previous node's cost (mirrors the old {@code Node.abstractNode}). {@code extraCost} is a one-off
	 * surcharge (the bank-pickup penalty when this abstract state is first entered via a bank tile), so
	 * global teleports expanded from it inherit the penalty. Clamped at free like every other edge.
	 */
	public int createAbstract(AbstractNodeKind abstractKind, int previous, boolean bankVisited, int extraCost)
	{
		byte flagBits = FLAG_ABSTRACT;
		if (bankVisited)
		{
			flagBits |= FLAG_BANK_VISITED;
		}
		return append(WorldPointUtil.UNDEFINED, previous, costOf(previous) + Math.max(0, extraCost), flagBits,
			(byte) abstractKind.ordinal());
	}

	public int packedPosition(int id)
	{
		return packedPosition[id];
	}

	public int previous(int id)
	{
		return previous[id];
	}

	public int cost(int id)
	{
		return cost[id];
	}

	/**
	 * The precomputed priority-queue key: the accumulated cost plus the A* heuristic value when
	 * one is attached (equal to {@link #cost} otherwise).
	 */
	public int orderCost(int id)
	{
		return orderCost[id];
	}

	public boolean bankVisited(int id)
	{
		return (flags[id] & FLAG_BANK_VISITED) != 0;
	}

	public boolean isTile(int id)
	{
		return (flags[id] & FLAG_ABSTRACT) == 0;
	}

	public boolean isAbstract(int id)
	{
		return (flags[id] & FLAG_ABSTRACT) != 0;
	}

	public boolean isTransport(int id)
	{
		return (flags[id] & FLAG_TRANSPORT) != 0;
	}


	public AbstractNodeKind abstractKind(int id)
	{
		return ABSTRACT_KINDS[abstractKind[id]];
	}

	/**
	 * Walks the previous chain from {@code id} to the start, collecting the tile nodes (abstract
	 * nodes are skipped) into an ordered list of path steps.
	 * <p>
	 * Safe to call from the render thread during the search: the arrays are snapshotted into locals
	 * and the walk is bounds-tolerant, so a concurrent grow or {@link #release()} yields an empty
	 * or one-frame-stale result rather than throwing.
	 */
	public List<PathStep> getPathSteps(int id)
	{
		final int[] prev = previous;
		final int[] packed = packedPosition;
		final byte[] flg = flags;
		if (prev == null || packed == null || flg == null || id == NO_NODE)
		{
			return new ArrayList<>();
		}
		final int len = prev.length;

		int node = id;
		int n = 0;
		while (node != NO_NODE && node < len)
		{
			if ((flg[node] & FLAG_ABSTRACT) == 0)
			{
				n++;
			}
			node = prev[node];
		}

		final List<PathStep> pathSteps = new ArrayList<>(n);
		for (int i = 0; i < n; i++)
		{
			pathSteps.add(null);
		}

		node = id;
		int i = n;
		while (node != NO_NODE && node < len && i > 0)
		{
			if ((flg[node] & FLAG_ABSTRACT) == 0)
			{
				pathSteps.set(--i, new PathStep(packed[node], (flg[node] & FLAG_BANK_VISITED) != 0));
			}
			node = prev[node];
		}

		return pathSteps;
	}

	/**
	 * Walks the previous chain from {@code id} until the first tile node and returns its packed
	 * position, or {@link WorldPointUtil#UNDEFINED} if none. Same threading guarantees as
	 * {@link #getPathSteps}.
	 */
	public int getClosestTilePosition(int id)
	{
		final int[] prev = previous;
		final int[] packed = packedPosition;
		final byte[] flg = flags;
		if (prev == null || packed == null || flg == null)
		{
			return WorldPointUtil.UNDEFINED;
		}
		final int len = prev.length;
		int node = id;
		while (node != NO_NODE && node < len && (flg[node] & FLAG_ABSTRACT) != 0)
		{
			node = prev[node];
		}
		return (node != NO_NODE && node < len) ? packed[node] : WorldPointUtil.UNDEFINED;
	}

	/**
	 * Releases the backing arrays once the search is finished and the final path has been
	 * materialised, so the large per-search working set becomes eligible for garbage collection
	 * (the old design dropped the explored {@code Node} objects the same way by clearing the
	 * frontier collections). A render-thread walk in flight keeps its own local references and
	 * finishes safely.
	 */
	public void release()
	{
		packedPosition = null;
		previous = null;
		cost = null;
		orderCost = null;
		flags = null;
		abstractKind = null;
		size = 0;
	}
}

package gps.pathfinder;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import gps.PrimitiveIntHashMap;
import gps.WorldPointUtil;
import gps.transport.Transport;

public final class TransportAvailability
{
	public static final Transport[] EMPTY_TRANSPORTS = new Transport[0];

	// Transports grouped by origin tile, stored as flat arrays. The per-origin HashSet/HashMap
	// wrappers used while building are not retained (issue #491).
	//
	// transportsPacked is the pathfinding view: a transport is reachable from its literal origin
	// tile, and POH transports are additionally reachable from the canonical landing tile.
	// displayTransports is the coarse display view used by overlays and getTransports(): POH origin
	// tiles are collapsed into the landing tile only. The two maps share their Transport[] arrays
	// for every non-POH origin.
	private final PrimitiveIntHashMap<Transport[]> transportsPacked;
	private final PrimitiveIntHashMap<Transport[]> displayTransports;
	private final Transport[] usableTeleports;

	TransportAvailability(
		PrimitiveIntHashMap<Transport[]> transportsPacked,
		PrimitiveIntHashMap<Transport[]> displayTransports,
		Transport[] usableTeleports)
	{
		this.transportsPacked = transportsPacked;
		this.displayTransports = displayTransports;
		this.usableTeleports = usableTeleports;
	}

	public PrimitiveIntHashMap<Transport[]> getTransportsPacked()
	{
		return transportsPacked;
	}

	public PrimitiveIntHashMap<Transport[]> getDisplayTransports()
	{
		return displayTransports;
	}

	public Transport[] getUsableTeleports()
	{
		return usableTeleports;
	}

	/**
	 * The transports that start at the given origin tile in the display view, or an empty array.
	 */
	public Transport[] getTransportsAt(int origin)
	{
		return displayTransports.getOrDefault(origin, EMPTY_TRANSPORTS);
	}

	/*
	 * Build a TransportAvailability by incrementally adding available transports.
	 */
	static final class Builder
	{
		// Temporary accumulation; converted to flat arrays in build() and not retained afterwards.
		// Primitive-keyed by origin tile: rebuildAvailabilityWithExclusions runs this per search, and a
		// Map<Integer, ...> boxed the int origin on every transport added. Each origin holds no
		// duplicate transports (every transport is added at most once), so a List is enough — no Set.
		private final PrimitiveIntHashMap<List<Transport>> transportsByOrigin;
		private final List<Transport> usableTeleports;
		private final Set<Integer> pohOrigins = new HashSet<>();

		Builder(int expectedTransportCount)
		{
			this.transportsByOrigin = new PrimitiveIntHashMap<>(Math.max(8, expectedTransportCount / 2));
			this.usableTeleports = new ArrayList<>(Math.max(8, expectedTransportCount / 20));
		}

		void add(Transport transport)
		{
			if (transport.getOrigin() == WorldPointUtil.UNDEFINED)
			{
				usableTeleports.add(transport);
				return;
			}

			List<Transport> atOrigin = transportsByOrigin.get(transport.getOrigin());
			if (atOrigin == null)
			{
				atOrigin = new ArrayList<>(2);
				transportsByOrigin.put(transport.getOrigin(), atOrigin);
			}
			atOrigin.add(transport);
		}

		void remapPohTransports()
		{
			int pohLanding = WorldPointUtil.packWorldPoint(1923, 5709, 0);
			List<Transport> pohTransports = new ArrayList<>();

			for (int origin : transportsByOrigin.keys())
			{
				int originX = WorldPointUtil.unpackWorldX(origin);
				int originY = WorldPointUtil.unpackWorldY(origin);
				if (gps.ShortestPathPlugin.isInsidePoh(originX, originY))
				{
					pohTransports.addAll(transportsByOrigin.get(origin));
					// Kept in the pathfinding view, collapsed out of the display view.
					pohOrigins.add(origin);
				}
			}

			if (!pohTransports.isEmpty())
			{
				List<Transport> landing = transportsByOrigin.get(pohLanding);
				if (landing == null)
				{
					landing = new ArrayList<>(pohTransports.size());
					transportsByOrigin.put(pohLanding, landing);
				}
				landing.addAll(pohTransports);
			}
		}

		TransportAvailability build()
		{
			int expected = Math.max(1, transportsByOrigin.size());
			PrimitiveIntHashMap<Transport[]> packed = new PrimitiveIntHashMap<>(expected);
			PrimitiveIntHashMap<Transport[]> display = new PrimitiveIntHashMap<>(expected);
			for (int origin : transportsByOrigin.keys())
			{
				Transport[] transports = transportsByOrigin.get(origin).toArray(EMPTY_TRANSPORTS);
				packed.put(origin, transports);
				if (!pohOrigins.contains(origin))
				{
					display.put(origin, transports);
				}
			}
			return new TransportAvailability(packed, display, usableTeleports.toArray(EMPTY_TRANSPORTS));
		}
	}
}

