package gps.pathfinder;

import java.util.Set;

import net.runelite.api.coords.WorldArea;
import gps.WorldPointUtil;

public class WildernessChecker
{

	private static final WorldArea WILDERNESS_ABOVE_GROUND = new WorldArea(2944, 3525, 448, 448, 0);
	private static final WorldArea WILDERNESS_UNDERGROUND = new WorldArea(2944, 9918, 518, 458, 0);

	private static final WorldArea FEROX_ENCLAVE_1 = new WorldArea(3123, 3622, 2, 10, 0);
	private static final WorldArea FEROX_ENCLAVE_2 = new WorldArea(3125, 3617, 16, 23, 0);
	private static final WorldArea FEROX_ENCLAVE_3 = new WorldArea(3138, 3636, 18, 10, 0);
	private static final WorldArea FEROX_ENCLAVE_4 = new WorldArea(3141, 3625, 14, 11, 0);
	private static final WorldArea FEROX_ENCLAVE_5 = new WorldArea(3141, 3619, 7, 6, 0);

	private static final WorldArea NOT_WILDERNESS_1 = new WorldArea(2997, 3525, 34, 9, 0);
	private static final WorldArea NOT_WILDERNESS_2 = new WorldArea(3005, 3534, 21, 10, 0);
	private static final WorldArea NOT_WILDERNESS_3 = new WorldArea(3000, 3534, 5, 5, 0);
	private static final WorldArea NOT_WILDERNESS_4 = new WorldArea(3031, 3525, 2, 2, 0);

	private static final WorldArea WILDERNESS_ABOVE_GROUND_LEVEL_20 = new WorldArea(2944, 3680, 448, 448, 0);
	private static final WorldArea WILDERNESS_ABOVE_GROUND_LEVEL_30 = new WorldArea(2944, 3760, 448, 448, 0);
	private static final WorldArea WILDERNESS_UNDERGROUND_LEVEL_20 = new WorldArea(2944, 10075, 518, 301, 0);
	private static final WorldArea WILDERNESS_UNDERGROUND_LEVEL_30 = new WorldArea(2944, 10155, 518, 221, 0);

	public static boolean isInWilderness(int packedPoint)
	{
		return WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_ABOVE_GROUND) == 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, FEROX_ENCLAVE_1) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, FEROX_ENCLAVE_2) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, FEROX_ENCLAVE_3) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, FEROX_ENCLAVE_4) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, FEROX_ENCLAVE_5) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, NOT_WILDERNESS_1) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, NOT_WILDERNESS_2) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, NOT_WILDERNESS_3) != 0
			&& WorldPointUtil.distanceToArea2D(packedPoint, NOT_WILDERNESS_4) != 0
			|| WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_UNDERGROUND) == 0;
	}

	public static boolean isInWilderness(Set<Integer> packedPoints)
	{
		for (int packedPoint : packedPoints)
		{
			if (isInWilderness(packedPoint))
			{
				return true;
			}
		}
		return false;
	}

	public static boolean isInLevel20Wilderness(int packedPoint)
	{
		return WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_ABOVE_GROUND_LEVEL_20) == 0
			|| WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_UNDERGROUND_LEVEL_20) == 0;
	}

	public static boolean isInLevel30Wilderness(int packedPoint)
	{
		return WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_ABOVE_GROUND_LEVEL_30) == 0
			|| WorldPointUtil.distanceToArea2D(packedPoint, WILDERNESS_UNDERGROUND_LEVEL_30) == 0;
	}
}

package gps.pathfinder;

public enum AbstractNodeKind
{
	// These four abstract teleport states mirror the wilderness buckets that change
	// which teleports are legal.
	GLOBAL_TELEPORTS_OVER_30,
	GLOBAL_TELEPORTS_OVER_20,
	GLOBAL_TELEPORTS_OVER_0,
	GLOBAL_TELEPORTS_NORMAL;

	public static AbstractNodeKind fromWildernessLevel(int wildernessLevel)
	{
		if (wildernessLevel > 30)
		{
			return GLOBAL_TELEPORTS_OVER_30;
		}
		if (wildernessLevel > 20)
		{
			return GLOBAL_TELEPORTS_OVER_20;
		}
		if (wildernessLevel > 0)
		{
			return GLOBAL_TELEPORTS_OVER_0;
		}
		return GLOBAL_TELEPORTS_NORMAL;
	}

	public int maxWildernessLevel()
	{
		switch (this)
		{
			case GLOBAL_TELEPORTS_OVER_30:
				return 31;
			case GLOBAL_TELEPORTS_OVER_20:
				return 30;
			case GLOBAL_TELEPORTS_OVER_0:
				return 20;
			case GLOBAL_TELEPORTS_NORMAL:
			default:
				return 0;
		}
	}
}

package gps.pathfinder;

/**
 * The pathfinder's cost currency, normalized to real time: one unit is the time a RUNNING player
 * takes to cover one tile — half a game tick (0.3 seconds). A walking edge costs its tile distance
 * (unchanged), and a transport's travel time in game ticks converts at {@link #UNITS_PER_TICK}
 * units per tick, so both kinds of edge are priced in the same wall-clock currency.
 * <p>
 * With no configured weights a path's cost IS its ETA ({@code units × 0.3s}), so routes ordered by
 * cost are ordered by estimated time. The per-method config weights are preference modifiers in
 * this same currency — positive disfavors a method, negative favors it — never a different unit,
 * which is what keeps the ordering consistent with the displayed ETAs.
 */
public final class CostUnits
{
	/** Cost units per game tick: one tick of transport travel time = two run-tiles of walking. */
	public static final int UNITS_PER_TICK = 2;
	/** Wall-clock seconds per cost unit (a 0.6s game tick covers 2 run-tiles). */
	public static final double SECONDS_PER_UNIT = 0.3;

	/** Converts a duration in game ticks to cost units. */
	public static int fromTicks(int ticks)
	{
		return UNITS_PER_TICK * ticks;
	}

	private CostUnits()
	{
	}
}

package gps.pathfinder;

import gps.WorldPointUtil;
import gps.transport.Transport;

/**
 * A consistent (and therefore admissible) A* heuristic for one search: a lower bound on the
 * remaining cost from any node to the target set, so the search prefers nodes heading toward the
 * target instead of flooding a Dijkstra disc in every direction. Guarantees identical costs to the
 * uninformed search — only the exploration order (and size) changes.
 * <p>
 * Backed by a per-generation {@link DistanceField} (one multi-source reverse flood from the target
 * set over walking edges and reversed origin-bound transports): {@code h(n) = min(field(n), floor)}
 * where {@code floor} is the cheapest jump this search's own usable origin-less teleports offer —
 * {@code max(0, duration + configured weight) + field(landing)}. The floor is what keeps global
 * teleports from breaking admissibility (a node 2000 tiles away is 8 units from the target if a
 * teleport lands there), and computing it per search from the search's post-exclusion availability
 * makes the heuristic STRONGER exactly when searches get expensive: excluding the good teleports
 * raises the floor.
 * <p>
 * Consistency argument (h(a) &le; edge(a,b) + h(b) for every edge kind): walking and origin-bound
 * transport edges satisfy the field's own shortest-path triangle inequality (their reversed edges
 * are inside the flood); a global-teleport edge from the abstract hub to a landing satisfies
 * {@code floor <= effCost + field(landing)} by the floor's definition; abstract hub nodes take
 * {@code h = floor}, which every tile's h is already &le;. Unflooded (reverse-unreachable) tiles
 * also take the floor — reaching a target from them requires a global teleport, which is exactly
 * what the floor bounds. Consistent h means the first settle of a state is optimal — the engine
 * needs no reopening. There is no weak regime to gate against: a flat field-heuristic implies a
 * genuinely cheap route, and therefore a small search anyway.
 */
public final class SearchHeuristic
{
	/**
	 * Widest target-set span the distance field is built for: a map-wide "nearest X" set would
	 * flood everything for searches that are already cheap, and h ~ 0 everywhere regardless.
	 */
	static final int MAX_TARGET_SPAN = 256;
	// The floor with no usable teleport at all (e.g. the walk-only search). Kept far below
	// Integer.MAX_VALUE so orderCost = cost + h can never overflow.
	static final int UNBOUNDED_FLOOR = 1 << 20;

	private final DistanceField field;
	private final int floor;
	// The field's flood horizon: a strict lower bound on any unflooded tile's distance. For a
	// full-map flood this is MAX_VALUE and unflooded tiles clamp to the floor exactly as before;
	// for a bounded flood, min(horizon, floor) stays admissible because the tile's true remaining
	// provably exceeds the horizon.
	private final int horizon;

	private SearchHeuristic(DistanceField field, int floor, int horizon)
	{
		this.field = field;
		this.floor = floor;
		this.horizon = horizon;
	}

	/**
	 * The heuristic value for a node position; {@link WorldPointUtil#UNDEFINED} (abstract
	 * global-teleport hub nodes) gets the floor, unflooded tiles min(horizon, floor).
	 */
	public int of(int packedPosition)
	{
		if (packedPosition == WorldPointUtil.UNDEFINED)
		{
			return floor;
		}
		final int distance = field.distance(packedPosition);
		if (distance == DistanceField.UNREACHED)
		{
			return Math.min(horizon, floor);
		}
		return distance >= floor ? floor : distance;
	}

	int floor()
	{
		return floor;
	}

	/**
	 * Builds the heuristic for one search over the given config's CURRENT (post-exclusion)
	 * availability, or null when there is no field (map-wide target sets — the caller falls back
	 * to the uninformed search).
	 */
	/**
	 * Like {@link #buildWithField(PathfinderConfig, DistanceField)}, but degeneracy-checked for
	 * the search's start: when the reverse flood ran to exhaustion (full-flood horizon) without
	 * reaching the start AND no usable teleport lands inside the flooded pocket (unbounded
	 * floor), h is effectively infinite everywhere the search can go — a finite-capped search
	 * then prunes its own start at the gate and finds nothing, collapsing the alternatives chain
	 * to a single route (user capture: locked in a sealed quest cell, one escape teleport shown
	 * instead of the menu). The target is unreachable either way, so closest-point routing wants
	 * an UNINFORMED search: return null.
	 */
	public static SearchHeuristic buildWithField(PathfinderConfig config, DistanceField field, int searchStart)
	{
		SearchHeuristic heuristic = buildWithField(config, field);
		if (heuristic != null
			&& heuristic.horizon == Integer.MAX_VALUE
			&& heuristic.floor >= UNBOUNDED_FLOOR
			&& field.distance(searchStart) == DistanceField.UNREACHED)
		{
			return null;
		}
		return heuristic;
	}

	public static SearchHeuristic buildWithField(PathfinderConfig config, DistanceField field)
	{
		if (field == null)
		{
			return null;
		}
		final int horizon = field.horizon();
		int floor = UNBOUNDED_FLOOR;
		// Both bank states: a path may flip into the banked state mid-search, so the floor must
		// cover every teleport either state can use (a superset only lowers the floor = safe).
		for (boolean bankVisited : new boolean[]{false, true})
		{
			for (Transport teleport : config.getUsableTeleports(bankVisited))
			{
				final int destination = teleport.getDestination();
				if (destination == WorldPointUtil.UNDEFINED)
				{
					continue;
				}
				int landingDistance = field.distance(destination);
				if (landingDistance == DistanceField.UNREACHED)
				{
					if (horizon == Integer.MAX_VALUE)
					{
						// Full flood: unflooded = genuinely reverse-unreachable, contributes nothing.
						continue;
					}
					// Bounded flood: the landing lies beyond the horizon, which lower-bounds its
					// distance. Skipping it instead would OVERESTIMATE the floor (inadmissible) when
					// the truly-cheapest teleport happens to land just past the horizon.
					landingDistance = horizon;
				}
				final int effectiveCost = Math.max(0,
					CostUnits.fromTicks(teleport.getDuration()) + config.getAdditionalTransportCost(teleport));
				floor = (int) Math.min(floor, (long) effectiveCost + landingDistance);
			}
		}
		return new SearchHeuristic(field, floor, horizon);
	}
}

package gps.pathfinder;

import java.util.ArrayList;

/**
 * A monotone priority queue of {@code int} node ids keyed by small non-negative integer costs —
 * Dial's algorithm: one FIFO bucket per cost value, popped in cost order by a forward-only cursor.
 * Push and pop are O(1), which is what lets the uninformed (no-heuristic) searches keep their old
 * FIFO-era speed after moving to cost-ordered settling: a binary heap pays log n per operation on
 * exactly the searches that explore the most nodes (map-wide "nearest X" floods).
 * <p>
 * Correct for Dijkstra because pops are monotone: every inserted key is {@code >=} the key being
 * expanded (non-negative edges), so the cursor never needs to move backwards. FIFO order within a
 * bucket preserves the creation-order tie-break the searches always had. Single-threaded (worker
 * only), like the heap it complements.
 */
class IntBucketQueue
{
	private final ArrayList<IntDeque> buckets = new ArrayList<>();
	// The lowest bucket that can still hold anything; only ever moves forward (monotone inserts).
	private int cursor;
	private int size;

	int size()
	{
		return size;
	}

	boolean isEmpty()
	{
		return size == 0;
	}

	void add(int id, int key)
	{
		if (key < cursor)
		{
			// Monotonicity safety net: never true with non-negative edges, but a backwards insert
			// must not be silently skipped by the cursor.
			cursor = key;
		}
		while (buckets.size() <= key)
		{
			buckets.add(null);
		}
		IntDeque bucket = buckets.get(key);
		if (bucket == null)
		{
			bucket = new IntDeque(16);
			buckets.set(key, bucket);
		}
		bucket.addLast(id);
		size++;
	}

	/**
	 * @return the minimum-key element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	int poll()
	{
		if (size == 0)
		{
			return NodeGraph.NO_NODE;
		}
		while (cursor < buckets.size())
		{
			IntDeque bucket = buckets.get(cursor);
			if (bucket != null && !bucket.isEmpty())
			{
				size--;
				return bucket.pollFirst();
			}
			cursor++;
		}
		size = 0;
		return NodeGraph.NO_NODE;
	}

	void clear()
	{
		buckets.clear();
		cursor = 0;
		size = 0;
	}
}

package gps.pathfinder;

import java.util.Arrays;

/**
 * A binary min-heap of primitive {@code int} node ids ordered by {@link NodeGraph#orderCost} (the
 * accumulated cost, plus the heuristic in A* mode).
 * <p>
 * Replaces the {@code PriorityQueue<TransportNode>} pending queue in {@link Pathfinder} so transport
 * candidates are stored as int ids rather than boxed node objects. The ordering key is fixed when a
 * node is created, so no decrease-key support is needed; the pathfinder discards stale costlier
 * duplicates with its dequeue-time visited re-check. Single-threaded (worker only), matching the
 * queue it replaces.
 */
class IntMinHeap
{
	private final NodeGraph graph;
	private int[] heap;
	private int size;

	IntMinHeap(NodeGraph graph, int initialCapacity)
	{
		this.graph = graph;
		this.heap = new int[Math.max(1, initialCapacity)];
	}

	boolean isEmpty()
	{
		return size == 0;
	}

	/**
	 * @return the minimum-cost element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	int peek()
	{
		return size == 0 ? NodeGraph.NO_NODE : heap[0];
	}

	void add(int id)
	{
		if (size == heap.length)
		{
			heap = Arrays.copyOf(heap, heap.length << 1);
		}
		heap[size] = id;
		siftUp(size);
		size++;
	}

	/**
	 * @return the removed minimum-cost element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	int poll()
	{
		if (size == 0)
		{
			return NodeGraph.NO_NODE;
		}
		final int top = heap[0];
		size--;
		if (size > 0)
		{
			heap[0] = heap[size];
			siftDown(0);
		}
		return top;
	}

	void clear()
	{
		size = 0;
	}

	/**
	 * Ordering: orderCost (f = g + h) first, then HIGHER g, then node id (creation order).
	 * <p>
	 * The g tie-break is what keeps a near-exact heuristic from flooding its own plateau: every
	 * tile on any optimal corridor shares the same f, so f-only ordering explores that whole
	 * plateau breadth-first — for a long walk that is the entire diamond of equal-cost grid paths
	 * (hundreds of thousands of tiles) — before the target can pop. Preferring the higher g among
	 * equal f always advances the deepest node (the one closest to the goal), so the search dives
	 * down one corridor and reaches the target having settled little beside it. Any tie-break
	 * among equal f is optimality-neutral under a consistent heuristic.
	 * <p>
	 * The final id (creation order) tie-break keeps the claims of same-f same-g tiles mirroring
	 * the FIFO search's (cardinals are generated first), which produces the long straight runs
	 * that match the game's own click-walk movement, and makes searches fully deterministic.
	 */
	private boolean less(int a, int b)
	{
		final int costA = graph.orderCost(a);
		final int costB = graph.orderCost(b);
		if (costA != costB)
		{
			return costA < costB;
		}
		final int gA = graph.cost(a);
		final int gB = graph.cost(b);
		if (gA != gB)
		{
			return gA > gB;
		}
		return a < b;
	}

	private void siftUp(int index)
	{
		final int id = heap[index];
		while (index > 0)
		{
			final int parent = (index - 1) >> 1;
			if (!less(id, heap[parent]))
			{
				break;
			}
			heap[index] = heap[parent];
			index = parent;
		}
		heap[index] = id;
	}

	private void siftDown(int index)
	{
		final int id = heap[index];
		final int half = size >> 1;
		while (index < half)
		{
			int child = (index << 1) + 1;
			final int right = child + 1;
			if (right < size && less(heap[right], heap[child]))
			{
				child = right;
			}
			if (!less(heap[child], id))
			{
				break;
			}
			heap[index] = heap[child];
			index = child;
		}
		heap[index] = id;
	}
}

package gps.pathfinder;

import static net.runelite.api.Constants.REGION_SIZE;

import gps.WorldPointUtil;

public class VisitedTiles
{
	private final SplitFlagMap.RegionExtent regionExtents;
	private final int widthInclusive;

	private final VisitedRegion[] visitedRegionsWithoutBank;
	private final VisitedRegion[] visitedRegionsWithBank;
	private final CollisionMap map;
	// Abstract nodes are visited separately from tile nodes because they represent
	// global search states, not map positions.
	private final boolean[] abstractVisitedWithoutBank = new boolean[AbstractNodeKind.values().length];
	private final boolean[] abstractVisitedWithBank = new boolean[AbstractNodeKind.values().length];

	public VisitedTiles(CollisionMap map)
	{
		this.map = map;
		regionExtents = SplitFlagMap.getRegionExtents();
		widthInclusive = regionExtents.getWidth() + 1;
		final int heightInclusive = regionExtents.getHeight() + 1;

		visitedRegionsWithoutBank = new VisitedRegion[widthInclusive * heightInclusive];
		visitedRegionsWithBank = new VisitedRegion[widthInclusive * heightInclusive];
	}

	public boolean get(int packedPoint, boolean bankVisited)
	{
		final int x = WorldPointUtil.unpackWorldX(packedPoint);
		final int y = WorldPointUtil.unpackWorldY(packedPoint);
		final int plane = WorldPointUtil.unpackWorldPlane(packedPoint);
		return get(x, y, plane, bankVisited);
	}

	public boolean get(int x, int y, int plane, boolean bankVisited)
	{
		VisitedRegion[] visitedRegions = bankVisited ? visitedRegionsWithBank : visitedRegionsWithoutBank;
		final int regionIndex = getRegionIndex(x / REGION_SIZE, y / REGION_SIZE);
		if (regionIndex < 0 || regionIndex >= visitedRegions.length)
		{
			return true; // Region is out of bounds; report that it's been visited to avoid exploring it
			// further
		}

		final VisitedRegion region = visitedRegions[regionIndex];
		if (region == null)
		{
			return false;
		}

		return region.get(x % REGION_SIZE, y % REGION_SIZE, plane);
	}

	public boolean set(int packedPoint, boolean bankVisited)
	{
		final int x = WorldPointUtil.unpackWorldX(packedPoint);
		final int y = WorldPointUtil.unpackWorldY(packedPoint);
		final int plane = WorldPointUtil.unpackWorldPlane(packedPoint);
		return set(x, y, plane, bankVisited);
	}

	public boolean get(int id, NodeGraph graph)
	{
		if (graph.isTile(id))
		{
			return get(graph.packedPosition(id), graph.bankVisited(id));
		}
		return getAbstract(graph.abstractKind(id), graph.bankVisited(id));
	}

	public boolean getAbstract(AbstractNodeKind abstractKind, boolean bankVisited)
	{
		return bankVisited
			? abstractVisitedWithBank[abstractKind.ordinal()]
			: abstractVisitedWithoutBank[abstractKind.ordinal()];
	}

	public boolean set(int id, NodeGraph graph)
	{
		if (graph.isTile(id))
		{
			return set(graph.packedPosition(id), graph.bankVisited(id));
		}

		final AbstractNodeKind abstractKind = graph.abstractKind(id);
		boolean visited = getAbstract(abstractKind, graph.bankVisited(id));
		if (graph.bankVisited(id))
		{
			abstractVisitedWithBank[abstractKind.ordinal()] = true;
			// A banked abstract state dominates the equivalent unbanked state.
		}
		abstractVisitedWithoutBank[abstractKind.ordinal()] = true;
		return !visited;
	}

	public boolean set(int x, int y, int plane, boolean bankVisited)
	{
		final int regionIndex = getRegionIndex(x / REGION_SIZE, y / REGION_SIZE);
		if (regionIndex < 0 || regionIndex >= visitedRegionsWithoutBank.length)
		{
			return false; // Region is out of bounds; report that it's been visited to avoid exploring it
			// further
		}

		if (bankVisited)
		{
			boolean unique = setInRegion(visitedRegionsWithBank, regionIndex, x, y, plane);
			// A banked tile dominates the equivalent unbanked tile, so populate both
			// buckets.
			setInRegion(visitedRegionsWithoutBank, regionIndex, x, y, plane);
			return unique;
		}

		return setInRegion(visitedRegionsWithoutBank, regionIndex, x, y, plane);
	}

	private boolean setInRegion(VisitedRegion[] visitedRegions, int regionIndex, int x, int y, int plane)
	{
		VisitedRegion region = visitedRegions[regionIndex];
		if (region == null)
		{
			region = new VisitedRegion(map.getRegionPlaneCounts(regionIndex));
			visitedRegions[regionIndex] = region;
		}
		return region.set(x % REGION_SIZE, y % REGION_SIZE, plane);
	}

	public void clear()
	{
		for (int i = 0; i < visitedRegionsWithoutBank.length; ++i)
		{
			visitedRegionsWithoutBank[i] = null;
			visitedRegionsWithBank[i] = null;
		}
		for (int i = 0; i < abstractVisitedWithoutBank.length; i++)
		{
			abstractVisitedWithoutBank[i] = false;
			abstractVisitedWithBank[i] = false;
		}
	}

	private int getRegionIndex(int regionX, int regionY)
	{
		return (regionX - regionExtents.minX) + (regionY - regionExtents.minY) * widthInclusive;
	}

	private static class VisitedRegion
	{
		// This assumes a row is at most 64 tiles and fits in a long
		private final long[] planes;
		private final byte planeCount;

		VisitedRegion(byte planeCount)
		{
			this.planeCount = planeCount;
			this.planes = new long[planeCount * REGION_SIZE];
		}

		// Sets a tile as visited in the tile bitset
		// Returns true if the tile is unique and hasn't been seen before or false if it
		// was seen before
		public boolean set(int x, int y, int plane)
		{
			if (plane >= planeCount)
			{
				// Plane is out of bounds; report that it has been visited to avoid further
				// exploration
				return false;
			}
			final int index = y + plane * REGION_SIZE;
			boolean unique = (planes[index] & (1L << x)) == 0;
			planes[index] |= 1L << x;
			return unique;
		}

		public boolean get(int x, int y, int plane)
		{
			if (plane >= planeCount)
			{
				// This check is necessary since we check visited tiles before checking the
				// collision map, e.g. the node
				// at (2816, 3455, 1) will check its neighbour to the north which is in a new
				// region with no plane = 1
				return true;
			}
			return (planes[y + plane * REGION_SIZE] & (1L << x)) != 0;
		}
	}
}

package gps.pathfinder;

/**
 * A minimal growable FIFO of primitive {@code int} node ids backed by a ring buffer.
 * <p>
 * Replaces the {@code ArrayDeque<Node>} boundary queue in {@link Pathfinder} so the search frontier
 * no longer boxes node references. Only the operations the pathfinder needs are implemented; it is
 * single-threaded (worker only) like the queue it replaces.
 */
class IntDeque
{
	private int[] elements;
	private int head;
	private int tail;
	private int size;

	IntDeque(int initialCapacity)
	{
		elements = new int[Math.max(1, initialCapacity)];
	}

	boolean isEmpty()
	{
		return size == 0;
	}

	void addLast(int value)
	{
		if (size == elements.length)
		{
			grow();
		}
		elements[tail] = value;
		tail = increment(tail);
		size++;
	}

	void addFirst(int value)
	{
		if (size == elements.length)
		{
			grow();
		}
		head = decrement(head);
		elements[head] = value;
		size++;
	}

	/**
	 * @return the first element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	int peekFirst()
	{
		return size == 0 ? NodeGraph.NO_NODE : elements[head];
	}

	/**
	 * @return the removed first element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	int pollFirst()
	{
		if (size == 0)
		{
			return NodeGraph.NO_NODE;
		}
		final int value = elements[head];
		head = increment(head);
		size--;
		return value;
	}

	void clear()
	{
		head = 0;
		tail = 0;
		size = 0;
	}

	private int increment(int index)
	{
		return index + 1 == elements.length ? 0 : index + 1;
	}

	private int decrement(int index)
	{
		return index == 0 ? elements.length - 1 : index - 1;
	}

	private void grow()
	{
		final int oldCapacity = elements.length;
		final int[] grown = new int[oldCapacity << 1];
		for (int i = 0; i < size; i++)
		{
			grown[i] = elements[(head + i) % oldCapacity];
		}
		elements = grown;
		head = 0;
		tail = size;
	}
}

package gps.pathfinder;

import static net.runelite.api.Constants.REGION_SIZE;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.Set;
import gps.PrimitiveIntHashMap;
import gps.WorldPointUtil;
import gps.transport.Transport;

/**
 * A target-rooted distance field: for every tile, a LOWER BOUND of the cost to reach the nearest
 * target — the per-generation preprocessing behind the near-exact A* heuristic. Built by one
 * multi-source reverse Dijkstra from the target set over:
 * <ul>
 * <li>walking edges (symmetric, mirrored from {@link CollisionMap}'s traversability rules with a
 * superset bias — anything uncertain is treated as walkable, which can only shorten distances and
 * therefore keeps the bound admissible), and</li>
 * <li>origin-bound transports reversed EXACTLY via a destination-keyed index (approximating
 * reverse edges with forward ones would overestimate across one-way transports — a jump-down
 * shortcut next to the target — and break admissibility).</li>
 * </ul>
 * Origin-less (global) teleports are deliberately NOT flooded: their reverse edge would reach
 * every tile at once, which is precisely the heuristic's constant floor —
 * {@link SearchHeuristic#buildWithField} computes it per search from the search's own usable
 * teleports, so per-search exclusions raise the floor exactly when searches get expensive.
 * <p>
 * The field is built from the generation's BASE availability (no per-search exclusions). Excluding
 * transports only raises true costs, so the field stays a valid lower bound for every search of
 * the generation. Unflooded tiles (reverse-unreachable from the targets) report
 * {@link #UNREACHED}; the heuristic maps them to its floor, which the consistency argument covers
 * because a forward transport edge into the flooded region implies its reversed edge existed in
 * the flood (so its origin would have been flooded) — EXCEPT teleport/transport landings on
 * blocked tiles, which the walking flood cannot step onto; {@link #patchBlockedLandings} values
 * those from their step-off neighbours after the flood (leaving them at the floor overestimated
 * the remaining cost, burying genuinely cheap routes through such landings).
 */
public final class DistanceField
{
	public static final int UNREACHED = Integer.MAX_VALUE;
	private static final short EMPTY = -1;
	// Distances are stored as shorts; anything longer than this is indistinguishable from
	// unreached for heuristic purposes (searches never run that far).
	private static final int MAX_DISTANCE = Short.MAX_VALUE - 1;
	// Extra flood distance past the bare floor * multiple horizon: covers the small gap between the
	// floor (a lower bound built from field values) and the best route's true cost, plus the +-1s of
	// blocked-landing patching. A pure speed knob — correctness never depends on the horizon (an
	// unflooded tile's true remaining provably exceeds the horizon, so reporting the horizon as its
	// heuristic is always admissible); overshooting just floods a little more.
	private static final int HORIZON_SLACK = 64;
	// The eight neighbour offsets (four cardinals, then four diagonals), shared by expandWalking and
	// patchBlockedLandings. Static so the per-tile flood never re-allocates them.
	private static final int[] DX = {-1, 1, 0, 0, -1, 1, -1, 1};
	private static final int[] DY = {0, 0, -1, 1, -1, -1, 1, 1};

	private final SplitFlagMap.RegionExtent regionExtents;
	private final int widthInclusive;
	private final short[][] regions;
	private final CollisionMap map;
	// Reused scratch for expandWalking's neighbour walkability. The flood is single-threaded per
	// DistanceField instance, so one buffer avoids a boolean[8] allocation on every settled tile —
	// which, across a whole-map flood, was the dominant allocation in build().
	private final boolean[] traversable = new boolean[8];
	// Every tile whose true field distance is <= this value is guaranteed flooded (the flood settles
	// in cost order and only stops past it), so an unflooded tile's remaining cost provably exceeds
	// it — the admissible fallback SearchHeuristic uses for unflooded tiles. MAX_VALUE = full flood
	// (unflooded means genuinely reverse-unreachable, e.g. an island).
	private int floodHorizon = Integer.MAX_VALUE;

	/** The bounded flood's horizon: a strict lower bound on any unflooded tile's distance. */
	int horizon()
	{
		return floodHorizon;
	}

	private DistanceField(CollisionMap map)
	{
		this.map = map;
		regionExtents = SplitFlagMap.getRegionExtents();
		widthInclusive = regionExtents.getWidth() + 1;
		final int heightInclusive = regionExtents.getHeight() + 1;
		regions = new short[widthInclusive * heightInclusive][];
	}

	/** The field value for a packed tile: cost lower bound to the nearest target, or UNREACHED. */
	public int distance(int packedPosition)
	{
		final int x = WorldPointUtil.unpackWorldX(packedPosition);
		final int y = WorldPointUtil.unpackWorldY(packedPosition);
		final int plane = WorldPointUtil.unpackWorldPlane(packedPosition);
		final int regionIndex = getRegionIndex(x / REGION_SIZE, y / REGION_SIZE);
		if (regionIndex < 0 || regionIndex >= regions.length)
		{
			return UNREACHED;
		}
		final short[] region = regions[regionIndex];
		if (region == null)
		{
			return UNREACHED;
		}
		final int index = tileIndex(x, y, plane, region.length);
		if (index < 0)
		{
			return UNREACHED;
		}
		final short value = region[index];
		return value == EMPTY ? UNREACHED : value;
	}

	/** Relaxes a tile to the given distance; true when it improved (and should be enqueued). */
	private boolean relax(int x, int y, int plane, int distance)
	{
		final int regionIndex = getRegionIndex(x / REGION_SIZE, y / REGION_SIZE);
		if (regionIndex < 0 || regionIndex >= regions.length)
		{
			return false;
		}
		short[] region = regions[regionIndex];
		if (region == null)
		{
			final byte planeCount = map.getRegionPlaneCounts(regionIndex);
			region = new short[planeCount * REGION_SIZE * REGION_SIZE];
			java.util.Arrays.fill(region, EMPTY);
			regions[regionIndex] = region;
		}
		final int index = tileIndex(x, y, plane, region.length);
		if (index < 0)
		{
			return false;
		}
		final short clamped = (short) Math.min(distance, MAX_DISTANCE);
		final short current = region[index];
		if (current != EMPTY && current <= clamped)
		{
			return false;
		}
		region[index] = clamped;
		return true;
	}

	private int getRegionIndex(int regionX, int regionY)
	{
		return (regionX - regionExtents.minX) + (regionY - regionExtents.minY) * widthInclusive;
	}

	private static int tileIndex(int x, int y, int plane, int regionLength)
	{
		final int index = (plane * REGION_SIZE + (y % REGION_SIZE)) * REGION_SIZE + (x % REGION_SIZE);
		return index < regionLength ? index : -1;
	}

	/**
	 * Builds the field for the given targets over the config's current (base) availability, or
	 * null when the targets span more than {@link SearchHeuristic#MAX_TARGET_SPAN} — a map-wide
	 * "nearest X" set floods everything for searches that are already cheap.
	 * <p>
	 * {@code costMultiple > 0} bounds the flood (see {@link #build(PathfinderConfig, Set, int)}):
	 * pass the generation's cost multiple so the flood stops once nothing beyond it can matter to
	 * any search of the generation. 0 floods the full map.
	 */
	public static DistanceField buildIfCompact(PathfinderConfig config, Set<Integer> targets, int costMultiple)
	{
		if (targets == null || targets.isEmpty())
		{
			return null;
		}
		int minX = Integer.MAX_VALUE;
		int maxX = Integer.MIN_VALUE;
		int minY = Integer.MAX_VALUE;
		int maxY = Integer.MIN_VALUE;
		for (int target : targets)
		{
			final int x = WorldPointUtil.unpackWorldX(target);
			final int y = WorldPointUtil.unpackWorldY(target);
			minX = Math.min(minX, x);
			maxX = Math.max(maxX, x);
			minY = Math.min(minY, y);
			maxY = Math.max(maxY, y);
		}
		if (Math.max(maxX - minX, maxY - minY) > SearchHeuristic.MAX_TARGET_SPAN)
		{
			return null;
		}
		return build(config, targets, costMultiple);
	}

	/** Builds the full-map field (tests use this directly). */
	public static DistanceField build(PathfinderConfig config, Set<Integer> targets)
	{
		return build(config, targets, 0);
	}

	/**
	 * Builds the field, optionally bounding the flood by the heuristic's own clamp: {@code h(n) =
	 * min(field(n), floor)}, so any value above the floor collapses to the floor, and every search is
	 * capped at {@code best * costMultiple} (≈ floor * costMultiple) — flooding past that band
	 * computes distances no consumer can distinguish from "far" (measured at 95%+ of the flood for
	 * teleport-rich configs). The floor is discovered DURING the flood: it is the cheapest
	 * {@code cast + field(landing)} over the base origin-free teleports, and since tiles settle in
	 * cost order, landings near the targets surface early; once the popped distance exceeds
	 * {@code floorSoFar * (costMultiple + 1) + HORIZON_SLACK} the flood stops itself.
	 * <p>
	 * Correctness does not depend on the horizon: the flood settles in cost order, so an unflooded
	 * tile's field distance — and therefore its true remaining cost, which the field lower-bounds —
	 * provably exceeds the recorded {@link #horizon()}. {@link SearchHeuristic} reports
	 * {@code min(horizon, floor)} for unflooded tiles, which is admissible and consistent
	 * unconditionally; an undersized horizon can only weaken the heuristic (slower searches), never
	 * change a result.
	 */
	static DistanceField build(PathfinderConfig config, Set<Integer> targets, int costMultiple)
	{
		final CollisionMap map = config.getMap();
		final DistanceField field = new DistanceField(map);
		final PrimitiveIntHashMap<Map<Integer, Integer>> reverseTransports = buildReverseTransportIndex(config);
		final VisitedTiles settled = new VisitedTiles(map);
		final IntDeque fifo = new IntDeque(4096);
		// Transport relaxations only (a few tens of thousands at most): boxed entries are fine.
		// Entry = (distance << 32) | (packed & 0xFFFFFFFF); natural ordering sorts by distance.
		final PriorityQueue<Long> heap = new PriorityQueue<>();
		// Bounded mode: cheapest cast cost per origin-free teleport landing, for in-flood floor
		// discovery. Null = unbounded (full flood).
		final PrimitiveIntHashMap<Integer> landingCasts =
			costMultiple > 0 ? buildTeleportLandingIndex(config) : null;
		int cheapestFloor = Integer.MAX_VALUE;
		long horizonTarget = Long.MAX_VALUE;

		for (int target : targets)
		{
			final int x = WorldPointUtil.unpackWorldX(target);
			final int y = WorldPointUtil.unpackWorldY(target);
			final int plane = WorldPointUtil.unpackWorldPlane(target);
			if (field.relax(x, y, plane, 0))
			{
				fifo.addLast(target);
			}
		}

		while (!fifo.isEmpty() || !heap.isEmpty())
		{
			int packed;
			if (!heap.isEmpty()
				&& (fifo.isEmpty() || (heap.peek() >>> 32) < field.distance(fifo.peekFirst())))
			{
				packed = (int) (long) heap.poll();
			}
			else
			{
				packed = fifo.pollFirst();
			}
			final int x = WorldPointUtil.unpackWorldX(packed);
			final int y = WorldPointUtil.unpackWorldY(packed);
			final int plane = WorldPointUtil.unpackWorldPlane(packed);
			if (!settled.set(x, y, plane, false))
			{
				continue;
			}
			final int distance = field.distance(packed);

			if (landingCasts != null)
			{
				// Everything below the popped distance is settled (cost-ordered), so once it passes
				// the horizon nothing else can matter: unflooded tiles provably lie beyond it.
				if (distance > horizonTarget)
				{
					field.floodHorizon = (int) Math.min(Integer.MAX_VALUE - 1L, horizonTarget);
					break;
				}
				final Integer cast = landingCasts.get(packed);
				if (cast != null && cast + distance < cheapestFloor)
				{
					cheapestFloor = cast + distance;
					horizonTarget = (long) cheapestFloor * costMultiple + cheapestFloor + HORIZON_SLACK;
				}
			}

			field.expandWalking(packed, x, y, plane, distance, fifo, settled, config);

			final Map<Integer, Integer> intoHere = reverseTransports.get(packed);
			if (intoHere != null)
			{
				for (Map.Entry<Integer, Integer> edge : intoHere.entrySet())
				{
					final int origin = edge.getKey();
					final int cost = edge.getValue();
					final int candidate = distance + cost;
					final int ox = WorldPointUtil.unpackWorldX(origin);
					final int oy = WorldPointUtil.unpackWorldY(origin);
					final int oplane = WorldPointUtil.unpackWorldPlane(origin);
					if (!settled.get(ox, oy, oplane, false) && field.relax(ox, oy, oplane, candidate))
					{
						heap.add(((long) candidate << 32) | (origin & 0xFFFFFFFFL));
					}
				}
			}
		}
		field.patchBlockedLandings(config, reverseTransports.keys());
		return field;
	}

	/**
	 * Values the landings the walking flood cannot reach: a teleport/transport destination on a
	 * BLOCKED tile (a quetzal platform, a jetty) is forward-occupiable — the player lands there and
	 * steps off — but the reverse flood never steps ONTO a blocked tile, so such landings stayed
	 * {@link #UNREACHED} and the heuristic sent them to its floor. That OVERESTIMATES the remaining
	 * cost from the landing (breaking admissibility: the search then buries routes through it), and
	 * inflates the floor itself, which skips unreached landings. Each such landing takes
	 * {@code min(field(step-off neighbour)) + 1}, mirroring the forward blocked-tile step-off rules
	 * exactly — a real forward edge, so the value stays a valid lower bound and h stays consistent.
	 * No propagation is needed: blocked tiles have no walk edges into other blocked tiles, so a
	 * patched value can never improve any other tile.
	 */
	private void patchBlockedLandings(PathfinderConfig config, int[] transportDestinations)
	{
		final Set<Integer> landings = new HashSet<>();
		for (int destination : transportDestinations)
		{
			landings.add(destination);
		}
		for (boolean bankVisited : new boolean[]{false, true})
		{
			for (Transport teleport : config.getUsableTeleports(bankVisited))
			{
				if (teleport.getDestination() != WorldPointUtil.UNDEFINED)
				{
					landings.add(teleport.getDestination());
				}
			}
		}
		for (int landing : landings)
		{
			final int x = WorldPointUtil.unpackWorldX(landing);
			final int y = WorldPointUtil.unpackWorldY(landing);
			final int plane = WorldPointUtil.unpackWorldPlane(landing);
			if (distance(landing) != UNREACHED || !map.isBlocked(x, y, plane))
			{
				continue;
			}
			// Forward step-off adjacency from a blocked tile (CollisionMap.getTileNeighbors'
			// isBlocked branch): any unblocked cardinal; diagonals need both flanking cardinals too.
			final boolean westBlocked = map.isBlocked(x - 1, y, plane);
			final boolean eastBlocked = map.isBlocked(x + 1, y, plane);
			final boolean southBlocked = map.isBlocked(x, y - 1, plane);
			final boolean northBlocked = map.isBlocked(x, y + 1, plane);
			final boolean[] stepOpen = {
				!westBlocked, !eastBlocked, !southBlocked, !northBlocked,
				!map.isBlocked(x - 1, y - 1, plane) && !westBlocked && !southBlocked,
				!map.isBlocked(x + 1, y - 1, plane) && !eastBlocked && !southBlocked,
				!map.isBlocked(x - 1, y + 1, plane) && !westBlocked && !northBlocked,
				!map.isBlocked(x + 1, y + 1, plane) && !eastBlocked && !northBlocked,
			};
			int best = UNREACHED;
			for (int i = 0; i < 8; i++)
			{
				if (!stepOpen[i])
				{
					continue;
				}
				final int neighbour = distance(WorldPointUtil.packWorldPoint(x + DX[i], y + DY[i], plane));
				if (neighbour != UNREACHED && neighbour + 1 < best)
				{
					best = neighbour + 1;
				}
			}
			if (best != UNREACHED)
			{
				relax(x, y, plane, best);
			}
		}
	}

	/**
	 * Relaxes the walking neighbours of a popped tile, mirroring {@link CollisionMap}'s forward
	 * traversability (walking is symmetric in the collision data). The blocked-tile branches mirror
	 * the forward rules for transport endpoints standing on blocked tiles (e.g. fairy ring
	 * platforms) with a superset bias — extra edges only shorten the field, which is safe.
	 */
	private void expandWalking(int packed, int x, int y, int plane, int distance,
		IntDeque fifo, VisitedTiles settled, PathfinderConfig config)
	{
		if (map.isBlocked(x, y, plane))
		{
			final boolean westBlocked = map.isBlocked(x - 1, y, plane);
			final boolean eastBlocked = map.isBlocked(x + 1, y, plane);
			final boolean southBlocked = map.isBlocked(x, y - 1, plane);
			final boolean northBlocked = map.isBlocked(x, y + 1, plane);
			traversable[0] = !westBlocked;
			traversable[1] = !eastBlocked;
			traversable[2] = !southBlocked;
			traversable[3] = !northBlocked;
			traversable[4] = !map.isBlocked(x - 1, y - 1, plane) && !westBlocked && !southBlocked;
			traversable[5] = !map.isBlocked(x + 1, y - 1, plane) && !eastBlocked && !southBlocked;
			traversable[6] = !map.isBlocked(x - 1, y + 1, plane) && !westBlocked && !northBlocked;
			traversable[7] = !map.isBlocked(x + 1, y + 1, plane) && !eastBlocked && !northBlocked;
		}
		else
		{
			// Diagonals composed exactly like CollisionMap's private sw/se/nw/ne: the diagonal is
			// walkable when all four half-edges around it are.
			final boolean w = map.w(x, y, plane);
			final boolean e = map.e(x, y, plane);
			final boolean s = map.s(x, y, plane);
			final boolean n = map.n(x, y, plane);
			traversable[0] = w;
			traversable[1] = e;
			traversable[2] = s;
			traversable[3] = n;
			traversable[4] = s && map.w(x, y - 1, plane) && w && map.s(x - 1, y, plane);
			traversable[5] = s && map.e(x, y - 1, plane) && e && map.s(x + 1, y, plane);
			traversable[6] = n && map.w(x, y + 1, plane) && w && map.n(x - 1, y, plane);
			traversable[7] = n && map.e(x, y + 1, plane) && e && map.n(x + 1, y, plane);
		}
		for (int i = 0; i < 8; i++)
		{
			final int nx = x + DX[i];
			final int ny = y + DY[i];
			boolean canStep = traversable[i];
			if (!canStep && Math.abs(DX[i] + DY[i]) == 1 && map.isBlocked(nx, ny, plane))
			{
				// Mirror of the forward rule that lets a path step onto a blocked tile hosting a
				// transport origin (fairy ring platform). Superset bias: any transport there counts.
				final int neighborPacked = WorldPointUtil.packWorldPoint(nx, ny, plane);
				canStep = config.getTransportsPacked(true)
					.getOrDefault(neighborPacked, TransportAvailability.EMPTY_TRANSPORTS).length > 0;
			}
			if (!canStep || settled.get(nx, ny, plane, false))
			{
				continue;
			}
			if (relax(nx, ny, plane, distance + 1))
			{
				fifo.addLast(WorldPointUtil.packWorldPoint(nx, ny, plane));
			}
		}
	}

	/**
	 * Destination-keyed index of every origin-bound transport in the config's base availability:
	 * {@code destination -> (origin -> cheapest cost to make that hop)}. Built over both bank states
	 * because a superset only shortens the field.
	 * <p>
	 * The inner map is keyed by origin and keeps the MINIMUM cost on purpose. The same origin lands
	 * on the same destination more than once here — a transport not gated on banking appears in both
	 * the no-bank and bank-visited availability, and two distinct methods can share an origin and
	 * landing — so a flat list would hold duplicate and redundant edges. The flood only ever relaxes
	 * an origin to the cheapest way it can reach the destination ({@code relax} keeps the minimum), so
	 * a pricier or duplicate edge could never improve the field. Folding them to one min-cost entry
	 * per origin as we build keeps the index minimal (and the flood's relax attempts non-redundant)
	 * without changing a single field value.
	 */
	/**
	 * Cheapest effective cast cost per origin-free teleport landing, over the config's base
	 * availability (both bank states) — the same teleport set {@link SearchHeuristic#buildWithField}
	 * scans, so the floor the bounded flood discovers matches the one the heuristic will use.
	 * Landings on blocked tiles never settle in the walk flood, so their casts simply never
	 * contribute — the floor stays a little high and the horizon a little wide, which is safe.
	 */
	private static PrimitiveIntHashMap<Integer> buildTeleportLandingIndex(PathfinderConfig config)
	{
		final PrimitiveIntHashMap<Integer> index = new PrimitiveIntHashMap<>(256);
		for (boolean bankVisited : new boolean[]{false, true})
		{
			for (Transport teleport : config.getUsableTeleports(bankVisited))
			{
				final int destination = teleport.getDestination();
				if (destination == WorldPointUtil.UNDEFINED)
				{
					continue;
				}
				final int cost = Math.max(0, CostUnits.fromTicks(teleport.getDuration())
					+ config.getAdditionalTransportCost(teleport));
				final Integer current = index.get(destination);
				if (current == null || cost < current)
				{
					index.put(destination, cost);
				}
			}
		}
		return index;
	}

	// Package-private for DistanceFieldTest's index-shape assertion. The OUTER map is keyed by a
	// primitive int (the destination): the flood looks it up for every settled tile, and a
	// Map<Integer, ...> would box that int into a throwaway Integer on each of the millions of tiles
	// — the second-biggest allocation in build() after the per-tile scratch arrays. The inner
	// origin -> min-cost map stays boxed: it is only iterated for the few thousand tiles that are
	// actually transport destinations, not per settled tile.
	static PrimitiveIntHashMap<Map<Integer, Integer>> buildReverseTransportIndex(PathfinderConfig config)
	{
		final PrimitiveIntHashMap<Map<Integer, Integer>> index = new PrimitiveIntHashMap<>(4096);
		for (boolean bankVisited : new boolean[]{false, true})
		{
			final PrimitiveIntHashMap<Transport[]> transports = config.getTransportsPacked(bankVisited);
			for (int origin : transports.keys())
			{
				final Transport[] set = transports.get(origin);
				if (set == null)
				{
					continue;
				}
				for (Transport transport : set)
				{
					final int destination = transport.getDestination();
					if (destination == WorldPointUtil.UNDEFINED)
					{
						continue;
					}
					final int cost = Math.max(0, CostUnits.fromTicks(transport.getDuration())
						+ config.getAdditionalTransportCost(transport));
					Map<Integer, Integer> byOrigin = index.get(destination);
					if (byOrigin == null)
					{
						byOrigin = new HashMap<>();
						index.put(destination, byOrigin);
					}
					// Keyed by the availability map's origin (the loop key), NOT transport.getOrigin():
					// the POH remap re-homes interior transports onto the landing tile by MAP KEY while
					// each Transport keeps its interior origin. Crediting the interior tile left the
					// landing unflooded, so the heuristic overestimated inside the POH (inadmissible)
					// and house-mediated best routes only surfaced after "+" (user capture pair).
					byOrigin.merge(origin, cost, Math::min);
				}
			}
		}
		return index;
	}
}

package gps.pathfinder;

import static net.runelite.api.Constants.REGION_SIZE;

import gps.WorldPointUtil;

/**
 * The best tentative cost seen so far for each (tile, bank) search state — the duplicate-enqueue
 * pruner for cost-ordered (settle-dedup) searches. Without it every settled tile re-enqueues each
 * unsettled neighbour, so a map-wide flood appends and queues each tile ~3-4 times; recording the
 * best candidate cost at enqueue time lets non-improving duplicates be skipped BEFORE the node is
 * even created, restoring the enqueue-once economy the old FIFO search had — without its claim-by-
 * first-enqueue incorrectness, because an IMPROVING duplicate still goes through and wins the
 * settle. Same lazily-allocated region layout as {@link VisitedTiles}, with a short per tile.
 * <p>
 * Costs above {@link #MAX_PRUNABLE} are never pruned or recorded (they don't fit the short), so
 * pathological modifier configs lose the optimisation, never correctness.
 */
class TentativeCosts
{
	private static final short EMPTY = -1;
	private static final int MAX_PRUNABLE = 30000;

	private final SplitFlagMap.RegionExtent regionExtents;
	private final int widthInclusive;
	private final short[][] regionsWithoutBank;
	private final short[][] regionsWithBank;
	private final CollisionMap map;

	TentativeCosts(CollisionMap map)
	{
		this.map = map;
		regionExtents = SplitFlagMap.getRegionExtents();
		widthInclusive = regionExtents.getWidth() + 1;
		final int heightInclusive = regionExtents.getHeight() + 1;
		regionsWithoutBank = new short[widthInclusive * heightInclusive][];
		regionsWithBank = new short[widthInclusive * heightInclusive][];
	}

	/**
	 * Whether an arrival at {@code packedPoint} costing {@code candidate} is known not to improve
	 * on an already-queued arrival (prune it); records the candidate as the new best otherwise.
	 */
	boolean shouldPrune(int packedPoint, boolean bankVisited, int candidate)
	{
		if (candidate > MAX_PRUNABLE || candidate < 0)
		{
			return false;
		}
		final int x = WorldPointUtil.unpackWorldX(packedPoint);
		final int y = WorldPointUtil.unpackWorldY(packedPoint);
		final int plane = WorldPointUtil.unpackWorldPlane(packedPoint);
		final int regionIndex = getRegionIndex(x / REGION_SIZE, y / REGION_SIZE);
		final short[][] regions = bankVisited ? regionsWithBank : regionsWithoutBank;
		if (regionIndex < 0 || regionIndex >= regions.length)
		{
			return false;
		}
		short[] region = regions[regionIndex];
		if (region == null)
		{
			final byte planeCount = map.getRegionPlaneCounts(regionIndex);
			region = new short[planeCount * REGION_SIZE * REGION_SIZE];
			java.util.Arrays.fill(region, EMPTY);
			regions[regionIndex] = region;
		}
		final int index = (plane * REGION_SIZE + (y % REGION_SIZE)) * REGION_SIZE + (x % REGION_SIZE);
		if (index >= region.length)
		{
			return false;
		}
		final short current = region[index];
		if (current != EMPTY && current <= candidate)
		{
			return true;
		}
		region[index] = (short) candidate;
		return false;
	}

	private int getRegionIndex(int regionX, int regionY)
	{
		return (regionX - regionExtents.minX) + (regionY - regionExtents.minY) * widthInclusive;
	}

	void clear()
	{
		for (int i = 0; i < regionsWithoutBank.length; i++)
		{
			regionsWithoutBank[i] = null;
			regionsWithBank[i] = null;
		}
	}
}

package gps.pathfinder;

import java.util.List;
import lombok.Getter;

@Getter
public class PathfinderResult
{
	private final int start;
	private final int target;
	private final boolean reached;
	private final List<PathStep> pathSteps;
	private final int closestReachedPoint;
	/**
	 * Accumulated search cost (blended walk distance + transport ticks/penalties) of the returned
	 * path. Used to rank alternative routes against each other.
	 */
	private final int totalCost;
	private final int nodesChecked;
	private final int transportsChecked;
	private final long elapsedNanos;
	private final PathTerminationReason terminationReason;

	public PathfinderResult(
		int start,
		int target,
		boolean reached,
		List<PathStep> pathSteps,
		int closestReachedPoint,
		int totalCost,
		int nodesChecked,
		int transportsChecked,
		long elapsedNanos,
		PathTerminationReason terminationReason)
	{
		this.start = start;
		this.target = target;
		this.reached = reached;
		this.pathSteps = pathSteps;
		this.closestReachedPoint = closestReachedPoint;
		this.totalCost = totalCost;
		this.nodesChecked = nodesChecked;
		this.transportsChecked = transportsChecked;
		this.elapsedNanos = elapsedNanos;
		this.terminationReason = terminationReason;
	}
}

package gps.pathfinder;

import gps.PrimitiveIntList;
import gps.WorldPointUtil;
import gps.transport.Transport;

public class CollisionMap
{
	// Enum.values() makes copies every time which hurts performance in the hotpath
	private static final OrdinalDirection[] ORDINAL_VALUES = OrdinalDirection.values();

	// Walking through a door costs real time: the collision data bakes doors open, so the walk
	// edge is passable, but the player still stops, clicks, and waits ~a tick for the swing —
	// priced here so the search prefers pure walking around a doorway when it's close. One mask
	// lookup per expanded tile (same profile as the transports lookup above it in the hot path).
	private static final int DOOR_COST_UNITS = CostUnits.fromTicks(gps.ClosedDoors.COST_TICKS);

	private final SplitFlagMap collisionData;
	// This is only safe if pathfinding is single-threaded. Holds the ids of the neighbour nodes
	// appended to the NodeGraph during the most recent getNeighbors call.
	private final PrimitiveIntList neighbors = new PrimitiveIntList(16);
	private final boolean[] traversable = new boolean[8];
	private final java.util.Map<Integer, Integer> doorMasks = gps.ClosedDoors.edgeMasks();

	public CollisionMap(SplitFlagMap collisionData)
	{
		this.collisionData = collisionData;
	}

	private static int packedPointFromOrdinal(int startPacked, OrdinalDirection direction)
	{
		final int x = WorldPointUtil.unpackWorldX(startPacked);
		final int y = WorldPointUtil.unpackWorldY(startPacked);
		final int plane = WorldPointUtil.unpackWorldPlane(startPacked);
		return WorldPointUtil.packWorldPoint(x + direction.x, y + direction.y, plane);
	}

	/**
	 * Walkable plane count for allocating region-indexed side arrays — never below one:
	 * pure-ocean regions record ZERO walkable planes, and every consumer that sized an array
	 * from the raw count silently refused plane 0 there (the water-pin blind-search outage,
	 * fixed three times in three consumers before the clamp moved here).
	 */
	public byte getRegionPlaneCounts(int regionIndex)
	{
		return (byte) Math.max(1, collisionData.getRegionPlaneCounts(regionIndex));
	}

	private boolean get(int x, int y, int z, int flag)
	{
		return collisionData.get(x, y, z, flag);
	}

	public boolean n(int x, int y, int z)
	{
		return get(x, y, z, 0);
	}

	public boolean s(int x, int y, int z)
	{
		return n(x, y - 1, z);
	}

	public boolean e(int x, int y, int z)
	{
		return get(x, y, z, 1);
	}

	public boolean w(int x, int y, int z)
	{
		return e(x - 1, y, z);
	}

	/**
	 * Whether a single walking step between two ADJACENT tiles is traversable, using the same
	 * edge rules as the neighbour expansion (walls block even between two walkable tiles). False
	 * for non-adjacent or cross-plane pairs. Used by the route progress tracker so straight-line
	 * proximity can't see through walls.
	 */
	public boolean canStep(int fromPacked, int toPacked)
	{
		int x = WorldPointUtil.unpackWorldX(fromPacked);
		int y = WorldPointUtil.unpackWorldY(fromPacked);
		int z = WorldPointUtil.unpackWorldPlane(fromPacked);
		if (z != WorldPointUtil.unpackWorldPlane(toPacked))
		{
			return false;
		}
		int dx = WorldPointUtil.unpackWorldX(toPacked) - x;
		int dy = WorldPointUtil.unpackWorldY(toPacked) - y;
		if (dx == 0 && dy == 1)
		{
			return n(x, y, z);
		}
		if (dx == 0 && dy == -1)
		{
			return s(x, y, z);
		}
		if (dx == 1 && dy == 0)
		{
			return e(x, y, z);
		}
		if (dx == -1 && dy == 0)
		{
			return w(x, y, z);
		}
		if (dx == 1 && dy == 1)
		{
			return ne(x, y, z);
		}
		if (dx == -1 && dy == 1)
		{
			return nw(x, y, z);
		}
		if (dx == 1 && dy == -1)
		{
			return se(x, y, z);
		}
		if (dx == -1 && dy == -1)
		{
			return sw(x, y, z);
		}
		return false;
	}

	private boolean ne(int x, int y, int z)
	{
		return n(x, y, z) && e(x, y + 1, z) && e(x, y, z) && n(x + 1, y, z);
	}

	private boolean nw(int x, int y, int z)
	{
		return n(x, y, z) && w(x, y + 1, z) && w(x, y, z) && n(x - 1, y, z);
	}

	private boolean se(int x, int y, int z)
	{
		return s(x, y, z) && e(x, y - 1, z) && e(x, y, z) && s(x + 1, y, z);
	}

	private boolean sw(int x, int y, int z)
	{
		return s(x, y, z) && w(x, y - 1, z) && w(x, y, z) && s(x - 1, y, z);
	}

	public boolean isBlocked(int x, int y, int z)
	{
		return !n(x, y, z) && !s(x, y, z) && !e(x, y, z) && !w(x, y, z);
	}

	public PrimitiveIntList getNeighbors(int node, VisitedTiles visited, PathfinderConfig config, int wildernessLevel, boolean targetInWilderness, NodeGraph graph)
	{
		return getNeighbors(node, visited, config, wildernessLevel, targetInWilderness, graph, null);
	}

	/**
	 * {@code tentative} (nullable) is the duplicate-enqueue pruner for settle-dedup searches: a
	 * neighbour whose candidate cost does not improve on an already-queued arrival at the same
	 * (tile, bank) state is skipped before its node is even created.
	 */
	public PrimitiveIntList getNeighbors(int node, VisitedTiles visited, PathfinderConfig config, int wildernessLevel, boolean targetInWilderness, NodeGraph graph, TentativeCosts tentative)
	{
		if (graph.isTile(node))
		{
			return getTileNeighbors(node, visited, config, wildernessLevel, graph, tentative);
		}
		else
		{
			return getAbstractNodeNeighbors(node, visited, config, targetInWilderness, graph);
		}
	}

	// Get neighbours for a walkable tile:
	//      * Neighbouring tiles we can walk to
	//      * An OPTIONAL same-tile transition into the banked state, if the current tile is a bank
	//        (priced at the bank-pickup cost — the un-banked path continues in parallel).
	//      * Transition into abstract global teleport nodes, if we haven't tried that yet.
	private PrimitiveIntList getTileNeighbors(int node, VisitedTiles visited, PathfinderConfig config, int wildernessLevel, NodeGraph graph, TentativeCosts tentative)
	{
		final int packedPosition = graph.packedPosition(node);
		final int x = WorldPointUtil.unpackWorldX(packedPosition);
		final int y = WorldPointUtil.unpackWorldY(packedPosition);
		final int z = WorldPointUtil.unpackWorldPlane(packedPosition);

		neighbors.clear();

		// Banking is a CHOICE, not a consequence of standing near a booth: from an un-banked node
		// on a bank-accessible tile, offer a same-tile transition into the banked state priced at
		// the pickup cost — every other edge continues un-banked, free of the surcharge. (The flip
		// used to be FORCED on every path touching a bank tile, which charged routes that never
		// withdraw anything — e.g. every route starting at the GE — cancelling the surcharge out
		// of the route ranking, and made plain walking detour around bank plazas to dodge it.)
		final boolean bankVisited = graph.bankVisited(node);
		if (!bankVisited && config.isBankPathEnabled() && config.bankAccessible(packedPosition)
			&& !visited.get(packedPosition, true)
			&& (tentative == null || !tentative.shouldPrune(packedPosition, true,
				graph.cost(node) + config.getBankPickupCost())))
		{
			neighbors.add(graph.createTile(packedPosition, node, true, config.getBankPickupCost()));
		}

		// Firstly check if there are any transports or teleports which are applicable from the current tile.
		Transport[] transports = config.getTransportsPacked(bankVisited).getOrDefault(packedPosition, TransportAvailability.EMPTY_TRANSPORTS);
		for (Transport transport : transports)
		{
			// A transport to an already-SETTLED destination is pointless (settled = final under
			// cost-ordered settling); same-destination competitors race in the queue otherwise.
			if (visited.get(transport.getDestination(), bankVisited))
			{
				continue;
			}
			// NB: Do not need to check for wilderness level for transports, since transports have specific origin tile.
			// The whistle differential is REAL cost inside getAdditionalTransportCost, so a chain
			// (whistle -> landing site A -> fly to B) prices itself above the direct whistle-to-B
			// teleport with no special inheritance.
			final int transportTravelTime = CostUnits.fromTicks(transport.getDuration());
			final int transportAdditionalCost = config.getAdditionalTransportCost(transport);
			if (tentative != null && tentative.shouldPrune(transport.getDestination(), bankVisited,
				graph.cost(node) + Math.max(0, transportTravelTime + transportAdditionalCost)))
			{
				continue;
			}
			neighbors.add(graph.createTransport(
				transport.getDestination(),
				node,
				transportTravelTime,
				transportAdditionalCost,
				bankVisited));
		}

		// Global teleports are only considered from an abstract node, so each
		// wilderness/bank state expands them once. Water nodes may be barred from expanding
		// it entirely (abandonment forbidden: no casting from the helm; land nodes fine).
		AbstractNodeKind abstractKind = AbstractNodeKind.fromWildernessLevel(wildernessLevel);
		if (!visited.getAbstract(abstractKind, bankVisited)
			&& !config.teleportsBlockedAt(WorldPointUtil.packWorldPoint(x, y, z)))
		{
			neighbors.add(graph.createAbstract(abstractKind, node, bankVisited, 0));
		}

		// Then add tiles which we can walk to, which go into the FIFO boundary queue.
		if (isBlocked(x, y, z))
		{
			boolean westBlocked = isBlocked(x - 1, y, z);
			boolean eastBlocked = isBlocked(x + 1, y, z);
			boolean southBlocked = isBlocked(x, y - 1, z);
			boolean northBlocked = isBlocked(x, y + 1, z);
			boolean southWestBlocked = isBlocked(x - 1, y - 1, z);
			boolean southEastBlocked = isBlocked(x + 1, y - 1, z);
			boolean northWestBlocked = isBlocked(x - 1, y + 1, z);
			boolean northEastBlocked = isBlocked(x + 1, y + 1, z);
			traversable[0] = !westBlocked;
			traversable[1] = !eastBlocked;
			traversable[2] = !southBlocked;
			traversable[3] = !northBlocked;
			traversable[4] = !southWestBlocked && !westBlocked && !southBlocked;
			traversable[5] = !southEastBlocked && !eastBlocked && !southBlocked;
			traversable[6] = !northWestBlocked && !westBlocked && !northBlocked;
			traversable[7] = !northEastBlocked && !eastBlocked && !northBlocked;
		}
		else
		{
			traversable[0] = w(x, y, z);
			traversable[1] = e(x, y, z);
			traversable[2] = s(x, y, z);
			traversable[3] = n(x, y, z);
			traversable[4] = sw(x, y, z);
			traversable[5] = se(x, y, z);
			traversable[6] = nw(x, y, z);
			traversable[7] = ne(x, y, z);
		}

		// One walking step costs 1 (Chebyshev-adjacent); stepping through a doorway adds the
		// door's opening + reaction time on top.
		final int walkStepCost = graph.cost(node) + 1;
		final int doorMask = doorMasks.getOrDefault(packedPosition, 0);
		for (int i = 0; i < traversable.length; i++)
		{
			OrdinalDirection d = ORDINAL_VALUES[i];
			int neighborPacked = packedPointFromOrdinal(packedPosition, d);
			if (visited.get(neighborPacked, bankVisited))
			{
				continue;
			}

			if (traversable[i])
			{
				final int doorCost = (doorMask & (1 << i)) != 0 ? DOOR_COST_UNITS : 0;
				if (tentative != null && tentative.shouldPrune(neighborPacked, bankVisited, walkStepCost + doorCost))
				{
					continue;
				}
				neighbors.add(graph.createTile(neighborPacked, node, bankVisited, doorCost));
			}
			else if (Math.abs(d.x + d.y) == 1 && isBlocked(x + d.x, y + d.y, z))
			{
				// The transport starts from a blocked adjacent tile, e.g. fairy ring
				// Only checks non-teleport transports (includes portals and levers, but not
				// items and spells)
				Transport[] neighborTransports = config.getTransportsPacked(bankVisited).getOrDefault(neighborPacked,
					TransportAvailability.EMPTY_TRANSPORTS);
				for (Transport transport : neighborTransports)
				{
					// Remapped transports (POH interiors re-homed onto the landing by MAP KEY) keep
					// their original origin field; stepping onto it would jump the path into the
					// house template. Only true blocked-tile transports (origin == the map key,
					// e.g. fairy rings) may be entered this way.
					if (transport.getOrigin() != neighborPacked
						|| !(transport.isUsableAtWildernessLevel(wildernessLevel))
						|| visited.get(transport.getOrigin(), bankVisited))
					{
						continue;
					}
					if (tentative != null && tentative.shouldPrune(transport.getOrigin(), bankVisited,
						graph.cost(node) + WorldPointUtil.distanceBetween(packedPosition, transport.getOrigin())))
					{
						continue;
					}
					neighbors.add(graph.createTile(transport.getOrigin(), node, bankVisited, 0));
				}
			}
		}

		return neighbors;
	}

	// The only abstract nodes are currently for global teleports
	private PrimitiveIntList getAbstractNodeNeighbors(int node, VisitedTiles visited, PathfinderConfig config,
		boolean targetInWilderness, NodeGraph graph)
	{
		neighbors.clear();
		int sourceTile = graph.getClosestTilePosition(node);
		boolean bankVisited = graph.bankVisited(node);
		int maxWildernessLevel = graph.abstractKind(node).maxWildernessLevel();
		for (Transport transport : config.getUsableTeleports(bankVisited))
		{
			if (visited.get(transport.getDestination(), bankVisited))
			{
				continue;
			}
			if (!transport.isUsableAtWildernessLevel(maxWildernessLevel))
			{
				continue;
			}
			if (config.avoidWilderness(sourceTile, transport.getDestination(), targetInWilderness))
			{
				continue;
			}
			neighbors.add(graph.createTransport(
				transport.getDestination(),
				node,
				CostUnits.fromTicks(transport.getDuration()),
				config.getAdditionalTransportCost(transport),
				bankVisited));
		}
		return neighbors;
	}
}

