	/** 1-3 stacked arrowheads filling the 16px canvas from the middle out. */
	private static BufferedImage priorityGlyph(int count, boolean up, Color colour)
	{
		return render(g ->
		{
			g.setColor(colour);
			// Each arrowhead is 4px tall with a 1px gap; the stack is centred vertically.
			double totalHeight = count * 5 - 1;
			double top = (16 - totalHeight) / 2.0;
			for (int i = 0; i < count; i++)
			{
				double y = top + i * 5;
				Path2D head = new Path2D.Double();
				if (up)
				{
					head.moveTo(3.0, y + 4);
					head.lineTo(13.0, y + 4);
					head.lineTo(8.0, y);
				}
				else
				{
					head.moveTo(3.0, y);
					head.lineTo(13.0, y);
					head.lineTo(8.0, y + 4);
				}
				head.closePath();
				g.fill(head);
			}
		});
	}

	private static BufferedImage chevron(Color colour, boolean down)
	{
		return render(g ->
		{
			g.setColor(colour);
			Path2D triangle = new Path2D.Double();
			if (down)
			{
				triangle.moveTo(4.5, 6.0);
				triangle.lineTo(11.5, 6.0);
				triangle.lineTo(8.0, 11.0);
			}
			else
			{
				triangle.moveTo(6.0, 4.5);
				triangle.lineTo(11.0, 8.0);
				triangle.lineTo(6.0, 11.5);
			}
			triangle.closePath();
			g.fill(triangle);
		});
	}

	private static void arrowHead(Graphics2D g, double x, double y, double angle, double size, Color colour)
	{
		Path2D head = new Path2D.Double();
		head.moveTo(x, y);
		head.lineTo(x - size * Math.cos(angle - Math.PI / 6), y - size * Math.sin(angle - Math.PI / 6));
		head.lineTo(x - size * Math.cos(angle + Math.PI / 6), y - size * Math.sin(angle + Math.PI / 6));
		head.closePath();
		g.setColor(colour);
		g.fill(head);
	}
}

package gps;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.gameval.ItemID;

/**
 * Parses the balloon log-storage chat messages into per-type stored counts. The storage crates'
 * contents are not exposed through varbits or varps — the game only reveals them in chat (verified
 * against the dedicated tictac7x-balloon hub plugin, which uses the same approach; the message
 * patterns below follow its battle-tested set). Counts persist in the plugin config, so they
 * survive sessions; they start at 0 (conservative: no flight is assumed payable from storage until
 * the game has confirmed logs are there) and re-sync whenever the player stores logs, checks the
 * crate, or flies.
 */
public final class BalloonLogStorage
{
	/** Config keys per log type, in {logs, oak, willow, yew, magic} order. */
	public static final String[] CONFIG_KEYS = {
		"balloonStoredLogs", "balloonStoredOakLogs", "balloonStoredWillowLogs",
		"balloonStoredYewLogs", "balloonStoredMagicLogs"};

	/** Display names per log type, in the same order as {@link #CONFIG_KEYS}. */
	public static final String[] TYPE_NAMES = {"normal", "oak", "willow", "yew", "magic"};

	/** Item ids per log type (for icons and requirement checks), in {@link #CONFIG_KEYS} order. */
	public static final int[] ITEM_IDS = {
		ItemID.LOGS, ItemID.OAK_LOGS, ItemID.WILLOW_LOGS, ItemID.YEW_LOGS, ItemID.MAGIC_LOGS};

	private static final Pattern LEFT_PLURAL = Pattern.compile("You have (?<count>\\d+) sets of (?<type>.*) left in storage\\.");
	private static final Pattern LEFT_SINGULAR = Pattern.compile("You have one set of (?<type>.*) left in storage\\.");
	private static final Pattern USED_LAST = Pattern.compile("You used the last of your (?<type>.*)\\.");
	private static final Pattern STORED = Pattern.compile("You put the (?<type>.*) in the crate\\. You now have (?<count>\\d+) stored\\.");
	private static final Pattern NEEDED = Pattern.compile("You need 1 (?<type>.*) logs to make this trip\\.");
	private static final Pattern CHECK = Pattern.compile(
		"This crate currently contains (?<regular>\\d+) logs, (?<oak>\\d+) oak logs, (?<willow>\\d+) willow logs, "
			+ "(?<yew>\\d+) yew logs and (?<magic>\\d+) magic logs\\.");

	private BalloonLogStorage()
	{
	}

	/**
	 * The stored-count updates a chat message implies: config key -> new count. Empty when the
	 * message is not a balloon-storage message.
	 */
	public static Map<String, Integer> parse(String message)
	{
		Map<String, Integer> updates = new LinkedHashMap<>();
		Matcher check = CHECK.matcher(message);
		if (check.find())
		{
			updates.put(CONFIG_KEYS[0], Integer.parseInt(check.group("regular")));
			updates.put(CONFIG_KEYS[1], Integer.parseInt(check.group("oak")));
			updates.put(CONFIG_KEYS[2], Integer.parseInt(check.group("willow")));
			updates.put(CONFIG_KEYS[3], Integer.parseInt(check.group("yew")));
			updates.put(CONFIG_KEYS[4], Integer.parseInt(check.group("magic")));
			return updates;
		}
		Matcher stored = STORED.matcher(message);
		if (stored.find())
		{
			put(updates, stored.group("type"), Integer.parseInt(stored.group("count")));
			return updates;
		}
		Matcher plural = LEFT_PLURAL.matcher(message);
		if (plural.find())
		{
			put(updates, plural.group("type"), Integer.parseInt(plural.group("count")));
			return updates;
		}
		Matcher singular = LEFT_SINGULAR.matcher(message);
		if (singular.find())
		{
			put(updates, singular.group("type"), 1);
			return updates;
		}
		Matcher last = USED_LAST.matcher(message);
		if (last.find())
		{
			put(updates, last.group("type"), 0);
			return updates;
		}
		Matcher needed = NEEDED.matcher(message);
		if (needed.find())
		{
			// "You need 1 X logs to make this trip" fires when neither inventory nor storage can
			// pay: the storage is empty for that type.
			put(updates, needed.group("type"), 0);
			return updates;
		}
		return updates;
	}

	/**
	 * The log types worth warning about: below the threshold in storage AND belonging to a balloon
	 * route the player has unlocked (a locked route's empty storage is noise, not a warning).
	 * Arrays follow the {@link #TYPE_NAMES} order; returns display names.
	 */
	public static List<String> lowTypes(int[] stored, boolean[] unlocked, int threshold)
	{
		List<String> low = new ArrayList<>();
		for (int i = 0; i < TYPE_NAMES.length; i++)
		{
			if (unlocked[i] && stored[i] < threshold)
			{
				low.add(TYPE_NAMES[i]);
			}
		}
		return low;
	}

	private static void put(Map<String, Integer> updates, String type, int count)
	{
		String key = keyOf(type);
		if (key != null)
		{
			updates.put(key, count);
		}
	}

	private static String keyOf(String type)
	{
		switch (type)
		{
			case "Logs":
			case "normal":
			case "regular":
				return CONFIG_KEYS[0];
			case "Oak logs":
			case "oak":
				return CONFIG_KEYS[1];
			case "Willow logs":
			case "willow":
				return CONFIG_KEYS[2];
			case "Yew logs":
			case "yew":
				return CONFIG_KEYS[3];
			case "Magic logs":
			case "magic":
				return CONFIG_KEYS[4];
			default:
				return null;
		}
	}
}

package gps;

import java.util.Locale;

/**
 * Fuzzy name matching for the destination search. {@link #score} returns 0 for no match and a
 * positive score otherwise, tiered so tighter matches always outrank looser ones:
 * exact name &gt; name prefix &gt; word prefixes ("var pal" finds "Varrock Palace") &gt;
 * substring &gt; subsequence (query letters appear in order with gaps — typo-tolerant
 * abbreviations like "brmhvn" for "Brimhaven"). Within a tier, shorter names rank higher.
 */
final class SearchMatcher
{
	private static final int TIER_EXACT = 1000;
	private static final int TIER_PREFIX = 900;
	private static final int TIER_WORD_PREFIX = 800;
	private static final int TIER_SUBSTRING = 700;
	private static final int TIER_SUBSEQUENCE = 300;
	// Within-tier penalty for longer names; kept below the tier spacing so tiers never cross.
	private static final int MAX_LENGTH_PENALTY = 80;
	// Subsequence matching needs a few characters to say anything — 1-2 letters match everything.
	private static final int MIN_SUBSEQUENCE_QUERY = 3;

	private SearchMatcher()
	{
	}

	static int score(String name, String query)
	{
		final String n = name.toLowerCase(Locale.ROOT);
		final String q = query.toLowerCase(Locale.ROOT).trim();
		if (q.isEmpty())
		{
			return 0;
		}
		final int lengthPenalty = Math.min(n.length(), MAX_LENGTH_PENALTY);
		if (n.equals(q))
		{
			return TIER_EXACT;
		}
		if (n.startsWith(q))
		{
			return TIER_PREFIX - lengthPenalty;
		}
		if (wordPrefixes(n, q))
		{
			return TIER_WORD_PREFIX - lengthPenalty;
		}
		if (n.contains(q))
		{
			return TIER_SUBSTRING - lengthPenalty;
		}
		final String letters = q.replaceAll("\\s+", "");
		if (letters.length() >= MIN_SUBSEQUENCE_QUERY && isSubsequence(n, letters))
		{
			return TIER_SUBSEQUENCE - lengthPenalty;
		}
		return 0;
	}

	/** Every whitespace-separated query token prefixes a distinct name word, in order. */
	private static boolean wordPrefixes(String name, String query)
	{
		final String[] tokens = query.split("\\s+");
		final String[] words = name.split("[^a-z0-9]+");
		int w = 0;
		for (String token : tokens)
		{
			boolean matched = false;
			while (w < words.length)
			{
				if (words[w++].startsWith(token))
				{
					matched = true;
					break;
				}
			}
			if (!matched)
			{
				return false;
			}
		}
		return true;
	}

	/** The query's letters appear in the name in order, gaps allowed. */
	private static boolean isSubsequence(String name, String letters)
	{
		int i = 0;
		for (int j = 0; j < name.length() && i < letters.length(); j++)
		{
			if (name.charAt(j) == letters.charAt(i))
			{
				i++;
			}
		}
		return i == letters.length();
	}
}

package gps;

import com.google.inject.Inject;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import gps.pathfinder.PathStep;

public class PathMinimapOverlay extends Overlay
{
	private final Client client;
	private final ShortestPathPlugin plugin;

	@Inject
	private PathMinimapOverlay(Client client, ShortestPathPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	public static void renderMinimapRect(Client client, Graphics2D graphics, Point center, Color color)
	{
		double angle = client.getCameraYawTarget() * Perspective.UNIT;
		double tileSize = client.getMinimapZoom();
		int x = (int) Math.round(center.getX() - tileSize / 2);
		int y = (int) Math.round(center.getY() - tileSize / 2);
		int width = (int) Math.round(tileSize);
		int height = (int) Math.round(tileSize);
		graphics.setColor(color);
		graphics.rotate(angle, center.getX(), center.getY());
		graphics.fillRect(x, y, width, height);
		graphics.rotate(-angle, center.getX(), center.getY());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.drawMinimap || !plugin.hasPathTargets())
		{
			return null;
		}

		Shape minimapClipArea = plugin.getMinimapClipArea();
		if (minimapClipArea == null)
		{
			return null;
		}
		else
		{
			graphics.setClip(plugin.getMinimapClipArea());
		}
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);

		java.util.List<PathStep> pathPoints = plugin.getDisplayPath();
		Color pathColor = plugin.getPathColor();
		Color doneColor = new Color(0x80, 0x80, 0x80);
		// Same tri-state colouring as the scene: grey for the covered stretch, blocked colour past
		// the first un-crossed obstacle, normal in between.
		int progress = plugin.displayedRouteProgress();
		int blockedFrom = plugin.blockedFromIndex(pathPoints);
		for (int i = 0; i < pathPoints.size(); i++)
		{
			int pathPoint = pathPoints.get(i).getPackedPosition();
			if (WorldPointUtil.unpackWorldPlane(pathPoint) != client.getTopLevelWorldView().getPlane())
			{
				continue;
			}

			Color color = i <= progress ? doneColor
				: (i >= blockedFrom ? plugin.colourPathBlocked : pathColor);
			drawOnMinimap(graphics, pathPoint, color);
		}
		for (int target : plugin.getPathTargets())
		{
			if (!pathPoints.isEmpty() && target != pathPoints.get(pathPoints.size() - 1).getPackedPosition())
			{
				drawOnMinimap(graphics, target, plugin.colourPathCalculating);
			}
		}

		return null;
	}

	private void drawOnMinimap(Graphics2D graphics, int location, Color color)
	{
		PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, location);
		for (int i = 0; i < points.size(); i++)
		{
			LocalPoint lp = WorldPointUtil.toLocalPoint(client, points.get(i));

			if (lp == null)
			{
				continue;
			}

			Point posOnMinimap = Perspective.localToMinimap(client, lp);

			if (posOnMinimap == null)
			{
				continue;
			}

			renderMinimapRect(client, graphics, posOnMinimap, color);
		}
	}
}

package gps;

import java.util.Arrays;
import java.util.Collection;

/**
 * A lightweight hash map keyed by primitive {@code int} values using an open-addressed table with
 * linear probing.
 * <p>
 * Keys and values are stored in two parallel arrays ({@link #keys} / {@link #values}) rather than a
 * node object per entry, so the map holds only a couple of arrays regardless of how many entries it
 * contains (issue #491). A slot is occupied iff its value reference is non-null; since null values
 * are rejected, {@code int} keys including {@code 0} need no separate sentinel. When the entry count
 * reaches the configured {@linkplain #capacity load threshold} the table is rehashed into a larger
 * power-of-two array.
 * <p>
 * This implementation is intentionally minimal and tailored for the plugin's pathfinding needs:
 * <ul>
 * <li>No support for removing entries.</li>
 * <li>No iteration views (keys, values, or entry set) are exposed beyond {@link #keys()}.</li>
 * <li>Duplicate key insertion replaces the previous value, or appends collection contents when both
 * the old and new values are {@link Collection}s (best effort; falls back to replacement on
 * errors).</li>
 * </ul>
 *
 * @param <V> the value type stored for each primitive {@code int} key. Must be non-null.
 */
public class PrimitiveIntHashMap<V>
{
	private static final int MINIMUM_SIZE = 8;

	// How full the map should get before growing it again. Smaller values speed up
	// lookup times at the expense of space
	private static final float DEFAULT_LOAD_FACTOR = 0.75f;
	private final float loadFactor;
	private int[] keys;
	private Object[] values;
	private int size;
	private int capacity;
	private int maxSize;
	private int mask;

	/**
	 * Creates a new map with the specified initial size and the default load factor (0.75).
	 *
	 * @param initialSize initial expected number of elements; rounded to the next power of two
	 *                    internally.
	 */
	public PrimitiveIntHashMap(int initialSize)
	{
		this(initialSize, DEFAULT_LOAD_FACTOR);
	}

	/**
	 * Creates a new map with the given initial size and load factor.
	 *
	 * @param initialSize initial expected number of elements; rounded up to maintain a
	 *                    power-of-two capacity.
	 * @param loadFactor  a value in the range {@code [0.0, 1.0]} determining when the map rehashes.
	 * @throws IllegalArgumentException if {@code loadFactor} is outside the inclusive range 0..1.
	 */
	public PrimitiveIntHashMap(int initialSize, float loadFactor)
	{
		if (loadFactor < 0.0f || loadFactor > 1.0f)
		{
			throw new IllegalArgumentException("Load factor must be between 0 and 1");
		}

		this.loadFactor = loadFactor;
		size = 0;
		setNewSize(initialSize);
		recreateArrays();
	}

	/**
	 * Hash function tuned for packed world point integer encodings. Mixes higher bits downward to
	 * reduce clustering while remaining inexpensive.
	 */
	private static int hash(int value)
	{
		// Full multiplicative avalanche. Linear probing is very sensitive to clustering, and packed
		// world points of nearby tiles differ only in a few low bits, so the cheap xor-shift mix used
		// previously left spatially-clustered transport origins clustered in the table too -> long
		// probe runs on the per-tile miss lookups. Fibonacci-style multiply + xorshift spreads them.
		int h = value * 0x9E3779B1;
		return h ^ (h >>> 16);
	}

	/**
	 * Returns the number of key/value pairs currently stored.
	 *
	 * @return current entry count (always {@code >= 0}).
	 */
	public int size()
	{
		return size;
	}

	/**
	 * Returns all keys present in the map as a freshly allocated {@code int[]}.
	 *
	 * @return array of all keys in unspecified order; length equals {@link #size()}.
	 */
	@SuppressWarnings("unused")
	public int[] keys()
	{
		int[] result = new int[size];
		int index = 0;
		for (int i = 0; i < values.length; ++i)
		{
			if (values[i] != null)
			{
				result[index++] = keys[i];
			}
		}
		return result;
	}

	/**
	 * Retrieves the value mapped to the provided key, or {@code null} if absent.
	 *
	 * @param key primitive key to look up.
	 * @return the mapped value, or {@code null} if the key does not exist.
	 */
	public V get(int key)
	{
		return getOrDefault(key, null);
	}

	/**
	 * Retrieves the value mapped to the provided key.
	 *
	 * @param key          primitive key to look up.
	 * @param defaultValue value to return if the key is not present.
	 * @return the mapped value, or {@code defaultValue} when absent.
	 */
	@SuppressWarnings("unchecked")
	public V getOrDefault(int key, V defaultValue)
	{
		final int slot = findSlot(key);
		if (slot < 0)
		{
			return defaultValue;
		}
		return (V) values[slot];
	}

	/**
	 * Associates the specified value with the given key.
	 * <p>
	 * If a mapping already exists and both the existing and new values implement {@link Collection},
	 * the method attempts to append all elements of the new collection into the existing one. If the
	 * append fails (e.g., due to incompatible element types or an unsupported operation) the existing
	 * value is replaced entirely. Otherwise the existing value is simply replaced.
	 *
	 * @param key   primitive key to insert or update.
	 * @param value non-null value to associate.
	 * @param <E>   inferred element type if both values are collections.
	 * @return the previous value mapped to {@code key} (if any), or {@code null} if inserting a new
	 * entry.
	 * @throws IllegalArgumentException if {@code value} is {@code null}.
	 */
	@SuppressWarnings({"unchecked"})
	public <E> V put(int key, V value)
	{
		if (value == null)
		{
			throw new IllegalArgumentException("Cannot insert a null value");
		}

		int i = (hash(key) & 0x7FFFFFFF) & mask;
		while (values[i] != null)
		{
			if (keys[i] == key)
			{
				V previous = (V) values[i];
				if (previous instanceof Collection<?> && value instanceof Collection<?>)
				{ // append
					try
					{
						Collection<E> prevCollection = (Collection<E>) values[i];
						Collection<E> newCollection = (Collection<E>) value;
						prevCollection.addAll(newCollection);
					}
					catch (ClassCastException | UnsupportedOperationException e)
					{
						// If the collections contain incompatible types or the operation is not
						// supported, just replace instead of append
						values[i] = value;
					}
				}
				else
				{ // replace
					values[i] = value;
				}
				return previous;
			}
			i = (i + 1) & mask;
		}

		keys[i] = key;
		values[i] = value;
		incrementSize();
		return null;
	}

	private int findSlot(int key)
	{
		int i = (hash(key) & 0x7FFFFFFF) & mask;
		while (values[i] != null)
		{
			if (keys[i] == key)
			{
				return i;
			}
			i = (i + 1) & mask;
		}
		return -1;
	}

	private void incrementSize()
	{
		size++;
		if (size >= capacity)
		{
			rehash();
		}
	}

	private int getNewMaxSize(int size)
	{
		int nextPow2 = -1 >>> Integer.numberOfLeadingZeros(size);
		if (nextPow2 >= (Integer.MAX_VALUE >>> 1))
		{
			return (Integer.MAX_VALUE >>> 1) + 1;
		}
		return nextPow2 + 1;
	}

	private void setNewSize(int size)
	{
		if (size < MINIMUM_SIZE)
		{
			size = MINIMUM_SIZE - 1;
		}

		maxSize = getNewMaxSize(size);
		mask = maxSize - 1;
		capacity = (int) (maxSize * loadFactor);
	}

	private void growCapacity()
	{
		setNewSize(maxSize);
	}

	// Grow the table then rehash all the values into it and discard the old arrays
	private void rehash()
	{
		growCapacity();

		final int[] oldKeys = keys;
		final Object[] oldValues = values;
		recreateArrays();

		for (int i = 0; i < oldValues.length; ++i)
		{
			if (oldValues[i] == null)
			{
				continue;
			}

			int slot = (hash(oldKeys[i]) & 0x7FFFFFFF) & mask;
			while (values[slot] != null)
			{
				slot = (slot + 1) & mask;
			}
			keys[slot] = oldKeys[i];
			values[slot] = oldValues[i];
		}
	}

	private void recreateArrays()
	{
		keys = new int[maxSize];
		values = new Object[maxSize];
	}

	/**
	 * Approximate fullness of the table as a percentage of the entry count over the table length.
	 *
	 * @return fullness percentage in {@code [0.0, 100.0]}, or {@link Double#NaN} when the map is
	 * empty.
	 */
	public double calculateFullness()
	{
		if (size == 0)
		{
			return Double.NaN;
		}
		return 100.0 * (double) size / (double) maxSize;
	}

	/**
	 * Removes all entries from the map. The backing arrays are retained and reused.
	 */
	public void clear()
	{
		size = 0;
		Arrays.fill(values, null);
	}
}

package gps;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.gameval.ObjectID;

/**
 * Maps the furniture object ids seen in a scanned player-owned house to the config declarations
 * they imply. Pure logic over object ids (the plugin supplies them from the live scene), so the
 * mapping is unit-testable.
 * <p>
 * Only furniture with an EXACT 1:1 config mapping is auto-detected — the jewellery box (its tier),
 * fairy ring, spirit tree and obelisk. The "Teleport portals & nexus" and "Mounted items" toggles
 * each bundle several furniture pieces, some with no stable object id (the portal nexus and the
 * functional glory/Xeric's/digsite mounts), so auto-enabling them would claim furniture GPS can't
 * verify; those stay manual.
 */
public final class PohScanner
{
	private PohScanner()
	{
	}

	/** What a house scan found: the present 1:1 features, and the jewellery-box tier. */
	public static final class Detected
	{
		final boolean fairyRing;
		final boolean spiritTree;
		final boolean obelisk;
		final JewelleryBoxTier jewelleryBox;

		Detected(boolean fairyRing, boolean spiritTree, boolean obelisk, JewelleryBoxTier jewelleryBox)
		{
			this.fairyRing = fairyRing;
			this.spiritTree = spiritTree;
			this.obelisk = obelisk;
			this.jewelleryBox = jewelleryBox;
		}

		boolean any()
		{
			return fairyRing || spiritTree || obelisk || jewelleryBox != JewelleryBoxTier.NONE;
		}

		boolean sameAs(Detected other)
		{
			return other != null
				&& fairyRing == other.fairyRing
				&& spiritTree == other.spiritTree
				&& obelisk == other.obelisk
				&& jewelleryBox == other.jewelleryBox;
		}
	}

	/**
	 * Serializes a scan result for cross-session storage: the jewellery-box tier followed by the
	 * present feature flags, comma-separated (e.g. {@code "ORNATE,fairyRing,obelisk"}).
	 */
	public static String encode(Detected detected)
	{
		if (detected == null)
		{
			return null;
		}
		StringBuilder sb = new StringBuilder(detected.jewelleryBox.name());
		if (detected.fairyRing)
		{
			sb.append(",fairyRing");
		}
		if (detected.spiritTree)
		{
			sb.append(",spiritTree");
		}
		if (detected.obelisk)
		{
			sb.append(",obelisk");
		}
		return sb.toString();
	}

	/** Parses {@link #encode}'s format. Null on missing or malformed data (treated as "never scanned"). */
	public static Detected decode(String encoded)
	{
		if (encoded == null || encoded.isEmpty())
		{
			return null;
		}
		String[] parts = encoded.split(",");
		JewelleryBoxTier tier;
		try
		{
			tier = JewelleryBoxTier.valueOf(parts[0]);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
		Set<String> flags = new HashSet<>(Arrays.asList(parts));
		return new Detected(flags.contains("fairyRing"), flags.contains("spiritTree"),
			flags.contains("obelisk"), tier);
	}

	/** Every furniture object id the scanner recognises — the spawn-event fast path filters on this. */
	private static final Set<Integer> RECOGNISED_IDS = Set.of(
		ObjectID.POH_FAIRY_RING, ObjectID.POH_FAIRY_HOUSE, ObjectID.POH_FAIRY_HOUSE_OPEN,
		ObjectID.POH_SPIRIT_TREE, ObjectID.POH_WILDERNESS_OBELISK,
		ObjectID.POH_JEWELLERY_BOX_1, ObjectID.POH_JEWELLERY_BOX_2, ObjectID.POH_JEWELLERY_BOX_3);

	/**
	 * Whether this object id is POH furniture the scanner recognises. These ids only exist inside
	 * player-owned houses, so one spawning is also proof the loaded scene is a house.
	 */
	public static boolean isRecognised(int objectId)
	{
		return RECOGNISED_IDS.contains(objectId);
	}

	public static Detected detect(Set<Integer> objectIds)
	{
		boolean fairyRing = objectIds.contains(ObjectID.POH_FAIRY_RING)
			|| objectIds.contains(ObjectID.POH_FAIRY_HOUSE)
			|| objectIds.contains(ObjectID.POH_FAIRY_HOUSE_OPEN);
		boolean spiritTree = objectIds.contains(ObjectID.POH_SPIRIT_TREE);
		boolean obelisk = objectIds.contains(ObjectID.POH_WILDERNESS_OBELISK);
		// Tiers are cumulative (each includes the ones below); pick the highest built.
		JewelleryBoxTier box = JewelleryBoxTier.NONE;
		if (objectIds.contains(ObjectID.POH_JEWELLERY_BOX_3))
		{
			box = JewelleryBoxTier.ORNATE;
		}
		else if (objectIds.contains(ObjectID.POH_JEWELLERY_BOX_2))
		{
			box = JewelleryBoxTier.FANCY;
		}
		else if (objectIds.contains(ObjectID.POH_JEWELLERY_BOX_1))
		{
			box = JewelleryBoxTier.BASIC;
		}
		return new Detected(fairyRing, spiritTree, obelisk, box);
	}
}

package gps;

import net.runelite.api.Client;
import static net.runelite.api.Constants.CHUNK_SIZE;
import static net.runelite.api.Perspective.LOCAL_COORD_BITS;
import net.runelite.api.Player;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;

/**
 * Utility functions for packing, unpacking, and transforming {@link WorldPoint}
 * coordinates as compact {@code int} values.
 * <p>
 * A packed world point encodes {@code x}, {@code y}, and {@code plane} into a
 * single 32-bit integer using:
 *
 * <pre>
 * bits 0..14   : x (15 bits)
 * bits 15..29  : y (15 bits)
 * bits 30..31  : plane (2 bits)
 * </pre>
 * <p>
 * This representation allows efficient storage and hashing of coordinates
 * within the pathfinding data structures.
 */
public class WorldPointUtil
{
	public static final int CHEBYSHEV_DISTANCE_METRIC = 1;
	public static final int EUCLIDEAN_SQUARED_DISTANCE_METRIC = 1414213562;
	public static final int MANHATTAN_DISTANCE_METRIC = 2;
	public static final int UNDEFINED = -1;

	/**
	 * Packs a {@link WorldPoint} into a compact {@code int} encoding.
	 *
	 * @param point world point (may be {@code null}).
	 * @return packed integer value, or {@link #UNDEFINED} if {@code point} is
	 * {@code null}.
	 */
	public static int packWorldPoint(WorldPoint point)
	{
		if (point == null)
		{
			return -1;
		}
		return packWorldPoint(point.getX(), point.getY(), point.getPlane());
	}

	/**
	 * Packs the provided coordinate triple into a single {@code int}.
	 * First 15 bits are {@code x}, next 15 bits are {@code y}, final 2 bits are the
	 * plane.
	 * Values are masked into range; overflow bits are discarded.
	 *
	 * @param x     world x (0..32767 effectively supported).
	 * @param y     world y (0..32767 effectively supported).
	 * @param plane plane (0..3).
	 * @return packed integer representation.
	 */
	public static int packWorldPoint(int x, int y, int plane)
	{
		return (x & 0x7FFF) | ((y & 0x7FFF) << 15) | ((plane & 0x3) << 30);
	}

	/**
	 * Unpacks a packed world point into a new {@link WorldPoint} instance.
	 *
	 * @param packedPoint packed coordinate.
	 * @return decoded {@link WorldPoint}.
	 */
	public static WorldPoint unpackWorldPoint(int packedPoint)
	{
		final int x = unpackWorldX(packedPoint);
		final int y = unpackWorldY(packedPoint);
		final int plane = unpackWorldPlane(packedPoint);
		return new WorldPoint(x, y, plane);
	}

	/**
	 * Extracts the x component from a packed world point.
	 *
	 * @param packedPoint packed coordinate.
	 * @return x value.
	 */
	public static int unpackWorldX(int packedPoint)
	{
		return packedPoint & 0x7FFF;
	}

	/**
	 * Extracts the y component from a packed world point.
	 *
	 * @param packedPoint packed coordinate.
	 * @return y value.
	 */
	public static int unpackWorldY(int packedPoint)
	{
		return (packedPoint >> 15) & 0x7FFF;
	}

	/**
	 * Extracts the plane component from a packed world point.
	 *
	 * @param packedPoint packed coordinate.
	 * @return plane value (0..3).
	 */
	public static int unpackWorldPlane(int packedPoint)
	{
		return (packedPoint >> 30) & 0x3;
	}

	/**
	 * Offsets a packed world point by {@code (dx, dy)} on the same plane.
	 *
	 * @param packedPoint base packed point.
	 * @param dx          delta x to add.
	 * @param dy          delta y to add.
	 * @return packed point after applying deltas.
	 */
	public static int dxdy(int packedPoint, int dx, int dy)
	{
		int x = unpackWorldX(packedPoint);
		int y = unpackWorldY(packedPoint);
		int z = unpackWorldPlane(packedPoint);
		return packWorldPoint(x + dx, y + dy, z);
	}

	/**
	 * Computes the distance between two packed points using Chebyshev metric
	 * (diagonal = 1).
	 */
	public static int distanceBetween(int previousPacked, int currentPacked)
	{
		return distanceBetween(previousPacked, currentPacked, 1);
	}

	/**
	 * Computes the 2D distance (ignoring plane) between two packed points using
	 * Chebyshev metric (diagonal = 1).
	 */
	public static int distanceBetween2D(int previousPacked, int currentPacked)
	{
		return distanceBetween2D(previousPacked, currentPacked, 1);
	}

	/**
	 * Computes distance between two packed points with selectable distance metric.
	 *
	 * @param previousPacked first packed point.
	 * @param currentPacked  second packed point.
	 * @param diagonal       {@code 1} for Chebyshev (max), {@code 2} for Manhattan
	 *                       (sum). Otherwise returns Euclidean squared distance.
	 * @return distance or {@code Integer.MAX_VALUE} if plane differs.
	 */
	public static int distanceBetween(int previousPacked, int currentPacked, int diagonal)
	{
		final int previousX = WorldPointUtil.unpackWorldX(previousPacked);
		final int previousY = WorldPointUtil.unpackWorldY(previousPacked);
		final int previousZ = WorldPointUtil.unpackWorldPlane(previousPacked);
		final int currentX = WorldPointUtil.unpackWorldX(currentPacked);
		final int currentY = WorldPointUtil.unpackWorldY(currentPacked);
		final int currentZ = WorldPointUtil.unpackWorldPlane(currentPacked);
		return distanceBetween(previousX, previousY, previousZ,
			currentX, currentY, currentZ, diagonal);
	}

	/**
	 * Computes 2D distance (ignoring plane) between two packed points with
	 * selectable metric.
	 *
	 * @see #distanceBetween(int, int, int, int, int, int, int)
	 */
	public static int distanceBetween2D(int previousPacked, int currentPacked, int diagonal)
	{
		final int previousX = WorldPointUtil.unpackWorldX(previousPacked);
		final int previousY = WorldPointUtil.unpackWorldY(previousPacked);
		final int currentX = WorldPointUtil.unpackWorldX(currentPacked);
		final int currentY = WorldPointUtil.unpackWorldY(currentPacked);
		return distanceBetween2D(previousX, previousY, currentX, currentY, diagonal);
	}

	/**
	 * Computes distance between two coordinates with selectable metric; returns
	 * {@code Integer.MAX_VALUE} if planes differ.
	 *
	 * @param previousX x of first point.
	 * @param previousY y of first point.
	 * @param previousZ plane of first point.
	 * @param currentX  x of second point.
	 * @param currentY  y of second point.
	 * @param currentZ  plane of second point.
	 * @param diagonal  metric selector ({@code 1}=Chebyshev, {@code 2}=Manhattan,
	 *                  otherwise Euclidean squared distance).
	 * @return distance or {@code Integer.MAX_VALUE} if planes differ.
	 */
	public static int distanceBetween(
		int previousX,
		int previousY,
		int previousZ,
		int currentX,
		int currentY,
		int currentZ,
		int diagonal)
	{
		final int dz = previousZ - currentZ;

		if (dz != 0)
		{
			return Integer.MAX_VALUE;
		}

		return distanceBetween2D(previousX, previousY, currentX, currentY, diagonal);
	}

	/**
	 * Computes a 2D distance using either Chebyshev, Manhattan or Euclidean squared
	 * distance metric.
	 *
	 * @param previousX x of first point.
	 * @param previousY y of first point.
	 * @param currentX  x of second point.
	 * @param currentY  y of second point.
	 * @param diagonal  metric selector ({@code 1}=Chebyshev, {@code 2}=Manhattan,
	 *                  otherwise Euclidean squared distance).
	 * @return distance.
	 */
	public static int distanceBetween2D(int previousX, int previousY,
		int currentX, int currentY, int diagonal)
	{
		final int dx = previousX - currentX;
		final int dy = previousY - currentY;

		if (diagonal == CHEBYSHEV_DISTANCE_METRIC)
		{
			return Math.max(Math.abs(dx), Math.abs(dy));
		}
		else if (diagonal == MANHATTAN_DISTANCE_METRIC)
		{
			return Math.abs(dx) + Math.abs(dy);
		}

		return dx * dx + dy * dy;
	}

	/**
	 * Convenience overload using Chebyshev distance between two
	 * {@link WorldPoint}s.
	 */
	public static int distanceBetween(WorldPoint previous, WorldPoint current)
	{
		return distanceBetween(previous, current, 1);
	}

	/**
	 * Distance between two {@link WorldPoint}s with selectable metric.
	 *
	 * @see #distanceBetween(int, int, int, int, int, int, int)
	 */
	public static int distanceBetween(WorldPoint previous, WorldPoint current, int diagonal)
	{
		return distanceBetween(previous.getX(), previous.getY(), previous.getPlane(),
			current.getX(), current.getY(), current.getPlane(), diagonal);
	}

	/**
	 * Distance from a packed point to a {@link WorldArea} using Chebyshev metric,
	 * respecting plane.
	 * Returns {@code Integer.MAX_VALUE} if the plane differs.
	 */
	public static int distanceToArea(int packedPoint, WorldArea area)
	{
		final int plane = unpackWorldPlane(packedPoint);
		if (area.getPlane() != plane)
		{
			return Integer.MAX_VALUE;
		}
		return distanceToArea2D(packedPoint, area);
	}

	/**
	 * 2D distance (Chebyshev) from a packed point to a {@link WorldArea} ignoring
	 * plane, equivalent to
	 * {@link WorldArea#distanceTo(WorldPoint)} semantics in 2D.
	 */
	public static int distanceToArea2D(int packedPoint, WorldArea area)
	{
		final int y = unpackWorldY(packedPoint);
		final int x = unpackWorldX(packedPoint);
		final int areaMaxX = area.getX() + area.getWidth() - 1;
		final int areaMaxY = area.getY() + area.getHeight() - 1;
		final int dx = Math.max(Math.max(area.getX() - x, 0), x - areaMaxX);
		final int dy = Math.max(Math.max(area.getY() - y, 0), y - areaMaxY);

		return Math.max(dx, dy);
	}

	private static int rotate(int originalX, int originalY, int z, int rotation)
	{
		int chunkX = originalX & -CHUNK_SIZE;
		int chunkY = originalY & -CHUNK_SIZE;
		int x = originalX & (CHUNK_SIZE - 1);
		int y = originalY & (CHUNK_SIZE - 1);
		switch (rotation)
		{
			case 1:
				return packWorldPoint(chunkX + y, chunkY + (CHUNK_SIZE - 1 - x), z);
			case 2:
				return packWorldPoint(chunkX + (CHUNK_SIZE - 1 - x), chunkY + (CHUNK_SIZE - 1 - y), z);
			case 3:
				return packWorldPoint(chunkX + (CHUNK_SIZE - 1 - y), chunkY + x, z);
		}
		return packWorldPoint(originalX, originalY, z);
	}

	private static int unpackChunkRotation(int chunkData)
	{
		return chunkData >> 1 & 0x3;
	}

	private static int unpackChunkTemplateY(int chunkData)
	{
		return (chunkData >> 3 & 0x7FF) * CHUNK_SIZE;
	}

	private static int unpackChunkTemplateX(int chunkData)
	{
		return (chunkData >> 14 & 0x3FF) * CHUNK_SIZE;
	}

	private static int unpackChunkTemplatePlane(int chunkData)
	{
		return chunkData >> 24 & 0x3;
	}

	/**
	 * A compact human-readable summary of an instance's template chunk origins, for debug logging:
	 * the distinct template chunk world coordinates, deduplicated, capped at 40 entries. "not an
	 * instance" when the world view isn't one.
	 */
	public static String describeInstanceChunks(WorldView worldView)
	{
		if (worldView == null || !worldView.isInstance())
		{
			return "not an instance";
		}
		int[][][] chunks = worldView.getInstanceTemplateChunks();
		if (chunks == null)
		{
			return "no chunk data";
		}
		java.util.LinkedHashSet<String> seen = new java.util.LinkedHashSet<>();
		for (int[][] planeChunks : chunks)
		{
			if (planeChunks == null)
			{
				continue;
			}
			for (int[] column : planeChunks)
			{
				if (column == null)
				{
					continue;
				}
				for (int chunkData : column)
				{
					if (chunkData == -1)
					{
						continue;
					}
					seen.add("(" + unpackChunkTemplateX(chunkData) + "," + unpackChunkTemplateY(chunkData)
						+ ",p" + unpackChunkTemplatePlane(chunkData) + ")");
					if (seen.size() >= 40)
					{
						return String.join(" ", seen) + " …";
					}
				}
			}
		}
		return seen.isEmpty() ? "all chunks empty" : String.join(" ", seen);
	}

	public static int fromLocalInstance(Client client, Player localPlayer)
	{
		WorldView worldView = localPlayer.getWorldView();
		int worldViewId = worldView.getId();
		boolean isOnBoat = worldViewId != WorldView.TOPLEVEL;
		if (isOnBoat)
		{
			// The boat is a WorldEntity in the top level; byIndex is briefly null during view
			// transitions (boarding, chunk swaps) — a single NPE here used to stall every
			// position consumer for the rest of the session. Resolution goes through
			// RuneLite's own fromLocalInstance, which stays correct on the open sea
			// (port-tasks' path matching depends on the same call mid-sail).
			WorldEntity worldEntity = client.getTopLevelWorldView().worldEntities().byIndex(worldViewId);
			if (worldEntity == null)
			{
				return UNDEFINED;
			}
			net.runelite.api.coords.LocalPoint boatLocal = worldEntity.getLocalLocation();
			if (boatLocal == null)
			{
				return UNDEFINED;
			}
			net.runelite.api.coords.WorldPoint world =
				net.runelite.api.coords.WorldPoint.fromLocalInstance(client, boatLocal);
			return world != null
				? packWorldPoint(world.getX(), world.getY(), world.getPlane())
				: UNDEFINED;
		}
		return fromLocalInstance(client, localPlayer.getLocalLocation());
	}

	/**
	 * Converts an instanced {@link LocalPoint} to its corresponding packed world
	 * point coordinate, resolving the
	 * underlying template chunk mapping and rotation.
	 *
	 * @param client     RuneLite client.
	 * @param localPoint local scene coordinate.
	 * @return packed world point.
	 */
	public static int fromLocalInstance(Client client, LocalPoint localPoint)
	{
		WorldView worldView = client.getWorldView(localPoint.getWorldView());
		int plane = worldView.getPlane();

		if (!worldView.isInstance())
		{
			return packWorldPoint(
				(localPoint.getX() >> LOCAL_COORD_BITS) + worldView.getBaseX(),
				(localPoint.getY() >> LOCAL_COORD_BITS) + worldView.getBaseY(),
				plane);
		}

		int[][][] instanceTemplateChunks = worldView.getInstanceTemplateChunks();

		// get position in the scene
		int sceneX = localPoint.getSceneX();
		int sceneY = localPoint.getSceneY();

		// get chunk from scene
		int chunkX = sceneX / CHUNK_SIZE;
		int chunkY = sceneY / CHUNK_SIZE;

		// get the template chunk for the chunk
		int templateChunk = instanceTemplateChunks[plane][chunkX][chunkY];

		int rotation = unpackChunkRotation(templateChunk);
		int templateChunkY = unpackChunkTemplateY(templateChunk);
		int templateChunkX = unpackChunkTemplateX(templateChunk);
		int templateChunkPlane = unpackChunkTemplatePlane(templateChunk);

		// calculate world point of the template
		int x = templateChunkX + (sceneX & (CHUNK_SIZE - 1));
		int y = templateChunkY + (sceneY & (CHUNK_SIZE - 1));

		// create and rotate point back to 0, to match with template
		return rotate(x, y, templateChunkPlane, 4 - rotation);
	}

	/**
	 * Converts a packed world point to one or more packed world points representing
	 * its locations within an instanced
	 * map (e.g., dungeons or raids). If the current top-level world is not
	 * instanced, the result contains exactly the
	 * original point.
	 *
	 * @param client      RuneLite client.
	 * @param packedPoint packed world coordinate.
	 * @return list of packed coordinates valid in the current instance.
	 */
	public static PrimitiveIntList toLocalInstance(Client client, int packedPoint)
	{
		WorldView worldView = client.getTopLevelWorldView();

		PrimitiveIntList worldPoints = new PrimitiveIntList();
		if (!worldView.isInstance())
		{
			worldPoints.add(packedPoint);
			return worldPoints;
		}

		int baseX = worldView.getBaseX();
		int baseY = worldView.getBaseY();
		int worldPointX = unpackWorldX(packedPoint);
		int worldPointY = unpackWorldY(packedPoint);
		int worldPointPlane = unpackWorldPlane(packedPoint);

		int[][][] instanceTemplateChunks = worldView.getInstanceTemplateChunks();

		// find instance chunks using the template point. there might be more than one.
		for (int z = 0; z < instanceTemplateChunks.length; z++)
		{
			for (int x = 0; x < instanceTemplateChunks[z].length; ++x)
			{
				for (int y = 0; y < instanceTemplateChunks[z][x].length; ++y)
				{
					int chunkData = instanceTemplateChunks[z][x][y];
					int rotation = unpackChunkRotation(chunkData);
					int templateChunkY = unpackChunkTemplateY(chunkData);
					int templateChunkX = unpackChunkTemplateX(chunkData);
					int plane = unpackChunkTemplatePlane(chunkData);
					if (worldPointX >= templateChunkX && worldPointX < templateChunkX + CHUNK_SIZE
						&& worldPointY >= templateChunkY && worldPointY < templateChunkY + CHUNK_SIZE
						&& plane == worldPointPlane)
					{
						worldPoints.add(rotate(
							baseX + x * CHUNK_SIZE + (worldPointX & (CHUNK_SIZE - 1)),
							baseY + y * CHUNK_SIZE + (worldPointY & (CHUNK_SIZE - 1)),
							z,
							rotation));
					}
				}
			}
		}
		return worldPoints;
	}

	private static boolean isInScene(WorldView worldView, int packedPoint)
	{
		int x = unpackWorldX(packedPoint);
		int y = unpackWorldY(packedPoint);

		int baseX = worldView.getBaseX();
		int baseY = worldView.getBaseY();

		int maxX = baseX + worldView.getSizeX();
		int maxY = baseY + worldView.getSizeY();

		return x >= baseX && x < maxX && y >= baseY && y < maxY;
	}

	/**
	 * Converts a packed world point into a {@link LocalPoint} relative to the
	 * top-level world view if it resides in
	 * the currently loaded scene and on the same plane; returns {@code null}
	 * otherwise.
	 *
	 * @param client      RuneLite client.
	 * @param packedPoint packed world point.
	 * @return {@link LocalPoint} or {@code null} if out of scene or plane.
	 */
	public static LocalPoint toLocalPoint(Client client, int packedPoint)
	{
		WorldView worldView = client.getTopLevelWorldView();

		if (worldView.getPlane() != unpackWorldPlane(packedPoint))
		{
			return null;
		}

		if (!isInScene(worldView, packedPoint))
		{
			return null;
		}

		return new LocalPoint(
			(unpackWorldX(packedPoint) - worldView.getBaseX() << LOCAL_COORD_BITS) + (1 << LOCAL_COORD_BITS - 1),
			(unpackWorldY(packedPoint) - worldView.getBaseY() << LOCAL_COORD_BITS) + (1 << LOCAL_COORD_BITS - 1),
			worldView.getId());
	}
}

package gps;

import java.awt.Graphics2D;
import java.awt.geom.AffineTransform;
import java.awt.geom.Path2D;

/**
 * Draws a small triangular arrowhead at the end of a line segment, rotated to the segment's
 * direction, in the current colour of the graphics context.
 * <p>
 * Adapted from Quest Helper's {@code DirectionArrow.drawLineArrowHead}
 * (Copyright (c) 2021, Zoinkwiz &lt;https://github.com/Zoinkwiz&gt;, BSD 2-Clause licence),
 * as also used by the port-tasks plugin.
 */
public final class ArrowHead
{
	private ArrowHead()
	{
	}

	/**
	 * Fills an arrowhead pointing from (x1, y1) towards (x2, y2), with its tip at (x2, y2).
	 *
	 * @param size length of the arrowhead in pixels (its width is {@code size})
	 */
	public static void draw(Graphics2D graphics, double x1, double y1, double x2, double y2, double size)
	{
		Path2D head = new Path2D.Double();
		head.moveTo(0, 0);
		head.lineTo(-size / 2.0, -size);
		head.lineTo(size / 2.0, -size);
		head.closePath();

		AffineTransform tx = new AffineTransform();
		double angle = Math.atan2(y2 - y1, x2 - x1);
		tx.translate(x2, y2);
		tx.rotate(angle - Math.PI / 2d);

		Graphics2D g = (Graphics2D) graphics.create();
		// Compose (not replace) so the overlay's existing transform/clip stay intact.
		g.transform(tx);
		g.fill(head);
		g.dispose();
	}
}

