	/** An icon-only quick button running one nearest-X option directly (tooltip names it). */
	private JButton nearestQuickButton(String optionId)
	{
		for (Destinations.NearestOption option : Destinations.NEAREST_OPTIONS)
		{
			if (option.id.equals(optionId))
			{
				JButton button = subtleButton(new JButton(RouteIcons.destinationIcon(option.id)));
				button.setToolTipText("Nearest " + option.label.toLowerCase(java.util.Locale.ROOT));
				button.addActionListener(e -> runNearestOption(option));
				return button;
			}
		}
		return null;
	}

	/** Shared subtle-button chrome: small font, outline, tight padding, hand cursor, hover lift. */
	private static JButton subtleButton(JButton button)
	{
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setForeground(Color.WHITE);
		button.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
		button.setFocusPainted(false);
		button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		button.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(3, 8, 3, 8)));
		button.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				button.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				button.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}
		});
		return button;
	}

	/** Runs one nearest-X option — shared by the menu items and the quick buttons. */
	private void runNearestOption(Destinations.NearestOption option)
	{
		Set<Integer> tiles = Destinations.tilesForCategory(option.id, plugin.getTransports());
		boolean roundTrip = "bank_round_trip".equals(option.id);
		if ("bank".equals(option.id) || roundTrip)
		{
			// Union in the engine's accessible-bank tiles: the amenity dump misses oddly-named
			// bank objects (e.g. Slepe's "Bank Chest-wreck"), and "nearest bank" must never
			// disagree with where the engine itself can bank.
			tiles.addAll(plugin.getEngineBankTiles());
		}
		plugin.setNearestCategory(tiles,
			"nearest " + option.label.toLowerCase(java.util.Locale.ROOT), roundTrip);
		destinationSearch.setText("");
	}

	private void showNearestMenu(JComponent anchor)
	{
		JPopupMenu menu = new JPopupMenu();
		menu.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		menu.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		for (Destinations.NearestOption option : Destinations.NEAREST_OPTIONS)
		{
			JMenuItem item = new JMenuItem(option.label, RouteIcons.destinationIcon(option.id));
			item.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			item.setForeground(Color.WHITE);
			item.setFont(FontManager.getRunescapeSmallFont());
			item.setIconTextGap(6);
			item.addActionListener(e -> runNearestOption(option));
			menu.add(item);
		}
		menu.show(anchor, 0, anchor.getHeight());
	}

	/** The cached name-search index; (re)built only once the transport data is available. */
	private List<Destinations.Entry> destinationIndex()
	{
		List<Destinations.Entry> cached = destinationIndex;
		if (cached != null)
		{
			return cached;
		}
		List<Destinations.Entry> built = Destinations.searchable(plugin.getTransports());
		if (plugin.getTransports() != null)
		{
			destinationIndex = built;
		}
		return built;
	}

	private void renderDestinationResults()
	{
		destinationResults.removeAll();
		resultRows.clear();
		resultEntries.clear();
		selectedResult = -1;
		String query = destinationSearch.getText().trim();
		final int player = plugin.getLastKnownPlayerLocation();
		if (query.isEmpty())
		{
			// An empty box offers the saved favourites and the recent selections instead of hiding —
			// reopening a frequent destination without retyping it.
			List<Destinations.Entry> favorites = plugin.getFavoriteDestinations();
			List<Destinations.Entry> history = plugin.getSearchHistory();
			if (favorites.isEmpty() && history.isEmpty())
			{
				destinationPopup.setVisible(false);
				return;
			}
			if (!favorites.isEmpty())
			{
				destinationResults.add(resultsHeader("Favourites"));
				for (Destinations.Entry entry : favorites)
				{
					addResultRow(entry, player);
				}
			}
			if (!history.isEmpty())
			{
				destinationResults.add(resultsHeader("Recent searches"));
				for (Destinations.Entry entry : history)
				{
					addResultRow(entry, player);
				}
			}
			preselectFirstResult();
			showDestinationPopup();
			return;
		}

		// A typed coordinate pair ("3221, 3218", "3221 3218", optional plane "3221 3218 1") becomes
		// a direct route-to-tile result ahead of the name matches.
		int coordinate = parseCoordinateQuery(query);
		if (coordinate != WorldPointUtil.UNDEFINED)
		{
			int plane = WorldPointUtil.unpackWorldPlane(coordinate);
			addResultRow(new Destinations.Entry("coordinates",
				"Tile (" + WorldPointUtil.unpackWorldX(coordinate) + ", " + WorldPointUtil.unpackWorldY(coordinate)
					+ (plane > 0 ? ", plane " + plane : "") + ")",
				coordinate), player);
		}

		// Fuzzy match, best first: the score tiers (exact > prefix > word prefixes > substring >
		// subsequence) rank the list; proximity to the player breaks ties within a tier. Saved
		// favourites are part of the pool, matched by their label.
		List<Destinations.Entry> pool = new ArrayList<>(plugin.getFavoriteDestinations());
		pool.addAll(destinationIndex());
		List<Destinations.Entry> matches = new ArrayList<>();
		Map<Destinations.Entry, Integer> scores = new java.util.HashMap<>();
		for (Destinations.Entry entry : pool)
		{
			int score = SearchMatcher.score(entry.name, query);
			if (score > 0)
			{
				matches.add(entry);
				scores.put(entry, score);
			}
		}
		Comparator<Destinations.Entry> byScore =
			Comparator.comparingInt(e -> -scores.getOrDefault(e, 0));
		if (player != WorldPointUtil.UNDEFINED)
		{
			matches.sort(byScore.thenComparingInt(
				e -> WorldPointUtil.distanceBetween(player, e.packedPosition)));
		}
		else
		{
			matches.sort(byScore.thenComparing(e -> e.name));
		}

		int shown = 0;
		for (Destinations.Entry entry : matches)
		{
			addResultRow(entry, player);
			if (++shown >= MAX_DESTINATION_RESULTS)
			{
				break;
			}
		}
		if (resultEntries.isEmpty())
		{
			JLabel none = new JLabel("No matching destination");
			none.setForeground(Color.GRAY);
			none.setFont(FontManager.getRunescapeSmallFont());
			none.setBorder(new EmptyBorder(2, 4, 2, 4));
			destinationResults.add(none);
		}
		preselectFirstResult();
		showDestinationPopup();
	}

	// "x, y" or "x y", with an optional plane (0-3): x is 4 digits (the playable range is roughly
	// 1000-4600), y 4-5 digits (surface ~3000-4200; dungeon/instance planes reach past 10000).
	private static final java.util.regex.Pattern COORDINATE_QUERY =
		java.util.regex.Pattern.compile("(\\d{4})[,;\\s]+(\\d{4,5})(?:[,;\\s]+([0-3]))?");

	/**
	 * Parses a typed coordinate query into a packed world point, or {@link WorldPointUtil#UNDEFINED}
	 * when the text isn't a plausible in-world coordinate pair.
	 */
	static int parseCoordinateQuery(String query)
	{
		java.util.regex.Matcher matcher = COORDINATE_QUERY.matcher(query);
		if (!matcher.matches())
		{
			return WorldPointUtil.UNDEFINED;
		}
		int x = Integer.parseInt(matcher.group(1));
		int y = Integer.parseInt(matcher.group(2));
		int plane = matcher.group(3) != null ? Integer.parseInt(matcher.group(3)) : 0;
		if (x > 4600 || y > 12900)
		{
			return WorldPointUtil.UNDEFINED;
		}
		return WorldPointUtil.packWorldPoint(x, y, plane);
	}

	/** Builds a result row, adds it to the popup and tracks it for keyboard navigation. */
	private void addResultRow(Destinations.Entry entry, int player)
	{
		JPanel row = destinationRow(entry, player);
		resultEntries.add(entry);
		resultRows.add(row);
		destinationResults.add(row);
	}

	/** A small grey group header inside the results popup ("Favourites", "Recent searches"). */
	private static JLabel resultsHeader(String text)
	{
		JLabel header = new JLabel(text);
		header.setForeground(Color.GRAY);
		header.setFont(FontManager.getRunescapeSmallFont());
		header.setBorder(new EmptyBorder(2, 4, 2, 4));
		return header;
	}

	// Inline favourite editor components (built in buildDestinationSearch).
	private final JPanel favoriteEditor = new JPanel();
	private final JTextField favoriteLabelInput = new JTextField();
	private final JTextField favoritePositionInput = new JTextField();
	private final JLabel favoriteError = new JLabel();

	/** A small captioned row for the favourite editor (caption west, component center). */
	private static JPanel favoriteFieldRow(String caption, java.awt.Component component)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setAlignmentX(LEFT_ALIGNMENT);
		JLabel label = new JLabel(caption);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setPreferredSize(new Dimension(34, label.getPreferredSize().height));
		row.add(label, BorderLayout.WEST);
		row.add(component, BorderLayout.CENTER);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, component.getPreferredSize().height + 4));
		return row;
	}

	/** The heart button: shows (or hides) the inline favourite editor, prefilled with the current tile. */
	private void toggleFavoriteEditor()
	{
		if (favoriteEditor.isVisible())
		{
			favoriteEditor.setVisible(false);
			return;
		}
		int player = plugin.getLastKnownPlayerLocation();
		String prefill = "";
		if (player != WorldPointUtil.UNDEFINED)
		{
			int plane = WorldPointUtil.unpackWorldPlane(player);
			prefill = WorldPointUtil.unpackWorldX(player) + " " + WorldPointUtil.unpackWorldY(player)
				+ (plane > 0 ? " " + plane : "");
		}
		favoriteLabelInput.setText("");
		favoritePositionInput.setText(prefill);
		favoriteError.setVisible(false);
		favoriteEditor.setVisible(true);
		favoriteEditor.revalidate();
		// Name first: type the label, Tab to adjust the (prefilled) position, Enter to save.
		favoriteLabelInput.requestFocusInWindow();
	}

	/** Enter/Save in the inline editor: label + position (empty position = current tile). */
	private void attemptSaveFavorite()
	{
		String label = favoriteLabelInput.getText().trim();
		if (label.isEmpty())
		{
			favoriteInputError("Name the favourite — it's what search results show.");
			favoriteLabelInput.requestFocusInWindow();
			return;
		}
		String positionText = favoritePositionInput.getText().trim();
		int position = positionText.isEmpty()
			? plugin.getLastKnownPlayerLocation() : parseCoordinateQuery(positionText);
		if (position == WorldPointUtil.UNDEFINED)
		{
			favoriteInputError(positionText.isEmpty()
				? "No position: log in, or type coordinates (\"3221 3218\", optional plane)."
				: "Not a coordinate: \"3221 3218\", \"3221,3218,1\" and \"3221, 3218 0\" all work.");
			favoritePositionInput.requestFocusInWindow();
			return;
		}
		plugin.addFavoriteDestination(label, position);
		favoriteEditor.setVisible(false);
		if (destinationPopup.isVisible())
		{
			renderDestinationResults();
		}
	}

	private void favoriteInputError(String message)
	{
		favoriteError.setText(message);
		favoriteError.setVisible(true);
		favoriteEditor.revalidate();
	}

	/** Preselects the top result so Enter works immediately; -1 when there are none. */
	private void preselectFirstResult()
	{
		selectedResult = resultRows.isEmpty() ? -1 : 0;
		applySelectionHighlight();
	}

	// Selected search-result row: a blue-tinted background plus a GPS-blue accent bar — the two
	// near-identical dark greys the highlight used before were invisible when arrowing through.
	private static final Color RESULT_SELECTED_BG = new Color(0x2E, 0x3E, 0x5E);

	/** Highlights the selected row (shared by keyboard and mouse) and resets the rest. */
	private void applySelectionHighlight()
	{
		for (int i = 0; i < resultRows.size(); i++)
		{
			boolean selected = i == selectedResult;
			JPanel row = resultRows.get(i);
			row.setBackground(selected ? RESULT_SELECTED_BG : ColorScheme.DARKER_GRAY_COLOR);
			// The accent bar replaces 3px of the left padding, so the row text doesn't shift.
			row.setBorder(selected
				? BorderFactory.createCompoundBorder(
					BorderFactory.createMatteBorder(0, 3, 0, 0, BANNER_INFO_ACCENT),
					new EmptyBorder(3, 1, 3, 4))
				: new EmptyBorder(3, 4, 3, 4));
		}
	}

	/** Moves the keyboard selection by {@code delta}, wrapping around the result list. */
	private void moveSelection(int delta)
	{
		if (resultRows.isEmpty())
		{
			return;
		}
		selectedResult = ((selectedResult + delta) % resultRows.size() + resultRows.size()) % resultRows.size();
		applySelectionHighlight();
	}

	/** Commits a destination selection (from a click or Enter): route to it, remember it, close. */
	private void selectEntry(Destinations.Entry entry)
	{
		plugin.setDestination(entry.packedPosition, "search");
		plugin.recordSearchSelection(entry);
		// Clearing the text re-renders the popup with the recent list; a selection should end the
		// interaction instead.
		destinationSearch.setText("");
		destinationPopup.setVisible(false);
	}

	/**
	 * Floats the results over the panel, matching the search field's width. Re-showing on every
	 * keystroke would flicker and can steal the caret, so a visible popup is resized in place.
	 */
	private void showDestinationPopup()
	{
		int width = Math.max(destinationSearch.getWidth(), 180);
		destinationPopup.setPreferredSize(new Dimension(width,
			destinationResults.getPreferredSize().height + 2));
		if (destinationPopup.isVisible())
		{
			destinationPopup.revalidate();
			destinationPopup.repaint();
			destinationPopup.pack();
		}
		else
		{
			destinationPopup.show(destinationSearch, 0, destinationSearch.getHeight());
		}
	}

	private JPanel destinationRow(Destinations.Entry entry, int player)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(3, 4, 3, 4));
		row.setCursor(new Cursor(Cursor.HAND_CURSOR));

		JLabel name = new JLabel(entry.name, RouteIcons.destinationIcon(entry.category), SwingConstants.LEADING);
		name.setIconTextGap(3);
		name.setForeground(Color.WHITE);
		name.setFont(FontManager.getRunescapeSmallFont());
		row.add(name, BorderLayout.CENTER);

		JPanel east = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		east.setOpaque(false);
		if (player != WorldPointUtil.UNDEFINED)
		{
			int distance = WorldPointUtil.distanceBetween(player, entry.packedPosition);
			if (distance != Integer.MAX_VALUE)
			{
				JLabel dist = new JLabel(distance + " tiles");
				dist.setForeground(Color.GRAY);
				dist.setFont(FontManager.getRunescapeSmallFont());
				east.add(dist);
			}
		}
		if ("favorite".equals(entry.category))
		{
			east.add(new IconActionLabel(RouteIcons.CROSS, RouteIcons.CROSS_HOVER,
				"Remove this favourite", () ->
			{
				plugin.removeFavoriteDestination(entry);
				renderDestinationResults();
			}));
		}
		if (east.getComponentCount() > 0)
		{
			row.add(verticallyCentered(east), BorderLayout.EAST);
		}

		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				selectEntry(entry);
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				// Move the shared selection to the hovered row so keyboard and mouse agree.
				selectedResult = resultRows.indexOf(row);
				applySelectionHighlight();
			}
		});
		return row;
	}

	private static Icon categoryDot(String category)
	{
		return dot(categoryColour(category));
	}

	private static Icon dot(Color colour)
	{
		final int s = 9;
		BufferedImage image = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(colour);
		g.fillRoundRect(0, 1, s - 1, s - 2, 4, 4);
		g.dispose();
		return new ImageIcon(image);
	}

	/**
	 * Fixed, deliberately-distinct colour per known category (the old hash assignment gave
	 * "Boats & ships" the exact same teal as the permanent-item dot). Items are teal to match the
	 * permanent-item dot; charged items get the amber dot via {@link #methodDot}. The hashed
	 * palette remains only as a fallback for categories added later.
	 */
	private static Color categoryColour(String category)
	{
		switch (category)
		{
			case "Spells": return new Color(0x5B, 0x9B, 0xD5);          // blue
			case "Items": return PERMANENT_ITEM_DOT;                     // teal (charged = amber)
			case "Jewellery box": return new Color(0xB4, 0x6F, 0xD4);   // purple
			case "Levers": return new Color(0xD1, 0x5B, 0x5B);          // red
			case "Minigame teleports": return new Color(0xE5, 0x73, 0x99); // pink
			case "Portals": return new Color(0x9C, 0x7B, 0xE8);         // violet
			case "Fairy rings": return new Color(0x4C, 0xAF, 0x50);     // green
			case "Spirit trees": return new Color(0x8B, 0xC3, 0x4A);    // lime
			case "Gnome gliders": return new Color(0xC9, 0x69, 0xC9);   // magenta
			case "Hot air balloons": return new Color(0xE9, 0x7D, 0x3B); // orange
			case "Magic carpets": return new Color(0xB0, 0x3A, 0x5B);   // wine
			case "Mushtrees": return new Color(0xE0, 0x60, 0x60);       // light red
			case "Minecarts": return new Color(0x60, 0x7D, 0x8B);       // slate
			case "Mountain guides": return new Color(0x8D, 0x6E, 0x63); // mountain brown
			case "Quetzals": return new Color(0x4A, 0xC6, 0xE0);        // cyan
			case "Obelisks": return new Color(0x9A, 0xA5, 0xB1);        // steel
			case "Boats & ships": return new Color(0x5C, 0x6B, 0xC0);   // indigo — NOT the item teal
			case "Canoes": return new Color(0xB5, 0x79, 0x3B);          // wood brown
			case "Seasonal": return new Color(0x94, 0xB4, 0x4A);        // olive
			default: return CATEGORY_PALETTE[Math.floorMod(category.hashCode(), CATEGORY_PALETTE.length)];
		}
	}

	private static String escapeHtml(String text)
	{
		if (text == null)
		{
			return "";
		}
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private static Component verticalGap(int height)
	{
		JPanel gap = new JPanel();
		gap.setBackground(ColorScheme.DARK_GRAY_COLOR);
		gap.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		gap.setPreferredSize(new Dimension(1, height));
		return gap;
	}
}

package gps;

import java.util.List;
import java.util.Set;
import lombok.Getter;
import gps.pathfinder.PathStep;
import gps.transport.Transport;

/**
 * One alternative route to the target, produced by {@link AlternativeRoutesService}. Each route is a
 * shortest path under the constraint that it uses a different set of teleport/transport methods than
 * the other routes in the same result list.
 */
@Getter
public final class RouteOption
{
	/**
	 * The full tile path, as returned by the pathfinder.
	 */
	private final List<PathStep> path;
	/**
	 * The teleport/transport methods used along the path, in travel order. Empty for a walk-only route.
	 */
	private final List<TeleportMethod> methods;
	/**
	 * Path index of the edge each method sits on, parallel to {@link #methods}: the index of the path
	 * step the method arrives at. Authoritative method positions for the directions overlay — the
	 * route was computed with the planning config's availability, so its methods cannot be reliably
	 * re-derived against the main config's.
	 */
	private final List<Integer> methodEdgeIndexes;
	/**
	 * Travel time of each method's transport in game ticks, parallel to {@link #methods} — for the
	 * directions overlay's time estimates.
	 */
	private final List<Integer> methodDurations;
	/**
	 * Blended search cost in CostUnits (run-tiles, 0.3s each): time-normalized walk + transport
	 * travel, plus any configured method weights. Routes are ordered by this; lower is faster.
	 */
	private final int totalCost;
	/**
	 * The path's cost without any configured weights, in CostUnits (run-tiles, 0.3s each): its ETA.
	 * Equal to {@link #totalCost} when no weights applied to this route.
	 */
	private final int rawCost;
	/**
	 * Whether the path actually reaches the exact target. When false it ends at the closest reachable
	 * tile (mirrors Shortest Path's own behaviour for unreachable targets, e.g. an NPC/object tile).
	 */
	private final boolean reached;
	/**
	 * The subset of {@link #methods} that require an item that must first be withdrawn from the bank —
	 * the path includes a walk to a bank before each of these is used. Empty when the route needs no
	 * bank visit. Lets the panel say <em>which</em> method the bank detour is for.
	 */
	private final Set<TeleportMethod> bankMethods;
	/**
	 * Plain connectors (not methods) the route can only use after the bank - a jungle bush
	 * needing a banked machete. Named in the withdraw step; never on the card.
	 */
	private final List<Transport> bankTransports;
	/**
	 * Tiles walked before each method, parallel to {@link #methods} (walking to a minecart, a fairy
	 * ring, a bank, ...). Plain connectors along the way (doors, stairs, shortcuts) count into the leg.
	 */
	private final List<Integer> walkBeforeSteps;
	/**
	 * Tiles walked after the last method to the destination; the whole walk for walk-only routes.
	 */
	private final int trailingWalkSteps;
	/**
	 * For round trips (out to the destination and back to the start): the path index of the
	 * turnaround — the destination tile where the outbound leg ends. -1 for ordinary routes.
	 * A round trip's path ends where it began, and its return leg often retraces the outbound
	 * street, so progress tracking and the arrival check gate the return leg behind this index —
	 * otherwise walking OUT reads as coming back (instant false arrival).
	 */
	private final int turnaroundIndex;

	/**
	 * DEPARTURE indexes of this route's sailing jumps: values i such that the path edge
	 * path[i] -> path[i+1] is a SAILING leg. methodEdgeIndexes stores each transport edge by
	 * its ARRIVAL step (scanMethods records edge (i-1)->i as i) — an implicit convention that
	 * cost us an invisible off-by-one in the overlay (every sea leg permanently dashed); this
	 * method is the single place that arithmetic lives now, pinned by RouteOptionTest.
	 */
	public java.util.Set<Integer> sailingJumpDepartures()
	{
		// Memoized: the overlay asks once per rendered frame, and this object is immutable.
		// Benign race — concurrent first calls compute identical sets.
		java.util.Set<Integer> cached = sailingJumpDeparturesCache;
		if (cached != null)
		{
			return cached;
		}
		java.util.Set<Integer> departures = new java.util.HashSet<>();
		for (int i = 0; i < methods.size() && i < methodEdgeIndexes.size(); i++)
		{
			if (methods.get(i).getType() == gps.transport.TransportType.SAILING)
			{
				departures.add(methodEdgeIndexes.get(i) - 1);
			}
		}
		sailingJumpDeparturesCache = java.util.Collections.unmodifiableSet(departures);
		return sailingJumpDeparturesCache;
	}

	private transient volatile java.util.Set<Integer> sailingJumpDeparturesCache;

	public RouteOption(List<PathStep> path, List<TeleportMethod> methods, List<Integer> methodEdgeIndexes,
		List<Integer> methodDurations, int totalCost, int rawCost, boolean reached, Set<TeleportMethod> bankMethods,
		List<Integer> walkBeforeSteps, int trailingWalkSteps)
	{
		this(path, methods, methodEdgeIndexes, methodDurations, totalCost, rawCost, reached, bankMethods,
			List.of(), walkBeforeSteps, trailingWalkSteps, -1);
	}

	public RouteOption(List<PathStep> path, List<TeleportMethod> methods, List<Integer> methodEdgeIndexes,
		List<Integer> methodDurations, int totalCost, int rawCost, boolean reached, Set<TeleportMethod> bankMethods,
		List<Transport> bankTransports, List<Integer> walkBeforeSteps, int trailingWalkSteps)
	{
		this(path, methods, methodEdgeIndexes, methodDurations, totalCost, rawCost, reached, bankMethods,
			bankTransports, walkBeforeSteps, trailingWalkSteps, -1);
	}

	public RouteOption(List<PathStep> path, List<TeleportMethod> methods, List<Integer> methodEdgeIndexes,
		List<Integer> methodDurations, int totalCost, int rawCost, boolean reached, Set<TeleportMethod> bankMethods,
		List<Integer> walkBeforeSteps, int trailingWalkSteps, int turnaroundIndex)
	{
		this(path, methods, methodEdgeIndexes, methodDurations, totalCost, rawCost, reached, bankMethods,
			List.of(), walkBeforeSteps, trailingWalkSteps, turnaroundIndex);
	}

	public RouteOption(List<PathStep> path, List<TeleportMethod> methods, List<Integer> methodEdgeIndexes,
		List<Integer> methodDurations, int totalCost, int rawCost, boolean reached, Set<TeleportMethod> bankMethods,
		List<Transport> bankTransports, List<Integer> walkBeforeSteps, int trailingWalkSteps, int turnaroundIndex)
	{
		this.path = path;
		this.methods = methods;
		this.methodEdgeIndexes = methodEdgeIndexes;
		this.methodDurations = methodDurations;
		this.totalCost = totalCost;
		this.rawCost = rawCost;
		this.reached = reached;
		this.bankMethods = bankMethods;
		this.bankTransports = bankTransports == null ? List.of() : bankTransports;
		this.walkBeforeSteps = walkBeforeSteps;
		this.trailingWalkSteps = trailingWalkSteps;
		this.turnaroundIndex = turnaroundIndex;
	}

	/** Whether this route is a round trip — see {@link #turnaroundIndex}. */
	public boolean isRoundTrip()
	{
		return turnaroundIndex >= 0;
	}

	/**
	 * Tiles walked before the method at {@code index}, or 0 when unknown.
	 */
	public int walkBefore(int index)
	{
		return (index >= 0 && index < walkBeforeSteps.size()) ? walkBeforeSteps.get(index) : 0;
	}

	/**
	 * Whether one of this route's methods requires a bank withdrawal first (see {@link #bankMethods}).
	 */
	public boolean isViaBank()
	{
		return !bankMethods.isEmpty() || !bankTransports.isEmpty();
	}

	public boolean isWalkOnly()
	{
		return methods.isEmpty();
	}
}

package gps;

import java.util.ArrayList;
import java.util.List;

/**
 * The destination search's recent-selections list: the last {@link #LIMIT} picks, most recent
 * first, persisted across sessions as one config string (rows of {@code category\tname\tpacked}).
 * Pure functions — the plugin owns the stored copy and the config write.
 */
final class SearchHistory
{
	static final int LIMIT = 10;

	private SearchHistory()
	{
	}

	/** A new list with {@code entry} at the front, duplicates removed, capped at {@link #LIMIT}. */
	static List<Destinations.Entry> push(List<Destinations.Entry> history, Destinations.Entry entry)
	{
		List<Destinations.Entry> out = new ArrayList<>();
		out.add(entry);
		for (Destinations.Entry old : history)
		{
			if (out.size() >= LIMIT)
			{
				break;
			}
			if (old.packedPosition != entry.packedPosition || !old.name.equals(entry.name))
			{
				out.add(old);
			}
		}
		return out;
	}

	static String serialize(List<Destinations.Entry> history)
	{
		StringBuilder sb = new StringBuilder();
		for (Destinations.Entry entry : history)
		{
			if (sb.length() > 0)
			{
				sb.append('\n');
			}
			sb.append(entry.category).append('\t').append(entry.name).append('\t').append(entry.packedPosition);
		}
		return sb.toString();
	}

	static List<Destinations.Entry> deserialize(String raw)
	{
		return deserialize(raw, LIMIT);
	}

	/** Deserializes an entry list with a caller-chosen cap (the favourites list allows more rows). */
	static List<Destinations.Entry> deserialize(String raw, int limit)
	{
		List<Destinations.Entry> out = new ArrayList<>();
		if (raw == null || raw.isEmpty())
		{
			return out;
		}
		for (String line : raw.split("\\R"))
		{
			String[] fields = line.split("\t");
			if (fields.length < 3)
			{
				continue;
			}
			try
			{
				out.add(new Destinations.Entry(fields[0], fields[1], Integer.parseInt(fields[2])));
				if (out.size() >= limit)
				{
					break;
				}
			}
			catch (NumberFormatException e)
			{
				// A malformed row (hand-edited config) is dropped rather than poisoning the list.
			}
		}
		return out;
	}
}

package gps;

import com.google.inject.Inject;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import gps.pathfinder.PathStep;
import gps.transport.Transport;

public class PathMapTooltipOverlay extends Overlay
{
	private static final int TOOLTIP_OFFSET_HEIGHT = 25;
	private static final int TOOLTIP_OFFSET_WIDTH = 15;
	private static final int TOOLTIP_PADDING_HEIGHT = 1;
	private static final int TOOLTIP_PADDING_WIDTH = 2;
	private static final int TOOLTIP_TEXT_OFFSET_HEIGHT = -2;

	private final Client client;
	private final ShortestPathPlugin plugin;

	@Inject
	private PathMapTooltipOverlay(Client client, ShortestPathPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_HIGHEST);
		setLayer(OverlayLayer.MANUAL);
		drawAfterInterface(InterfaceID.WORLDMAP);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.drawMap || client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER) == null)
		{
			return null;
		}

		if (plugin.hasPathTargets())
		{
			List<PathStep> path = plugin.getDisplayPath();
			Point cursorPos = client.getMouseCanvasPosition();
			for (int i = 0; i < path.size(); i++)
			{
				int nextPoint = WorldPointUtil.UNDEFINED;
				if (path.size() > i + 1)
				{
					nextPoint = path.get(i + 1).getPackedPosition();
				}
				if (drawTooltip(graphics, cursorPos, path.get(i).getPackedPosition(), nextPoint, i + 1, path, i))
				{
					return null;
				}
			}
			for (int target : plugin.getPathTargets())
			{
				if (!path.isEmpty() && target != path.get(path.size() - 1).getPackedPosition())
				{
					drawTooltip(graphics, cursorPos, target, WorldPointUtil.UNDEFINED, -1, path, -1);
				}
			}
		}

		return null;
	}

	private boolean drawTooltip(Graphics2D graphics, Point cursorPos, int point, int nextPoint, int n,
		List<PathStep> path, int pathIndex)
	{
		int offsetPoint = WorldPointUtil.dxdy(point, 1, -1);
		int startX = plugin.mapWorldPointToGraphicsPointX(point);
		int startY = plugin.mapWorldPointToGraphicsPointY(point);
		int endX = plugin.mapWorldPointToGraphicsPointX(offsetPoint);
		int endY = plugin.mapWorldPointToGraphicsPointY(offsetPoint);

		if (startX == Integer.MIN_VALUE || startY == Integer.MIN_VALUE ||
			endX == Integer.MIN_VALUE || endY == Integer.MIN_VALUE)
		{
			return false;
		}

		int width = endX - startX;

		if (cursorPos.getX() < (startX - width / 2) || cursorPos.getX() > (endX - width / 2) ||
			cursorPos.getY() < (startY - width / 2) || cursorPos.getY() > (endY - width / 2))
		{
			return false;
		}

		List<String> rows = new ArrayList<>(Arrays.asList("GPS route:",
			n < 0 ? "Unused target" : ("Step " + n + " of " + path.size())));
		if (nextPoint != WorldPointUtil.UNDEFINED)
		{
			PathStep currentStep = path.get(pathIndex);
			PathStep nextStep = plugin.nextPathStep(path, pathIndex);
			for (Transport transport : plugin.transportsForEdge(currentStep, nextStep))
			{
				if (transport.getDisplayInfo() != null && !transport.getDisplayInfo().isEmpty())
				{
					String displayInfo = transport.getDisplayInfo();
					// Check if this transport goes to POH - if so, look ahead to find the exit
					// transport
					String pohExitInfo = plugin.getPohExitInfo(nextPoint, path, pathIndex);
					if (pohExitInfo != null)
					{
						displayInfo = displayInfo + " (Exit: " + pohExitInfo + ")";
					}
					rows.add(displayInfo);
					break;
				}
			}
		}

		graphics.setFont(FontManager.getRunescapeFont());
		FontMetrics fm = graphics.getFontMetrics();
		int tooltipHeight = fm.getHeight();
		int tooltipWidth = 0;
		if (rows.stream().map(fm::stringWidth).max(Integer::compare).isPresent())
		{
			tooltipWidth = rows.stream().map(fm::stringWidth).max(Integer::compareTo).get();
		}
		int clippedHeight = tooltipHeight * rows.size() + TOOLTIP_PADDING_HEIGHT * 2;
		int clippedWidth = tooltipWidth + TOOLTIP_PADDING_WIDTH * 2;

		Rectangle worldMapBounds = Objects.requireNonNull(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).getBounds();
		int worldMapRightBoundary = worldMapBounds.width + worldMapBounds.x;
		int worldMapBottomBoundary = worldMapBounds.height + worldMapBounds.y;

		int drawPointX = startX + TOOLTIP_OFFSET_WIDTH;
		int drawPointY = startY;
		if (drawPointX + clippedWidth > worldMapRightBoundary)
		{
			drawPointX = worldMapRightBoundary - clippedWidth;
		}
		if (drawPointY + clippedHeight > worldMapBottomBoundary)
		{
			drawPointY = startY - clippedHeight;
		}
		drawPointY += TOOLTIP_OFFSET_HEIGHT;

		int tooltipRectX = drawPointX - TOOLTIP_PADDING_WIDTH;
		int tooltipRectY = drawPointY - TOOLTIP_PADDING_HEIGHT;

		graphics.setColor(JagexColors.TOOLTIP_BACKGROUND);
		graphics.fillRect(tooltipRectX, tooltipRectY, clippedWidth, clippedHeight);

		graphics.setColor(JagexColors.TOOLTIP_BORDER);
		graphics.drawRect(tooltipRectX, tooltipRectY, clippedWidth, clippedHeight);

		graphics.setColor(JagexColors.TOOLTIP_TEXT);
		for (int i = 0; i < rows.size(); i++)
		{
			graphics.drawString(rows.get(i), drawPointX, drawPointY + TOOLTIP_TEXT_OFFSET_HEIGHT + (i + 1) * tooltipHeight);
		}

		return true;
	}
}

package gps;

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.concurrent.TimeUnit;
import org.openjdk.jmh.annotations.Benchmark;
import org.openjdk.jmh.annotations.BenchmarkMode;
import org.openjdk.jmh.annotations.Fork;
import org.openjdk.jmh.annotations.Measurement;
import org.openjdk.jmh.annotations.Mode;
import org.openjdk.jmh.annotations.OutputTimeUnit;
import org.openjdk.jmh.annotations.Scope;
import org.openjdk.jmh.annotations.Setup;
import org.openjdk.jmh.annotations.State;
import org.openjdk.jmh.annotations.Warmup;

/**
 * Microbenchmarks for the water-pin hot paths: the wet-endpoint flood a water target runs per
 * generation, and the sea-track builder the overlay schedules per sailing leg. Dev-only (jmh
 * source set, -Pjmh) — never ships, never counts toward the hub review surface.
 *
 * Each case CYCLES through several inputs so the production single-entry / LRU caches miss on
 * every call — these measure the compute, not the cache.
 *
 * Run:
 *   ./gradlew -Pjmh jmh --args='SailingSea -f 1 -wi 3 -i 5'
 * Allocation profile (B/op — the metric that caught the boxed-queue churn):
 *   ./gradlew -Pjmh jmh --args='SailingSea -f 1 -wi 3 -i 5 -prof gc'
 */
@State(Scope.Benchmark)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MILLISECONDS)
@Warmup(iterations = 2, time = 2)
@Measurement(iterations = 3, time = 2)
@Fork(1)
public class SailingSeaBenchmark
{
	/** Coastal pins: endpoints settle fast, small flood. */
	private static final int[][] COASTAL = {{2692, 3142}, {3051, 2645}, {2929, 3138}};
	/** Mid-ocean pins: the flood must reach 12 coastal endpoints — the worst case. */
	private static final int[][] MID_OCEAN = {{2894, 2637}, {2404, 2580}, {3200, 2700}};

	private final List<long[]> legs = new ArrayList<>();
	private int coastalAt;
	private int oceanAt;
	private int legAt;

	@Setup
	public void setup()
	{
		// Warm the resource load out of the measurement.
		SailingSea.isSailable(WorldPointUtil.packWorldPoint(2894, 2637, 0));
		// 16+ distinct static-row legs (> the 8-entry LRU) so every seaPath call computes.
		try (Scanner scanner = new Scanner(
			SailingSea.class.getResourceAsStream("/transports/sailing.tsv"), "UTF-8"))
		{
			while (scanner.hasNextLine() && legs.size() < 16)
			{
				String line = scanner.nextLine();
				if (line.startsWith("#") || line.isBlank())
				{
					continue;
				}
				String[] fields = line.split("\t");
				String[] origin = fields[0].split(" ");
				String[] destination = fields[1].split(" ");
				legs.add(new long[]{
					WorldPointUtil.packWorldPoint(
						Integer.parseInt(origin[0]), Integer.parseInt(origin[1]), 0),
					WorldPointUtil.packWorldPoint(
						Integer.parseInt(destination[0]), Integer.parseInt(destination[1]), 0)});
			}
		}
	}

	@Benchmark
	public int[] wetFloodCoastal()
	{
		int[] pin = COASTAL[coastalAt++ % COASTAL.length];
		return SailingSea.seaDistances(WorldPointUtil.packWorldPoint(pin[0], pin[1], 0));
	}

	@Benchmark
	public int[] wetFloodMidOcean()
	{
		int[] pin = MID_OCEAN[oceanAt++ % MID_OCEAN.length];
		return SailingSea.seaDistances(WorldPointUtil.packWorldPoint(pin[0], pin[1], 0));
	}

	@Benchmark
	public int[] seaTrackLeg()
	{
		long[] leg = legs.get(legAt++ % legs.size());
		return SailingSea.seaPathBlocking((int) leg[0], (int) leg[1]);
	}
}

