import org.openjdk.jmh.annotations.Measurement;
import org.openjdk.jmh.annotations.Mode;
import org.openjdk.jmh.annotations.OutputTimeUnit;
import org.openjdk.jmh.annotations.Param;
import org.openjdk.jmh.annotations.Scope;
import org.openjdk.jmh.annotations.Setup;
import org.openjdk.jmh.annotations.State;
import org.openjdk.jmh.annotations.Warmup;
import gps.ShortestPathConfig;
import gps.WorldPointUtil;

/**
 * Microbenchmark for the per-generation distance-field build: one multi-source reverse flood plus
 * the reverse-transport index and the blocked-landing patch. Dev-only — it lives in the jmh source
 * set so it never ships and never counts toward the hub's review surface.
 * <p>
 * The heavy setup (loading the real collision map + transport data and refreshing the everything-mode
 * config) runs once per trial in {@link #setup()} and is NOT measured; only {@link DistanceField#build}
 * is timed. Returning the field lets JMH consume it so the JIT cannot elide the flood.
 * <p>
 * Run e.g.: {@code ./gradlew jmh --args='DistanceFieldBenchmark -f 1 -wi 3 -i 5'}
 */
@State(Scope.Benchmark)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Warmup(iterations = 3, time = 1)
@Measurement(iterations = 5, time = 1)
@Fork(1)
public class DistanceFieldBenchmark
{
	// Varrock, and a spread-out three-target set (Varrock / Falador / Draynor) whose wider initial
	// frontier makes the flood do more work — the two ends of what a real generation asks for.
	private static final int VARROCK = WorldPointUtil.packWorldPoint(3213, 3424, 0);
	private static final int FALADOR = WorldPointUtil.packWorldPoint(2965, 3380, 0);
	private static final int DRAYNOR = WorldPointUtil.packWorldPoint(3093, 3245, 0);

	@Param({"single", "multi"})
	public String scenario;

	// 0 = full-map flood; 3 = the production default cost multiple (floor-bounded flood).
	@Param({"0", "3"})
	public int costMultiple;

	private PathfinderConfig config;
	private Set<Integer> targets;

	@Setup(Level.Trial)
	public void setup()
	{
		Client client = Mockito.mock(Client.class);
		ShortestPathConfig cfg = Mockito.mock(ShortestPathConfig.class);
		Mockito.when(cfg.calculationCutoff()).thenReturn(120);
		Mockito.when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		Mockito.when(client.getClientThread()).thenReturn(Thread.currentThread());
		Mockito.when(client.getBoostedSkillLevel(any(Skill.class))).thenReturn(99);

		config = new TestPathfinderConfig(client, cfg).copyForPlanning();
		config.refresh();

		switch (scenario)
		{
			case "single":
				targets = Set.of(VARROCK);
				break;
			case "multi":
				targets = Set.of(VARROCK, FALADOR, DRAYNOR);
				break;
			default:
				throw new IllegalArgumentException("unknown scenario: " + scenario);
		}
	}

	@Benchmark
	public DistanceField build()
	{
		return DistanceField.build(config, targets, costMultiple);
	}
}

package gps.pathfinder;

import java.util.Set;
import java.util.concurrent.TimeUnit;
import org.openjdk.jmh.annotations.Benchmark;
import org.openjdk.jmh.annotations.BenchmarkMode;
import org.openjdk.jmh.annotations.Fork;
import org.openjdk.jmh.annotations.Level;
import org.openjdk.jmh.annotations.Measurement;
import org.openjdk.jmh.annotations.Mode;
import org.openjdk.jmh.annotations.OutputTimeUnit;
import org.openjdk.jmh.annotations.Param;
import org.openjdk.jmh.annotations.Scope;
import org.openjdk.jmh.annotations.Setup;
import org.openjdk.jmh.annotations.State;
import org.openjdk.jmh.annotations.Warmup;

/**
 * Microbenchmark for the CLASSIC pathfinder — the plugin's original single-path flow
 * ({@code ShortestPathPlugin.restartPathfinding}): an uninformed (no distance field, no heuristic),
 * uncapped search. It still runs on every target change as the fallback/state-holder alongside the
 * alternative-routes generation, so this measures exactly what removing that redundant search would
 * save per target set.
 * <p>
 * The {@code availability} axis brackets reality: {@code everything} is the planning-mode superset
 * (every teleport usable — the alt-routes engine's view, and the worst case for transport fan-out);
 * {@code classic-defaults} is the true classic view — a possession-checked config with the plugin's
 * default settings, finished quests and empty containers (walking plus quest-gated networks).
 * <p>
 * Run: {@code ./gradlew -Pjmh jmh --args='ClassicPathfinderBenchmark -prof gc'}
 */
@State(Scope.Benchmark)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Warmup(iterations = 3, time = 1)
@Measurement(iterations = 5, time = 1)
@Fork(1)
public class ClassicPathfinderBenchmark
{
	@Param({"lumbridge-barrows", "ge-shilo", "capture"})
	public String scenario;

	@Param({"everything", "classic-defaults"})
	public String availability;

	private PathfinderConfig config;
	private int start;
	private Set<Integer> targets;

	@Setup(Level.Trial)
	public void setup()
	{
		config = "everything".equals(availability)
			? BenchScenarios.everythingConfig()
			: BenchScenarios.classicConfig();
		start = BenchScenarios.start(scenario);
		targets = BenchScenarios.targets(scenario);
	}

	@Benchmark
	public PathfinderResult search()
	{
		// The classic flow's configuration: costCap = MAX_VALUE, heuristic = null (uninformed).
		Pathfinder pathfinder = new Pathfinder(config, start, targets);
		pathfinder.run();
		return pathfinder.getResult();
	}
}

package gps.pathfinder;

import java.util.Set;
import java.util.concurrent.TimeUnit;
import org.openjdk.jmh.annotations.Benchmark;
import org.openjdk.jmh.annotations.BenchmarkMode;
import org.openjdk.jmh.annotations.Fork;
import org.openjdk.jmh.annotations.Level;
import org.openjdk.jmh.annotations.Measurement;
import org.openjdk.jmh.annotations.Mode;
import org.openjdk.jmh.annotations.OutputTimeUnit;
import org.openjdk.jmh.annotations.Param;
import org.openjdk.jmh.annotations.Scope;
import org.openjdk.jmh.annotations.Setup;
import org.openjdk.jmh.annotations.State;
import org.openjdk.jmh.annotations.Warmup;

/**
 * Microbenchmark for the third pipeline step: one {@link Pathfinder} search from start to targets.
 * The {@code mode} axis contrasts the production A* (with the distance-field heuristic) against the
 * uninformed search (heuristic = null), so the numbers show what the heuristic actually buys per
 * scenario.
 * <p>
 * The config, and the field + heuristic for the A* mode, are built once per trial in {@link #setup()}
 * and are NOT measured. Each invocation constructs a fresh Pathfinder (the search state is single-use)
 * and runs it — that construction is part of a real per-route cost, so it is measured too. Returning
 * the result lets JMH consume it.
 * <p>
 * Run: {@code ./gradlew jmh --args='PathfinderBenchmark'}
 */
@State(Scope.Benchmark)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Warmup(iterations = 3, time = 1)
@Measurement(iterations = 5, time = 1)
@Fork(1)
public class PathfinderBenchmark
{
	@Param({"lumbridge-barrows", "ge-shilo", "capture", "island", "deep-wild", "wilderness-escape"})
	public String scenario;

	@Param({"astar", "uninformed"})
	public String mode;

	private PathfinderConfig config;
	private int start;
	private Set<Integer> targets;
	private SearchHeuristic heuristic;

	@Setup(Level.Trial)
	public void setup()
	{
		config = BenchScenarios.everythingConfig();
		start = BenchScenarios.start(scenario);
		targets = BenchScenarios.targets(scenario);
		heuristic = "astar".equals(mode)
			? SearchHeuristic.buildWithField(config, DistanceField.build(config, targets))
			: null;
	}

	@Benchmark
	public PathfinderResult search()
	{
		Pathfinder pathfinder = new Pathfinder(config, start, targets, Integer.MAX_VALUE, heuristic);
		pathfinder.run();
		return pathfinder.getResult();
	}
}
